const getCoupon = require('common/getCoupon')
const getCouponNew = require('common/getCouponNew')

let adzoneIdObj = {
  'bjg923253': {
    'adzone_id1': '10021',
    'adzone_id2': '10021'
  },
  'union_bijiago': {
    'adzone_id1': '10019',
    'adzone_id2': '10019'
  },
  'union_bijiago_mogu': {
    'adzone_id1': '10019',
    'adzone_id2': '10019'
  },
  'union_bijiago_uos': {
    'adzone_id1': '10015',
    'adzone_id2': '10013'
  },
}

let pidConfig = require('bjgou/modules/pidConfig');

let globalData = {
  tmall: [],
  taobao: []
}
let sizeObj = {},
  totalObj = {}
let minPriceObj = {}
let minPriceStatus = {}

let cnt = 0

const renderCoupon = (data, type, isBottom) => {
  cnt++
  if (cnt > 29) {
    //debugger
  }
  sizeObj[type]++;
  if (data && data.data)
    globalData[type].push(data.data);
  if (sizeObj[type] === totalObj[type]) {
    if (isBottom) {
      renderProdutBt(type, isBottom)
    } else {
      renderProdut(type)
    }
    if (G.aliSite) {
      if (G.runminiCoup === '1') {
        require('common/miniCouponCompare').init(globalData, "#bjgext_mb_bg")
        require('common/dpCouponImg').init(globalData)
      } else if (!G.runminiCoup) {
        G.runminiCoupon2 = true;
        $(document).on('runminiCoupon2', function() {
          require('common/miniCouponCompare').init(globalData, "#bjgext_mb_bg")
          require('common/dpCouponImg').init(globalData)
        })

      }
    }

  }
}
const renderProdutBt = (type, bdata) => {
  let arr = globalData[type]

  for (let i = 0; i < bdata.length; i++) {
    for (let j = 0; j < arr.length; j++) {
      if (bdata[i] && arr[j] && bdata[i].num_iid == arr[j].reqid) {
        let lastP = (Number(bdata[i].price) - parseFloat(arr[j].coupon.coupon_money)).toFixed(2);
        if (bdata[i].priceCut) {
          lastP = Number(bdata[i].price)
        }
        if (Number(lastP) < minPriceObj[type]) {
          minPriceObj[type] = lastP;
          minPriceStatus[type] = true;
        }
        let coupon_money = arr[j].coupon.coupon_money;
        bdata[i].url = arr[j].click_url2;

        if (lastP < 0) {
        }
        let ori = bdata[i].price;
        if (bdata[i].priceCut) {
          ori += parseFloat(arr[j].coupon.coupon_money)
        }
        ori = parseFloat(ori)
        lastP = parseFloat(lastP).toFixed(2)
        bdata[i].tspan = `<span class="coupon_span">领${coupon_money}元券</span>`
        bdata[i].ta = `<div class="coupon_price">
              <span class="cou-pri-sp1">券后价:</span>
              <span class="cou-pri-sp2">￥${lastP}</span>
              <span class="cou-pri-sp3">￥${ori.toFixed(2)}</span>
            </div>`
        if (G.lang === 'en') {
          bdata[i].tspan = `<span class="coupon_span">${coupon_money} Coupon</span>`
          bdata[i].ta = `<div class="coupon_price">
              <span class="cou-pri-sp1">Price after coupon:</span>
              <span class="cou-pri-sp2">￥${lastP}</span>
              <span class="cou-pri-sp3">￥${ori.toFixed(2)}</span>
            </div>`
        }
        break;
      }
    }
  }

  if (minPriceStatus[type]) {
    $(`.bjgext-item-tb[data-id="${type}"] .item-pri`).text('￥' + parseFloat(minPriceObj[type]).toFixed(2))
  }
}
const renderProdut = (type) => {
  let ul = $(`#${type}-item-list li`)
  let len = ul.length;
  let arr = globalData[type]
  for (let i = 0; i < len; i++) {
    let id = ul.eq(i).attr('data-id')
    for (let j = 0; j < arr.length; j++) {
      if (arr[j] && arr[j].reqid == id) {
        ul.eq(i).find('.small-img').append($(`<span class="coupon_span">领${arr[j].coupon.coupon_money}元券</span>`))
        let price = ul.eq(i).find('span.gwd-price').text()
        let lastP = (Number(price.replace(/[¥￥]/g, '')) - arr[j].coupon.coupon_money).toFixed(2);
        ul.eq(i).find('.gwd-price').after(
          $(`<a href="${arr[j].click_url2}" target="_blank" class="coupon_price">
              <span class="cou-pri-sp1">${G.lang === 'en' ? 'Price after coupon': '券后价'}:</span>
              <span class="cou-pri-sp2">￥${lastP}</span>
              <span class="cou-pri-sp3">${price}</span>
            </a>`)).remove()
        ul.eq(i).find('a').attr('href', arr[j].click_url2)
      }
    }
  }

}

module.exports.init = (data, type, isBottom, minpri) => {
  if (G.forbidCoupon) {
    require('common/globalCondition').setMet(`AliProduct${type}`, data)
    return;
  }
  if (!data) return;
  if (!data.length) return;
  minPriceObj[type] = minpri;
  totalObj[type] = data.length;
  sizeObj[type] = 0;
  if (isBottom)
    isBottom = data;
  let f2 = function(newData) {
    renderCoupon(newData, type, isBottom)
  }
  if (!adzoneIdObj[G.union]) {
    adzoneIdObj[G.union] = {
      adzone_id1: 'default',
      adzone_id2: 'default'
    }
  }
  let adzone_id = adzoneIdObj[G.union]['adzone_id2'];
  if (G.aliSite) {
    adzone_id = adzoneIdObj[G.union]['adzone_id1'];
    for (let i = 0; i < data.length; i++) {
      getCoupon.init(data[i].num_iid, adzone_id, f2)
    }
    return ;
  }
  Promise.all(data.map(product => new Promise(async resolve => {
    // let coupon = await getCouponNew.initWithDpAsync(product.num_iid, pidConfig[G.union], 'compare');
    let coupon = await getCoupon.byIdAndAdzone(product.num_iid, adzone_id)
    if (coupon) {
      renderCoupon(coupon, type, isBottom)
      product.price = product.price - coupon.data.coupon.coupon_money
      product.priceCut = true
      product.tspan = `<span class="coupon_span">领${coupon.data.coupon.coupon_money}元券</span>`
      product.ta = `<div class="coupon_price">
                    <span class="coupon_price_span">
                      <span class="cou-pri-sp1">券后价:</span>
                      <span class="cou-pri-sp2 prifontf">¥${product.price.toFixed(2)}</span>
                      <span class="cou-pri-sp3 prifontf">¥${(parseFloat(product.price) + parseFloat(coupon.data.coupon.coupon_money)).toFixed(2)}</span>
                    </span>
            </div>`
      if (G.lang === 'en') {
        product.tspan = `<span class="coupon_span">${coupon.data.coupon.coupon_money} Coupon</span>`
        product.ta = `<div class="coupon_price">
                    <span class="coupon_price_span">
                      <span class="cou-pri-sp1">Price after coupon:</span>
                      <span class="cou-pri-sp2 prifontf">¥${product.price.toFixed(2)}</span>
                      <span class="cou-pri-sp3 prifontf">¥${(parseFloat(product.price) + parseFloat(coupon.data.coupon.coupon_money)).toFixed(2)}</span>
                    </span>
            </div>`
      }
      product.url = coupon.data.click_url2
    }
    resolve()
  }))).then(() => {
    require('common/globalCondition').setMet(`AliProduct${type}`, data)
    if (isBottom) {
      renderProdutBt(type, isBottom)
    } else {
      renderProdut(type)
    }
  })
}



