const bgClient = require('common/background/bgClient');

const getList = async () => {
  const res = await bgClient.get('/getStorage', { key: 'aliSkuHistory' });
  if (!res) return []
  return res;
}

const setList = async (list) => {
  await bgClient.get('/setStorage', { 'aliSkuHistory' :list });
}

const add = async (item) => {
  let list = await getList();
  list.push(item);
  list = [...new Set(list)]
  await setList(list);
}

const remove = async (item) => {
  let list = await getList();
  list = list.filter(i => i !== item);
  await setList(list);
}

module.exports = {
  getList,
  setList,
  add,
  remove
}



