var Times = 0;
let mainW = $(window).width();
let caches = {}


// 计算有多少空间给比价
const calFreeWidth = () => {
  let head = 300;
  let rightW = 0;
  let ad = 0;
  let compare = $('.bjgext-product-compare').outerWidth()
  if ($('#bijiago-banner-ad').length > 0) {
    ad += 176;
  }
  if ($('#bijiago-banner-ad2').length > 0) {
    ad += 136;
  }
  let freeWidth = mainW - head - rightW - compare - ad;
  return freeWidth;
}
const changeUrl = (start, end, dom) => {
  const replaceHref = require('common/replaceHref')
  let urlObj = replaceHref.getInfo()
  for (let i = start; i < end; i++) {
    let item = $(dom).find('.bjgext-item-img').eq(i)
    let href = item.attr('href')
    if (urlObj[href]) {
      item.attr('href', urlObj[href])
    }
  }
}

module.exports.calCompare = () => {
  let width = calFreeWidth()
  return parseInt(width / 120);
}

module.exports.loadImage = (start, end, dom) => {
  for (let i = start; i < end; i++) {
    let itemimg = $(dom).find('img').eq(i)[0];
    if (!itemimg) return;
    let src = itemimg.getAttribute('data-original') || '';
    let defaultsrc = itemimg.src;
    if (src.indexOf('start.png') > -1 || src.indexOf('blank.png') > -1) {
      $(itemimg).attr('src', G.noImg)
      continue;
    }
    if (src !== defaultsrc)
      module.exports.checkImage(itemimg, src);
  }
}

module.exports.checkImage = (dom, src) => {
  let image = new Image()
  image.onload = () => {
    $(dom).attr('src', src)
  }
  image.onerror = () => {
    $(dom).attr('src', G.noImg);
  }
  image.src = src;
}

module.exports.calDetailNum = () => {
  let turnpage = 66 * 2;
  let itemW = 190 + 30;
  // 最后一个不需要右边距 所以加30  总距离减两边翻页
  return {
    'num': parseInt((mainW - turnpage) / itemW),
    'width': (mainW - turnpage - 1)
  }
}

module.exports.changePage = (o, dom) => {
  let parentDom = $(dom).parent().parent();
  let list = parentDom.find('.bjgext-product-box li');
  let len = list.length;
  let curpage = Number(parentDom.find('.bjgext-page-num em').text());
  let perpage = module.exports.calDetailNum().num;
  let totalpage = Math.ceil(len / perpage);
  list.hide();
  if (o == 1) {
    if (curpage === totalpage) {
      curpage = 0;
    }
    for (let i = curpage * perpage, size = ((curpage + 1) * perpage > len ? len : (curpage + 1) * perpage); i < size; i++) {
      list.eq(i).show()
    }
    module.exports.loadImage(curpage * perpage, ((curpage + 1) * perpage > len ? len : (curpage + 1) * perpage), list);
    curpage++;
  } else {
    if (curpage === 1) {
      curpage = totalpage + 1;
    }
    for (let i = (curpage - 2) * perpage, size = ((curpage - 1) * perpage > len ? len : (curpage - 1) * perpage); i < size; i++) {
      list.eq(i).show()
    }
    module.exports.loadImage((curpage - 2) * perpage, ((curpage - 1) * perpage > len ? len : (curpage - 1) * perpage), list)
    curpage--;
  }
  parentDom.find('.bjgext-page-num em').text(curpage)
}

module.exports.setSimplePagePos = (size, dom) => {
  let left = dom.offset().left;
  let domw = dom.outerWidth();
  let detail = dom.find('.bjgext-product-detail')
  let width = 220 * size + 2;
  let dleft = left + domw / 2 - width / 2;
  if (dleft < 0)
    dleft = 0;
  if ((dleft + width) > mainW)
    dleft = (mainW - width - 2);
  detail.css('left', dleft + 'px');
}

module.exports.autoWidth = () => {
  setTimeout(() => {
    let timer = 0
    while ($('#bjg-space').width() > 0 && timer < 10) {
      timer ++
      let len = $('.bjgext-item-dp').length
      if (len === 0) return;
      $('.bjgext-item-dp')[len - 1].remove()
    }
  }, 0)
  if (Times > 10) return;
  let width = calFreeWidth();
  if (width < 0) {
    Times++;
    $('.bjgext-item-dp:last').remove()
    module.exports.autoWidth()
  } else {
    return;
  }
}

module.exports.resizeAutoWidth = () => {
  mainW = $(window).width();
  $('.bjgext-product-detail').remove()
  module.exports.autoWidth()
}



