module.exports.get = async function() {
  if (!G.aliSite) {
    return
  }
  const globalConfig = await require('common/globalCondition').met('GwdConfig')
  const configs = globalConfig.aliMobileNotifierConfig
  let selectorConfig = null
  await require('standard/module/util').waitForConditionFn(() => {
    selectorConfig = configs.find(item => {
      return $(item.priceText).length || $(item.priceTextMini).length
    })
    return selectorConfig
  })
  return selectorConfig
}


