<template>
  <div class="gwd-column pricedog-transport">
    <div v-if="innerData.catName" class="pricedog-transport-bar gwd-row gwd-align">
      <span class="pricedog-bold">
        類別：{{ innerData.catName }}
      </span>
    </div>
    <div v-if="!question && innerData.catName" class="pricedog-transport-bar gwd-row pricedog-transport-result">
      <span class="pricedog-bold pricedog-sub gwd-row gwd-align" style="padding-right: 8px">
        運輸方式：
      </span>
      <span
          v-if="innerData.catEmbargoAir !== 'None'"
          class="pricedog-sub gwd-row gwd-align"
          style="flex: 1; justify-content: center">
        <img src="../assets/transport-air@2x.png" alt="" style="width: 20px; height: 20px">
        <span style="margin-left: 8px;">空運</span>
        <span style="margin-left: 20px" :class="innerData.catEmbargoAir === '0' ? 'pricedog-allow': 'pricedog-forbid'">
          {{ innerData.catEmbargoAir === '0' ? '允許': '禁運' }}
        </span>
        <img
            v-if="innerData.catEmbargoAir === '0'"
            src="../assets/allow.svg" alt="" style="width: 13px; height: 13px; margin-left: 8px">
        <img
            v-else
            src="../assets/disallow.svg" alt="" style="width: 13px; height: 13px; margin-left: 8px">
      </span>
      <span
          v-if="innerData.catEmbargoSe !== 'None'"
          class="pricedog-sub gwd-row gwd-align"
          style="flex: 1; justify-content: center">
        <img src="../assets/transport-sea@2x.png" alt="" style="width: 20px; height: 20px">
        <span style="margin-left: 8px;">海運</span>
        <span style="margin-left: 20px" :class="innerData.catEmbargoSe === '0' ? 'pricedog-allow': 'pricedog-forbid'">
          {{ innerData.catEmbargoSe === '0' ? '允許': '禁運' }}
        </span>
        <img
            v-if="innerData.catEmbargoSe === '0'"
            src="../assets/allow.svg" alt="" style="width: 13px; height: 13px; margin-left: 8px">
        <img
            v-else
            src="../assets/disallow.svg" alt="" style="width: 13px; height: 13px; margin-left: 8px">
      </span>
    </div>
    <div v-if="!question && innerData.catName" class="pricedog-transport-bar gwd-column">
      <span class="pricedog-bold" style="line-height: 40px">進口限製：</span>
      <div style="padding-bottom: 10px;">
        <span :class="innerData.catShptBrief ? 'pricedog-forbid': 'pricedog-allow'">{{ innerData.catShptBrief ? innerData.catShptBrief: '無限製' }}</span>
      </div>
    </div>
    <div v-if="question && innerData.catName" class="pricedog-transport-bar gwd-column pricedog-question">
      <span class="pricedog-bold" style="line-height: 40px">{{ question }}</span>
      <div class="gwd-row gwd-align" style="padding-bottom: 16px">
        <input type="radio" v-model="currentSelect" value="qaRadioA"><span>{{ radioA }}</span>
        <input type="radio" v-model="currentSelect" value="qaRadioB" style="margin-left: 40px"><span>{{ radioB }}</span>
        <button @click="submit" :class="{ 'pricedog-active': currentSelect, 'gwd-button': currentSelect }">提交</button>
      </div>
    </div>
    <div v-if="!innerData.catName" class="pricedog-transport-bar gwd-row gwd-align">
      <span>很抱歉，暫未獲取到該商品的集運信息，pricedog努力收錄中～</span>
    </div>
  </div>
</template>
<script>
export default {
  props: ['data'],
  data: () => ({
    currentSelect: '',
    question: '',
    radioA: '',
    radioB: '',
    innerData: {}
  }),
  methods: {
    submit() {
      if (!this.currentSelect) return
      this.question = ''
      this.data.catalogQas.forEach(item => {
        const selected = item[this.currentSelect]
        if (selected.brief) {
          this.innerData.catShptBrief = selected.brief
        }
        if (selected.catEmbargoSe) {
          this.innerData.catEmbargoSe = selected.catEmbargoSe
        }
        if (selected.catEmbargoAir) {
          this.innerData.catEmbargoAir = selected.catEmbargoAir
        }
        if (selected.catCcMaxQty === '0') {
          this.innerData.catEmbargoSe = '1'
          this.innerData.catEmbargoAir = '1'
        }
      })
    }
  },
  mounted() {
    this.innerData = this.data
    if (this.data.catalogQas && this.data.catalogQas.length) {
      this.question = this.data.catalogQas[0].qaTitle
      this.radioA = this.data.catalogQas[0].qaRadioA.text
      this.radioB = this.data.catalogQas[0].qaRadioB.text
    }
  }
}
</script>
<style scoped lang="less">
.pricedog-transport {
  box-sizing: border-box;
  width: 462px;
  border: 1px solid #eeeeee;
  margin-bottom: 10px;
  background: white;
  span {
    font-size: 13px;
    color: #3c4c54;
  }
  .pricedog-forbid {
    color: #ff4449;
  }
  .pricedog-allow {
    color: #44cc66;
  }
  .pricedog-bold {
    font-weight: normal;
    font-size: 14px;
    color: #000000;
  }
  .pricedog-transport-bar {
    min-height: 40px;
    border-bottom: 1px solid #eeeeee;
    padding-left: 16px;
    padding-right: 16px;
  }
  .pricedog-transport-bar:last-of-type {
    border-bottom: none;
  }
  .pricedog-transport-result {
    .pricedog-sub {
      border-right: 1px solid #eeeeee;
      span {
        font-size: 14px;
      }
    }
    .pricedog-sub:last-of-type {
      border-right: none;
    }
  }
  .pricedog-question {
    input[type=radio] {
      margin-top: 0;
      margin-left: 0;
      margin-right: 8px;
      width: 16px;
      height: 16px;
      position: relative;
      appearance: none;
      bottom: 0;
      cursor: pointer;
    }
    input[type=radio]::after {
      content: '';
      position: absolute;
      width: 16px;
      height: 16px;
      box-sizing: border-box;
      border: 2px solid #999999;
      border-radius: 8px;
      z-index: 2;
    }
    input[type=radio]:checked::after {
      content: '';
      position: absolute;
      width: 16px;
      height: 16px;
      box-sizing: border-box;
      border: 2px solid #ff6132;
      border-radius: 8px;
      z-index: 2;
    }
    input[type=radio]:checked::before {
      content: '';
      position: absolute;
      width: 10px;
      height: 10px;
      border-radius: 5px;
      top: 50%;
      left: 50%;
      margin-top: -5px;
      margin-left: -5px;
      background: #ff6132;
      box-sizing: border-box;
      z-index: 2;
    }
    button {
      margin-left: 52px;
      width: 60px;
      height: 30px;
      background: #F0ECEC;
      border-radius: 4px;
      font-size: 14px;
      color: #3c4c54;
      border: none;
    }
    button.pricedog-active {
      color: #FFFFFF;
      cursor: pointer;
      background: #FF6132;
    }
  }
}
</style>


