const request = require('common/request')
const host = 'https://i.bijiago.com'
const communicate = require('common/communicate')
const util = require('bjgou/modules/util')
const store = require('bjgou/store/index')
const client = require('common/background/bgClient')

let loginCache = undefined
let dpCache = undefined

module.exports = {
  hasUserToken() {
    return new Promise(async resolve => {
      let resolved = false
      communicate.trigger({
        type: 'checkUserTokenBjg'
      })
      communicate.on(data => {
        if (typeof data === 'string') {
          data = JSON.parse(data)
        }
        if (data.type === 'checkUserTokenBjg') {
          resolved = true
          resolve(data.value)
        }
      })

      if (navigator.userAgent.toLowerCase().indexOf('metasr') > -1 || !G.allowBackgroundRequest) {
      //if (true) {
        if (loginCache !== undefined) {
          resolve(loginCache)
          return
        }
        let dpId = await require('common/globalCondition').met('GwdDpIdGot')
        request.requestXHR(`${host}/UserCollection/Check?dp_id=${dpId}&app_platform=ext`).then(res => {
          if (res.code !== -3) {
            loginCache = true
            resolve(true)
            dpCache = res
          } else {
            loginCache = false
            resolve(false)
          }
        })
      }

    })
  },
  goLogin(forceOpen = false) {
    if (G.bgVer > 1) {
      location.href = 'https://www.bijiago.com/login?to=' + encodeURIComponent(location.href + (forceOpen ? '#forceOpen': ''))
    } else {
      location.href = `https://i.bijiago.com/UserUnion/Authorize?utype=2&app_platform=ext&_referer=${encodeURIComponent(location.href + (forceOpen ? '#forceOpen': ''))}`
    }
  },
  del(dp_id) {
    return request.post(`${host}/UserCollection/Delete?app_platform=ext`, {
      collection_id: dp_id
    }, true)
  },
  getList(pg, tab = 'default') {
    return request.get(`${host}/UserCollection/List?tab=${tab}&pg=${pg}&app_platform=ext&union=${G.union}`)
  },
  collect(dp_id) {
    let payload = {
      dp_id: dp_id,
      //price: G.dp.price * 100,
      url: location.href,
      title: G.dp.name ? G.dp.name: document.title,
      img: G.dp.img ? G.dp.img: (G.dp.pic ? G.dp.pic: '')
    }
    console.log('dp price collect', G.dp.price)
    if (G.dp.price) {
      payload.price = G.dp.price * 100
    } else {
      payload.price = 0
    }
    if (require('common/haitao').isHaitao()) {
      payload.price = G.dp.oldPrice * 100
    }
    return request.post(`${host}/UserCollection/Add?app_platform=ext`, payload, true)
  },
  sendCartLog(payload) {
    return request.requestXHRPost(`${host}/UserExtend/WorthOrderUpload?app_platform=ext`, payload, false)
  },
  hasWx() {
    return new Promise(resolve => {
      let t = util.getStorage('userHasWx')
      if (t) {
        resolve(true)
      } else {
        request.requestXHR(`${host}/UserUnion/hasWx`).then(res => {
          if (res.data.hasWx) {
            util.setStorage('userHasWx', true)
            resolve(true)
          }
        })
      }
    })
  },
  checked(dp_id) {
    if (G.productChecked) {
      return new Promise(resolve => resolve(G.productChecked))
    } else {
      return new Promise(resolve => {
        if (dpCache) {
          resolve(dpCache)
        }
        request.get(`${host}/UserCollection/Check?dp_id=${dp_id}&app_platform=ext`).then(function(res) {
          resolve(res)
        })
      })
    }
  }
};

let inited = false

module.exports.init = async () => {
  if (inited) {
    return true
  }
  let user = await module.exports.hasUserToken()
  store.commit('user/setState', {
    userLogin: user
  })

  if (!user) {
    await client.get('/clearUserName', {})
  }

  if (G.allowBackgroundRequest) {
    client.get('/getUserName', {}, async data => {
      store.commit('user/setState', {
        userName: data
      })
      if (await module.exports.hasWx()) {
        store.commit('user/setState', {
          userHasWx: true
        })
      }
    })
  }

  inited = true
  return true
}



