const request = require('common/request')
const template = require('vendor/template')

module.exports = {
  init: async function(hasCoupon) {
    if (window.bjgActivity) return
    if (G.ss_name === 'priceDog') {
      require('bjgou/modules/priceDogActivity').init(hasCoupon)
      return
    }
    window.bjgActivity = true
    let configUrl = 'https://cdn.bijiago.com/js/configs/activity-bijiago-online.json'
    if (G.from_device === 'biyibi') {
      configUrl = 'https://cdn.bijiago.com/js/configs/activity-biyibi.json'
    }
    let config = await request.rawGet(configUrl)
    if (config.aliActivity && G.aliSite) {
      let c = config.aliActivity
      let onlyCenter = false
      if (c.disableWhenHasCoupon && hasCoupon) {
        onlyCenter = true
      }
      const t = (new Date())
      const s = new Date(c.start)
      const e = new Date(c.end)
      if (t < e && t > s) {
        if (!onlyCenter) {
          if (window.innerWidth - $('#bjgext_mainbar').outerWidth() > 160) {
            // 底部
            let html = template.compile(require('art-template-loader!activities/gwd-ali-bottom-link.html'))({
              img: c.bottom.img,
              qr: c.bottom.qr,
              extClass: '',
              link: c.link
            })
            $('#bjgext_mainbar .common-banner').after(html)
            require('common/cnzz').hoverLog('.gwd-bottom-tmall', '底部活动二维码')
          }

          let html2 = template.compile(require('art-template-loader!activities/gwd-tmall-middle-link.html'))({
            qr: c.top.qr,
            text: c.middle.text,
            link: c.link
          });
          $('#bjgext_minibar').after(html2)
        }

        if (true) {
          // 中间
          let html = template.compile(require('art-template-loader!activities/gwd-ali-center-link.html'))({
            img: c.top.img,
            qr: c.top.qr,
            text: c.center.text,
            extClass: '',
            link: c.link,
            qrText: c.qrText
          })
          // $('.bjgext-mini-trend').after(html)
          $('.gwd-middle-tmall').css('border', '1px solid #f1f1f1')

          let centerLogged = false
          require('common/cnzz').log('中间活动二维码', '曝光')
          setTimeout(() => {
            $('.gwd-middle-tmall').hover(() => {
              if (!centerLogged) {
                centerLogged = true
                require('common/cnzz').log('中间活动二维码', '悬浮')
              }
            })
            $('.gwd-take').hover(() => {
              if (!centerLogged) {
                centerLogged = true
                require('common/cnzz').log('中间活动二维码', '悬浮')
              }
            })
          }, 0)
        }
      } else if (G.from_device === 'biyibi' && G.mv3) {
        // if (!hasCoupon) {
        //   $('#bjgext_mainbar .common-banner').after('<a href="https://www.biyibi.com" id="bijiago-banner-ad" target="_blank" class="rinfo-btn close-models" title="点击领取" style="width: initial;"></a>')
        // }
      }
    }
    if (config.jdActivity && G.site === '360buy') {
      let c = config.jdActivity
      const t = (new Date())
      if (t < new Date(c.end) && t > new Date(c.start)) {
        $('#bijiago-banner-ad').remove()

        if (!hasCoupon) {
          if (c.center.textlong) {
            // 购物党中间
            let html = template.compile(require('art-template-loader!activities/gwd-jd-middle.html'))({
              link: c.center.link,
              text: c.center.textlong
            });
            $('#bjgext_minibar').append(html)

            $('.bjgext-toptabs').css('width', '100%')
            // $('.minibar-tab').css('width', '128px')
            // $('.gwd-middle-tmall').css('width', '159px;')
          }

          if (window.innerWidth - $('#bjgext_mainbar').outerWidth() > 160) {
            // 购物党底部
            let html = `<a href="${c.bottom.link}" target="_blank" class="rinfo-btn" title="点击领取" style="width: initial; margin-left: 8px; margin-right: 8px"><img style="height: 48px" src="${c.bottom.img}"/></a>`
            $('#bjgext_mainbar .common-banner').after(html)
          }

        }

      } else {
        if (window.bjgAutoPriceProtect && !hasCoupon && !G.disableLogin) {
          let html = require('html-loader!../views/priceProtectMiniAd.html')
          $('.bjgext-toptabs').after(html)
        }
      }
    }

    if (G.from_device === 'biyibi' && G.mv3 && !navigator.userAgent.toLowerCase().includes('edg')) {
      // check version.json for updates
      let version = await request.rawGet('https://cdn.bijiago.com/js/configs/biyibi-version.json')
      if (version.build > G.version) {
        $('#bijiago-banner-ad').html(version.HTML)
        $('#bijiago-banner-ad').attr('href', version.link)
        $('#bijiago-banner-ad').attr('title', '')
      }
    }
  }
}



