module.exports.raw = function(url, isarg) {
    if (isarg) {
        url = `${url}&union=${G.union}&version=${G.version}&from_device=${G.from_device}`
    }
    var done
    if (G.allowBackgroundRequest) {
        return new Promise((resolve) => {
            communicate.trigger({
                type: 'proxyRequest',
                url: url
            })
            communicate.on(info => {
                if (info.type === 'proxyRequest' && info.id === url) {
                    resolve(JSON.stringify(info.value))
                }
            })
        });
    } else {
        var r = {
            done: function(cb) {
                done = cb
            }
        };
        var xhr = new XMLHttpRequest();
        xhr.addEventListener('load', function() {
            if (done) done(xhr.responseText)
        })
        xhr.addEventListener('error', function() {
            if (done) done(xhr.responseText)
        })
        xhr.open("GET", url, true);
        xhr.send();
        return r;
    }
}

/**
 * 普通GET请求，不会加上多余的参数
 * @param urls
 * @returns {Promise<unknown>|*}
 */
module.exports.rawGet = (url, allowCredentials = false, timeout = 3000) => {
    if (url.includes('/helper/qrcode?')) {
        url = require('common/productInfo').appendTbInfoForUrl(url)
    }
    if (G.allowBackgroundRequest) {
        return new Promise((resolve, reject) => {
            let resolved = false;
            communicate.trigger({
                type: 'proxyRequest',
                url: url,
                referer: location.href
            })
            communicate.on(info => {
                if (info.type === 'proxyRequest' && info.id === url) {
                    resolved = true;
                    resolve(info.value)
                }
            })
            setTimeout(() => {
                if (!resolved) {
                    require('common/extConsole').warn('请求超时', url)
                    reject()
                }
            }, timeout)
        });
    } else {
        if (allowCredentials) {
            return module.exports.requestXHR(url, {})
        }
        return new Promise((resolve, reject) => {
            $.get(url).then(res => resolve(res)).fail(err => reject(err))
        })
        // return $.get(url)
    }
};

