/** 请求自己接口 */
module.exports.get = function(url) {
    let instanceId = G.instanceId
    let from_type = ""
    if (G.from_type) {
        from_type = `&from_type=${G.from_type}`
    }
    url = `${wrap(url)}version=${G.version}&from_device=${G.from_device}${from_type}`
    if (!url.includes('union=')) {
        url += '&union=' + G.union
    }
    if (G.crc64) url += "&crc64=1"

    if (!Promise.prototype.done) {
        Promise.prototype.done = Promise.prototype.then;
        Promise.prototype.fail = Promise.prototype.catch;
    }
    if (G.allowBackgroundRequest) {
        return new Promise((resolve) => {
            communicate.trigger({
                type: 'proxyRequest',
                url: url,
                referer: location.href
            })
            communicate.on(info => {
                if (instanceId && instanceId !== G.instanceId && !location.href.startsWith('https://s.taobao.com')) {
                    // debugger
                    // require('common/extConsole').warn('instanceId不一致，不处理', instanceId, G.instanceId)
                    resolve(null)
                    return
                }
                if (info.type === 'proxyRequest' && info.id === url) {
                    resolve(info.value)
                }
            })
        });
    } else {
        return new Promise((resolve, reject) => {
            // request(url, function(res) {
            //     try {
            //         resolve(JSON.parse(res))
            //     } catch (e) {
            //         resolve(res)
            //     }
            // }, location.href)
            window.ts = $
            $.ajax({
                beforeSend: function(request) {
                    if (G.requestNeedToken) {
                        //request.setRequestHeader("x-bjg-token", G.requestNeedToken);
                    }
                },
                dataType: "json",
                url: url,
                success: function(data) {
                    if (instanceId && instanceId !== G.instanceId) {
                        resolve(null)
                        return
                    }
                    resolve(data)
                }
            });

            // $.getJSON(url).then(res => resolve(res))
            // console.log(url)
            // $.ajax(url, {
            //     xhrFields: {
            //         withCredentials: true
            //     },
            //     jsonp: false,
            //     jsonpCallback: ''
            // }).then(res => {
            //     resolve(res)
            // })
        })
    }

}

const requesting = {}
module.exports.getOnce = function(url) {
    let key = 'getOnce-' + url
    return new Promise((resolve, reject) => {
        if (requesting[url]) {
            require('common/globalCondition').met(key).then(res => {
                resolve(res)
            })
            return
        } else {
            requesting[url] = true
            module.exports.get(url).then(res => {
                resolve(res)
                require('common/globalCondition').setMet(key, res)
            })
        }
    })
}

let postingId = 0

module.exports.urlContentToDataUri = url => {
    return fetch(url)
      .then(response => response.blob())
      .then(blob => new Promise(callback => {
          let reader = new FileReader();
          reader.onload = function () {
              callback(this.result)
          };
          reader.readAsDataURL(blob);
      }));
}

module.exports.imgUrlToDataUri = imgUrl => {
    return new Promise((resolve, reject) => {
        let img = new Image();
        img.crossOrigin = 'Anonymous';
        img.onload = function () {
            let canvas = document.createElement('CANVAS');
            let ctx = canvas.getContext('2d');
            let dataURL;
            // canvas.height = this.naturalHeight;
            // canvas.width = this.naturalWidth;
            // ctx.drawImage(this, 0, 0);
            const naturalWidth = this.naturalWidth, naturalHeight = this.naturalHeight
            if (naturalWidth > 400) {
                const r = naturalWidth / 400
                canvas.width = 400
                canvas.height = naturalHeight / r
            } else {
                canvas.width = naturalWidth
                canvas.height = naturalHeight
            }
            ctx.drawImage(this, 0, 0, canvas.width, canvas.height)
            dataURL = canvas.toDataURL('image/jpeg');
            resolve(dataURL);
        };
        img.src = imgUrl;
    });
}

module.exports.makeUrl = (host, path, query, noEncode = false) => {
    let url = host + path
    if (query) {
        url += '?'
        for (let key in query) {
            url += `${key}=${noEncode ? query[key]: encodeURIComponent(query[key])}&`
        }
        url = url.substring(0, url.length - 1)
    }
    return url
}

module.exports.post = (url, data, useForm = false, withCredentials = true) => {
    let reqId = postingId;
    postingId++;
    if (G.allowBackgroundRequest) {
        return new Promise((resolve) => {
            communicate.trigger({
                type: useForm ? (useForm === 'www' ? 'proxyRequestPostWWWForm': 'proxyRequestPostForm'): 'proxyRequestPost',
                url: url,
                payload: data,
                reqId: reqId,
                referer: location.href
            })
            communicate.on(info => {
                if (info.type.indexOf('proxyRequestPost') > -1 && info.id === reqId) {
                    resolve(info.value)
                }
            })
        });
    } else {
        return module.exports.requestXHRPost(url, data, useForm, withCredentials)
    }
};

