module.exports.requestXHR = function requestXHR(url, withCredentials = true, customHeaders = null) {
    if (G.serviceWorker) {
        return fetch(url, {
            "credentials": withCredentials ? "include": '',
        }).then(r => r.text())
    }
    return new Promise(resolve => {
        var xmlhttp = new XMLHttpRequest();
        xmlhttp.addEventListener('load', function() {
            try {
                let res = JSON.parse(xmlhttp.responseText)
                resolve(res)
            } catch (e) {
                resolve(xmlhttp.responseText)
            }
        })
        xmlhttp.withCredentials = withCredentials
        xmlhttp.open("GET", url, true);
        if (customHeaders) {
            Object.keys(customHeaders).forEach(key => {
                xmlhttp.setRequestHeader(key, customHeaders[key])
            })
        }
        xmlhttp.send();
    })
};

module.exports.requestXHRPost  = function requestXHR(url, data, form = true, withCredentials = true) {
    return new Promise(resolve => {
        let xmlhttp = new XMLHttpRequest();
        xmlhttp.addEventListener('load', function() {
            try {
                let res = JSON.parse(xmlhttp.responseText)
                resolve(res)
            } catch (e) {
                resolve(xmlhttp.responseText)
            }
        })
        xmlhttp.withCredentials = withCredentials
        xmlhttp.open("POST", url, true);

        if (G.requestNeedToken) {
            //xmlhttp.setRequestHeader('x-bjg-token', G.requestNeedToken)
        }

        if (form) {
            let formData = new FormData()
            Object.keys(data).forEach(item => {
                formData.append(item, data[item])
            });
            xmlhttp.send(formData);
        } else {
            xmlhttp.setRequestHeader('Content-Type', 'text/plain')
            xmlhttp.send(data)
        }
    })
};

module.exports.jdRequest = async (id) => {
    const gwdConfig = await require('common/globalCondition').met('GwdConfig')
    if (!gwdConfig.allowJdRequest || location.hostname.includes('.jd.hk')) {
        return
    }
    const cat = pageConfig.product.cat.join(','), t = Date.now(), shopId = pageConfig.product.shopId, vendorId = pageConfig.product.venderId
    await require('standard/module/util').waitForConditionFn(() => $('.ui-area-text').length)
    const area = $('.ui-area-text').attr('data-id').replaceAll('-', '_')
    const params = {
        skuId: id,
        cat: cat,
        area: area,
        shopId: shopId,
        venderId: vendorId,
        paramJson: pageConfig.product.paramJson,
        num: pageConfig.product.countNum || '1'
    }
    const payload = {
        appid: 'pc-item-soa',
        functionId: 'pc_detailpage_wareBusiness',
        client: 'pc',
        clientVersion: '1.0.0',
        t: t,
        body: JSON.stringify(params)
    }
    const payloadCopy = Object.assign({}, payload)
    payloadCopy.body = SHA256(JSON.stringify(params)).toString()
    let sign = await window.PSign.sign(payloadCopy)
    payload.h5st = encodeURI(sign.h5st)
    if (window.jdtRiskContext && window.jdtRiskContext.deviceInfo) {
        payload['x-api-eid-token'] = jdtRiskContext.deviceInfo.jsToken
    }
    if (window.getJsToken) {
        payload['x-api-eid-token'] = await new Promise(resolve => {
            getJsToken(res => {
                resolve(res.jsToken)
            })
        })
    }
    payload.loginType = '3'
    payload.uuid = window.getCookie('__jda')
    const host = location.hostname.includes('.jkcsjd.com') ? 'https://color.jkcsjd.com' : 'https://api.m.jd.com'
    return module.exports.requestXHR( `${host}/?` + Object.keys(payload).map(key => `${key}=${encodeURIComponent(payload[key])}`).join('&'), true, {
        'x-referer-page': `https://${location.hostname}/` + id + '.html',
        'x-rp-client': 'h5_1.0.0'
    })
}

module.exports.buildUrl = (url, payload) => {
    return url + '?' + Object.keys(payload)
      .map(key => `${key}=${encodeURIComponent(payload[key])}`).join('&')
}



