<template>
  <div class="bjg-mini-products">
    <img src="../assets/left@2x.png" alt="" class="turnImg left-turn" @click="prevPage" :style="currentPage === 0 ? 'visibility: hidden': ''">
    <div style="display: flex; flex: 1; justify-content: space-between; flex-direction: row; flex-wrap: nowrap">
      <a v-for="item in showingList" class="bjg-cmp-product" :href="item.url" target="_blank">
        <img :src="item.img_url" alt="" onerror="this.src = 'http://cdn.bijiago.com/images/extensions/default_load_image.png'">
        <span class="redPrice">¥{{item.price}}</span>
        <span class="iconText"><img :src="item.icon_url" alt=""> {{item.site_name}}</span>
        <span class="productTitle">{{item.title}}</span>
      </a>
    </div>
    <img src="../assets/left@2x.png" alt="" class="turnImg right-turn" @click="nextPage" :style="currentPage === totalPage - 1 ? 'visibility: hidden': ''">
  </div>
</template>
<style lang="less" scoped>
  .bjg-mini-products {
    img {
      display: inline-block;
      vertical-align: middle;
    }
    width:462px;
    /*height:243px;*/
    padding-bottom: 28px;
    background:rgba(255,255,255,1);
    /*box-shadow:0px 2px 4px 0px rgba(226,226,226,1);*/
    /*border-radius:0px 0px 4px 4px;*/
    border:1px solid rgba(230,233,235,1);
    display: flex;
    line-height: initial;
    flex-direction: row;
    .turnImg {
      margin-top: 94px;
      width: 14px;
      height: 24px;
      cursor: pointer;
    }
    .left-turn {
      margin-left: 20px;
      margin-right: 6px;
    }
    .right-turn {
      margin-left: 6px;
      margin-right: 20px;
      transform: rotate(180deg);
    }
    .bjg-cmp-product:hover {
      text-decoration: none;
    }
    .bjg-cmp-product {
      display: flex;
      flex-direction: column;
      cursor: pointer;
      width: 177px;
      align-items: center;
      img {
        width: 100px;
        height: 100px;
        margin-top: 16px;
      }
      .redPrice {
        margin-top: 14px;
        color: #ff6132;
        font-size: 14px;
      }
      .iconText {
        vertical-align: middle;
        img {
          width: 16px;
          height: 16px;
          margin-right: 6px;
          margin-top: 0;
        }
        color: #6b6761;
        font-size: 12px;
        margin-top: 10px;
        font-weight: bold;
      }
      .productTitle {
        display: -webkit-box;
        color: #6b6761;
        font-size: 12px;
        margin-top: 9px;
        height: 40px;
        line-height: 20px;
        text-overflow: ellipsis;
        -webkit-box-orient:vertical;
        overflow: hidden;
        -webkit-line-clamp: 2;
      }
    }
  }
</style>
<script>
  export default {
    props: ['products'],
    data() {
      return {
        currentPage: 0
      }
    },
    methods: {
      nextPage() {
        this.currentPage++
      },
      prevPage() {
        this.currentPage--
      }
    },
    computed: {
      totalPage() {
        return Math.ceil(this.products.length / 2)
      },
      showingList() {
        let list = [this.products[this.currentPage * 2]]
        if (this.products[this.currentPage * 2 + 1]) {
          list.push(this.products[this.currentPage * 2 + 1])
        }
        return list
      }
    }
  }
</script>


