const getCoupon = require('common/getCoupon')
const template = require('vendor/template')
let html = require('art-template-loader!../views/dpPageCoupon.html')
const request = require('common/request')
const userData = require('common/userData')
const cnzz = require('common/cnzz')
const log = require('common/log')
const util = require('./util')
const QRReloader = require('common/coupon/QRReloader')

let adzoneIdObj = {
  'bjg923253': {
    'adzone_id': '10015',
    'adzone_id2': '10016'
  },
  'union_bijiago': {
    'adzone_id': '10015',
    'adzone_id2': '10013'
  },
  'union_bijiago_mogu': {
    'adzone_id': '10015',
    'adzone_id2': '10013'
  },
  'union_bijiago_uos': {
    'adzone_id': '10015',
    'adzone_id2': '10013'
  },
  'union_biyibi': {
    'adzone_id': '10015',
    'adzone_id2': '10013'
  },
}
let randomNum

const renderTop = (data) => {
  if (!data || data.code !== 200 || !data.data) {
    setTimeout(async () => {
      await require('common/globalCondition').met('noOtherGiftMoney')
      require('bjgou/modules/specialActivityBjgou').init(false)
    }, 1000)
    require('bjgou/modules/shopCouponBjg').init()
    return;
  }
  require('bjgou/modules/specialActivityBjgou').init(true)
  data = data.data;
  data.pid = adzoneIdObj[G.union]['adzone_id2'];
  getPageInfo(data, function(newData, url) {
    let html = require('art-template-loader!../views/topCoupon.html')
    let isShowPic = false;
    let tle = "点击领券"
    if (isShowPic) {
      tle = "";
    }
    $('.bjg-coupon-space').after(template.compile(html)({
      price: data.coupon.coupon_money,
      url: require('common/productInfo').appendTbInfoForUrl(`${G.tb_server}/extension/qrpage?union=${G.union}&dp_id=${G.dp.dpId}&tag=9_chrome&discount=${data.coupon.coupon_money}`),
      tle: tle,
      isShowPic: isShowPic,
      picUrl: 'xx',
      isBottom: true,
      lang: G.lang
    }))
    let hasCoupon = false
    $('#top_coupon_btn .coupon_detail img').css('visibility', 'hidden')
    cnzz.log('淘宝优惠券底部二维码', '曝光')
    require('common/log')('coupon:show')
    $('#top_coupon_btn').hover(function() {
      if (!hasCoupon) {
        QRReloader.init(newData, url, '#top_coupon_btn .coupon_detail > img',function(newData2) {
          hasCoupon = true
          cnzz.log('淘宝优惠券底部二维码', '悬浮')
          cnzz.log('track:topcoupon:' + G.from_device)
          util.tongjiLog('track:topcoupon:' + G.from_device)
          addEvent('click:topcoupon:' + G.from_device)
        }, false, false)
      }
    })
  })

}
const renderTop2 = (data) => {
  return;
  if (data instanceof Array) {
    return;
  }
  let html = require('art-template-loader!../views/topCoupon.html')
  $('.bjg-coupon-space').replace(template.compile(html)({
    price: data.discount,
    url: data.click_url2
  }))
  cnzz.log('track:topcoupon_2:' + G.from_device)
  util.tongjiLog('track:topcoupon_2:' + G.from_device)
  addEvent('click:topcoupon_2:' + G.from_device)
}

let callbacks, hasreq, urls
const getPageInfo = require('common/coupon/getCouponInfo')

const getQRcode = require('common/coupon/getQRCode')

const addEvent = (str) => {
  let showQRcode
  $('#top_coupon_btn_bjg').on('click', function() {
    cnzz.log(str)
    util.tongjiLog(str)
  })
  $('.coupon-close-btn').on('click', function(e) {
    $('#top_coupon_btn_bjg').remove()
    return false;
  })
  $('#top_coupon_btn_bjg').on('mouseenter', function() {
    if (!showQRcode) {
      cnzz.log("track:coupon:qrcode:top")
      util.tongjiLog("track:coupon:qrcode:top")
      showQRcode = true;
    }
  })
}

const renderMini = (data) => {
  if (!data || (data && data.code !== 200) || (data && !data.data)) {
    if (G.runminiCoupon2) {
      $(document).trigger('runminiCoupon2')
    } else {
      G.runminiCoup = '1';
    }
    return;
  }
  G.runminiCoup = '2';
  data = data.data;
  data.pid = adzoneIdObj[G.union]['adzone_id'];
  getPageInfo(data, function(newData, url) {
    data.coupon.lastPrice = Number(G.dp.price - data.coupon.coupon_money).toFixed(2);
    let isShowPic = (randomNum > -1) ? true : false;
    let str = ``;
    let classes = '';
    let str2 = `
          <div class="mini-coup-detail">
              <img src="xx">
              <span style="line-height: initial">微信扫码领券</span>
          </div>
      `
    // if (G.ss_name === 'priceDog') {
    //   require('common/copyTkl').init()
    // }
    if (!isShowPic) {
      str = `href="${data.click_url2}" target="_blank"`
      str2 = ``;
      classes = 'haslink'
    }
    let tle = "点击领券"
    if (G.lang === 'en') tle = 'Get'
    if (isShowPic) {
      tle = "";
    }
    let html2 = require('art-template-loader!../views/aliMiniCoupon.html')
    let dom = template.compile(html2)({
      data: data,
      isShowPic: false,
      lang: G.lang,
      url: require('common/productInfo').appendTbInfoForUrl(`${G.tb_server}/extension/qrpage?&union=${G.union}&dp_id=${G.dp.dpId}&tag=9_chrome&discount=${data.coupon.coupon_money}`)
    })
    //$(`#bjgext_minibar`).after($(dom))
    $('#bjg-coupon-placeholder').replaceWith($(dom))
    if (!G.showMinibar) {
      $('#bjgext_minibar').css('display', 'inline-block')
      G.showMinibar = true;
    }
    $('.bjgext-mini-trend').addClass('hascoupon')
    cnzz.log('track:minicoupon:' + G.from_device)
    util.tongjiLog('track:minicoupon:' + G.from_device)
    $('#coupon_box').on('click', function() {
      cnzz.log('click:minicoupon:' + G.from_device)
      util.tongjiLog('click:minicoupon:' + G.from_device)
    })
    let showQRcode
    $('.bjgext-toptabs .mini-coup-detail img').css('visibility', 'hidden')
    cnzz.log('淘宝优惠券中间二维码', '曝光')
    $('.bjgou-mini-coupon-bar').on('mouseenter', function() {
      if (!showQRcode) {
        QRReloader.init(newData, url, '.bjgou-coupon-box > img', function(newData2) {
        }, false, false)
        cnzz.log('淘宝优惠券中间二维码', '悬浮')
        cnzz.log("track:coupon:qrcode:mini")
        util.tongjiLog("track:coupon:qrcode:mini")
        showQRcode = true;
      }
    })
  })

}
const renderMini2 = (data) => {
  if (data instanceof Array) {
    $(document).trigger('runyifenqian')
    return;
  }
  data = {
    'click_url': data.click_url2,
    'coupon': {
      'coupon_money': data.discount,
      'lastPrice': data.couponPricePC
    }
  }
  let views = template.compile(html)({
    data: data
  });
  $(`#bjgext_minibar`).append(views)
  if (!G.showMinibar) {
    $('#bjgext_minibar').css('display', 'inline-block')
    G.showMinibar = true;
  }
  cnzz.log('track:topcoupon_2:' + G.from_device)
  util.tongjiLog('track:topcoupon_2:' + G.from_device)
  $('#coupon_box').on('click', function() {
    cnzz.log('click:minicoupon_2:' + G.from_device)
    util.tongjiLog('click:minicoupon_2:' + G.from_device)
  })
}
const getCouponInfo = (callback) => {
  let dp_id = userData.get('dp_data').now.now_dp_id;
  let url = `https://browser.bijiago.com/app/quanbtc?dpid=${dp_id}`;
  request.get(url).done((data) => {
    callback(data)
  })
}

const render2 = (data) => {
  if (data.length instanceof Array || (!data.lt_short_link && !data.click_url)) {
    $(document).trigger('runyifenqian')
    return;
  }
  if (data.lt_short_link)
    data.click_url = data.lt_short_link;
  if (!data.couponPricePC) {
    data.couponPricePC = (Number(data.pcPrice) - Number(data.discount)).toFixed(2);
  }
  require('common/log')('coupon:show')
  renderMini2(data)
  renderTop2(data)
}


module.exports.init = (dom) => {
  let pIdObj = require('bjgou/modules/pidConfig')
  if (G.forbidCoupon) return;
  if ($('#BIJIA_HAS_BUILT').length > 0) return;
  let dp_id = G.dp.dpId;
  let adzoneItem = adzoneIdObj[G.union]
  if (!adzoneItem) {
    adzoneItem = adzoneIdObj['union_bijiago']
  }
  // let adzone_id = adzoneItem['adzone_id'];
  randomNum = parseInt(Math.random() * 100);
  let instanceId = window.bjgou_G.instanceId;
  require('common/coupon/getTbCouponValue')(dp_id).then(r => {
    if (instanceId !== window.bjgou_G.instanceId) return;
    renderMini(r)
    renderTop(r)
  })
  // getCoupon.init(dp_id, adzone_id, renderMini)
  // let adzone_id2 = adzoneItem['adzone_id2'];
  // getCoupon.init(dp_id, adzone_id2, renderTop)
  // let pid = pIdObj[G.union]
  // require('common/getCouponNew').init(pid, "mini", renderMini)
  // require('common/getCouponNew').init(pid, "bottom", renderTop)
}
module.exports.init2 = () => {
  getCouponInfo(render2)
}



