const parseprice = require('common/parseprice')
const template = require('vendor/template')
const request = require('common/request')
const util = require('./util')
const cnzz = require('common/cnzz')
let Time1, pagePrice, priceDom, pageSku

let pricePattern = {
  'amazon-com': [
    '#priceblock_dealprice span',
    '#priceblock_ourprice span .buyingPrice',
    '#priceblock_dealprice',
    '#priceblock_saleprice',
    '#priceblock_ourprice',
    '#price_feature_div .a-color-price',
    '#wineTotalPrice'
  ],
  'amazon-jp': [
    '#priceblock_dealprice span',
    '#priceblock_ourprice span .buyingPrice',
    '#priceblock_dealprice',
    '#priceblock_saleprice',
    '#priceblock_ourprice',
    '#price_feature_div .a-color-price',
    '#wineTotalPrice'
  ],
  '6pm': [
    'li[id="priceSlot"] div[class="price"]'
  ]
}
let feePattern = {
  'amazon-com': [
    '#priceBadging_feature_div .a-color-secondary',
    '#ourprice_shippingmessage .a-color-secondary'
  ],
  'amazon-jp': [
    '#priceBadging_feature_div .a-color-secondary',
    '#ourprice_shippingmessage .a-color-secondary'
  ],
  '6pm': [

  ]
}


const calPrice = (dp) => {
  dp.goods_original_price = Number((dp.goods_original_price / 100).toFixed(2))
  dp.goods_price = Number((dp.goods_price / 100).toFixed(2))
  dp.official_original_postage = Number((dp.official_original_postage / 100).toFixed(2))
  dp.official_postage = Number((dp.official_postage / 100).toFixed(2))
  dp.xm_official = dp.official_original_postage - dp.official_postage;
  dp.international_original_postage = Number((dp.international_original_postage / 100).toFixed(2))
  dp.international_postage = Number((dp.international_postage / 100).toFixed(2))
  dp.xm_international = dp.international_original_postage - dp.international_postage;
  dp.tax_original_fee = Number((dp.tax_original_fee / 100).toFixed(2))
  dp.tax_fee = Number((dp.tax_fee / 100).toFixed(2))
  dp.xm_fee = dp.tax_original_fee - dp.tax_fee
  dp.purePrice = dp.goods_price + dp.official_postage + dp.international_postage + dp.tax_fee;
  dp.purePrice = dp.purePrice.toFixed(2);
  dp.goods_price = dp.goods_price.toFixed(2);
  return dp;
}

const getSpec = () => {
  let color = $('#color+p').text();
  if (!color)
    color = $('#stage-swatches a.active').attr('title');
  let spec = {
    'color': color
  }
  return JSON.stringify(spec)
}
const getFee = () => {
  let domarr = feePattern[G.site]
  if (!domarr) return;
  for (let i = 0; i < domarr.length; i++) {
    let txt = $(domarr[i]).text()
    if (txt && txt.match(/\d+/)) {
      txt = parseprice.getPriceBeforeExchangeRate(txt)
      return txt;
    }
  }
  return 0;
}

const getPrice = () => {
  let domarr = pricePattern[G.site]
  if (!domarr) return;
  for (let i = 0; i < domarr.length; i++) {
    let txt = $(domarr[i]).text()
    if (txt && txt.match(/\d+/)) {
      txt = parseprice.getPriceBeforeExchangeRate(txt)
      return txt;
    }
  }
}
const getSku = () => {
  let sku = '';
  if (G.site.indexOf('amazon') > -1) {
    // sku = $('#bottomRow').text().match(/current_asin\"\:\"(\w+)\"/);
    sku = location.href.match(/\/dp\/(\w+)\//)
    sku = sku && sku[1];
    if (!sku)
      sku = $('#addToCart #ASIN').val()
  } else if (G.site === '6pm') {
    sku = $('span[id="sku"]').text().match(/\d+/)
    if (!sku) {
      sku = $('span[id="sku"]').text().match(/\d+/)
      sku = sku && sku[0]
    } else {
      sku = sku[0]
    }
  }

  return sku;
}
const isZiYing = () => {
  let dom = $('div[id="merchant-info"] a')
  if (dom.length === 0) {
    return 1;
  } else if (dom.length === 1) {
    if (dom.text().toLocaleLowerCase().indexOf('amazon') > -1)
      return 1;
    else
      return 2;
  } else if (dom.length === 2) {
    if (dom.eq(1).text().toLocaleLowerCase().indexOf('amazon') > -1)
      return 1;
    else
      return 2;
  } else {
    return 2;
  }
}
const isGoodProduct = (score, num, type) => {
  if (type == 1 && num >= 5 && score >= 3.5) {
    return true;
  }
  if (type == 2 && num >= 10 && score >= 4) {
    return true;
  }
  return false;
}
const addMark = (url) => {
  if (!url)
    return url;
  if (url.indexOf('?') > -1) {
    url = `${url}&p_r=gouwudang&p_k=plug_top_1&outer_pid=8507`;
  } else {
    url = `${url}?p_r=gouwudang&p_k=plug_top_1&outer_pid=8507`;
  }
  return url;
}
const buildJumpUrl = (dp) => {
  let url = `http://www.gwdang.com/promotion/haitaomid?url_crc=${dp.sku}&url=${encodeURIComponent(location.href)}&f_d=${G.from_device}`
  return url;
}

const getProductInfo = () => {
  let review_score = 0,
    review_number = 0
  if (G.site.indexOf('amzon') > -1) {
    review_score = $('div[id="averageCustomerReviews"] span[class="a-icon-alt"]').text().match(/^[0-9.]+/)
    review_score = review_score && review_score[0];
    review_number = $('div[id="averageCustomerReviews"] span[id="acrCustomerReviewText"]').text().match(/^\d+/);
    review_number = review_number && review_number[0]
  }
  let sku = getSku()
  pageSku = sku;
  let price = getPrice()
  pagePrice = price;
  let fee = getFee()
  let ziying = isZiYing()
  if (price)
    price = Number(price) + Number(fee);
  let goodP = isGoodProduct(review_score, review_number, ziying)
  return {
    price: price,
    sku: sku,
    review_score: review_score,
    review_number: review_number,
    goodP: goodP,
    ziying: ziying
  }
}

const getHtInfo = (obj, callback) => {
  let dp = G.dp;
  // if (!obj.price) {
  //   $('#bjgext_minibar').hide()
  //   $('#bjgext_mb_bg').hide()
  //   G.showMinibar = false;
  //   return;
  // }
  let price = (Number(obj.price) * 100);
  price = Number(price.toFixed(2))
  let str = '';
  if (G.site === '6pm')
    str = '&spec=' + getSpec()
  let url = `${G.server}/api/haitao?price=${price}&url_crc=${obj.sku}&url=${encodeURIComponent(location.href)}&review_number=${obj.review_number}&review_score=${obj.review_score}&sell_side=${obj.ziying}&priority=${obj.priority}${str}`
  request.get(url).done(function(data) {
    if (data && data.data.product_status === 1) {
      let dpinfo = data.data.product_detail;
      dpinfo.url = addMark(data.data.product_url)
      callback(dpinfo)
    } else if (data.data.product_status === 2) {
      let dpinfo = data.data.product_detail_estimate;
      if (!dpinfo) {
        $('#bjgext_minibar').hide()
        $('#bjgext_mb_bg').hide()
        return;
      }
      dpinfo.url = buildJumpUrl(dp)
      callback(dpinfo)
    } else {
      let tle = '';
      if (data.data.product_status === 4)
        tle = '抱歉，由于相关法律或者转运禁运的原因，该商品暂时不支持一键海淘'
      if (data.data.product_status === 5)
        tle = '抱歉，该商品已下架，暂时不支持一键海淘'
      if (data.data.product_status === 6)
        tle = '抱歉该商家口碑不好，不建议您购买'
      let dpinfo = {
        goods_price: parseprice(pagePrice),
        url: 'javascript:void();',
        type: data.data.product_status,
        tle: tle,
        noinfo: true
      }
      callback(dpinfo)
    }
  })
}
const specialFixed = () => {
  if (G.site.indexOf('amazon') > -1 && $('#actionPanelWrapper').length > 0) {
    $('.bjgext-mini-compare').remove()
    $('body').addClass('specailHack')
  }
}

const addEvent = () => {
  let logs
  $('#bjgext_htbtn').on('mouseenter', function() {
    $(this).find('.yjht-box').show()
    if (!logs) {
      cnzz.log('track:yjht:detail')
      util.tongjiLog('track:yjht:detail')
      logs = true;
    }
    $('#bjgext_minibar').addClass('_mshover')
  })
  $('#bjgext_htbtn').on('mouseleave', function() {
    $('#bjgext_htbtn .yjht-box').hide()
    $('#bjgext_minibar').removeClass('_mshover')
  })
  $('#bjgext_htbtn .yjht-box').on('mouseleave', function() {
    $(this).hide()
    $('#bjgext_minibar').removeClass('_mshover')
  })
  $('#bjgext_htbtn').on('click', function() {
    cnzz.log('click:yjht:title')
    util.tongjiLog('click:yjht:title')
  })
}

const renderBtn2 = (data) => {
  if (G.amazonGlobal) return;
  listenBody('off')
  if (!data.noinfo)
    data = calPrice(data)
  let html = require('art-template-loader!../views/yjhtBtn.html')
  $('#bjgext_htbtn').remove()
  $('.bjgext-mini-logo').after(template.compile(html)({
    data: data
  }))
  listenBody('on')
  if (!G.showMinibar) {
    $('#bjgext_minibar').css('display', 'inline-block')
    G.showMinibar = true;
  }
  G.showYjht = true;
  addEvent()
}


const mainRender = () => {
  let info = getProductInfo()
  if (info.goodP) {
    info.priority = 3;
    getHtInfo(info, renderBtn2)
  } else {
    info.priority = 1;
    getHtInfo(info, renderBtn2)
  }
}
const listenBody = (type) => {
  // 只有亚马逊需要监控价格变化
  if (type === 'on') {
    document.getElementById(priceDom).addEventListener('DOMSubtreeModified', func)
  } else if (type === 'off') {
    document.getElementById(priceDom).removeEventListener('DOMSubtreeModified', func)
  }
}
const func = function() {
  clearTimeout(Time1)
  Time1 = setTimeout(function() {
    if (pagePrice !== getPrice() || pageSku !== getSku()) {
      mainRender()
    }
  }, 500)
};

module.exports.init = () => {
  priceDom = 'unifiedPrice_feature_div'
  if ($(`#${priceDom}`).length === 0) {
    priceDom = 'price_feature_div';
  }
  if ($(`#${priceDom}`).length === 0) {
    priceDom = 'winePriceAndSavings_feature_div';
  }
  if (G.site === '6pm') {
    priceDom = 'priceSlot'
  }
  mainRender()
  specialFixed()
}


