<template>
  <button class="bjg-orange-button" :class="selected ? 'bjg-selected': ''" @click="$emit('click', $event)">
    <slot></slot>
  </button>
</template>
<style lang="less" scoped>
  .bjg-orange-button {
    width: 64px;
    height: 24px;
    background: #EBEBEB;
    border-radius: 12px;
    font-size: 14px;
    color: #666666;
    outline: none;
    box-shadow: none;
    box-sizing: border-box!important;
    border: none;
  }

  .bjg-selected {
    background: linear-gradient(134deg, #FD693A 0%, #FB9912 100%);
    color: #ffffff;
  }
</style>
<script>
  export default {
    props: ['selected']
  }
</script>



