<template>
  <a :href="href" :target="target" @click="onClick"><slot></slot></a>
</template>
<script>
  export default {
    props: ['href', 'target'],
    methods: {
      onClick() {
        if (G.site === 'suning') {
          if (this.target === '_blank') {
            window.open(this.href)
          } else {
            location.href = this.href
          }
        }
      }
    }
  }
</script>


