const request = require('common/request')
const globalCondition = require('common/globalCondition')
const PromotionPlan = require('common/components/PromotionPlan.vue').default

let load = async (dpId, skuId = null) => {
  let promo = await globalCondition.met('promoGot')
  let promoString = promo && promo.origin_promo ? '&origin_promo=' + encodeURIComponent(promo.origin_promo): ''
  let text = promo && promo.promo_text ? '&promo_text=' + promo.promo_text: '&promo_text=None'
  //let text = '&promo_text=none'
  let price = require('common/productInfo').productPattern[G.site]().price
  let data = await request.get(G.server + `/extension/PromotionPlan?price=${price}&dp_id=${dpId}${skuId ? '&sku_id=' + skuId: ''}${promoString}${text}`)
  let res = data.data
  let el = '#gwd-pp'
  if (G.from_device === 'bijiago' || G.from_device.indexOf('biyibi') > -1) {
    el = '#bjg-pp'
  }
  const plan = new Vue({
    el: el,
    render: h => h(PromotionPlan, {
      ref: 'plan',
      props: {
        data: res,
        tag: G.from_device === 'bijiago' ? 10: 3
      }
    })
  })
  if (res.length) {
    const single = res.find(item => item.plan.buy_count === 1 && item.plan.remain === 0)
    const multi = res.find(item => item.plan.buy_count > 1)
    const mul100 = x => parseInt(parseFloat(x) * 100)
    G._pp = `${single ? mul100(single.current_price): ''},${multi ? mul100(multi.current_price): ''}`
    if (single) {
      globalCondition.setMet('SinglePrice', single.current_price)
    }
  }
  $('.dsj-promo-link').hover(() => {
    plan.$refs.plan.over()
  })
}

module.exports = {
  async init() {
    let dp_id =  await globalCondition.met('GwdDpIdGot')

    load(dp_id, require('common/commonUtil').getParameterByName('skuId'))
    if (!G.on) return
    G.on('skuChange', function(skuId) {
      load(dp_id, skuId)
    })
  }
}



