const product = require('./product')
const request = require('common/request')
const util = require('./util')
// const loadCss = require('standard/module/loadCss')
const communicate = require('common/communicate')
const extConsole = require('common/extConsole')
const bgClient = require("../../common/background/bgClient");

const markPage = () => {
  $('html').addClass('bd_' + G.site);
  $('html').addClass(G.from_type)
}

const loadCss = () => {
  // if (G.from_device === 'biyibi') {
  //   return
  // }
  let chrom
  try {
    chrom = chrome;
  } catch (e) {
    chrom = null;
  }
  let url = '';
  if (chrom && chrom.extension && chrom.extension.getURL) {
    url = chrom.extension.getURL(`css/${G.cssname}`)
  } else {
    url = `${G.s_server}/css/brwext/${G.cssname}`
  }
  $(`head`).append(`<link type="text/css" href="${url}?v=${G.version}" rel="stylesheet" />`);
  setTimeout(() => {
    const hasGwd = $('html').hasClass('gwd_bottom') || window.disable_gwd_privacy;
    if (!hasGwd) {
      // $(`head`).append(`<link type="text/css" href="https://cdn.bijiago.com/css/brwext/gwdang-notifier-new6.css?v=${G.version}" rel="stylesheet" />`);
    }
  }, 300)
  // $(`head`).append(`<link type="text/css" href="https://cdn.bijiago.com/css/brwext/gwdang-notifier-new6.css?v=${G.version}" rel="stylesheet" />`);
}

const getConfigInfo = (callback) => {
  let runned = false
  setTimeout(() => {
    if (!runned) {
      G.show_minibar = '1';
      G.show_inner_low = '0'
      G.show_promo = '1'
      G.show_leftguess = '1'
      G.guess_fold = '0'
      G.main_fold = '1';
      G.lang = 'zh'
      console.log('bjgext start')
      callback()
    }
  }, 1000)
  communicate.on(data => {
    if (typeof data === 'string') {
      data = JSON.parse(data)
    }
    if (data.type === 'get_permanent' && (G.from_device === 'bijiago' || G.from_device === 'biyibi')) {
      if (data.value) {
        data = JSON.parse(data.value)
        G.show_minibar = data.show_minibar || '1';
        G.show_inner_low = data.show_inner_low || '0'
        G.show_promo = data.show_promo || '1'
        G.show_leftguess = data.show_leftguess || '1'
        G.guess_fold = data.guess_fold || '0'
        G.guid = data.guid || '';
        G.main_fold = data.main_fold || (G.from_device.includes('biyibi') ? '0': '1');
        // if in taiwan, set lang to zh-tr
        G.lang = data.lang || (navigator.language === 'zh-TW' ? 'zh-tr' : 'zh');
        if (G.from_device === 'biyibi') {
          G.lang = 'zh'
        }
      } else {
        G.show_minibar = '1';
        G.show_inner_low = '0'
        G.show_promo = '1'
        G.show_leftguess = '1'
        G.guess_fold = '0'
        G.main_fold = (G.from_device.includes('biyibi') ? '0': '1');
        G.lang = (navigator.language === 'zh-TW' ? 'zh-tr' : 'zh')

      }
      if (G.lang === 'zh-tr') {
        G.disableLogin = true
      }
      runned = true
      callback()
    } else if (data.type === 'get_local_img') {
      G.localImg = data.value
      if (G.aliSite) {
        G.loadImg = data.value + '120.gif';
        G.noImg = data.value + 'default_load_image.png';
      }
    } else if (data.type === 'user_extension_id') {
      G.userid = data.value
    } else if (data.type === 'getUnion' && data.value) {
      G.union = data.value
    }
  })
  communicate.trigger({
    'type': 'user_extension_id'
  })
  communicate.trigger({
    'type': 'get_permanent'
  })
  communicate.trigger({
    'type': 'get_local_img'
  })
  communicate.trigger({
    'type': 'getUnion',
    'value': 'bajbgcodue_fugnhijoknl'
  })



}

let urltimes = 0;
const listenUrlChange = () => {
  if (urltimes > 99999) return;
  urltimes++;
  let url = location.href;
  if (!window.bjgGlobalStart) {
    window.bjgGlobalStart = Date.now()
  }
  let k = setInterval(function() {
    if (url !== location.href || window.extNeedReload) {
      window.extNeedReload = false
      require('common/extConsole').log('ext reload start')
      if (!$('#bjgext_mainbar').length && G.pageInfo.type === 2) {
        url = location.href
        extConsole.warn('reload exit', G.pageInfo)
        return
      }
      if (Date.now() - window.bjgGlobalStart < 2000) {
        extConsole.warn('reload exit')
        url = location.href
        return
      }
      clearInterval(k)
      extConsole.log('begin reload ', {
        before: url,
        after: location.href
      })
      require('bjgou/modules/extReloader').init()
    } else {
      // require('common/extConsole').log('match')
    }
  }, 200);
}

module.exports.init = async () => {
  request.rawGet('https://cdn.bijiago.com/js/configs/gwdang.json?v=1').then(r => {
    require('common/globalCondition').setMet('GwdConfig', r)
  })
  require('standard/module/miniSameList').reset()
  var event = require('event')
  event(G);
  if (G.site === 'amazon')
    G.site = G.logsite;
  if (G.site === 'apple' || G.site === 'shopee' || G.site === 'taobao' || G.site === '6pm' || G.site.indexOf('amazon') > -1 || G.site.indexOf('tmall') > -1 || G.site.indexOf('lining') > -1) {
    listenUrlChange()
  }
  if (G.site === 'shopee') {
    await require('standard/module/util').waitForConditionFn(() => $('.product-briefing .flex span').text())
  }
  if (G.allowBackgroundRequest) {
    let installSource = await bgClient.get('/getStorage', {
      key: 'install_source'
    })
    if (installSource) {
      G.union = 'union_bijiago_' + installSource
    }
  }
  getConfigInfo(() => {
    util.tongjiLog('page_view')
    util.getPermanent(function() {
      // require('./quanlogo').init()
      util.tongjiLog('union_log:' + G.union)
      require('common/styleFix/siteCss').init()
      require('common/ad').init()
      if (G.pageInfo.type === 2) {
        util.tongjiLog('product_page_visit')
        if (G.aliSite) {
          require('common/getTaobaoTrend').init2()
          require('common/commonTaobaoUniqPid').init()
        }
        product.init()
        require('common/detail_coupon_tip').init()
        // if (G.ss_name !== 'priceDog') {
          require('common/copyTkl').init()
        // }
        markPage()
        loadCss()
        require('standard/module/jdMlink').init()
        require('common/getPromoInfo').init()
        require('standard/module/miniSameList').init()

        if (G.aliSite && !window.gwd_G) {
          require('standard/module/aliMobilePriceNotifier').init()
        }

        setTimeout(() => {
          if (!window.gwd_G) {
            require('common/jdPromoLinks').init()
          }
        }, 1000)

      } else if (G.pageInfo.type === 1) {
        markPage()
        require('common/extConsole').log('instanceId', G.instanceId)
        if (G.from_device === 'biyibi') {
          require('bjgou/style/biyibi.less')
        }
        // if (G.ss_name !== 'priceDog') {
          require('standard/module/priceTip').init()
        // }
        util.getDicts(function() {
          // 比价狗暂时去掉跳转
          // require('common/setForceInfo')()
        })
        let hosts = location.host;
        if (hosts.indexOf('taobao') > -1 || hosts.indexOf('tmall') > -1) {
          require('standard/module/searchCoupon').init()
        }
        if (hosts.includes('.jd.com')) {
          require('standard/module/searchCouponJd').init()
        }
        require('./houseTrend2').init()
        loadCss()
      }
    })

  })

  window.bjgou_G = G

}



