// 有时需要等待条件满足再执行

let metConditions = [];

let waitList = {};
let dataList = {};

module.exports = {
    met: function(condition, timeout = null, defaultValue = null) {
        return new Promise((resolve) => {
            if (metConditions.indexOf(condition) > -1) {
                resolve(dataList[condition])
            } else {
                if (waitList[condition]) {
                    waitList[condition].push(resolve)
                } else {
                    waitList[condition] = [resolve]
                }
                if (timeout) {
                    setTimeout(() => {
                        resolve(defaultValue)
                    }, timeout)
                }
            }
        })
    },
    clearAll() {
        metConditions = metConditions.filter(x => x === 'GwdConfig')
        waitList = {}
        dataList = {
            GwdConfig: dataList.GwdConfig
        }
    },
    clear: function(condition) {
        let idx = metConditions.indexOf(condition)
        if (idx > -1) {
            metConditions.splice(idx, 1)
            delete dataList[condition]
        }
    },
    setMet: function(condition, data = null) {
        if (metConditions.indexOf(condition) === -1) {
            metConditions.push(condition);
            dataList[condition] = data
        }
        if (waitList[condition]) {
            waitList[condition].forEach(x => x(data));
            waitList[condition] = []
        }
    }
};



