module.exports.getSymbol = name => {
  let v = Object.values(money)
  let tgt = v.filter(x => x[2] === name || x[1] === name)
  if (tgt.length) {
    return tgt[0]
  }
}

module.exports.getMoneyInfo = (site) => {
  if (countrys[site] && money[countrys[site]]) {
    return countrys[site] && money[countrys[site]]
  }
  return ['¥', '元', 'CNY'];
}


