module.exports.checkimg = (url, imgObj, size, callback) => {
  var sz = ((typeof size == 'undefined' || size == "" || size == null) ? 90 : size);
  var val = url;
  var img = new Image();
  if (G.browser.msie && G.browser.version < 11) {
    img.onreadystatechange = function() {
      if (img.readyState == "complete" || img.readyState == "loaded") {
        if (img.width > 0 && img.height > 0) {
          var rate = (sz / img.width < sz / img.height) ? sz / img.width : sz / img.height;
          if (rate <= 1) {
            imgObj.css('width', img.width * rate);
            imgObj.css('height', img.height * rate);
          } else {
            imgObj.css('width', img.width);
            imgObj.css('height', img.height);
          }
        }
        imgObj.attr('src', url);
      }
    }
  } else {
    img.onload = function() {
      if (img.complete == true) {
        if (img.width > 0 && img.height > 0) {
          var rate = (sz / img.width < sz / img.height) ? sz / img.width : sz / img.height;
          if (rate <= 1) {
            imgObj.css('width', img.width * rate);
            imgObj.css('height', img.height * rate);
          } else {
            imgObj.css('width', img.width);
            imgObj.css('height', img.height);
          }
        }
        imgObj.attr('src', url);
        if (callback) {
          callback();
        }
      }
    }
  }
  img.onerror = function() {
    imgObj.attr('src', G.s_server + "/images/extensions/default_load_image.png").css('width', 90);
    imgObj.attr('data-original', G.s_server + "/images/extensions/default_load_image.png");
  };
  img.src = val;
}

module.exports.getParameterByName = function(name, url) {
  if (!url) {
    url = window.location.href;
  }
  if (URL) {
    const params = (new URL(url)).searchParams
    return params.get(name)
  }
  name = name.replace(/[\[\]]/g, "\\$&");
  var regex = new RegExp("[?#&]" + name + "(=([^&#]*)|&|#|$)"),
    results = regex.exec(url);
  if (!results) return null;
  if (!results[2]) return '';
  return decodeURIComponent(results[2].replace(/\+/g, " "));
}

module.exports.sleep = function(time) {
  return new Promise(resolve => {
    setTimeout(() => resolve(), time)
  })
}

module.exports.asyncForEach = async function(array, callback) {
  for (let index = 0; index < array.length; index++) {
    await callback(array[index], index, array);
  }
}

module.exports.getPageCookie = () => {
  return document.cookie.split('; ').reduce((prev, current) => {
    const [name, ...value] = current.split('=')
    prev[name] = value.join('=')
    return prev
  }, {})
}

// 通用数组去重
module.exports.arrayUnique = (arr, valueFn) => {
  let list = []
  return arr.filter(x => {
    let val = valueFn(x)
    if (list.indexOf(val) === -1) {
      list.push(val)
      return true
    }
    return false
  })
}

module.exports.appendCss = cssText => {
  let s = document.createElement('STYLE')
  s.innerHTML = cssText
  document.body.appendChild(s)
}

module.exports.debounce = (func, timeout = 300) => {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => { func.apply(this, args); }, timeout);
  };
}

module.exports.throttle = (func, timeout = 300) => {
  let timer;
  return (...args) => {
    if (!timer) {
      timer = setTimeout(() => { timer = null; func.apply(this, args); }, timeout);
    }
  };
}

module.exports.limit = (func, timeout = 300) => {
  let lastExecTime = 0;
  return (...args) => {
    let now = Date.now();
    if (now - lastExecTime > timeout) {
      lastExecTime = now;
      func.apply(this, args);
    }
  };
}

module.exports.arrayToObj = (array, key) => {
  let obj = {}
  array.forEach(item => {
    obj[item[key]] = item
  })
  return obj
}

module.exports.getBodyOffset = (el) => {
  if (typeof el === 'string') {
    el = document.querySelector(el)
  }
  el.style.display = 'block'
  const rect = el.getBoundingClientRect()
  return {
      left: rect.left + window.scrollX,
      top: rect.top + window.scrollY,
      width: el.clientWidth,
      height: rect.height
  }
}

module.exports.findStringFromSelectors = (selectors) => {
  for (let i = 0; i < selectors.length; i++) {
    if (document.querySelector(selectors[i])) {
      return document.querySelector(selectors[i]).innerText
    }
  }
}



