let sitearr = ['360buy', 'suning', 'gome', 'yihaodian', 'dangdang', 'kaola', 'tmall'];
const inventoryCheck = require("common/inventoryCheck");
const log = require('common/log')
const userData = require('common/userData')
// const request = require('common/request')

const promosPattern = {
  'tmall': () => {
    let promo = $('.tm-shopPromo-panel').text().trim()
    if (!promo) {
      promo = $('[class^=Promotion--caption]').text().trim()
    }
    if (!promo) {
      promo = $('.contentWrap--eIMKdlQ7 > .couponInfo--DRQjTMKl [class^=couponText--]').toArray().map(x => x.innerText).join(',')
    }
    return {
      promo: promo
    }
  },
  '360buy': () => {
    let tle1 = $('.J-more-prom-ins').text();
    let tle2 = $('.J-prom em.hl_red_bg').text();
    let price = $('.J-summary-price .p-price').text().replace(/[￥¥\s]+/g, '')
    let arr = []
    if (tle1.indexOf('满减') > -1 || tle2.indexOf('满减') > -1) {
      arr.push('满减:' + $('.J-prom em.hl_red_bg:contains("满减") + em.hl_red').text())
    }
    if (tle1.indexOf('多买优惠') > -1 || tle2.indexOf('多买优惠') > -1) {
      arr.push('多买优惠:' + $('.J-prom em.hl_red_bg:contains("多买优惠") + em.hl_red').text())
    }
    if (tle1.indexOf('满折') > -1 || tle2.indexOf('折') > -1) {
      arr.push('满折:' + $('.J-prom em.hl_red_bg:contains("满折") + em.hl_red').text())
    }
    if ($('#summary-quan .quan-item').text().length > 0) {
      let text = Array.prototype.map.call($('#summary-quan .quan-item'), function(v) {
        return $(v).text().replace(/\s/g, '');
      }).join(',')
      arr.push('领券:' + text)
    }
    return {
      price: price,
      promo: arr.join(';')
    }
  },
  'suning': () => {
    let dom = $('#voucherTitle')
    let labels = dom.find('label').text().replace(/\s/g, '')
    let text = ''
    let arr = []
    if (labels.indexOf('满减') > -1 && dom.is(':visible')) {
      text = $('#voucherBox').text()
      let smtxt = $('#voucherBox a').text()
      text = '满减:' + text.replace(smtxt, '');
      arr.push(text)
    }
    if ($('#getCoupon').length > 0 && $('#getCoupon').is(':visible')) {
      let text2 = Array.prototype.map.call(document.querySelectorAll('#freeCouponBox .p-quan2 .p-quan-white'), function(e) {
        return $(e).text()
      }).join(",")
      if (text2) {
        text2 = "领券:" + text2;
        arr.push(text2)
      }
    }
    return {
      promo: arr.join(";")
    }
  },
  'gome': () => {
    let dom = $('.prd-promotions-red')
    let labels = dom.find('label').text()
    let texts = [];
    if (dom.is(':visible') && labels.indexOf('满减') > -1) {
      texts.push('满减:' + $('.prd-promotions-red label:contains("满减")+span').text().replace(/\s/g, ''))
    }
    if (dom.is(':visible') && labels.indexOf('领劵') > -1) {
      texts.push('领券:' + $('.prd-promotions-red label:contains("领劵")+b').text().replace(/(?:左边|右边)/g, '').replace(/劵/g, '券'))
    }
    if ($('.prd-price-left').is(':visible') && $('.prd-price-left').text().indexOf('劵') > -1) {
      let arr = $('#lanjuan b').text().match(/满\d+减\d+/g);
      if (arr.length > 0) {
        texts.push('领券：' + arr.join(','))
      }
    }
    return {
      promo: texts.join(';')
    }
  },
  'yihaodian': () => {
    let dom = $('#promotion_title')
    let arr = []
    let labels = dom.find('.list .fl span.sub').text();
    if (labels.indexOf('满减') > -1 && dom.find('.list .fl span.sub').is(':visible')) {
      let text = "满减" + $('#promotion_title .list .fl span.sub:contains("满减")+ span.tit').text()
      arr.push(text)
    }
    if (labels.indexOf('折扣') > -1 && dom.find('.list .fl span.sub').is(':visible')) {
      let text = "折扣" + $('#promotion_title .list .fl span.sub:contains("折扣")+ span.tit').text()
      arr.push(text)
    }

    return {
      promo: arr.join(';')
    }
  },
  'dangdang': () => {
    let dom = $('#promo-list')
    let arr = []
    if (dom.find('div.clearfix b:contains("满额减")').is(':visible')) {
      let txt = '满额减:' + $('#promo-list div.clearfix b:contains("满额减")+div.rule span').text()
      arr.push(txt)
    }
    if (dom.find('div.clearfix b:contains("店铺促销")').is(':visible')) {
      let txt = '店铺促销:' + $('#promo-list div.clearfix b:contains("店铺促销")+div.rule span').text()
      arr.push(txt)
    }
    return {
      promo: arr.join(';')
    }
  },
  'kaola': () => {
    let arr = []
    if ($('.promotionwrap .m-zd-prt .m-dp-prt-title:contains("满额减")').is(':visible')) {
      let text = '满额减:' + $('.promotionwrap .m-zd-prt .m-dp-prt-title:contains("满额减")+span a').text()
      arr.push(text)
    }
    if ($('.couponwrap').is(':visible')) {
      let text2 = '领券:' + Array.prototype.map.call(document.querySelectorAll('.couponwrap .li.ellipsis'), function(e) {
        return $(e).text()
      }).join(",")
      arr.push(text2)
    }
    return {
      promo: arr.join(';')
    }
  }
}
const getJdPromoInfo = () => {
  let promos = []
  let dom = $('#prom-one .J-prom .prom-item');
  let dom2 = $('#prom-quan .J-prom-quan')
  if (dom.length > 0) {
    for (let i = 0; i < dom.length; i++) {
      if (dom.eq(i).find('a').text().indexOf('详情') > -1) {
        let tle = dom.eq(i).find('.hl_red').text()
        let url = dom.eq(i).find('a').attr('href')
        promos.push(encodeURIComponent(tle) + ',' + encodeURIComponent(url));
      }
    }
  }
  if (dom2.length > 0) {
    for (let i = 0; i < dom2.length; i++) {
      if (dom2.eq(i).find('a').text().indexOf('详情') > -1) {
        let tle = dom2.eq(i).find('.hl_red').text()
        let url = dom2.eq(i).find('a').attr('href')
        promos.push(encodeURIComponent(tle) + ',' + encodeURIComponent(url));
      }
    }
  }
  return promos.join(';');
}

const getPromoInfo = (inventory) => {
  let dp = G.dp;
  let other_info = userData.get('other_info');
  let promoinfo = promosPattern[G.site]();
  let price = other_info['code-server'].price || dp.price
  if (!price)
    price = promoinfo.price;
  let info = {
    dp_id: other_info.now.dp_id,
    name: dp.name,
    price: price,
    promo: promoinfo.promo,
    stock: inventory
  }
  return info;
}
const getJdPromo = (inventory, callback) => {
  let dp = G.dp;
  let other_info = userData.get('other_info');
  let price = other_info['code-server'].price || dp.price
  let promoinfo = promosPattern[G.site]();
  if (!price)
    price = $('.J-summary-price .p-price').text().replace(/[￥¥\s]+/g, '')
  let promo_info = getJdPromoInfo()
  let zytxt = $('.name.goodshop.EDropdown').text();
  let isZy = '0'
  if (zytxt.indexOf('自营') > -1) {
    isZy = '1';
  }
  if (!dp.fans_price)
    dp.fans_price = $('.fans-price .p-price-fans span').text().replace(/[￥¥]+/, '');
  let info = {
    dp_id: other_info.now.dp_id,
    name: dp.name.trim(),
    price: price,
    promo: promoinfo.promo,
    promo_info: promo_info,
    plus_price: dp.plus_price,
    fans_price: dp.fans_price,
    isZy: isZy,
    stock: inventory
    // cat: cat,
    // venderId: vendorId,
    // noquan: noquan
  }
  info = JSON.stringify(info)
  callback(info)
}

const specialFilter = () => {
  if (G.site === 'suning') {
    if ($('#timePanel span').text().indexOf('定金团') > -1 && $('#mainPrice .price-promo span').text().indexOf('定金') > -1) {
      return true;
    }
  }
  if (G.site === '360buy') {
    if ($('#pingou .summary-price').text().indexOf('定金') > -1) {
      return true;
    }
  }
  return false;
}

const sendPromo = (info) => {
  if (window.XMLHttpRequest) {
    try {
      let xml = new XMLHttpRequest()
      xml.open('POST', `${G.server}/extension?ac=sendPromos&site_id=${G.site_id}&jfrom=int`)
      xml.send(info);
      log('sendPromo_success');
    } catch (e) {}
  }
}
module.exports.init = () => {
  if (G.new_extension || G.btype == 'luyou') return;
  if (G.dp.activePrice) return;
  if (specialFilter()) return;
  try {
    let inventory = inventoryCheck.init(G.site);
    if (sitearr.indexOf(G.site) > -1) {
      if (G.site == '360buy') {
        getJdPromo(inventory, sendPromo)
      } else {
        let info = getPromoInfo(inventory);
        info = JSON.stringify(info)
        sendPromo(info)
      }
    }
  } catch (e) {}
}
module.exports.specialFilter = specialFilter;


