const getQRCode = require('common/coupon/getQRCode')

module.exports = {
  data() {
    return {
      qrcode: '',
      error: false,
      logged: false,
      loading: false,
      site: location.hostname.indexOf('.jd.com') > -1 ? 'jd': 'taobao',
      payload: {}
    }
  },
  methods: {
    goLink() {
      if (this.qr) return
      require('common/cnzz').log(this.site + 'GiftMoney:click')
      if (this.url) {
        window.open(this.url)
      }
    },
    over() {
      if (!this.qr) return
      if (this.qrcode) return
      if (this.loading) return
      this.loading = true
      let payload = {
        id: G && G.dp ? G.dp.itemId: this.id,
        amount: this.value,
        title: '',
        _type: 'rebate'
      }
      if (this.price) {
        payload.price = this.price
        payload.tip = this.price
      }
      if (this.tag) {
        payload._tag = this.tag
      }
      this.payload = payload
      getQRCode(payload, '', res => {
        if (res[0].etag) {
          this.error = true
          return
        } else {
          this.error = false
        }
        this.qrcode = res[0].imgSrc
        if (!this.logged) {
          require('common/cnzz').log(this.site + 'GiftMoney:hover')
          require('common/cnzz').log(this.site + 'GiftMoney:-hover')
          if (this.oldPatch) {
            require('common/cnzz').log(this.site + 'GiftMoney:hover-oldPatch')
          }
          this.logged = true
        }
      })
    }
  }
}


