var pako = require('pako');
module.exports.gZip = (str) => {
  return pako.gzip(JSON.stringify(str));
}
module.exports.unGzip = (str) => {
  let z = pako.ungzip(str);
  const decoder = new TextDecoder('utf8');
  return JSON.parse(decoder.decode(z));
}




