let userData = require('common/userData')
let request = require('common/request')
const countryConfig = require('common/countryConfig')
let communicate = require('common/communicate')
let globalCurrency = {}

let unitConfig = [{
  unitName: '千',
  times: 1000
}, {
  unitName: '万',
  times: 10000
}];
let unit = 1;

let getPriceBeforeExchangeRate = (price, type) => {
  if (!price) return;
  price = price.toString();
  unit = 1;
  if (Array.prototype.forEach) {
    unitConfig.forEach((i) => {
      if (price.indexOf(i.unitName) > -1) {
        unit = i.times;
      }
    });
  }
  price = price.replace(/^[^\d]+/ig, '');
  price = price.replace(/[￥\$]/ig, '');
  price = price.match(/[0-9.,]+/) && price.match(/[0-9.,]+/)[0]
  if (!price) return price;
  price = priceFormat(price, type)
  price = price.replace(/,/ig, '');
  price = $.trim(price);
  var range_left = price.indexOf('-');
  if (range_left > 0) {
    price = price.substr(0, range_left);
  }
  //修正价格提取出现的小数部分不准确问题（如一号店）
  price = price.replace(/^(\d+\.)\<.+\>(\d{0,2})\<\/.+\>/ig, "$1$2");
  return price;
};

module.exports = (price, type) => {
  price = getPriceBeforeExchangeRate(price, type);
  //fix end
  price = exchangeRate(price, type)
  if (parseFloat(price) > 0) {
    price = parseFloat(price);
    if (unit) price = price * unit;
    return price
  } else return 0
}

module.exports.getPriceBeforeExchangeRate = getPriceBeforeExchangeRate;

let exchangeRate = (price, type) => {
  let exRate;
  if (type) {
    exRate = globalCurrency[type] || 1;
  } else {
    exRate = userData.get('currency') || G.currency || 1;
  }
  return parseFloat((Number(price) * exRate).toFixed(2));
}

let priceFormat = (price, type) => {
  if (type) return price;
  if (G.pageInfo.type == 1) return price;
  let host = location.host;
  let euroAmazonConfig = {
    'www.amazon.de': 'prime',
    'www.amazon.fr': 'premium'
  };
  if (euroAmazonConfig[host] && $('#nav-logo .nav-logo-tagline').text().replace(/\s/g, '').trim().toLowerCase().indexOf(euroAmazonConfig[host]) > -1)
    price = price.replace('.', '').replace(',', '.');
  return price;
}
let storeRate = (currency) => {
  communicate.trigger({
    type: 'setStoreRate',
    info: JSON.stringify(currency)
  })
}
let getStoreRate = () => {
  communicate.on((info) => {
    if (info && info.type == 'getStoreRate') {
      try {
        var currency = info.value.currency;
        var newInfo = JSON.parse(currency)
        globalCurrency = newInfo.elsecurr
        G.currency = newInfo.currency;
      } catch (e) {}
    }
  })
  communicate.trigger({
    type: 'getStoreRate'
  })
}
let readyGet = () => {
  if (location.host === 'www.amazon.cn') return;
  if (location.host.indexOf('amazon') > -1 || location.host.indexOf('6pm') > -1) {
    getStoreRate()
  }
}
readyGet()

module.exports.getExRate = (type) => parseFloat(globalCurrency[type] | 1);

module.exports.getRate = (callback) => {
  require('common/extConsole').log('getRate')
  let site = G.logsite;
  let moneyInfo = countryConfig.getMoneyInfo(site)
  if (moneyInfo) {
    let url = `${G.server}/extension?ac=currency&url=${encodeURIComponent(location.href)}`;
    request.get(url).then((data) => {
      if (data && data.currency) {
        userData.set('currency', data.currency);
        globalCurrency = data.elsecurr;
        G.currency = data.currency;
        storeRate(data)
      }
      callback()
    }).catch(() => {
      callback()
    })
  } else {
    callback()
  }

}



