      <div class="third-login">
        <span @click="goLink('wechat')" :target="position === 'gwd-popup' ? '_blank': ''" class="weixinlogin  gwd_bg loginBox"></span>
        <span @click="goLink('qq')" :target="position === 'gwd-popup' ? '_blank': ''" class="qqlogin gwd_bg loginBox"></span>
        <span @click="goLink('weibo')" :target="position === 'gwd-popup' ? '_blank': ''" class="sinalogin  gwd_bg loginBox"></span>
