const request = require('common/request')
const productInfo = require('common/productInfo')

module.exports = async dpId => {
  if (G.site === 'taobao') {
    await Promise.race([
      require('standard/module/util').waitForConditionFn(() => $('.shop-name-link').length),
      require('common/commonUtil').sleep(2000)
    ])
  }
  const link = productInfo.appendTbInfoForUrl(`${G.u_server}/gyp/taobao/coupon?dp_id=${dpId}&scene=item2&rebate=1&slist=1`)
  const res = await request.get(link)
  let toReturn = {
    code: 200
  }
  if (res.data && res.data.coupon) {
    toReturn.data = {
      coupon: {
        coupon_money: res.data.coupon.split('减')[1].replace('元', ''),
      }
    }
    if (res.data.rebate) {
      toReturn.data.rebate = res.data.rebate
      toReturn.data.utoken = res.data.utoken
    }
  } else {
    toReturn.code = 500
    toReturn.msg = '获取优惠券失败'
    if (res.data && res.data.rebate) {
      G.dp.rebate = res.data.rebate
    } else {
      if (res.data && res.data.slist) {
        G.dp.slist = res.data.slist
      } else {
        G.dp.slist = []
      }
      require('common/globalCondition').setMet('dpSlist', G.dp.slist)
    }
  }
  return toReturn
}



