let communicate = require('common/communicate')
let globalObj, callbacks = [];
let hascallback;
let init = () => {
  let nowurl = location.href;
  let itemId = nowurl.match(/[?&]id=([0-9]+)/) && nowurl.match(/[?&]id=([0-9]+)/)[1];
  if (!itemId) return;
  let website = (G.dp && G.dp.site) || G.site;
  if (website.indexOf('95095') > -1) {
    globalObj = {
      'nodata': true
    };
    return;
  }
  if (website == 'ai-taobao')
    website = 'taobao'
  // let price = Number(G.dp.price)*100;
  // let url = 'https://browserre.taotaosou.com/priceHistory.do?itemId='+ itemId + '&website=' + website + '&price=' + price.toString();
  let url = require('getTrendParam').init()
  communicate.trigger({
    'type': 'getTaobaoTrend',
    'info': url
  })
  communicate.on(data => {
    if (typeof data === 'string') {
      data = JSON.parse(data)
    }
    if (data.type == 'getTaobaoTrend') {
      if (data.value)
        try {
          globalObj = JSON.parse(data.value).priceHistoryData
          if (!globalObj) globalObj = {
            'nodata': true
          };
          if (callbacks.length > 0 && !hascallback) {
            //hascallback = true; // debug
            for (var i = 0; i < callbacks.length; i++) {
              callbacks[i](globalObj)
            }
            hascallback = true;
          }

        } catch (e) {}
    }
  })

}

module.exports._init = () => {
  // G.on('pageType=2', () => {
  //   init()
  // })
}
module.exports.init2 = () => {
  // init()
}
module.exports.getTrend = (callback) => {
  if (globalObj) {
    if (globalObj['nodata']) globalObj = null;
    hascallback = true;
    callback(globalObj)
    return;
  } else {
    callbacks.push(callback);
  }
  setTimeout(function() {
    if (!hascallback) {
      hascallback = true;
      callback(null);
    }
  }, 3000)
}


