<template>
  <div class="bjgou-mini-favor">
    <img :src="productChecked ? checked: clock" alt="" :style="productChecked ? 'margin-top: -3px;': ''">
    <span :style="productChecked ? 'margin-left: 9px;': 'margin-left: 3px;'" class="bjg-down">{{ productChecked ? '降价提醒': '降价提醒' }}</span>
    <div class="bjgou-qr" v-if="login">
      <span @click="favorClick" :class="'bjgou-set ' + (productChecked ? '': 'bjgou-unset')">{{ productChecked ? '取消提醒': '设置提醒' }}</span>
      <img src="https://cdn.bijiago.com/images/extensions/bijiago/bjgou-qr-wechat-small.png" alt="" style="width: 96px; height: 96px; margin-top: 18px; image-rendering: crisp-edges">
      <span style="margin-top: 6px; color: #ffae45; font-size: 14px; line-height: 22px; font-weight: bold">关注公众号</span>
      <span style="margin-top: 2px; color: #6b6761; font-size: 12px; line-height: 17px">商品降价实时提醒</span>
    </div>
    <div class="bjgou-login" v-if="!login">
      <button @click="goLogin()">登录</button>
      <span>商品降价实时提醒</span>
    </div>
  </div>
</template>
<style lang="less" scoped>
  .bjgou-set {
    display: block;
    color: #ffae45;
    width: 90px;
    height: 24px;
    border-radius: 14px;
    border: 1px solid #ffae45;
    font-size: 12px;
    margin-top: 24px;
    text-align: center;
    line-height: 24px;
  }

  .bjgou-unset {
    color: white;
    background: #ffae45;
  }

  .bjgou-mini-favor {
    flex: 1;
    position: relative;
    min-width: 133px;
    border: 1px solid #e6e9eb;
    border-top-right-radius: 5px;
    border-left: none;
    align-items: center;
    cursor: pointer;
    justify-content: center;
    display: flex;
    .bjg-down {
      color: #6b6761;
      font-size: 14px;
    }
    .bjgou-qr {
      position: absolute;
      top: 36px;
      right: -1px;
      width: 182px;
      height: 231px;
      background: white!important;
      /*box-shadow:0px 2px 4px 0px rgba(226,226,226,1);*/
      border:1px solid rgba(230,233,235,1);
      flex-direction: column;
      align-items: center;
      display: none;
      z-index: 99;
    }
    .bjgou-login {
      position: absolute;
      top: 36px;
      right: -1px;
      width: 293px;
      height: 88px;
      background: white!important;
      border:1px solid rgba(230,233,235,1);
      flex-direction: column;
      align-items: center;
      display: none;
      z-index: 99;
      button {
        margin-top: 21px;
        width: 228px;
        height: 28px;
        background: linear-gradient(270deg,rgba(255,205,71,1) 0%,rgba(255,159,34,1) 100%);
        border-radius: 16px;
        color: white;
        font-size: 12px;
        border: none!important;
        outline: none;
      }
      span {
        margin-top: 6px;
        color: #8c847b;
        font-size: 12px;
      }
    }
  }

  .bjgou-mini-favor:hover {
    background: #fffbef;
    .bjgou-login {
      display: flex;
    }
    .bjgou-qr {
      display: flex;
    }
  }
</style>
<script>
  const user = require('../modules/user')
  const globalCondition = require('common/globalCondition')

  export default {
    name: "MiniFavor.vue",
    data() {
      return {
        productChecked: G.productChecked,
        clock: require('../assets/clock.svg'),
        checked: require('../assets/checked.svg'),
        qr: G.qr,
        login: G.userLogin
      }
    },
    methods: {
      async checkCollected() {
        let dpId = await globalCondition.met('GwdDpIdGot')
        let token = await user.hasUserToken()
        if (!token) {
          G.userLogin = false
          this.login = false
          G.trigger('bjgouFavor')
          return
        }
        G.userLogin = true
        this.login = true
        user.checked(dpId).then(res => {
          if (res.code === -3) {
            G.userLogin = false
            this.login = false
            G.trigger('bjgouFavor')
            return
          }
          if (res.code === 0) {
            this.productChecked = false
            G.productChecked = false
            G.trigger('bjgouFavor')
            return
          }
          this.productChecked = res.data.id
          G.productChecked = res.data.id
          G.trigger('bjgouFavor')
          // G.productChecked = res.data
        })
      },
      async favorClick() {
        let dpId = await globalCondition.met('GwdDpIdGot')
        if (!this.productChecked) {
          let res = await user.collect(dpId)
          console.log(res)
          if (res.code === 1) {
            this.productChecked = res.data.id
            G.productChecked = res.data.id
          }
        } else {
          let res = await user.del(this.productChecked)
          console.log(res)
          if (res.code === 1) {
            this.productChecked = false
            G.productChecked = false
          }
        }
        G.trigger('bjgouFavor')
      },
      goLogin() {
        //location.href = `https://i.bijiago.com/UserUnion/Authorize?utype=2&app_platform=ext&_referer=${encodeURIComponent(location.href)}`
        user.goLogin()
      }
    },
    mounted() {
      this.checkCollected()
      G.on('bjgouFavor', () => {
        this.productChecked = G.productChecked
        this.login = G.userLogin
      })
    }
  }
</script>


