<template>
  <div class="gwd-column gwd-align bjg-item" :style="line ? 'border-top: 1px solid #f1f1f1': ''">
    <div class="gwd-row bjg-dp-item" @click="goLink">
      <img
          :src="product.img"
          onerror="this.src='https://cdn.bijiago.com/images/extensions/default_load_image.png'"
          alt=""
          style="width: 100px; height: 100px; margin-right: 10px; margin-left: 14px;" :class="outdated ? 'bjg-op': ''">
      <div class="gwd-column" style="flex: 1">
        <span class="title" :style="outdated ? 'color: #8c847b': ''">{{ product.title }}</span>
        <div style="margin-top: 16px" v-if="product.inTime">
          <span class="bjg-price-text">订单价: {{ (product.price / 100).toFixed(2) }}</span>
        </div>
        <div style="flex: 1"></div>
        <div class="gwd-row">
          <span class="bjg-price-text" style="flex: 1" v-if="product.inTime">现&nbsp;&nbsp;&nbsp;价: {{ (product.currentPrice ? product.currentPrice / 100: (product.price / 100)).toFixed(2) }}</span>
          <span class="bjg-price-text" style="flex: 1" v-if="!product.inTime">订单价: {{ (product.price / 100).toFixed(2) }}</span>
          <span class="bjg-price-text" style="flex: 1">下单时间: {{ product.ctime.substr(0, 10).replace(/-/g, '.') }}</span>
        </div>
      </div>
    </div>
    <div v-if="product.errorText" style="width: 372px;">
      <span style="font-size: 12px; color: #333333; transform: scale(0.9166); transform-origin: top left; display: block; margin-top: 12px;">{{ product.errorText }}</span>
    </div>
    <div v-if="product.currentPrice < product.price && !outdated" class="bjg-tip">
      <span style="position: relative; top: 4px;">可申请价格保护，预估：{{ ((product.price - product.currentPrice) / 100).toFixed(2) }}元/件 ></span>
    </div>
  </div>
</template>
<style scoped lang="less">
  .bjg-op {
    filter: opacity(0.5);
  }

  .bjg-item {
    padding-top: 14px;
    padding-bottom: 14px;
  }
  .bjg-tip {
    width: 372px;
    height: 24px;
    background: url("../assets/tip.svg");
    text-align: center;
    margin-top: 6px;
    span {
      font-size: 12px;
      color: #ffffff;
      margin-top: 5px;
    }
  }
  .bjg-dp-item {
    height: 100px;
    margin-right: 10px;
    .title {
      width: 259px;
      height: 40px;
      font-size: 13px;
      color: #333333;
      line-height: 20px;
      overflow: hidden;
      text-overflow: ellipsis;
      display: block;
    }
    .bjg-price-text {
      font-size: 12px;
      color: #8c847b;
    }
  }
</style>
<script>
  export default {
    props: ['product', 'line', 'outdated'],
    methods: {
      goLink() {
        window.open('https://pcsitepp-fm.jd.com/')
      }
    }
  }
</script>


