<template>
  <div class="gwd-row gwd-align pricedog-bottom-tab close-models">
    <img src="../assets/gear_yellow.svg" alt="" style="width: 16px;">
    <span style="margin-left: 8px;">{{ lang === 'zh-tr' ? '設置': '设置' }}</span>
    <div class="pricedog-setting gwd-column">
      <span>{{ lang === 'zh-tr' ? '語言': '语言' }}</span>
      <div class="gwd-option gwd-row gwd-align" @click="setLang('zh')">
        <img :src="selected === 'zh' ? checked: unChecked" alt="">
        <span style="margin-left: 4px">简体中文</span>
      </div>
      <div class="gwd-option gwd-row gwd-align" @click="setLang('zh-tr')">
        <img :src="selected === 'zh-tr' ? checked: unChecked" alt="">
        <span style="margin-left: 4px">繁體中文</span>
      </div>
    </div>
  </div>
</template>
<style scoped lang="less">
  .pricedog-bottom-tab {
    justify-content: center;
    width: 90px;
    height: 60px;
    border-left: 1px solid #f1f1f1;
    position: relative;
    cursor: default;
    span {
      font-size: 14px;
      color: #64615d;
    }
  }

  .pricedog-setting {
    display: none;
    width: 94px;
    height: 93px;
    background: #FFFFFF;
    border: 1px solid #F1F1F1;
    position: absolute;
    bottom: 60px;
    box-sizing: border-box;
    left: -1px;
    padding-left: 10px;
    padding-top: 8px;
    span {
      font-size: 12px;
      color: #64615d;
    }
    .gwd-option {
      margin-top: 16px;
      img {
        width: 12px;
      }
    }
  }

  .pricedog-bottom-tab:hover {
    background: #fffbef;
    .pricedog-setting {
      display: block;
    }
  }
</style>
<script>
  export default {
    data() {
      return {
        lang: G.lang,
        selected: G.lang,
        checked: require('../assets/radio-checked@2x.png'),
        unChecked: require('../assets/radio-unchecked@2x.png')
      }
    },
    methods: {
      setLang(lang) {
        this.selected = lang
        require('../modules/util').settings('lang', lang)
        setTimeout(() => {
          location.reload()
        }, 0)
      }
    }
  }
</script>



