export default {
  data() {
    return {
      positionStyle: 'left: 0'
    }
  },
  mounted() {
    this.$el.parentElement.addEventListener('DOMSubtreeModified', () => {
      if (window.innerWidth - this.$el.offsetLeft <= 564) {
        this.positionStyle = 'right: -1'
      }
    })
  }
}


