import AliMobilePriceNotifier from './components/AliMobilePriceNotifier.vue'
import log from 'common/log'

let appNode, observer

const minAllowedWidth = 280

const getMiniPriceWidth = (originPriceSelector, extraPriceSelector) => {
  const originPriceEl = $(originPriceSelector)[0]
  const extraPriceEl = $(extraPriceSelector)[0]
  let totalWidth = 0
  if (originPriceEl) {
    totalWidth += originPriceEl.offsetWidth
  }
  if (extraPriceEl) {
    totalWidth += extraPriceEl.offsetWidth
  }
  return totalWidth
}

let hide = false

module.exports = {
  async init() {
    hide = false
    if (!G.aliSite) {
      return
    }
    if (observer) {
      observer.disconnect()
    }
    if (appNode) {
      appNode.remove()
    }
    let nowPrice = await require('common/globalCondition').met('NowPrice')
    const pagePrice = G.dp.onPagePrice || G.dp.price

    if (G.dp.mobilePrice) {
      nowPrice = G.dp.mobilePrice
    }

    const selectorConfig = await require('common/aliPriceSelector').get()

    const originPriceEl = $(selectorConfig.priceOrigin)[0]
    const extraPriceEl = $(selectorConfig.priceExtra)[0]
    let totalWidth = 0
    if (originPriceEl) {
      totalWidth += originPriceEl.offsetWidth
    }
    if (extraPriceEl) {
      totalWidth += extraPriceEl.offsetWidth
    }
    
    if (totalWidth >= 265) {
      return
    }

    let needHideWhenScrollDown = false
    if (totalWidth >= 230 && false) {
      // change this when ui version older than 0.2.49
      needHideWhenScrollDown = true
    }

    const div = document.createElement('div')
    div.id = 'gwd_mobile_price_notifier'

    let priceRootEl = $(selectorConfig.priceRoot)[0]

    if (window.tbOwnQr) {
      return
    }

    if (priceRootEl && (priceRootEl.innerHTML.includes('前往手淘查看更多优惠') || priceRootEl.innerHTML.includes('前往手淘查看大促优惠') || priceRootEl.innerHTML.includes('加入购物车查看更多优惠'))) {
      window.tbOwnQr = true
      return
    }

    log('mobilePriceNotifier:' + (nowPrice <= pagePrice * 0.95 ? '手淘购买可能更优惠' : '前往手淘查看更多优惠'))
    const app = new Vue({
      el: div,
      render: h => h(AliMobilePriceNotifier, {
        props: {
          hintText: nowPrice <= pagePrice * 0.95 ? `手淘购买可能更优惠`: `前往手淘查看更多优惠`,
          tag: 13,
          hideInMini: needHideWhenScrollDown
        }
      })
    })

    G.priceNotifierApp = app
    appNode = app.$el

    let lastRecover = Date.now()

    // 创建一个观察器实例
    observer = new MutationObserver((mutationsList, observer) => {
      // 如果priceRootEl被移除或者重新添加进DOM中，重新添加div
      for (let mutation of mutationsList) {
        if (mutation.type === 'childList') {
          let priceRootEl = $(selectorConfig.priceRoot)[0]
          if (!priceRootEl) {
            priceRootEl = $(selectorConfig.priceRootMini)[0]
          }
          if (priceRootEl && !priceRootEl.contains(appNode)) {
            // priceRootEl.appendChild(div);

            let now = Date.now()
            if (now - lastRecover < 500) {
              require('common/extConsole').warn('aliPriceNotifier: recover too fast')
              return
            }
            lastRecover = now

            if ($(selectorConfig.priceWrap).length) {
              $(selectorConfig.priceWrap).append(appNode)
            } else if ($(selectorConfig.priceTextMini).length) {
              // 新版滚到下面，带图片
              $(selectorConfig.priceRootMini).append(appNode)
            } else {
              const totalWidth = getMiniPriceWidth(selectorConfig.priceOriginMini, selectorConfig.priceExtraMini)
              if (totalWidth <= minAllowedWidth && !hide) {
                $(selectorConfig.priceOriginMini).after(appNode)
                hide = false
              } else {
                hide = true
              }
            }
          }
        }
      }
    });

    // 配置观察器：观察子节点和后代的变化
    const config = { childList: true, subtree: true };

    if ($(selectorConfig.panel).length) {
      // 传入目标节点，以及观察选项
      observer.observe($(selectorConfig.panel)[0], config);
      if ($(selectorConfig.priceWrap).length) {
        $(selectorConfig.priceWrap).append(appNode)
      } else {
        const totalWidth = getMiniPriceWidth(selectorConfig.priceOriginMini, selectorConfig.priceExtraMini)
        if (!$(selectorConfig.priceOriginMini).length) {
          console.error('aliPriceNotifier: mini price not found')
        }
        if (totalWidth <= minAllowedWidth) {
          $(selectorConfig.priceOriginMini).after(appNode)
        } else {
          console.warn('aliPriceNotifier: mini price width is too large', totalWidth)
        }
      }
    } else {
      console.warn('aliPriceNotifier: pannel not found')
      $(selectorConfig.priceWrap).append(appNode)
    }

    // 稍后，你可以停止观察
    // observer.disconnect();
  }
}


