const request = require('common/request')
const template = require('vendor/template')

module.exports = {
  async init(hasCoupon = false) {
    let site = G.site
    if (site === '360buy') {
      site = 'jd'
    }
    if (hasCoupon) return
    let res = await request.get(G.server + '/extension?ac=promoActivity&site=' + site)
    let config = await request.rawGet('https://cdn.bijiago.com/js/configs/activity-bijiago-online.json')
    let c = config.aliActivity
    console.log(res)
    if (res.type === 'link') {
      if (window.innerWidth - $('#bjgext_mainbar').outerWidth() > 160) {
        // 购物党底部
        let html = `<a href="${res.link}" target="_blank" class="rinfo-btn" style="width: initial; margin-left: 8px; margin-right: 8px"><img style="height: 48px" src="${res.img}"/></a>`
        $('#bjgext_mainbar .common-banner').after(html)
      }
    } else if (res.type === 'qrcode') {
      if (window.innerWidth - $('#bjgext_mainbar').outerWidth() > 160) {
        // 底部
        let html = template.compile(require('art-template-loader!activities/gwd-ali-bottom.html'))({
          img: res.img,
          qr: '',
          extClass: ''
        })
        $('#bjgext_mainbar .common-banner').after(html)
      }

      let html2 = template.compile(require('art-template-loader!activities/gwd-tmall-middle.html'))({
        qr: '',
        text: config.aliActivity.middle.text
      });
      $('#bjgext_minibar').append(html2)

      // let html = template.compile(require('art-template-loader!activities/gwd-ali-center.html'))({
      //   img: res.img,
      //   qr: '',
      //   text: c.center.text,
      //   extClass: '',
      //   qrText: c.qrText
      // })
      // $('.bjgext-mini-trend').after(html)
      // $('.gwd-middle-tmall').css('border', '1px solid #f1f1f1')
      
      let qrLoaded = false
      function loadQr() {
        if (qrLoaded) return
        request.get(res.qrcode).then(data => {
          if (data.code === 1 && data.data && data.data.qrImgStr) {
            $('.gwd-act-qr-img').attr('src', data.data.qrImgStr)
            qrLoaded = true
          }
        })
      }

      $('.gwd-middle-tmall').hover(loadQr)
      $('.gwd-middle-act-bar').hover(loadQr)
      $('.gwd-bottom-tmall').hover(loadQr)
    }

  }
}


