<template>
  <div class="gwd-inline-row gwd-align gwd-jd-rank" :class="additionalClass" :style="`margin-top: ${mt}px`">
    <img class="gwd-icon-rank" src="https://cdn.gwdang.com/images/extensions/jdRanking/icon.svg" alt="">
    <img v-if="additionalClass === 'gwd-w217'" style="margin-left: -2px" src="https://cdn.gwdang.com/images/extensions/jdRanking/text.svg" alt="">
    <img v-if="additionalClass === 'gwd-w210' || additionalClass === 'gwd-w235'" style="margin-left: 2px; margin-right: 1px" src="https://cdn.gwdang.com/images/extensions/jdRanking/text-w210.svg" alt="">
    <hr class="gwd-vline" />
    <div class="gwd-rank-list gwd-row gwd-align" :class="data.length > 1 ? 'gwd-rotate': ''" style="position: relative">
      <a :title="data[0].rname" :href="data[0].rurl" target="_blank" class="gwd-row gwd-align gwd-rank-first" ><span class="gwd-font11">
        <span class="gwd-mw">{{ data[0].rname }}</span><span v-if="data[0].rank">第{{data[0].rank}}名</span>
      </span></a>
      <div v-if="data.length > 1" class="gwd-rank-addition">
        <a :title="item.rname" v-for="item in addition" :key="item.rurl" :href="item.rurl" target="_blank">
          <span class="gwd-font11 gwd-mw">{{ item.rname }}</span>
        </a>
      </div>
    </div>
    <form :action="debugMode ? `https://localdev.gwdang.com:3000/v2/ext/jd_rank`: `https://www.gwdang.com/v2/ext/jd_rank`" method="post" target="_blank" style="display: none">
      <input type="hidden" name="products" v-model="content">
      <input type="hidden" name="search" v-model="search">
      <input type="hidden" name="rank" v-model="rankName">
      <input type="hidden" name="from" v-model="from">
      <input type="submit" style="display: inline-block; font-size: 20px; color: #666" value="测试" :id="`gwd-jdrank-submit-${id}`">
    </form>
  </div>
</template>
<style scoped lang="less">
  .gwd-jd-rank {
    width: 232px;
    height: 32px;
    background: url(https://cdn.gwdang.com/images/extensions/jdRanking/ranklistBg.svg);

    .gwd-icon-rank {
      width: 15px;
      height: 15px;
      margin-left: 5px;
    }

    .gwd-vline {
      display: block;
      width: 1px;
      height: 10px;
      background: #000000;
      margin-left: 0px;
      border: 0;
    }

    .gwd-rank-list {
      flex: 1;
      height: 100%;
      a {
        padding-left: 7px;
        flex: 1;
        span {
          display: inline-block;
          transform-origin: left center;
          color: #111111;
          white-space: nowrap;
          overflow: hidden;
          vertical-align: middle;
          text-overflow: ellipsis;
        }
        span.gwd-mw {
          max-width: 130px;
        }
      }

      a:hover {
        span {
          color: #e03024;
          font-weight: bold;
        }
      }

      .gwd-rank-first {
        span {
          color: #e03024;
        }
      }

      .gwd-rank-addition {
        display: none;
        position: absolute;
        right: 0;
        width: 153px;
        top: 100%;
        border: 1px solid #ffeded;
        overflow: hidden;
        background: white;
        z-index: 9;
        a {
          height: 25px;
          line-height: 25px;
          display: inline-block;
          width: 100%;
          vertical-align: middle;
          border-bottom: 1px solid #f1f1f1;
        }

        a:last-of-type {
          border-bottom: none;
        }
      }
    }

    .gwd-rank-list:hover {
      .gwd-rank-addition {
        display: block;
      }
    }

    .gwd-rank-list::after {
      content: '';
      position: absolute;
      width: 16px;
      height: 16px;
      background: url(https://cdn.gwdang.com/images/extensions/jdRanking/arrow-right-default.svg);
      right: 3px;
      top: 5px;
      pointer-events: none;
    }

    .gwd-rank-list.gwd-rotate::after {
      transform: rotate(90deg);
    }

    .gwd-rank-list.gwd-rotate:hover::after {
      transform: rotate(270deg);
    }

    .gwd-rank-list:hover::after {
      background: url(https://cdn.gwdang.com/images/extensions/jdRanking/arrow-right-hilighted.svg);
    }
  }

  .gwd-w217 {
    width: 217px;
    height: 26px;
    background: url(https://cdn.gwdang.com/images/extensions/jdRanking/w217.svg);
  }

  .gwd-w210, .gwd-w235 {
    width: 210px;
    height: 30px;
    background: url(https://cdn.gwdang.com/images/extensions/jdRanking/w210.svg);
    .gwd-rank-list {
      .gwd-rank-addition {
        width: 140px;
      }
    }
    .gwd-rank-list::after {
      top: 7px;
      background: url(https://cdn.gwdang.com/images/extensions/jdRanking/arrow-right-default-gray.svg);
    }
    .gwd-rank-list a span {
      color: #555555;
      span.gwd-mw {
        max-width: 80px;
      }
    }
    .gwd-font11 {
      transform: scale(1);
    }
  }

  .gwd-w235 {
    width: 235px;
    height: 23px;
    background: url(https://cdn.gwdang.com/images/extensions/jdRanking/w235.svg);
    .gwd-rank-list a {
      padding-left: 12px;
      span {
        span.gwd-mw {
          max-width: 95px;
        }
      }
    }
    .gwd-rank-list {
      .gwd-rank-addition {
        width: 165px;
      }
    }
    .gwd-rank-list::after {
      right: 6px;
      top: 3px;
    }
  }
</style>
<script>
  const commonUtil = require('common/commonUtil')

  export default {
    props: ['data', 'top', 'additionalClass'],
    data() {
      return {
        mt: 0,
        debugMode: !!window.GwdToolkit,
        // debugMode: false,
        search: $('#key').val(),
        content: '',
        from: (location.hostname === 'search.jd.com' || location.hostname === 'list.jd.com') ? '京东搜索结果页': '商品详情页',
        rankName: '',
        id: parseInt(Math.random() * 10000)
      }
    },
    mounted() {
      if (this.top) {
        this.mt = this.top
      }
      if (!window.gwdRank) {
        window.gwdRank = this
      }
    },
    methods: {
      async rankClick(item) {
        if (!location.hostname.includes('.jd.com')) {
          window.open(item.rurl)
        }
        const link = commonUtil.getParameterByName('target_url', item.rurl)
        const contentId = commonUtil.getParameterByName('contentId', link)
        const rankType = commonUtil.getParameterByName('rankType', link)
        const payload = {
          functionId: 'getRankLanding',
          appid: 'JDReactRankingList',
          body: JSON.stringify({
            version: '109',
            rankType: rankType,
            source: 'dacu',
            rankId: contentId,
            extraParam: {},
            fromName: '-100',
            hasVenderRank: '1'
          }),
          clientVersion: '9.4.2',
          client: 'wh5',
          uuid: Date.now() * 1000 + parseInt(Math.random() * 1000),
          area: '1_2802_54747_0'
        }
        const url = require('common/request').buildUrl(`https://api.m.jd.com/client.action`, payload)
        const res = await require('common/request').requestXHR(url)
        this.content = JSON.stringify(res.result.products.map(item => {
          item.zyTag = parseInt(item.zyTag)
          return item
        }))
        this.rankName = item.rname
        let search = $('#key').val()
        this.search = search ? search: 'fake'
        this.$nextTick(() => {
          $('#gwd-jdrank-submit-' + this.id).click()
        })
      }
    },
    computed: {
      addition() {
        return this.data.length ? this.data.filter((item, idx) => idx > 0): []
      }
    }
  }
</script>



