// site css fix
module.exports.init = () => {
  if (G.site.includes('amazon')) {
    require('common/commonUtil').appendCss(`
      #dp { max-width: 1650px; }
    `)
  }

  if (G.site === 'tmall' || G.site === 'taobao') {
    require('common/commonUtil').appendCss(`
      .Price--sale--1huSj6m { z-index: 99 }

      .undefined {
        visibility: visible!important;
      }

      .BasicContent--detailInfoWrap--3U0iFLv, .detailInfoWrap--XXyEmkTY{
        position: relative;
        top: 105px;
      }

      .gwd_top .gwd_unfold .DetailInfo--tabTitleWrap--3q2Jn-e { top: 36px!important }

      .miniPanel .gwd-minibar-bg { display: none }
      .miniPanel #bjgext_mb_bg { display: none }

      .PurchasePanel--miniPanel--2qnyyyB { top: 126px!important }

      .gwd_top .gwd_unfold .isStickied--cAvTq3XA {
        top: 36px!important;
      }

      .Price--priceWrap--3MY0wsh {
        white-space: nowrap;
      }

      .Price--priceAction--1hvOH5u {
        white-space: initial;
      }

      .miniPanel .beautify-scroll-bar {
        overflow: hidden scroll!important;
      }

      .bannerWrap--ApeVpytP { position: relative; top: 102px; }

      .PurchasePanel--footWrap--3w0gUyF { overflow: visible!important }

    `)

    if ($('[class^=GoLoginInfo--]').length) {
      require('common/commonUtil').appendCss(`
      .BasicContent--detailInfoWrap--3U0iFLv, .detailInfoWrap--XXyEmkTY{
        top: 15px;
      }
      `)
    }

    if (location.host === 'chaoshi.detail.tmall.com') {
      require('common/commonUtil').appendCss(`
      .gwd-contact-link { z-index: 0!important }
      `)
    }

    if ($('.bannerWrap--ApeVpytP').length) {
      require('common/commonUtil').appendCss(`
        .BasicContent--detailInfoWrap--3U0iFLv, .detailInfoWrap--XXyEmkTY {
          top: 108px;
        }
      `)
    }
  }
}



