let totalPages = 0,
  nowPage;

const getPosition = (callback) => {
  let site = G.site;
  if (site.includes('amazon')) {
    site = 'amazon-com'
  }
  let pos = sitePattern[site];
  if (!pos) return;
  for (let i = 0; i < pos.length; i++) {
    const selector = pos[i].selector || pos[i];
    const position = pos[i].position || 'after';
    if ($(selector).length > 0) {
      callback(selector, position)
      return;
    }
  }
  setTimeout(() => {
    getPosition(callback)
  }, 400)
}

const setMiniBarComTle = (item, num, isfuzzy) => {
  if (G.ss_name === 'priceDog' && require('common/haitao').isHaitao()) return
  if (G.site === '6pm') return;
  // const selector = '#bjgext_minibar #gwd_mini_compare'
  const selector = '.bjgext-mini-compare'
  $(selector).show()
  let tle
  if (!item && !num) {
    tle = `<span class="no_pri_sp">暂无商家比价</span>`;
  } else if (isfuzzy) {
    tle = `<span class="" style="width: 100%; display: flex; align-items: center; justify-content: center"><img src="https://cdn.bijiago.com/images/extensions/bijiago/exchange@2x.png" style="width: 16px; height: 16px; margin-right: 6px; vertical-align: middle">${G.lang === 'zh-tr' ? '商城相似款': '商城相似款'}</span>`;
  } else {
    let lowest = Number(item.price.toString().replace(',', ''));
    if (lowest < G.dp.price) {
      let site_name = item.site_name;
      let price = item.price;
      tle = `<img src="https://cdn.bijiago.com/images/extensions/bijiago/yuan.svg" style="display: inline-block; vertical-align: middle; width: 10px; height: 14px; margin-right: 4px" alt=""><span class="low_sp1">${G.lang === 'zh-tr' ? '更低價': '更低价'}:&nbsp;</span><span class="low_sp3">￥${price}</span>`;
    } else {
      tle = `<div class="low_qtdiv"><img src="https://cdn.bijiago.com/images/extensions/bijiago/yuan.svg" style="display: inline-block; vertical-align: middle; width: 10px; height: 14px; margin-right: 6px;">其他<span class="other_sp">${num}</span>家报价</div>`;
      if (G.lang === 'zh-tr') {
        tle = `<div class="low_qtdiv"><img src="https://cdn.bijiago.com/images/extensions/bijiago/yuan.svg" style="display: inline-block; vertical-align: middle; width: 10px; height: 14px; margin-right: 6px;">其他<span class="other_sp">${num}</span>家報價</div>`;
      }
    }
  }
  if (!item && !num) {
    $(selector).remove()
  }
  $(selector).append($(tle)).show();
}
let lock, hidebtn
const turnPage = (t, dom) => {
  lock = true;
  let left = Number(dom.css('left').replace('px', ''))
  if (t === '-1') {
    nowPage--;
    if (nowPage === 1) {
      $('.mini-com-foot .mini-com-tleft').hide()
    }
    if (hidebtn) {
      hidebtn = false;
      $('.mini-com-tright').show()
    }
    dom.animate({
      left: (left + 450) + 'px'
    }, 500, function() {
      lock = false;
    })
  } else if (t === '1') {
    if (nowPage === totalPages) {
      lock = false;
      return;
    }
    nowPage++
    if (nowPage === totalPages) {
      hidebtn = true;
      $('.mini-com-tright').hide()
    }
    if (nowPage === 2) {
      $('.mini-com-foot .mini-com-tleft').show()
    }
    dom.animate({
      left: (left - 450) + 'px'
    }, 500, function() {
      lock = false;
    })
  }
}
const renderMiniCompare = () => {
  let html1 = require('art-template-loader!../views/minibarCompare.html')
  let html2 = require('art-template-loader!../views/minibarCompare_fuzzy.html')
  let html
  let dp_data = userData.get('dp_data');
  let products = [];
  let domid

  let renderCmp = false

  if (dp_data.b2c.store && dp_data.b2c.store.length > 0) {
    html = html1;
    let len = dp_data.b2c.store && dp_data.b2c.store.length;
    len = (len > 6 ? 6 : len);
    for (let i = 0; i < len; i++) {
      let item = dp_data.b2c.store[i].product[0];
      if (dp_data.now.now_dp_id == item.dp_id && dp_data.b2c.store[i].product[1])
        item = dp_data.b2c.store[i].product[1]
      item.site_id = item.dp_id.match(/\d+-(\d+)/)[1];
      products.push(item);
    }
    setMiniBarComTle(dp_data.b2c.store[0].product[0], len)
  } else if (dp_data.b2c_fuzzy && dp_data.b2c_fuzzy.product && dp_data.b2c_fuzzy.product.length > 0) {
    html = html2;
    for (let i = 0; i < dp_data.b2c_fuzzy.product.length; i++) {
      let item = dp_data.b2c_fuzzy.product[i]
      if (item.price && item.url && item.site_name && (item.img_url || item.pic_url)) {
        products.push(item)
      }
    }
    let len = products.length;
    totalPages = parseInt(len / 3)
    products = products.slice(0, totalPages * 3)
    if (totalPages === 0) {
      setMiniBarComTle()
      return;
    }
    nowPage = 1;
    domid = '.mini-compare-fuzzy-detail ul';

    setMiniBarComTle(products[0], len, true)
    renderCmp = true
  } else {
    setMiniBarComTle()
    return;
  }
  $('#bjgext_minibar').css('display', 'inline-block')
  G.showMinibar = true;
  let dom = template.compile(html)({
    data: products,
    totalPages: totalPages,
    s_server: G.s_server
  })

  $('.bjgext-mini-compare').append(dom)
  if (G.ss_name === 'priceDog') {
    $('#minibar_compare').css('left', '50%')
    $('#minibar_compare').css('margin-left', '-147px')
  }

  if (renderCmp) {
    $('.bjgext-mini-compare').css('position', 'static')
    const MiniList = require('../components/MiniList.vue').default
    new Vue({
      el: '#bjg-mini-cmp-fuzzy',
      render: h => h(MiniList, {
        props: {
          products: products
        }
      })
    })
    return
  }
  addEvent(domid)
}

const addEvent = (id) => {
  let uldom = $(id)
  $('.bjgext-mini-compare').on('mouseenter', () => {
    $('#bjgext_minibar').addClass('_mshover')
  })
  $('.bjgext-mini-compare').on('mouseleave', () => {
    $('#bjgext_minibar').removeClass('_mshover')
  })
  if (id) {
    $('.bjgext-mini-compare .mini-com-foot').on('click', function(e) {
      let type = $(e.target).attr('data-type')
      if (type && !lock && e.target.nodeName !== 'A') {
        turnPage(type, uldom)
      }
    })
  }

}
