const renderMiniBar = (pos, insertPlace) => {
  let html = require('art-template-loader!../views/minibar.html')
  let p = insertPlace
  if (G.site === 'shopee') {
    p = 'before'
  }
  $(pos).eq(0)[p](template.compile(html)({
    alisite: G.aliSite,
    setting: `${G.server}/brwext/setting_feedback?set=1`
  }))
  util.tongji('1', 'show')
  if (G.site.indexOf('amazon') > -1) {
    $('#bjgext_mb_bg').css('display', 'inline-block')
  }
  $('#bjgext_minibar').css('display', 'inline-block')
  $('#bjgext_minibar .bjgext-mini-logo').on('click', () => {
    cnzz.log('minibar-logo-click')
  })
  $('#bjgext_minibar').on('click', (e) => {
    let href
    if (e.target.nodeName === 'A') {
      href = e.target.href;
    } else if (e.target.parentNode.nodeName === 'A') {
      href = e.target.parentNode.href
    }
    if (href && href.indexOf('javascript:') === -1) {
      util.tongji('1', 'click', href)
    }
  })
  if (location.host === 'item.taobao.com') {
    setTimeout(function() {
      if (!($('#J_PromoPrice').is(':visible'))) {
        $('#bjgext_mb_bg').css('margin-top', '10px')
      }
    }, 500)
  } else if (G.site === 'gome') {
    if ($('#bjgext_mb_bg').prev().hasClass('p20')) {
      $('#bjgext_mb_bg').addClass('p20')
    }
  }
  if (G.site === '360buy') {
    let bgcolor = $('.summary-price-wrap').css('background-color');
    if (bgcolor) {
      $('#bjgext_mb_bg').css('background-color', bgcolor)
    }
  }
  setHackSite()

  if (G.disableLogin) {
    return
  }

  // if (navigator.userAgent.toLowerCase().indexOf('metasr') === -1) {
    const MiniFavor = require('../components/MiniFavor.vue').default
    new Vue({
      el: '#bjgouRemind',
      render: h => h(MiniFavor)
    })
  // } else {
  //   $('#bjgouRemind').remove()
  // }
}

async function recoverMiniBar() {
  extConsole.log('recoverMiniBar')
  if ($('.miniPanel').length) {
    extConsole.log('miniPanel exist')
    return
  }

  if (window.gwd_g) {
    await require('common/commonUtil').sleep(200)
  }

  // 确保.gwd-minibar-bg在.ActiveInfo上方

  const bgSelector = '#bjgext_mb_bg'

  if (!$(bgSelector).length) {
    extConsole.log('recoverMiniBar no minibar')
    document.body.appendChild(G.miniBar)
  }

  extConsole.log('recoverMiniBar selector res:', $(bgSelector)[0])

  const globalConfig = await require('common/globalCondition').met('GwdConfig')

  if (globalConfig && globalConfig.gwdMiniBarRecoverConfig) {
    const recoverConfig = globalConfig.gwdMiniBarRecoverConfig.aliSite
    for (let i = 0; i < recoverConfig.length; i++) {
      const selector = recoverConfig[i].selector
      const position = recoverConfig[i].position
      const target = $(selector)
      if (target.length) {
        if (position === 'before') {
          $(bgSelector).insertBefore(target)
        } else {
          $(bgSelector).insertAfter(target)
        }
        return
      }
    }
  }
}

module.exports.init = async () => {
  const globalConfig = await require('common/globalCondition').met('GwdConfig')
  if (G.show_minibar === '0') return;
  if (location.host === 'www.amazon.cn') return;
  extConsole.log('minibar init')

  if (globalConfig && globalConfig.gwdMiniBarPositions) {
    if (G.aliSite) {
      sitePattern['taobao'] = globalConfig.gwdMiniBarPositions.aliSite
      sitePattern['tmall'] = globalConfig.gwdMiniBarPositions.aliSite
    } else {
      if (globalConfig.gwdMiniBarPositions[G.site]) {
        sitePattern[G.site] = globalConfig.gwdMiniBarPositions[G.site]
      }
    }
  }

  getPosition((pos, insertPlace) => {
    if (G.aliSite) {
      const panel = globalConfig.aliMobileNotifierConfig.map(i => i.panel).find(item => {
        if ($(item).length) {
          return $(item)[0]
        }
        return false
      })
      if (panel) {
        require('common/mutationObserver').observe(panel, async (mutations) => {
          extConsole.log('mutations:', mutations)
          const config = globalConfig.gwdMiniBarRecoverConfig.aliSite        
          await require('standard/module/util').waitForConditionFn(() => {
            for (let i = 0; i < config.length; i++) {
              const selector = config[i].selector
              if ($(selector).length) {
                return true
              }
            }
            return false
          })
          // 仅在panel的class发生变化时重新渲染minibar
          recoverMiniBar()
        }, {
          attributes: true,
          attributeFilter: ['class']
        })
      }
    }

    extConsole.log('begin minibar render')
    renderMiniBar(pos, insertPlace)
    if (G.ss_name === 'priceDog') {
      $('.bjgext-mini-logo a').attr('title', 'PriceDog')
      let div = document.createElement('div')
      div.id = 'pricedog-toolbar'
      if (location.host.indexOf('detail.ju.taobao.com') > -1) {
        $('#bjgext_mb_bg').eq(0).append(div)
        setTimeout(() => {
          $('.pricedog-bar').css({
            position: 'relative',
            top: '4px'
          })
        }, 0)
      } else {
        $('#bjgext_mb_bg').eq(0).after(div)
      }
      if (require('common/haitao').isHaitao()) {
        // const TaxViewer = require('../components/TaxViewer.vue').default
        // if (location.host === 'www.amazon.com') {
        //   new Vue({
        //     el: '#pricedog-toolbar',
        //     render: h => h(TaxViewer)
        //   })
        // }
      } else {
        const PriceDogMiniBar = require('../components/PriceDogMiniBar.vue').default
        new Vue({
          el: '#pricedog-toolbar',
          render: h => h(PriceDogMiniBar)
        })
      }
    }
    $('.bjgext-mini-compare').hide()
    if (!G.aliSite && G.site.indexOf('amazon') === -1)
      renderMiniCompare()
    // require('./yifenqian').init()
    if (location.host.indexOf('taobao') > -1 || location.host.indexOf('tmall') > -1)
      require('./dpPageCoupon').init()
    if (location.host.indexOf('.jd.com') > -1 || location.host.indexOf('suning') > -1)
      require('./dpPageCoupon').init2()
    if (location.host.includes('amazon.co.jp')) {
      $('#centerCol').css('overflow', 'visible')
    }

    const el = $('#bjgext_mb_bg')[0]
    G.miniBar = el
    if (el) {
      require('common/mutationObserver').observe(el, (mutations) => {
        mutations.forEach(mutation => {
          if (mutation.removedNodes.length) {
            require('common/extConsole').log('minibar被移除')
            if (G.instanceId === $('html').attr('data-bjg-id')) {
              recoverMiniBar()
            }
          }
        })
      })
    }
  })
}



