let widthObj

const calB2cWidth = () => {
  let winWidth = $(window).width();
  let itemlistW = 268;
  let turnpW = 130;
  let storeList = 304;
  let allProductW = (winWidth - turnpW * 2 - storeList);
  let showListNum = parseInt(allProductW / itemlistW);
  // 如果使用最小的翻页宽度能再增加一个商品list 就再增加， 宽度动态计算
  if ((allProductW - showListNum * itemlistW + 80) > 268) {
    showListNum++;
    turnpW = parseInt((winWidth - showListNum * itemlistW - storeList) / 2);
    allProductW = winWidth - turnpW * 2 - storeList;
  }
  return {
    productW: allProductW,
    turnpW: turnpW,
    showListNum: showListNum
  }
}

module.exports.init = () => {
  if (widthObj) return widthObj;
  let winWidth = $(window).width();
  let itemlistW = 268;
  let turnpW = 147;
  let allProductW = (winWidth - turnpW * 2);
  let showListNum = parseInt(allProductW / itemlistW);
  // 如果使用最小的翻页宽度能再增加一个商品list 就再增加， 宽度动态计算

  if ((allProductW - showListNum * itemlistW + 92) > 268) {
    showListNum++;
    turnpW = parseInt((winWidth - showListNum * itemlistW) / 2);
    allProductW = winWidth - turnpW * 2;
  }
  if (G.site === 'amazon') {
    turnpW--;
  }
  let B2cW = calB2cWidth()
  widthObj = {
    'allProductW': allProductW,
    'turnpW': turnpW,
    'showListNum': showListNum,
    'b2cProductW': B2cW.productW,
    'b2cTurnpW': B2cW.turnpW,
    'b2cShowListNum': B2cW.showListNum
  }
  return widthObj;
}

module.exports.calBottomBar = () => {
  let logo = $('#bjd_logo').outerWidth()
  let leftCom = $('.left-compare').outerWidth()
  let adinfo = $('.nbt-adinfo').outerWidth()
  let close = $('.nbt-close-btn').outerWidth()
  let rightInfo = $('.right-info').outerWidth()
  let winWidth = $(window).width();
  if (rightInfo < 500)
    rightInfo = 502;
  // 110 价格走势宽度
  let comBox = winWidth - (logo + leftCom + adinfo + close + rightInfo);
  return comBox;
}


