<template>
  <div class="bjg-window" data-foo="bar" @mouseover="$emit('mouseover')">
    <div class="bjg-window-title" v-if="user || alwaysShow">
      <img v-if="from_device === 'bijiago'" src="../assets/windowLogo@2x.png" alt="" style="width: 28px; height: 24px; margin-left: 5px;">
      <img v-else src="../assets/biyibi-rounded.png" style="width: 24px; height: 24px; margin-left: 5px;">
      <span class="username" v-if="user && userName">{{ userName }}</span>
      <div style="flex: 1"></div>
      <span style="margin-right: 14px; font-size: 12px; color: white; position: relative" class="bjg-qrText" v-if="!alwaysShow">
          <span style="text-decoration: underline">扫码关注公众号</span>
          ，及时获取{{ name }}通知
          <img :src="qrImg" alt=""
               style="width: 157px; height: 194px; position: absolute; left: 209px;" :style="name === '降价' ? 'top: -7px': 'top: -16px'">
          <img v-if="!hasWx" src="https://cdn.bijiago.com/images/extensions/bijiago/qr-wechat-click@2x.png" alt=""
               @click="imgClick"
               style="width: 157px; height: 194px; position: absolute; left: 209px; top: -16px; display: block!important;">
          <img src="https://cdn.bijiago.com/images/extensions/bijiago/price-protect-qr.jpeg" alt=""
               :style="`width: ${qrWidth}px; height: ${qrWidth}px; position: absolute; left: 228px; top: 6px;`">
        </span>
    </div>
    <slot></slot>
    <div class="bjg-window-bt" style="border-bottom: 1px solid #f1f1f1"></div>
  </div>
</template>
<style scoped lang="less">
.bjg-qrText {
  cursor: pointer;
  img {
    display: none;
  }
}

.bjg-qrText:hover {
  img {
    display: block;
  }
}

.bjg-window {
  border-radius: 2px 2px 0px 0px;
  cursor: default;
  display: none;
  background: white;
  position: absolute;
  width: 407px;
  bottom: 59px;
  div {
    border-left: 1px solid #f1f1f1;
    border-right: 1px solid #f1f1f1;
  }
  .bjg-window-title {
    background: url(../assets/protectWindowTitleBar@2x.png);
    height: 32px;
    display: flex;
    border-left: none;
    border-right: none;
    align-items: center;
    border-radius: 2px 2px 0px 0px;
    background-size: contain;
    span.username {
      margin-left: 8px;
      font-size: 12px;
      color: white;
      max-width: 125px;
      text-overflow: ellipsis;
      overflow: hidden;
      white-space: nowrap;
    }
  }
  .bjg-window-bottom {
    border-top: 1px solid #f1f1f1;
    background: white;
    height: 41px;
    a {
      cursor: pointer;
      font-size: 12px;
      color: #64615d;
      text-decoration: underline;
    }
  }

  .bjg-window-bt {
    position: absolute;
    bottom: -1px;
    height: 2px;
    background: transparent;
    left: 0;
    right: 0;
  }
}
</style>
<script>
  import { mapState } from 'vuex'

  export default {
    props: ['name', 'alwaysShow'],
    data() {
      return {
        from_device: G.from_device
      }
    },
    computed: {
      qrImg() {
        if (this.name === '降价') {
          return 'https://cdn.bijiago.com/images/extensions/bijiago/qr-wechat-hover-down@2x.png'
        }
        return 'https://cdn.bijiago.com/images/extensions/bijiago/qr-wechat-hover@2x.png'
      },
      qrWidth() {
        if (this.name === '降价') {
          return 125
        }
        return 116
      },
      ...mapState({
        userName: state => state.user.userName,
        user: state => state.user.userLogin,
        hasWx: state => state.user.userHasWx
      })
    },
    mounted() {
    },
    methods: {
      imgClick(e) {
        if (e.offsetX >= 140 && e.offsetY <= 20) {
          store.commit('user/setState', {
            userHasWx: true
          })
        }
      }
    }
  }
</script>



