module.exports.init = () => {
  // skuId=100014979337&cat=12218%2C21455%2C21456&venderId=1000362423&isCanUseDQ=isCanUseDQ-1&isCanUseJQ=isCanUseJQ-1
  const skuId = window.pageConfig.product.skuid
  const cat = window.pageConfig.product.cat.join(',')
  const venderId = window.pageConfig.product.venderId
  return new Promise(resolve => {
    let domain = location.hostname
    if (domain.includes('.jkcsjd.com')) {
      resolve(false)
    }
    $.get(`https://${domain}/coupons?skuId=${skuId}&cat=${encodeURIComponent(cat)}&venderId=${venderId}`).then(res => {
      let a = $('.coupon-wrap', res).children().toArray();
      let r = []
      for (let i = 0; i < a.length; i++) {
        if ($(a[i]).text().indexOf('已领取的券') > -1) {
          break
        }
        if ($(a[i]).hasClass('coupon-item')) {
          r.push(a[i])
        }
      }
      if (!r.length) {
        resolve(false)
        return
      }
      let resCoupon = r.map(x => {
        let couponVal = $(x).find('.coupon-val').text()
        let cond = $(x).find('.condition').text()
        let time = $(x).find('.coupon-time').html()
        if (cond.endsWith('可减')) {
          cond = cond.replace('可减', '减' + couponVal)
        }
        return {
          text: cond.replace('可用', '减' + couponVal),
          time: time
        }
      }).filter(x => {
        if (x.time) {
          let reList = [new RegExp('有效期([\\d\\-: ]*)至([\\d\\-: ]*)'), new RegExp('([\\d\\-: ]*)<br([\\d\\-: ]*)')]

          for (let re of reList) {
            let res = re.exec(x.time)
            if (res && res[1]) {
              if (new Date(res[1].trim()) > new Date()) {
                console.warn('filter early coupon', x)
                return false
              }
            }
          }
        }
        return true
      }).map(x => x.text)
      resolve(resCoupon)
    })
  })
}



