const request = require('common/request')
const aliSku = require('common/infoCollect/aliSku')

const getH5ShopCoupon = async () => {
  let id;
  if (G.site === 'taobao') {
    id = document.URL.match(/(?:\?|&)id=(\d+)/)[1]
  } else {
    id = require('common/commonUtil').getParameterByName('id')
  }
  let s;
  if (G.site === "taobao") {
    s = await aliSku.taobaoDetail(id)
  } else if (G.site === "tmall") {
    s = await aliSku.tmallDetail(id)
  } else {
    return false
  }

  let promotionFloatingData = s.promotionFloatingData
  let couponInfoData = await aliSku.couponInfo(id, promotionFloatingData)
  try {
    if (couponInfoData && couponInfoData.commonPromotions) {
      return {
        shop_coupon: {
          limit: couponInfoData.commonPromotions[0].titles[0].match(/满(\d+)使用/)[1],
          discount: couponInfoData.commonPromotions[0].priceText
        }
      }
    }
  } catch (e) {
    return 'no-coupon'
  }
  return 'no-coupon'
}

const getShopCoupon = g_config => {
  return request.get(`${G.server}/extension/Coupon?dp_id=${G.dp.itemId}&sellerId=${g_config.sellerId}&price=${G.dp.price}`)
}

const getResult = g_config => {
  return new Promise(async resolve => {
    let res = await getH5ShopCoupon()
    if (res && res.shop_coupon !== 'no-coupon') {
      resolve(res)
    } else {
      res = await getShopCoupon(g_config)
      resolve(res)
    }
  })
}

module.exports = {
  async init() {
    await require('standard/module/util').waitForConditionFn(() => {
      return window.g_config
    })
    let g_config = window.g_config
    let hasShopCoupon = false
    setTimeout(() => {
      if (!hasShopCoupon) require('common/globalCondition').setMet('shopCouponGot', false)
    }, 3000)
    getResult(g_config).then(async res => {
      require('common/globalCondition').setMet('shopCouponGot', res && res.shop_coupon)
      hasShopCoupon = true
      if (!res || !res.shop_coupon) {
        let memberCoupon = await require('standard/module/memberCoupon').init()
        console.log(memberCoupon)
        if (memberCoupon) {
          return
        }
        require('bjgou/modules/subsidy').init()
        return
      }
      let coupon = res.shop_coupon
      setTimeout(() => {
        // if ($('.dsj-content').length) {
        //   $('.dsj-content').after('<div id="shopCouponMini"></div>')
        // } else {
        //   $('#bjgext_minibar').after('<div id="shopCouponMini"></div>')
        // }
        $('#bjg-coupon-placeholder').replaceWith('<div id="shopCouponMini"></div>')
        const ShopCouponMini = require('bjgou/components/ShopCouponMini.vue').default
        const ShopCouponTop = require('bjgou/components/ShopCouponTop.vue').default
        new Vue({
          el: '#shopCouponMini',
          render: h => h(ShopCouponMini, {
            props: {
              coupon: coupon,
              useTb: res._dtao
            }
          })
        })
        $('.bjg-coupon-space').after('<div id="shopCouponTop"></div>')
        new Vue({
          el: '#shopCouponTop',
          render: h => h(ShopCouponTop, {
            props: {
              coupon: coupon,
              useTb: res._dtao
            }
          })
        })
      }, 0)
    })
  }
}



