<template>
  <a @click.prevent="click" class="gwd-tkl-float gwd-column gwd-align" title="一键分享到微信/QQ">
    <img src="../assets/tklIcon@2x.png" alt="" style="margin-top: 14px; width: 24px; height: 24px;">
    <span style="text-decoration: none; font-size: 12px; color: #333; margin-top: 4px;">{{ tkl ? (copied ? '复制成功': '点击复制'): '淘口令' }}</span>
  </a>
</template>
<style scoped lang="less">
.gwd-tkl-float {
  position: fixed;
  right: 0;
  width: 56px;
  height: 72px;
  top: calc(50% - 290px);
  background-color: #f7f9fa;
  cursor: pointer;
  box-shadow: 2px 2px 30px 0px rgba(97,105,119,0.18);
  border-radius: 18px 0 0 18px;
  text-decoration: none;
  font: 12px/1.5 tahoma, arial, 'Hiragino Sans GB', '\5b8b\4f53', sans-serif;
}

.gwd-tkl-float:hover {
  text-decoration: none;
}
</style>
<script>
function copyTextToClipboard(text) {
  const textArea = document.createElement('textarea')
  textArea.value = text
  document.body.appendChild(textArea)
  textArea.select()
  document.execCommand('copy')
  document.body.removeChild(textArea)
}

export default {
  props: ['getTKL'],
  data() {
    return {
      tkl: '',
      copied: false
    }
  },
  methods: {
    click() {
      if (!this.tkl) {
        console.log(this.getTKL)
        this.getTKL(data => {
          if (data) {
            this.tkl = '7' + data
          } else {
            this.tkl = location.href
          }
        })
      } else {
        this.copyTkl()
      }
    },
    copyTkl() {
      copyTextToClipboard(this.tkl)
      this.copied = true
    }
  }
}
</script>


