const request = require('common/request')

import QRLinkTaobaoLogin from 'components/QRLinkTaobaoLogin'

module.exports.init = async () => {
  const redirectUrl = require('common/commonUtil').getParameterByName('redirectURL')

  if (location.hostname !== 'login.m.taobao.com' || !redirectUrl) {
    return
  }

  if (redirectUrl.includes('taolijin')) {
    return
  }

  const res = await request.rawGet('https://www.gwdang.com/api/uland_to_dpid?u=' + encodeURIComponent(redirectUrl))
  $('.fm-agreement input').click()
  require('common/extConsole').log('res', res)
  //
  // if (!res || !res.dp_id) {
  //   return
  // }

  const div = document.createElement('DIV')
  document.body.appendChild(div)
  let tag = 5
  if (G.from_device === 'bijiago') {
    tag = 7
  }
  new Vue({
    el: div,
    render: h => h(QRLinkTaobaoLogin, {
      props: {
        tag: tag,
        dpId: res.dp_id
      }
    })
  })
}



