<template>
  <div class="pricedog-bar gwd-row" style="margin-top: 6px;" v-show="showSizeHelp">
    <div class="pricedog-tab gwd-align gwd-row" style="width: 102px;" v-show="false">
      <span style="color: #ff6132; line-height: initial" v-if="rate">税费预估 : ¥{{ (price * rate).toFixed(2) }}</span>
      <div class="pricedog-tab-content"></div>
    </div>
    <!--<div style="width: 1px; height: 100%; background: #e6e9eb" v-if="showSizeHelp"></div>-->
    <div class="pricedog-tab gwd-align gwd-row" style="width: 97px;" v-if="showSizeHelp">
      <img src="../assets/ruler.svg" alt="" style="width: 15px; height: 15px;">
      <span style="margin-left: 6px; color: #64615d">{{ lang === 'en'? 'Size Chart': '尺码帮助' }}</span>
      <div class="pricedog-tab-content" style="width: 475px; height: 278px;">
        <SizeHelp></SizeHelp>
      </div>
    </div>
  </div>
</template>
<style scoped lang="less">
  .pricedog-bar {
    width: 100px;
    height: 37px;
    font-size: 0;
    background: white;
    border-radius: 4px;
    border: 1px solid #E6E9EB;
    position: relative;
    box-sizing: border-box;
    .pricedog-tab-content {
      display: none;
      position: absolute;
      left: -1px;
      top: 35px;
      text-align: center;
      z-index: 9;
      background: #FFFFFF;
      border-radius: 0px 0px 4px 4px;
      border: 1px solid #E6E9EB;
      box-sizing: border-box;
    }
    .pricedog-tab:hover {
      background: #fffbef;
      .pricedog-tab-content {
        display: flex;
      }
    }
    .pricedog-tab {
      justify-content: center;
      span {
        font-size: 12px;
      }
    }
  }
</style>
<script>
  import SizeHelp from './SizeHelp.vue'

  let showSize = false
  let k = G.exact_arr.all
  let l = ['男装', '女装', '童装', '鞋', '裤', '裙', '衣']
  l.forEach(item => {
    if (k.indexOf(item) > -1) {
      showSize = true
    }
  })

  export default {
    components: { SizeHelp },
    data() {
      return {
        showSizeHelp: showSize,
        rate: 0,
        price: G.dp.price,
        lang: G.lang
      }
    },
    methods: {
      async load() {

      }
    },
    mounted() {
      require('common/request').get('https://cdn.bijiago.com/js/configs/outTax.json').then(res => {
        Object.keys(res).map(item => {
          if (k.indexOf(item) > -1) {
            this.rate = res[item]
          }
        })
        if (!this.rate) {
          this.rate = res['default']
        }
      })
      if (showSize) {
        $('.main-box .botbar').css('margin-top', '86px')
      }
      if (location.host.indexOf('detail.ju.taobao.com') > -1) {
        if ($('.status-banner').hasClass('status-sku')) {
          // setTimeout(() => {
          //   $('#bjgext_mb_bg').css('margin-left: -10px').css('margin-top', '2px')
          // }, 100)
          let k = document.createElement('STYLE')
          k.innerHTML = `
            #bjgext_mb_bg {
              margin-left: -10px!important;
              margin-top: 2px!important;
            }
          `
          document.body.appendChild(k)
        }
      }
    }
  }
</script>


