const template = require('vendor/template')
const html = require('art-template-loader!../views/guess.html')
const taotaos = require('common/taotaosouSuggest')
const util = require('./util')

let totalPages


const render = data => {
  if (!data) return;
  let pages
  let winH = $(window).height();
  let winW = $(window).width();
  if (winH < 768 || winW < 1336)
    return;
  let newdata = data.productsuggest;
  let len = newdata.length;
  if (len > 4)
    pages = true;
  totalPages = Math.ceil(len / 4);
  $('body').append(template.compile(html)({
    data: newdata.slice(0, 8),
    pages: pages
  }))
  if (G.guess_fold === '1') {
    $('.bjgext_big_content').hide()
    $('.bjgext_small').show()
  }
  util.tongji('3', 'show')
  addEvent()
}
const turnPage = (status, nowp, tp) => {
  nowp = Number(nowp);
  let lists = $('.bjgext_guess_body li')
  let len = lists.length;
  lists.hide()
  if (status === -1) {
    if (nowp === 1)
      nowp = tp + 1;
    for (let i = (nowp - 2) * 4, size = ((nowp - 1) * 4 > len ? len : (nowp - 1) * 4); i < size; i++) {
      lists.eq(i).show()
    }
    nowp--
  } else {
    if (nowp === tp)
      nowp = 0;
    for (let i = nowp * 4, size = ((nowp + 1) * 4 > len ? len : (nowp + 1) * 4); i < size; i++) {
      lists.eq(i).show()
    }
    nowp++
  }
  $('.guess-n-p').text(nowp)
}
const addEvent = () => {
  $('.bjgext_guess_footer .bjgext-guess-tl').on('mousedown', function() {
    $(this).addClass('_press')
  })
  $('.bjgext_guess_footer .bjgext-guess-tl').on('click', function() {
    let nowp = $('.guess-n-p').text();
    turnPage(-1, nowp, totalPages)
  })
  $('.bjgext_guess_footer .bjgext-guess-tl').on('mouseup', function() {
    $(this).removeClass('_press')
  })
  $('.bjgext_guess_footer .bjgext-guess-tr').on('mousedown', function() {
    $(this).addClass('_press')
  })
  $('.bjgext_guess_footer .bjgext-guess-tr').on('click', function() {
    let nowp = $('.guess-n-p').text();
    turnPage(1, nowp, totalPages)
  })
  $('.bjgext_guess_footer .bjgext-guess-tr').on('mouseup', function() {
    $(this).removeClass('_press')
  })
  $('.bjgext-guess-close').on('click', () => {
    $('.bjgext_big_content').hide()
    $('.bjgext_small').show()
    util.settings('guess_fold', '1')
  })
  $('.bjgext_small').on('click', () => {
    $('.bjgext_big_content').show()
    $('.bjgext_small').hide()
    util.settings('guess_fold', '0')
  })
  $('.bjgext_guess_body a').on('click', function() {
    let href = $(this).attr('href')
    if (href) {
      util.tongji('3', 'click', href)
    }

  })
}

module.exports.init = () => {
  if (G.show_leftguess === '0') return;
  if (G.site.indexOf('taobao') > -1 || G.site.indexOf('tmall') > -1) {
    taotaos.init(render)
  }

}


