import {appendCss} from "../../common/commonUtil";

const QRLink = require('./components/QRLink.vue').default
import QRLinkContactTmall from './components/QRLinkContactTmall.vue'
import QRLinkContact from './components/QRLinkContact'
import QRLinkLeft from './components/QRLinkLeft'
import QRLinkTbV3 from './components/QRLinkTbV3'

const qrReplaceJd = async () => {
  await require('standard/module/util').waitForConditionFn(() => $('.mobile-only.J-mobile-only .qrcode.fl img').length, 300, 20)
  if ($('.qrcode.fl img').length) {
    require('common/models/appQrcode').get('baiyibutie').then(r => {
      $('.mobile-only.J-mobile-only').css('position', 'relative').append(
        `<img style="position: absolute; top: 0; left: -110px; width: 105px" src="https://cdn.gwdang.com/images/extensions/${G.lang==='zh-tr' ? 'jdScanHintTr.png': 'jdScanHint.svg'}">`
      )
      $('.qrcode.fl img').attr('src', r).css('width', '80px')
    })
  }
}

const qrReplaceTaobao = async () => {
  if (window.gwd_qr_replaced) return

  let s = document.createElement('STYLE')
  s.innerHTML = `
    .tk-qr-wrapper > canvas, .tk-qr-wrapper > img { display: none!important }
    `
  document.body.appendChild(s)

  let s2 = document.createElement('STYLE')
  s2.innerHTML = `
    .gwd-minibar-bg { margin-top: 20px; }
  `
  document.body.appendChild(s2)

  let imgSrc = ''
  const loadQr = () => {
    require('common/extConsole').log('qrload start')
    if (imgSrc) return
    require('common/models/appQrcode').get(10).then(r => { imgSrc = r} )
  }

  let imgSrcRight = ''
  const loadQrRight = () => {
    require('common/extConsole').log('qrload start')
    if (imgSrcRight) return
    require('common/models/appQrcode').get(11).then(r => { imgSrcRight = r} )
  }

  await require('standard/module/util').waitForConditionFn(() => {
    return $('.tk-qr-wrapper').length || $('.tb-qrcode-tool').length || $('.toolkit-item-qrcode').length
  })

  $('[class^=Promotion--trigger]').hover(loadQr)
  $('.tb-qrcode-tool').hover(loadQr)

  $('.toolkit-item-qrcode').hover(loadQrRight)
  window.gwd_qr_replaced = true

  require('standard/module/util').waitForConditionFn(() => imgSrc).then(() => {
    if ($('[class^=ItemQR--itemQR]').find('img').length) {
      $('[class^=ItemQR--itemQR]').find('img').attr('src', imgSrc)
    } else {
      $('[class^=ItemQR--itemQR]').prepend(`<img src="${imgSrc}" style="width: 91px; height: 91px;">`)
    }
    $('[class^=ItemQR--itemQR] canvas').hide()
    $('.ks-popup-content img.image').attr('src', imgSrc).css({
      width: '167px',
      height: '167px',
      padding: '10px',
      boxSizing: 'border-box'
    })
  })

  require('standard/module/util').waitForConditionFn(() => {
    // return $('.tk-qr-wrapper > img').length && imgSrcRight !== ''
    return imgSrcRight !== ''
  }).then(() => {
    // $('.tk-qr-wrapper > img').attr('src', imgSrcRight).css('width', '100px')
    $('.tk-qr-inner canvas').hide()
    $('.tk-qr-inner > img').remove()
    $('.tk-qr-inner').prepend(`<img src="${imgSrcRight}" style="width: 100px">`)
    s.remove()
  })



  let taoScanQr = ''
  let className = $('[class^=Price--tooltipImage]').attr('class')
  if (className) {
    appendCss(`.${className} { visibility: hidden } .gwd-qrlink-force-display { visibility: visible!important }`)
  }

  const hoverLoad = () => {
    if (taoScanQr) return
    require('common/models/appQrcode').get(13).then(r => { taoScanQr = r} )
  }
  $('[class^=Price--priceAction]').hover(hoverLoad)

  const selectorConfig = await require('common/aliPriceSelector').get()

  // 淘宝滑下去时可能会删除 Price--priceAction
  require('common/mutationObserver').observe(selectorConfig.panel, (mutations) => {
    const addedNodes = mutations.map(x => x.addedNodes).filter(x => x.length > 0)
    if (addedNodes.some(item => {
      return $(item).find('[class^=Price--tooltipImage]').length
    })) {
      $('[class^=Price--priceAction]').hover(hoverLoad)
    }
    if ($('.gwd-qrlink-force-display').length || !taoScanQr) {
      return
    }
    $('[class^=Price--tooltipImage]').attr('src', taoScanQr)
      .css('margin', '10px')
      .css('width', '80px')
      .css('height', '80px')
      .addClass('gwd-qrlink-force-display')
    $('[class^=Price--priceTooltip]').css('z-index', '999')
  }, {
    childList: true
  })

  require('standard/module/util').waitForConditionFn(() => {
    return taoScanQr
  }).then(() => {
    if ($('[class^=Price--tooltipImage]').length) {
      $('[class^=Price--tooltipImage]').attr('src', taoScanQr)
        .css('margin', '10px')
        .css('width', '80px')
        .css('height', '80px')
        .addClass('gwd-qrlink-force-display')
      $('[class^=Price--priceTooltip]').css('z-index', '999')
    }
  })
}

module.exports.init = async () => {
  if (['tmall', 'taobao', '360buy'].indexOf(G.site) === -1) {
    return
  }

  window.gwd_qr_replaced = false

  const e = document.createElement('DIV')
  if (G.site === '360buy') {
    $('.preview-wrap').append(e)
    qrReplaceJd()
  } else {
    qrReplaceTaobao()
    // await require('standard/module/util').waitForConditionFn(() => {
    //   return $('#cptklbox').length > 0
    // })
    // if ($('#cptklbox').length) {
    //   $('#cptklbox').after(e)
    // } else {
    //   $('.tb-gallery').append(e)
    // }
  }
  let tag = 7
  if (G.from_device === 'bijiago') {
    tag = 9
  }
  if (G.ss_name !== 'priceDog') {
    $('.gwd-qrlink').remove()
    new Vue({
      el: e,
      render: h => h(QRLink, {
        props: {
          tag: tag
        }
      })
    })
  }
  //
  // $('.tb-gallery').append(`
  //   <div style="position: absolute; width: 50px; height: 50px; background: aqua; top: 0; left: 0"></div>
  // `)
  if (G.aliSite) {
    $('.gwd-qrlink-left').remove()
    const e2 = document.createElement('DIV')
    let left = -113
    let bottom
    let style = {}
    let className = 'gwd-normal'
    if ($('[class^=Item2024--root--]').length) {
      // await require('common/commonUtil').sleep(0)
      // const position = require('common/commonUtil').getBodyOffset('.gwd-bottom-img-area-placeholder')
      // $('body').append(`<div class="gwd-bottom-img-area" style="position: absolute; left: ${position.left}px; top: ${position.top}px; width: ${position.width}px; height: ${position.height}px"></div>`)
      $('.gwd-bottom-img-area').append(e2)
      left = 0
      bottom = '0'
      className = 'gwd-tb-v3'
    } else if ($('[class^=PicGallery--mainPicWrap]').length) {
      $('[class^=PicGallery--mainPicWrap]').append(e2)
      left = -125
      bottom = '0'
    } else {
      $('.tb-item-info-l').append(e2)
    }

    let fixedEl = document.createElement('div')
    document.body.appendChild(fixedEl)
    new Vue({
      el: fixedEl,
      render: h => h(QRLinkLeft, {
        props: {
          tag: tag,
          left: 0,
          bottom: 0
        },
        style: style,
        class: className
      })
    })
    // new Vue({
    //   el: e2,
    //   render: h => h(className === 'gwd-tb-v3' ? QRLinkTbV3 : QRLinkLeft, {
    //     props: {
    //       tag: tag,
    //       left: left,
    //       bottom: bottom
    //     },
    //     style: style,
    //     class: className
    //   })
    // })
  }



  require('common/globalCondition').setMet('QRLinkReady')


  const isNewStyle = true
  // 天猫顶部联系客服
  if (isNewStyle) {
    $('.gwd-contact-link').remove()
    const div = document.createElement('DIV')
    if (isNewStyle) {
      $('.gwd-fake').remove()
      $('#purchasePanel > [class^=Actions--]').append('<div class="Actions--divider--2U8scvj gwd-fake"></div>')
      $('#purchasePanel > [class^=Actions--]').append(div)
    } else {
      $('.ww-light.ww-static').css({
        whiteSpace: 'nowrap',
      }).append(div)
    }
    window.contact = new Vue({
      el: div,
      render: h => h(QRLinkContactTmall, {
        props: {
          tag: 4,
          withLogo: isNewStyle
        }
      })
    })

    const globalConfig = await require('common/globalCondition').met('GwdConfig')

    let dom 
    await require('standard/module/util').waitForConditionFn(() => {
      dom = globalConfig.aliBuyQr.find(item => $(item).length)
      return !!dom
    })
    $(dom).append(`
    <dl class="gwd-qrlink" style="overflow: visible; width: 0; white-space: nowrap; line-height: 48px;">
      <dd style="overflow: initial; display: inline-flex; align-items: center; position: relative; top: -1px;">
        <div class="ww-light ww-static" style="display: inline-block; vertical-align: middle; overflow: inherit; width: 20px; height: 22px; line-height: 0; margin-left: 12px; margin-right: 4px">
          <img src="https://cdn.gwdang.com/images/extensions/wangwang@2x.png" alt="" style="width: 24px; height: 24px;"/>
        </div>
        <div id="gwd-link" style="display: inline-block; vertical-align: middle"></div>
      </dd>
    </dl>
    `)

    globalConfig.aliFloatPanel.forEach(config => {
      require('common/commonUtil').appendCss(`
        ${config.float} .gwd-qrlink { display: none!important }
        ${config.panel} { overflow: visible }
      `)
    })

    require('common/commonUtil').appendCss(`
      .gwd-qrlink { display: inline-block }
      .PurchasePanel--floatShow--1p-8tE4 .gwd-qrlink { display: none!important }
      .miniPanel .gwd-qrlink { display: none }

      .Actions--root--hwEujgc .gwd-qrlink { position: relative; top: 15px; line-height: 0!important }
    `)

    if (!$('#gwd-link').length) return

    new Vue({
      el: '#gwd-link',
      render: h => h(QRLinkContact, {
        props: {
          tag: ''
        }
      })
    })
  }

}



