<template>
  <div class="gwd-row pricedog-size-list" style="width: 100%">
    <ul :style="`width: ${lang === 'en'? '110': '82'}px;`" class="gwd-column">
      <li v-for="item in list"
          :key="item.name"
          :class="item.url === src ? 'active': ''"
          @click="src = item.url">{{ item.name }}</li>
    </ul>
    <div style="flex: 1" class="gwd-row">
      <iframe :src="src"
              style="margin-top: 12px; margin-right: 10px; margin-bottom: 16px; border: 1px solid #e6e9eb; flex: 1"></iframe>
    </div>
  </div>
</template>
<style scoped lang="less">
  .pricedog-size-list {
    ul {
      li {
        font-size: 12px;
        color: #64615d;
        margin-top: 13px;
        display: inline-block;
        cursor: pointer;
        height: 16px;
        line-height: 16px;
      }
      .active {
        color: #ff6132;
      }
    }
  }

  iframe {
    overflow-x: hidden;
  }
</style>
<script>
  const request = require('common/request')

  export default {
    data() {
      return {
        showing: '',
        list: [],
        src: '',
        lang: G.lang
      }
    },
    mounted() {
      let link = 'https://cdn.bijiago.com/js/configs/sizeHelp.json'
      if (G.lang === 'en') {
        link = 'https://cdn.bijiago.com/js/configs/sizeHelp_en.json'
      }
      request.get(link).then(res => {
        this.list = res
        this.showing = res[0].name
        this.src = res[0].url
      })
    }
  }
</script>


