module.exports.clear = () => {
  nowPrice = null;
}

const sitePriceElements = {
  '360buy': '.p-price .price'
}

module.exports.init = async (siteId, callback) => {
  if (location.host === 'www.amazon.de') {
    callback(G.dp.oldPrice)
    return;
  }
  if (nowPrice) {
    callback(nowPrice)
    return;
  }

  if (sitePriceElements[G.site]) {
    await Promise.race([
      require('common/commonUtil').sleep(3000),
      require('standard/module/util').waitForConditionFn(
        () => $(sitePriceElements[G.site]).text()
      )
    ])
  }

  let s = priceParsers[siteId];
  if (s instanceof Array) {
    template(s)(callback)
  } else if (s instanceof Object && s.prototype) {
    s()(callback)
  } else {
    callback()
  }
}



