const request = require('common/request')
const globalCondition = require('common/globalCondition')
const cnzz = require('common/cnzz')

const getRebate = (rate, dp_id, url) => {
  if (G.dp.rebate) {
    return new Promise(resolve => resolve({
      rebate: G.dp.rebate
    }))
  }
  return request.get(`${G.server}/extension/Coupon?rebate=1&${rate}&price=${G.dp.ori_price ? G.dp.ori_price: G.dp.price}&${dp_id}&${url}`)
}

module.exports = {
  async init() {
    if ($('body').hasClass('gwd_unfold') || $('html').hasClass('gwd_bottom')) {
      return
    }
    if (G.from_device === 'biyibi') {
      globalCondition.setMet('noOtherGiftMoney')
      return
    }
    let dp_id = G.dp.itemId
    if (G.aliSite) {
      dp_id = require('common/commonUtil').getParameterByName('id')
      if (G.site === 'tmall') {
        dp_id = dp_id + '-83'
      } else {
        dp_id = dp_id + '-123'
      }
    }
    dp_id = dp_id ? `dp_id=${dp_id}` : '';
    let url = encodeURIComponent(location.href)
    url = url ? `url=${url}` : '';
    let rate = 'rate='
    let price = G.dp.price
    let config = await request.rawGet('https://cdn.bijiago.com/js/configs/gwdang.json')
    if (G.site === '360buy' && config.allowDuomai) {
      require('common/extConsole').log('duomai before', G.dp.itemId)
      let duomaiData = await request.rawGet(`https://u.bijiago.com/gyp/jd/item?id=${G.dp.itemId.replace('-3', '')}`, false, 30000)
      require('common/extConsole').log('duomai after')
      if (typeof duomaiData === 'string') {
        duomaiData = JSON.parse(duomaiData)
      }
      rate = 'rate=' + (parseFloat(duomaiData.commission_rate) * 100).toFixed(2)
      price = duomaiData.price * (location.href.indexOf('debugExt') > -1 ? 10000: 1)
    }
    require('common/extConsole').log('duomai rate', rate)
    let t = $('#summary-tips').text()
    if (G.site === '360buy' && (t.indexOf('不可使用东券') > -1 || t.indexOf('不可使用京券、东券') > -1)) {
      globalCondition.setMet('noOtherGiftMoney')
      return
    }
    if (G.ss_name === 'priceDog') return
    if ($('.bjgou-subsidy-bar').length) return
    if ($('.bjgou-mini-coupon-bar').length) return
    getRebate(rate, dp_id, url).then(res => {
      if (!res.rebate) {
        globalCondition.setMet('noOtherGiftMoney')
        return
      }
      // if ($('.dsj-content').length) {
      //   $('.dsj-content').after('<div id="bjgou-subsidy"></div>')
      // } else {
      //   $('#bjgext_minibar').after('<div id="bjgou-subsidy"></div>')
      // }
      $('#bjg-coupon-placeholder').replaceWith('<div id="bjgou-subsidy"></div>')
      const Subsidy = require('../components/Subsidy.vue').default
      cnzz.logOnce((G.site === '360buy' ? 'jd': 'taobao') + 'GiftMoney:show')

      const jumpLink = G.site === '360buy' ? (res.url.replace('/?', '/index.html?') + '&lang=' + G.lang): require('common/productInfo').appendTbInfoForUrl(`https://tb.bijiago.com/extension/qrpage?${dp_id}&tag=9_chrome&rebate=1&discount=${res.rebate}&union=${G.union}&lang=${G.lang}`)

      new Vue({
        el: '#bjgou-subsidy',
        render: h => h(Subsidy, {
          props: {
            value: res.rebate,
            qr: false,
            url: jumpLink
          }
        })
      })

      $('#bijiago-banner-ad').remove()
      $('.bjg-coupon-space').after('<div id="bjgou-subsidy-bottom"></div>')
      const SubsidyBottom = require('../components/SubsidyBottom.vue').default
      new Vue({
        el: '#bjgou-subsidy-bottom',
        render: h => h(SubsidyBottom, {
          props: {
            value: res.rebate,
            qr: false,
            url: jumpLink
          }
        })
      })

      let text = '领红包下单'
      if (G.lang === 'zh-tr') {
        text = '領紅包下單'
      }
      require('common/components/JdFakeBtn').init(jumpLink, text)
    })
  }
}



