const template = require('vendor/template')
const request = require('common/request')

const sendFeedback = (i, m) => {
  let contact = m;
  let feedbackTxt = i;
  contact += 'bijiago'
  if (G.ss_name === 'priceDog') {
    contact += '-priceDog'
  }
  if (G.from_device === 'biyibi') {
    contact = m + '-biyibi插件用户'
  }
  let agent = navigator.userAgent.toLowerCase();
  let refer = encodeURIComponent(location.href)
  let url = `${G.server}/brwext/feedback?nick=${contact}&content=${feedbackTxt}&agent=${agent}&refer=${refer}&from_device=${G.from_device}&format=json`;
  request.get(url).then(function(msg) {
    if (msg && (msg.code == 1 || msg.status === 1)) {
      $('#feedback_detail textarea').val('')
      $('#feedback_detail input').val('')
      $('#feedback_detail').hide()
    }
  })
}

const renderDetail = () => {
  const lang = require('./language')
  const config = require('../lang/feedback.json')
  let html = require('art-template-loader!../views/fdback.html')
  $('.bjgext-feedback').append(template.compile(html)({
    content: lang.getString(config, 'content'),
    contact: lang.getString(config, 'contact'),
    mail: lang.getString(config, 'mail'),
    submit: lang.getString(config, 'submit'),
    showQQ: G.ss_name !== 'priceDog' && G.from_device !== 'biyibi'
  }))
  $('.bjgext-feedback').on('mouseenter', function() {
    if ($(window).width() - $('#bjgext_mainbar').outerWidth() < 150) {
      $('#feedback_detail').css('right', '0px')
    }
    $('#feedback_detail').show()
  })
  $('.bjgext-feedback').on('mouseleave', function() {
    $('#feedback_detail').hide()
  })
  $('#feedback_btn').on('click', () => {
    let info = $('#feedback_detail textarea').val()
    let mail = $('#feedback_detail input').val()
    if (!info) return;
    sendFeedback(info, mail)
  })
  // $('.bjgext-feedback').on('DOMNodeRemoved', function(e) {
  //   console.warn(e.target, ' was removed');
  // });
}


module.exports.init = () => {
  renderDetail()
}



