module.exports.init = (id, style) => {
  style = style || "mini";
  if (!id) return;
  let pidItemObj = pidPattern[id]
  let pidItem = pidItemObj[style];
  if (pidItem.length === 1) {
    pidItem = pidItem[0]
  } else {
    pidItem = pidItem[parseInt(Math.random() * 2)]
  }
  let pids = pidItem.pid;
  let size = pids.length;
  let pid1 = pids[parseInt(Math.random() * size)]
  let pitem = {
    token: pidItem.token,
    pid: pid1
  }
  return pitem;
}


