const QRLink = require('standard/module/components/QRLink.vue').default
const util = require('common/commonUtil')

const getId = url => {
  const id = util.getParameterByName('wareId', url)
  if (id) {
    return id + '.html'
  } else {
    return url.split('item.m.jd.com/product/')[1]
  }
}

module.exports = {
  async init() {
    if (window.gwd_G && G.from_device === 'bijiago') return
    if (!location.hostname.includes('.jd.com')) return
    if (location.hostname.includes('cfe.m.jd.com')) {
      const returnUrl = util.getParameterByName('returnurl')
      if (returnUrl.includes('jingfen.jd.com')) {
        const e = document.createElement('DIV')
        document.body.appendChild(e)
        let app = new Vue({
          el: e,
          render: h => h(QRLink, {
            ref: 'qr',
            props: {
              mode: 'gwd-mode-login gwd-cfe',
              dpId: dpId + '-3',
              tag: tag,
              url: d
            }
          })
        })
        require('common/commonUtil').appendCss(`.gwd-qrlink { position: relative; margin-top: 95px; }`)
        setTimeout(() => {
          app.$refs.qr.over()
        }, 0)
        return
      }
      const id = getId(returnUrl)
      if (id) {
        await require('standard/module/util').waitForConditionFn(() => $('.main-wrap').length)
        const link = 'https://item.jd.com/' + id
        const a = document.createElement('A')
        a.href = `${G.u_server}/union/go?site_id=3&target_url=${encodeURIComponent(link)}&union=${G.union}&column=h5_to_pc`
        a.innerHTML = `无需验证，直达商品详情页`
        a.style.width = '350px'
        a.style.height = '46px'
        a.style.lineHeight = '46px'
        a.style.textAlign = 'center'
        a.style.fontSize = '15px'
        a.style.border = '1px solid #e23a3a'
        a.style.borderRadius = '35px'
        a.style.color = '#e23a3a'
        a.style.display = 'inline-block'
        a.style.position = 'relative'
        a.style.top = '-36px'
        location.href = a.href
        $('.main-wrap').append(a)
      }
    }
    if (location.href.indexOf('plogin.m.jd.com') === -1) {
      return
    }
    setTimeout(() => {
      if (!document.querySelector('.policy_tip-checkbox')) {
        return
      }
      if (!document.querySelector('.policy_tip-checkbox').checked) {
        document.querySelector('.policy_tip-checkbox').click()
      }
    }, 2000)

    let d = decodeURIComponent(util.getParameterByName('returnurl'))
    let d2 = util.getParameterByName('returnurl', d)
    if (d2) {
      d = decodeURIComponent(d2)
    }
    if (d.includes('item.m.jd.com/product')) {
      const id = d.split('item.m.jd.com/product/')[1]
      const link = 'https://item.jd.com/' + id
      const img = require('common/assets/jdLink.svg')
      const a = document.createElement('A')
      a.style.position = 'absolute'
      a.style.left = '50%'
      a.style.bottom = '10%'
      a.style.transform = 'translate(-50%, -10%)'
      a.href = `${G.u_server}/union/go?site_id=3&target_url=${encodeURIComponent(link)}&union=${G.union}&column=h5_to_pc`
      a.innerHTML = `<img src="${img}" />`
      document.body.appendChild(a)
    }
    // if (location.href.indexOf('sku') === -1) {
    //   return
    // }
    let giftMoney = false
    if (location.href.indexOf('giftcoupon') > -1) {
      giftMoney = true
      //return
    }

    let dpId = util.getParameterByName('sku', d)
    if (!dpId) {
      dpId = '1'
    }

    if (d.includes('item.m.jd.com/product')) {
      return
    }

    const e = document.createElement('DIV')
    document.body.appendChild(e)
    let tag = 'login'
    if ((G.from_device === 'bijiago' || G.from_device === 'biyibi') && dpId !== '1') {
      tag = 7
    }

    let mode = giftMoney ? 'gwd-mode-login gwd-giftMoney': 'gwd-mode-login'

    //check if dpid contains character
    // if (dpId.match(/[a-zA-Z]/)) {
    //   dpId = 'fake'
    //   mode = 'gwd-mode-login gwd-fake-cfe'
    // }

    let app = new Vue({
      el: e,
      render: h => h(QRLink, {
        ref: 'qr',
        props: {
          mode: mode,
          dpId: dpId + '-3',
          tag: tag,
          url: d
        }
      })
    })
    setTimeout(() => {
      app.$refs.qr.over()
    }, 0)
  }
}



