const template = require('vendor/template')
const request = require('common/request')
const option = require('./option')
const util = require('./util')
const buildTaobaoUrl = require('common/buildTaobaoUrl')
const userData = require('common/userData')
// const replaceHref = require('common/replaceHref')
let tbhtml = require('art-template-loader!../views/tbDetail.html')
const globalCondition = require('common/globalCondition')
var globalProduct = {}


const renderTaobao = (name, title, price, tts) => {
  let view = require('art-template-loader!../views/itemProduct.html')
  var obj = {
    dp_id: name,
    price: parseFloat(price).toFixed(2),
    site_name: title
  }
  let dom = template.compile(view)({
    data: [obj],
    classname: 'bjgext-item-tb'
  })

  $('.bjgext-product-compare').append(dom).css('display', 'flex')
  option.autoWidth()
  addEvent(tts)
}
const editData = (data, id, tts) => {
  let newdata = [];
  for (let i = 0; i < data.length; i++) {
    if (!data[i].title || !data[i].pic_url || !data[i].price || !data[i].url) continue;
    data[i].img_url = data[i].pic_url;
    if (data[i].img_url.match(/_\d+x\d+/)) {
      let match = data[i].img_url.match(/_(\d+)x\d+/);
      if (match) {
        match = Number(match[1])
        if (match > 200) {
          data[i].img_url = data[i].img_url + '_100x100';
        }
      }
    } else {
      data[i].img_url = data[i].img_url + '_100x100';
    }
    // if (data[i].num_iid && !G.aliSite) {
    //   data[i].oldUrl = data[i].url;
    //   let type = data[i].type ? ('&type=' + data[i].type) : '';
    //   data[i].url = `https://browser.bijiago.com/coupon_redirect?id=${data[i].num_iid}${type}&column=bijiago&union=${G.union}`;
    // }
    data[i].rev_cnt = 0;
    newdata.push(data[i]);
  }
  return newdata;
}
const renderDetail = (dom, id, tts) => {
  var pages = 0;
  let width = $(window).width()
  let itemDetail = editData(globalProduct[id], id, tts);
  let len = itemDetail.length;
  let itemPageInfo = option.calDetailNum();
  let itemPageNum = itemPageInfo.num;
  if (len >= itemPageNum) {
    pages = Math.ceil(len / itemPageNum);
  }
  if (pages <= 1)
    width = 220 * len;

  let html = require('art-template-loader!../views/productDetail.html');
  if (id === "tmall" || id === "taobao")
    html = tbhtml;
  if (id === 'taobao') {
    itemDetail.forEach(x => {
      x.nick = x.item_location
    })
  }
  dom.append(template.compile(html)({
    data: itemDetail,
    'per': itemPageNum,
    'loadimg': G.loadImg,
    'b_width': width,
    pages: pages,
    sale: G.lang === 'en'? 'Sales:': '最近销量'
  }))
  if (len > itemPageNum) {
    dom.find('.bjgext-product-box').width(itemPageInfo.width)
    turnpageEvent(dom)
    option.loadImage(0, itemPageNum, dom.find('.bjgext-product-box'))
  } else {
    option.loadImage(0, len, dom.find('.bjgext-product-box'))
    option.setSimplePagePos(len, dom)
  }
  let lastClick = Date.now();
  dom.find('.bjgext-product-box').on('click', 'a', async function(e) {
    let now = Date.now()
    console.log('time between', now - lastClick);
    if (now - lastClick < 100) return;
    lastClick = now;
    e.preventDefault()
    console.log(e.target)
    let k = e.target
    let href = ''
    let id = ''
    if (k.tagName === 'IMG') {
      href = $(k).parents('a').attr('href')
      id = $(k).parents('a').attr('data-id')
    } else {
      href = k.href
      id = $(k).attr('data-id')
    }
    // https://u.bijiago.com/redirect/tao?id=623934330690&site=&source=common&from_device=bijiago&union=union_bijiago_mogu
    if (G.aliSite) {
      window.open(href)
    } else {
      window.open(`${G.u_server}/redirect/tao?id=${id}&site=&source=common&from_device=${G.from_device}&union=${G.union}`)
    }
    // if (href.indexOf('coupon') > -1) {
    //   console.log($(e.target).attr('data-id'))
    //   let pidConfig = require('bjgou/modules/pidConfig');
    //   let coupon = await require('common/getCouponNew').initWithDpAsync(id, pidConfig[G.union], 'compare');
    //   console.log('window open', Date.now())
    //   window.open(coupon.data.click_url2)
    // } else {
    //   window.open(href)
    // }
   })
}
const turnpageEvent = (dom) => {
  dom.find('.bjgext-turnleft .turnpage-btn').on('click', function() {
    option.changePage(-1, this);
  })
  dom.find('.bjgext-turnright .turnpage-btn').on('click', function() {
    option.changePage(1, this);
  })
}
const addEvent = (tts) => {
  var time1
  $('.bjgext-item-tb').on('mouseenter', function() {
    clearTimeout(time1);
    $('.bjgext-product-detail').hide();
    var dom = $(this);
    var detail = dom.find('.bjgext-product-detail');
    if (detail.length > 0) {
      detail.show();
    } else {
      let id = dom.attr('data-id');
      if (id) {
        renderDetail(dom, id, tts);
      }
    }
  })
  $('.bjgext-item-tb').on('mouseleave', function() {
    let that = this;
    time1 = setTimeout(() => {
      $(that).find('.bjgext-product-detail').hide();
    }, 100);
  })
  $('.bjgext-item-tb').on('click', function(e) {
    let href1 = $(e.target).attr('href')
    let href2 = $(e.target).parent().attr('href')
    if (href1 || href2) {
      href1 = href1 || href2;
      util.tongjiLog('tbuniontotal')
      if (href1.indexOf('redirect.simba.taobao.com') > -1) {
        util.tongjiLog('tbunionsuccess')
      }
    }
  })
}
const getTbres = (data, callback) => {
  if (location.href.indexOf('pcsitepp-fm.jd.com') > -1) return
  var msg = data.exact_arr;
  var code_server = '1';
  var code = data['code-server'];
  if (!code) {
    code = {};
    code_server = '0';
  }
  var price = (data.now.price) * 100;
  if (!price) {
    price = G.dp.price * 100;
  }
  var url = `${G.server}/brwext/tbres?union=${G.union}&url=${encodeURIComponent(msg.url)}&site=${msg.site}&isbn=${msg.isbn}&keywords=${encodeURIComponent(msg.keywords)}&brand=${encodeURIComponent(msg.brand)}&type=${encodeURIComponent(msg.type)}&price=${price}&class_id=${msg.class_id}&name=${encodeURIComponent(G.dp.name)}&code_brand_id=${code.brand_id}&code_clean_title=${encodeURIComponent(code.clean_title)}&code_code=${code.code}&code_display_brand=${encodeURIComponent(code.display_brand)}&code_brand=${encodeURIComponent(code.brand)}&code_class_id=${encodeURIComponent(code.class_id)}&code_price=${encodeURIComponent(code.price)}&code_spec=${encodeURIComponent(code.spec)}&code-server=${code_server}`;
  request.get(url).done((data) => {
    if (G.site == 'taobao' || G.site == 'tmall') {
      getUniqPid(data, (mm) => {
        callback(mm)
      })
    } else {
      getImgSearch(data, (mm) => {
        callback(mm)
      })
    }
  })
}

const renderTTSdata = (data) => {
  let tmalls = [],
    taobaos = [];
  for (let i = 0; i < data.length; i++) {
    data[i].pic_url = data[i].originalimage;
    data[i].price = data[i].cutprice.toFixed(2);
    if (data[i].sitename === '淘宝')
      taobaos.push(data[i])
    else
      tmalls.push(data[i])
  }
  let obj = {}
  if (taobaos.length > 0) {
    let lp = taobaos[0].price,
      hp = taobaos[taobaos.length - 1].price;
    if (lp === hp)
      obj.taobao = lp
    else
      obj.taobao = lp + '~' + hp;
    globalProduct.taobao = taobaos;
  }
  if (tmalls.length > 0) {
    let lp = tmalls[0].price,
      hp = tmalls[tmalls.length - 1].price;
    if (lp === hp)
      obj.tmall = lp
    else
      obj.tmall = lp + '~' + hp;
    globalProduct.tmall = tmalls;
  }
  return obj;
}
const getImgSearch = function(msg, callback) {
  msg = buildTaobaoUrl.buildCommon(msg)
  let exact_arr = userData.get('dp_data') && userData.get('dp_data')['exact_arr']
  if (exact_arr.type && exact_arr.brand && (!msg.taobao.sort || !msg.tmall.sort)) {
    // 在京东有brand 有比价结果的情况下， 不走图片检索
    callback(msg);
    return;
  }
  require('common/commonTaobaoImg').init((data) => {
    if (data) {
      if (msg.tmall.sort) msg.tmall = {}
      if (data.tmall.length > 0) {
        msg.tmall.min_price = data.tmall[0].price
        msg.tmall.max_price = data.tmall[data.tmall.length - 1].price
        msg.tmall.store = data.tmall
        msg.tmall.product = data.tmall
      }
      if (msg.taobao.sort) msg.taobao = {}
      if (data.taobao.length > 0) {
        msg.taobao.product = data.taobao
        msg.taobao.store = data.taobao
        msg.taobao.min_price = data.taobao[0].price
        msg.taobao.max_price = data.taobao[data.taobao.length - 1].price
      }
      callback(msg)
    } else {
      callback(msg)
    }
  })
}
const getUniqPid = function(msg, callback) {
  msg = buildTaobaoUrl.buildCommon(msg)
  let exact_arr = userData.get('dp_data') && userData.get('dp_data')['exact_arr']
  require('common/commonTaobaoUniqPid').getTaobaouniqData(data => {
    if (data && data.img_s && exact_arr.type && exact_arr.brand && (!msg.taobao.sort || !msg.tmall.sort)) {
      callback(msg)
      return;
    }
    if (data) {
      if (msg.tmall.sort) {
        msg.tmall = {}
      }
      if (data.tmall.length > 0) {
        msg.tmall.min_price = data.tmall[0].price
        msg.tmall.max_price = data.tmall[data.tmall.length - 1].price
        msg.tmall.store = data.tmall
        msg.tmall.product = data.tmall
      }
      if (msg.taobao.sort) {
        msg.taobao = {}
      }
      if (data.taobao.length > 0) {
        msg.taobao.product = data.taobao
        msg.taobao.store = data.taobao
        msg.taobao.min_price = data.taobao[0].price
        msg.taobao.max_price = data.taobao[data.taobao.length - 1].price
      }
      callback(msg)
    } else {
      callback(msg)
    }
  })
}

module.exports.init = (data) => {
  if (require('common/haitao').isHaitao() && G.ss_name === 'priceDog') {
    return
  }
  getTbres(data, info => {
    info.ss = 0;
    if (!(info.tmall instanceof Array) && info.tmall.product && info.tmall.product.length > 0) {
      if (!G.showMainbar && $('#bjgext_mainbar').length) {
        require('common/extConsole').log('mainbar flex c')
        $('#bjgext_mainbar').css('display', 'flex');
        G.showMainbar = true;
        util.tongji('mainbar', 'show')
        require('common/extConsole').log('mainbar', $('#bjgext_mainbar')[0])

      }
      var price = info.tmall.min_price;
      if (info.tmall.min_price === info.tmall.max_price) {
        price = info.tmall.min_price;
      }
      renderTaobao('tmall', '天猫', price)
      info.ss++;
      info.tmm = true;
      require('./dpCoupon2').init(info.tmall.product, 'tmall', true, info.tmall.min_price)
      globalProduct.tmall = info.tmall.product;
      // replaceHref.init('tmall', globalProduct.tmall)
    } else {
      require('common/globalCondition').setMet(`AliProducttmall`, [])
    }
    if (info.taobao || info.tmall) {
      require('common/log')('tbcompare:show')
    }
    if (!(info.taobao instanceof Array) && info.taobao.product && info.taobao.product.length > 0) {
      if (!G.showMainbar) {
        require('common/extConsole').log('mainbar flex f')
        $('#bjgext_mainbar').css('display', 'flex');
        G.showMainbar = true;
        util.tongji('mainbar', 'show')
      }
      var price = info.taobao.min_price;
      if (info.taobao.min_price === info.taobao.max_price) {
        price = info.taobao.min_price;
      }
      renderTaobao('taobao', '淘宝', price)
      info.ss++;
      info.tbb = true;
      require('./dpCoupon2').init(info.taobao.product, 'taobao', true, info.taobao.min_price)
      globalProduct.taobao = info.taobao.product;
      // replaceHref.init('taobao', globalProduct.taobao)
    } else {
      require('common/globalCondition').setMet(`AliProducttaobao`, [])
    }
    userData.set('tbData', info)
  })
}

module.exports.init2 = data => {
  if (require('common/haitao').isHaitao() && G.ss_name === 'priceDog') {
    return
  }
  let info = renderTTSdata(data)
  if (info.taobao) {
    renderTaobao('taobao', '淘宝', info.taobao, true)
    if (!G.showMainbar) {
      require('common/extConsole').log('mainbar flex a')
      $('#bjgext_mainbar').css('display', 'flex');
      G.showMainbar = true;
      util.tongji('mainbar', 'show')
    }
  }
  if (info.tmall) {
    renderTaobao('tmall', '天猫', info.tmall, true)
    if (!G.showMainbar) {
      require('common/extConsole').log('mainbar flex b')
      $('#bjgext_mainbar').css('display', 'flex');
      G.showMainbar = true;
      util.tongji('mainbar', 'show')
    }
  }
  if (info.taobao || info.tmall) {
    require('common/log')('tbcompare:show')
  }
}



