<template>
  <div class="bjgou-trend-qr-right" style="width: 100%; display: flex; align-items: center; height: 100%; flex-direction: column;">
    <div style="flex: 1;"></div>
    <span @click="favorClick" v-if="login" :class="'bjgou-bottom-favor ' + (productChecked ? '': 'bjgou-bottom-notchecked')">{{ productChecked ? '取消降价提醒': '设置降价提醒' }}</span>
    <img v-if="login" src="https://cdn.bijiago.com/images/extensions/bijiago/bjgou-qr-wechat.png" alt="" style="width: 111px; height: 111px; box-sizing: border-box; margin-top: 14px; image-rendering: crisp-edges">
    <span v-if="login" style="margin-top: 15px; font-size: 16px; color: #ffae45; font-weight: bold">微信扫码关注</span>
    <span v-if="login" style="margin-top: 8px; font-size: 14px; color: #6b6761">商品降价实时提醒</span>
    <span v-if="!login" class="bjgou-login-btn" @click="goLogin()">登录</span>
    <span v-if="!login" style="margin-top: 6px; font-size: 12px; color: #8c847b; display: inline-block;">商品降价实时提醒</span>
    <div style="flex: 1;"></div>
  </div>
</template>
<style lang="less" scoped>
  .bjgou-login-btn {
    display: inline-block;
    width: 228px;
    height: 28px;
    line-height: 28px;
    background:linear-gradient(270deg,rgba(255,205,71,1) 0%,rgba(255,159,34,1) 100%);
    border-radius:16px;
    cursor: pointer;
    /*margin-top: 112px;*/
    text-align: center;
    font-size: 12px;
    color: white;
  }

  .bjgou-bottom-favor {
    margin-top: 35px;
    width: 110px;
    height: 24px;
    line-height: 24px;
    text-align: center;
    border-radius: 14px;
    border: 1px solid #ffae45;
    display: block;
    color: #ffae45;
    font-size: 12px;
    cursor: pointer;
  }

  .bjgou-bottom-notchecked {
    background: #ffae45;
    color: white
  }
</style>
<script>
  const user = require('../modules/user')
  const globalCondition = require('common/globalCondition')

  export default {
    data() {
      return {
        productChecked: G.productChecked,
        login: G.userLogin
      }
    },
    methods: {
      async checkCollected() {
        let dpId = await globalCondition.met('GwdDpIdGot')
        let token = await user.hasUserToken()
        if (!token) {
          G.userLogin = false
          this.login = false
          G.trigger('bjgouFavor')
          return
        }
        G.userLogin = true
        this.login = true
        user.checked(dpId).then(res => {
          if (res.code === -3) {
            G.userLogin = false
            this.login = false
            G.trigger('bjgouFavor')
            return
          }
          if (res.code === 0) {
            this.productChecked = false
            G.productChecked = false
            G.trigger('bjgouFavor')
            return
          }
          this.productChecked = res.data.id
          G.productChecked = res.data.id
          G.trigger('bjgouFavor')
          // G.productChecked = res.data
        })
      },
      async favorClick() {
        let dpId = await globalCondition.met('GwdDpIdGot')
        if (!this.productChecked) {
          let res = await user.collect(dpId)
          console.log(res)
          if (res.code === 1) {
            this.productChecked = res.data.id
            G.productChecked = res.data.id
          }
        } else {
          let res = await user.del(this.productChecked)
          console.log(res)
          if (res.code === 1) {
            this.productChecked = false
            G.productChecked = false
          }
        }
        G.trigger('bjgouFavor')
      },
      goLogin() {
        //location.href = `https://i.bijiago.com/UserUnion/Authorize?utype=2&app_platform=ext&_referer=${encodeURIComponent(location.href)}`
        user.goLogin()
      }
    },
    created() {
      console.log('created execute')
      let k = setInterval(async () => {
        k++
        if (k > 10) return
        let token = await user.hasUserToken()
        if (!token) {
          G.userLogin = false
          this.login = false
          G.trigger('bjgouFavor')
          return
        }
        G.userLogin = true
        this.login = true
      }, 1000)
      this.checkCollected()
      G.on('bjgouFavor', () => {
        this.productChecked = G.productChecked
        this.login = G.userLogin
      })
    }
  }
</script>


