const pidConfig = require('./pidConfig')
const request = require('./request')


module.exports.init = (id, style, callback) => {
  let pidInfo = pidConfig.init(id, style);
  let dp_id = G.dp.itemId;
  if (!dp_id) {
    if (G.site === 'taobao-ju') {
      dp_id = location.href.match(/item_id=(\d+)/)[1];
    }
  }
  getInfo(dp_id, pidInfo, callback)
};

module.exports.initWithDp = (dpId, id, style, callback) => {
  let pidInfo = pidConfig.init(id, style)
  getInfo(dpId, pidInfo, callback)
};

module.exports.initWithDpAsync = (dpId, id, style) => {
  let pidInfo = pidConfig.init(id, style);
  return new Promise(resolve => {
    getInfo(dpId, pidInfo, resolve)
  });
};

const getInfo = (dpId, pidInfo, callback) => {
  let dp_id = dpId;
  if (!dp_id) return;
  dp_id = `${dp_id}`;
  dp_id = dp_id.replace('-83', '')
  if (!pidInfo) pidInfo = { token: 'visit', pid: 'show' };
  let url = `https://q.apptimes.cn/union/coupon/${pidInfo.token}?pid=${pidInfo.pid}&good_id=${dp_id}`;
  request.getCouponFromUrl(url).then(res => {
    let data = res;
    //console.log(res)
    if (data && data.data) {
      data.data.reqid = dp_id;
      data.data.click_url2 = `${G.u_server}/?url=${encodeURIComponent(data.data.click_url)}&union=${G.union}`
      if (G.from_device === 'bijiago' && G.aliSite) {
        data.data.click_url2 = `https://tb.${G.ss_name === 'priceDog' ? 'pricedog': 'bijiago'}.com/extension/qrpage?union=${G.union}&dp_id=${dpId}&tag=9_chrome&discount=${data.data.coupon.coupon_money}`
      }
      if (G.from_device === 'biyibi' && G.aliSite) {
        data.data.click_url2 = `https://tb.biyibi123.com/extension/qrpage?union=${G.union}&dp_id=${dpId}&tag=9_chrome&discount=${data.data.coupon.coupon_money}`
      }
    }
    callback(res)
  })
}



