<template>
  <div class="bjg-page-protect-button" v-show="ready && (!user || !enabled)" @mouseover="over">
    <img src="../assets/PriceProtectPageButton@2x.png" alt="" style="width: 186px; height: 46px;">
    <div class="bjg-box">
      <PriceProtectAuthLoginRequest
          @userAgreed="setEnable()"
          :center="true"
          :login="user"></PriceProtectAuthLoginRequest>
    </div>
  </div>
</template>
<style>
  .bjgext-item-dp {
    display: none;
  }
</style>
<style scoped lang="less">
  .bjg-page-protect-button {
    position: absolute;
    top: 0;
    left: 310px;
    .bjg-box {
      z-index: 99;
      display: none;
      background: white;
      border: 1px solid #f1f1f1;
      box-shadow: 0px 2px 4px rgba(176,176,176,0.5);
      left: -65px;
      position: relative;
      padding: 5px;
    }
  }

  .bjg-page-protect-button:hover {
    .bjg-box {
      display: block;
    }
  }
</style>
<script>
  const cnzz = require('common/cnzz')
  const client = require('common/background/bgClient')
  import { mapState } from 'vuex'
  import PriceProtectAuthLoginRequest from './PriceProtectAuthLoginRequest.vue'

  export default {
    components: { PriceProtectAuthLoginRequest },
    data() {
      return {
        ready: false
      }
    },
    methods: {
      async init() {
        await require('common/globalCondition').met('PriceProtectReady')
        this.ready = true
        if ((!this.user || !this.enabled)) {
          cnzz.log('价格保护中心按钮', '引导提示展示')
        }
      },
      setEnable() {
        this.enable()
        document.body.dispatchEvent(new Event('bjgWindowOpen'))
      },
      over() {
        cnzz.logOnce('价格保护中心按钮', '展示下拉框')
      },
      enable() {
        cnzz.log('价格保护', '用户手动开启')
        client.get('/setStorage', {enabled: true})
        this.$store.commit('user/setState', {
          priceProtectEnabled: true
        })
      }
    },
    computed: mapState({
      userName: state => state.user.userName,
      user: state => state.user.userLogin,
      hasWx: state => state.user.userHasWx,
      enabled: state => state.user.priceProtectEnabled
    }),
    mounted() {
      this.init()
    }
  }
</script>


