const md5 = require('js-md5')
const request = require('common/request')
const bgClient = require("../background/bgClient");

module.exports = {
  async get(itemId, skuId) {
    let _m_h5_tk = await bgClient.get('/getCookie', {
      url: 'https://www.taobao.com',
      name: '_m_h5_tk'
    })
    if (location.hostname.includes('.taobao.com')) {
      let tk = ''
      const t = setInterval(() => {
        const token = document.cookie.match(/_m_h5_tk=([^;]+)/)[1].split("_")[0]
        if (token !== tk) {
          tk = token
          bgClient.get('/setStorage', {
            taobaoTk: {
              tk: tk,
              time: Date.now()
            }
          })
          clearInterval(t)
        }
      }, 500)
    }
    if (!_m_h5_tk) {
      const localTkResult = await bgClient.get('/getStorage', { key: 'taobaoTk' })
      if (localTkResult && localTkResult.tk && Date.now() - localTkResult.time < 3600000) {
        _m_h5_tk = {
          value: localTkResult.tk
        }
      }
    }
    if (!_m_h5_tk) {
      return
    }
    const token = _m_h5_tk.value.split('_')[0]
    const api = 'mtop.tmw.affiliate.highvalueuser.sameitem.get'
    const data = {
      itemId: itemId.replace('-83', '').replace('-123', ''),
      skuId
    }
    const t = Date.now()
    return request.requestXHR(request.makeUrl('https://acs.m.taobao.com', `/h5/${api}/1.0/`, {
      jsv: '2.6.3',
      appKey: 12574478,
      t: t,
      sign: md5(`${token}&${t}&12574478&${JSON.stringify(data)}`),
      type: 'originaljson',
      v: '1.0',
      dataType: 'json',
      api: api,
      data: JSON.stringify(data)
    }))
  }
}



