const extConsole = require('common/extConsole')
const bgClient = require('common/background/bgClient')


extConsole.log('pricedog start', location.href);
(async function() {
  require('bjgou/modules/util').settings('lang', 'zh-tr')
  const Vuex = require('vuex')
  Vue.use(Vuex)
  'use strict'
  require('bjgou/modules/config-biyibi.js')
  require("common/siteInfo").init()
  require('common/infoCollect/collect').init();
  require('bjgou/modules/util').tongjiLog('bdvisit')

  G.allowBackgroundRequest = true
  require('bjgou/modules/priceProtect').init()
  let installSource = await bgClient.get('/getStorage', {
    key: 'install_source'
  })
  if (installSource) {
    G.union = 'union_bijiago_' + installSource
  }
  
  if (location.href.indexOf('/installComplete') > -1) {
    let _PD_UTMSEO_KEY = localStorage.getItem('_PD_UTMSEO_KEY')
    let _PD_UTMSEO_TIM = localStorage.getItem('_PD_UTMSEO_TIM')
    require('common/communicate').trigger({
      type: 'setToken',
      _PD_UTMSEO_KEY: _PD_UTMSEO_KEY,
      _PD_UTMSEO_TIM: _PD_UTMSEO_TIM
    })
  }
  // require('bjgou/modules/priceProtect').init()
  if (G.pageInfo.type === 0) {
    require('common/extConsole').log(location.href)
    let failUrl = location.href
    return;
  }
  var cnzz = require('common/cnzz')
  if (cnzz && G.from_type !== 'bjg_chm') cnzz.init(G.bd_cnzz);
  if (location.host === 'm.fine3q.com')
    require('bjgou/modules/bdyjhtLog').init()
  require('common/polyfillx');
  require('common/firstVisit').init(() => {
    if (require('bjgou/modules/hasBuild')) return;
    if (G.site == 'iqiyi') G.set_force = false;
    require('standard/module/jdLoginQrLink').init()
    require('standard/module/taobaoLoginQrLink').init()
    require('common/forbidCity').common((data) => {
      if (data && data.result instanceof Array) {
        G.set_force = false;
        G.forbidCoupon = true;
      } else if (data && data.result) {
        let result = data.result.address;
        if (result.indexOf('北京') > -1 || result.indexOf('上海') > -1 || result.indexOf('广州') > -1 || result.indexOf('深圳') > -1 || result.indexOf('杭州') > -1) {
          G.set_force = false;
          G.forbidAd = true;
        } else if (result.indexOf('南京') > -1) {
          G.set_force = false;
        }
        if (result.indexOf('北京') > -1 || result.indexOf('上海') > -1) {
          G.forbidTkl = true;
        }
        if (result.indexOf('北京') > -1 || result.indexOf('杭州') > -1) {
          G.forbidCoupon = true;
          G.forbidApp = true;
        }
      }

      require('common/parseprice').getRate(() => {
        console.log('pricedog rate got', location.href)
        const main = require("bjgou/modules/main")
        console.log('pricedog main ', main)
        main.init();
      })
    })
  })();
})()



