const timeFormat = (date) => {
  let x = new Date(date);
  let year = x.getFullYear();
  if (G.IE7 || G.IE8) {
    year = x.getFullYear();
  }
  let month = x.getMonth() + 1;
  let day = x.getDate();
  if (month < 10) {
    month = '0' + month + '';
  }
  if (day < 10) {
    day = '0' + day + '';
  }
  // let hour = x.getHours();
  let timeStr = `${year}/${month}/${day}`;
  return timeStr;
}
const supplementPoint = (data) => {
  if (data.length === 1) {
    data.unshift([data[0][0] - 1000, data[0][1]])
  }
  console.log(data)
  return data;
  // let newdata = []
  // for (let i=0; i<data.length-1; i++) {
  //   newdata.push(data[i])
  //   let days = parseInt( (data[i+1][0] - data[i][0]) / (3600*1000*24) );
  //   if (days >= 2) {
  //     for (let j=1; j<days; j++) {
  //       newdata.push([
  //         data[i][0] + (3600*1000*24)*j, data[i][1]
  //       ])
  //     }
  //   }
  // }
  // newdata.push(data[data.length-1])
  // return newdata;
}
module.exports = (data, opt = null) => {
  // console.log(data)
  try {
    var obj = {
      chart: {
        renderTo: data.el,
        type: 'line',
        style: {
          marginLeft: '4px',
          paddingLeft: '0px',
          marginTop: '0',
          paddingTop: '0px',
          marginBottom: '0px',
          paddingBottom: '0px'
        },
        events: {
          load: function() {
            this.xAxis[0].update({
              max: this.xAxis[0].max + 3600 * 1000 * 24 * 10
            });
          }
        }
      },
      credits: {
        enabled: false
      },
      colors: [
        '#d150f0', '#f0b507', '#3ebdf7'
      ],
      title: {
        text: data.title || '',
        x: -20,
        style: {
          color: '#2f7ed8'
        }
      },
      xAxis: {
        type: 'datetime',
        dateTimeLabelFormats: {
          day: '%Y/%m',
          week: '%Y/%m',
          month: '%Y/%m'
        },
        minTickInterval: 3600 * 24 * 1000 * 30,
        plotLines: [{
          color: 'red',
          dashStyle: 'longdashdot',
          value: 3,
          width: 2
        }],
        minorGridLineColor: "#dfdfdf",
        labels: {
          rotation: -25,
          y: 30,
          style: {
            fontSize: '12px',
            fontFamily: 'Arial',
            color: '#323333'
          },
          align: 'center'
        }
      },
      yAxis: {
        title: {
          text: '',
          rotation: 0,
          align: 'high',
          y: -16,
          x: -12,
          offset: -55,
          margin: 0,
          style: {
            color: '#585858'
          }
        },
        plotLines: [{
          value: 0,
          width: 1,
          color: '#808080'
        }],
        gridLineColor: '#c0d0e0',
        minorGridLineColor: '#dfdfdf',
        tickPixelInterval: 50
      },
      tooltip: {
        xDateFormat: '%Y-%m-%d',
        shared: true,
        valueDecimals: 2,
        valuePrefix: '',
        useHTML: true,
        valueSuffix: ' 万',
        borderColor: 'none',
        padding: 20,
        formatter: function() {
          let timeStr = timeFormat(this.x);
          let result = `<table style="margin-left:12px"><tr><td width="100%" colspan="8" style="text-align: center;font-weight: bold;font-family: Arial;font-size:14px">${timeStr}</td></td></tr>`;
          for (let i = 0; i < this.points.length; i++) {
            let priceStr = parseFloat(Number(this.points[i].y).toFixed(2)) + '万';
            result += `<tr><td style="width: 80px; text-align: left"><span style="color: ${this.points[i].point.series.color};font-size:12px;font-family:arial;float:none;margin-right:5px;">●</span>${this.points[i].point.series.name}</td>
          <td style="padding-left:4px;">${priceStr}</td></tr>`;
          }
          result += '</table>';
          return result;

        }
      },
      plotOptions: {
        series: {
          marker: {
            radius: 1,
            states: {
              hover: {
                radius: 2
              }
            }
          },
          lineWidth: 1.5,
          shadow: false,
          states: {
            hover: {
              lineWidth: 1
            }
          }
        }
      },
      legend: {
        enabled: true,
        borderWidth: 0,
        verticalAlign: 'top',
        x: 228,
        y: -8,
        itemStyle: {
          color: '#585858',
          fontWeight: 'normal',
          fontSize: '14px',
          marginBottom: '0px'
        },
        symbolWidth: 12,
        symbolHeight: 3,
        itemMarginBottom: 0,
        itemMarginTop: 0,
        margin: 12
      },
      series: []
    }
    if (opt) {
      obj = opt
    }
    obj.title.style.display = 'none';
    var msg = data.msg
    if (data.mainTrend) {
      obj.series[0] = {
        visible: true,
        name: '房源价格走势',
        marker: {
          symbol: 'circle'
        },
        data: []
      }
      obj.series[0].data = msg.price_history
      obj.series[0].data = supplementPoint(obj.series[0].data)
      obj.colors = ['#3ebdf7']
      obj.legend.enabled = false;
    } else
    {
      let index1 = 0,
        index2 = 0,
        index3 = 0;
      let colorArr = []
      if (msg.onsale.length >= 1) {
        obj.series[index1] = {
          visible: true,
          name: '挂牌单价',
          marker: {
            symbol: 'circle'
          },
          data: []
        }
        index2++
        index3++
        colorArr.push('#d150f0')
        obj.legend.x = obj.legend.x - 48;
        for (let i = 0; i < data.msg.onsale.length; i++) {
          let arr = new Array(2)
          arr[0] = data.msg.onsale[i][0] * 1000;
          arr[1] = Math.round(data.msg.onsale[i][1] * 100) / 100;
          obj.series[index1].data.push(arr)
        }
        obj.series[index1].data = supplementPoint(obj.series[index1].data)
      }
      if (msg.dealt.length >= 1) {
        obj.series[index2] = {
          visible: true,
          name: '成交单价',
          marker: {
            symbol: 'circle'
          },
          data: []
        }
        index3++
        colorArr.push('#f0b507')
        obj.legend.x = obj.legend.x - 48;
        for (let i = 0; i < data.msg.dealt.length; i++) {
          let arr = new Array(2)
          arr[0] = data.msg.dealt[i][0] * 1000;
          arr[1] = Math.round(data.msg.dealt[i][1] * 100) / 100;
          obj.series[index2].data.push(arr)
        }
        obj.series[index2].data = supplementPoint(obj.series[index2].data)
      }
      obj.yAxis.title.text = '单位(万)'
      obj.colors = colorArr;
    }
    new Highcharts.Chart(obj);
  } catch (e) {}
}



