<template>
  <div class="minibar-btn-box gwd-row gwd-align gwd-jcc" style="display: inline-flex">
<!--    <em class="setting-bg collect_mailout_icon" :class="{favored: checked}"></em>-->
    <em class="gwd-favor-icon" :class="{'gwd-favored': checked}"></em>
    <span>{{ checked ? '已添加提醒': '降价提醒' }}</span>
  </div>
</template>
<style scoped lang="less">
.gwd-favor-icon {
  display: inline-block;
  width: 24px;
  height: 24px;
  background: url(../assets/favorEmpty.svg) no-repeat;
  &.gwd-favored {
    background: url(../assets/favorFull.svg) no-repeat;
  }
}

.ms-tab-enter .gwd-favor-icon {
  background: url(../assets/favorFull.svg) no-repeat;
}
</style>
<script>
  import { mapState } from 'vuex'

  export default {
    computed: mapState({
      checked: state => state.priceRemind.collected,
      id: state => state.priceRemind.instanceId,
    })
  }
</script>




