module.exports.init = async () => {
  disPrice = 0
  if (['360buy', 'suning', 'tmall', 'dangdang', 'taobao'].indexOf(G.site) === -1) return
  let instanceId = G.instanceId
  let perform = function() {
    var siteName = G.site;
    let siteId = detect.getSiteId(siteName)
    priceParser.init(siteId, async function(price) {
      await require('common/globalCondition').met('productInfoReady')
      if (!G.dp) return
      if (G.instanceId && instanceId !== G.instanceId) return
      if (price && price > 0) {
        G.dp.oldPrice = price;
        G.dp.price = price;
      }
      init2()
    });
  };
  if (G.site === '360buy') {
    if (location.hostname.includes('.jd.com')) {
      await require('standard/module/util').waitForConditionFn(() => ($('.prom-item').length || $('.quan-item').length ))
    }
    perform()
  } else {
    setTimeout(perform, 4000)
  }

}



