const template = require('vendor/template')
const request = require('common/request')
const cnzz = require('common/cnzz')

let posDict = {
  'taobao': '#J_Social',
  'tmall': '#J_DetailMeta .tm-action.tm-clear'
}
let tokenCache

module.exports.init = () => {
  if (G.from_device.indexOf('bijiago') > -1 && $('html').hasClass('gwd_taobao_ju')) return ;
  if (window.bjd_tkl_exist && window.bjd_tkl_exist.indexOf(G.from_device) === -1) {
    return ;
  }
  window.bjd_tkl_exist = G.from_device;
  if (G.forbidTkl) return;
  if (location.host.indexOf('taobao') === -1 && location.host.indexOf('tmall') === -1) {
    return;
  }

  if (G.site === 'taobao-ju') {
    if ($('#bjg-tkl').length) {
      $('#bjg-tkl').remove();
    }
    renderJu();
    return ;
  }

  render()
}

const renderJu = () => {
  const html = require('art-template-loader!./views/copyTklJu.html')
  const res = template.compile(html)({
    s_server: G.s_server
  });
  window.$ = $;
  $('.botbar .operation').append(res)

  addEventJu()
};

const addEventJu = () => {
  let tklOK = false;
  $('#bjg-tkl').on('click', e => {
    if (tklOK) {
      clipboard()
      e.preventDefault()
      return;
    } else {
      cnzz.log("gettklinfo");
      getTkl(function(data) {
        if (data) {
          $('#gwd-tkl-text').text("点击复制淘口令")
          tklOK = true;
          let dptle = getTbTle()
          let newTxt = '7' + data
          $('#box_btn').text(newTxt)
          $('.gggbox-input').val(newTxt)
        } else {
          // $('.cptkl-remind-err').show()
          cnzz.log("gettklerr");
          $('#bjg-tkl').addClass('gwd-notkl-error')
        }
      })
    }
    e.preventDefault()
  })
};

const getTkl = (callback) => {
  if (tokenCache) {
    callback(tokenCache)
    return;
  }
  // callback(false); return
  // let id = location.href.match(/id=(\d+)/)[1];
  // if (G.site === 'taobao-ju') {
  //   id = location.href.match(/item_id=(\d+)/)[1];
  // }
  let id = require('common/commonUtil').getParameterByName('id')
  if (!id) id = require('common/commonUtil').getParameterByName('item_id')
  let pic = G.dp.pic
  // let s = $('#J_UlThumb img')
  // if (s.length) {
  //   pic = s[s.length - 1].src
  // }

  let url =
    `${G.server}/extension/TaoKL?id=${id}&title=${encodeURIComponent(G.dp.name.trim())}&img=${encodeURIComponent(pic)}&price=${G.dp.price}&shopName=${encodeURIComponent(G.dp.shopName.trim())}&sellAmount=${encodeURIComponent(G.dp.shopAmount)}`
  if (G.ss_name === 'priceDog') {
    url = `${G.u_server}/redirect/tao?id=${id}&format=json&tkl=1`
  }
  request.get(url).then(function(data) {
    if (data && data.ios_token) {
      tokenCache = data.ios_token;
      callback(data.ios_token)
    } else {
      callback()
    }
  }).catch(() => {
    callback()
  })
}
const getTbTle = () => {
  let tle = ''
  if (G.site === 'taobao') {
    tle = $('#J_Title h3').text().trim()
  } else if (G.site === 'taobao-ju') {
    tle = $('.title').text().trim()
  } else {
    tle = $('.tb-detail-hd>h1').text().trim()
  }
  return tle;
}

const render = async () => {
  $('.gwd-bottom-img-area').remove()
  let html = require('art-template-loader!./views/copyTkl.html')
  if (G.lang === 'zh-tr') {
    html = require('art-template-loader!./views/copyTklTr.html')
  }
  // let pos = posDict[G.site];
  let str = 'is_tb_site'
  if (G.site === 'tmall')
    str = 'is_tm_site'

  let posContainer = '[class^=PicGallery--mainPicWrap--]',
  htmlContainer = `<div class="gwd-bottom-img-area" style="height: 70px; position: absolute; z-index: 9999; background: white; bottom: -100px; width: 100%"></div>`
  if (!$('[class^=Item2024--main--]').length) {
    posContainer = '[class^=PicGallery--root--]'
    htmlContainer = `<div class="gwd-bottom-img-area" style="height: 70px; position: relative; z-index: 9999; background: white; top: 10px; width: 100%"></div>`
  }
  const config = await require('common/globalCondition').met('GwdConfig')
  if (!$(posContainer).length) {
    require('common/extConsole').warn('no posContainer');
    await require('standard/module/util').waitForConditionFn(() => {
      posContainer = config.tklContainer.find(item => $(item).length)
      htmlContainer = `<div class="gwd-bottom-img-area" style="height: 70px; position: absolute; z-index: 9999; background: white; bottom: -100px; width: 100%"></div>`
      return !!posContainer
    })
  }
  if ($('[class^=GoLoginInfo--]').length) {
    posContainer = config.loginTklContainer.find(item => $(item).length)
    htmlContainer = `<div class="gwd-bottom-img-area" style="position: absolute; top: 0; z-index: 9999; width: 500px; left: 110px;"></div>`
  }
  $(posContainer).append(htmlContainer)
  // await require('standard/module/util').waitForConditionFn(() => $('.gwd-bottom-img-area').length > 0)
  let pos = '.gwd-bottom-img-area'
  if ($(pos).length > 0) {
    $('.' + str).remove()
    $(pos).append(template.compile(html)({
      s_server: G.s_server,
      str: str
    }))
    if (G.ss_name === 'priceDog') {
      $('#cptklbox').hide()
    }
  }
  addEvent()

  if ((G.from_device === 'biyibi' || G.from_device === 'bijiago') && window.gwd_G) {
    return
  }

  if (G.tklSideBar) {
    G.tklSideBar.$el.remove()
    G.tklSideBar.$destroy()
  }
  const el = document.createElement('div')
  document.body.appendChild(el)
  const TklSideBar = require('./components/TklSideBar').default
  G.tklSideBar = new Vue({
    el: el,
    render: h => h(TklSideBar, {
      props: {
        getTKL: getTkl,
      }
    })
  })
}
let clicked
const clipboard = () => {
  //if (clicked) return;
  var element = document.getElementById('box_btn')
  var element2 = document.querySelectorAll('.gggbox-input')[0];
  if (element.hasAttribute('contenteditable')) {
    element.focus();
  }
  var selection = window.getSelection();
  var range = document.createRange();
  range.selectNodeContents(element);
  selection.removeAllRanges();
  selection.addRange(range);
  window.selectedText = selection.toString();
  if (!window.selectedText) {
    element2.select();
    element2.setSelectionRange(0, element2.value.length);
    window.selectedText = element2.value;
  }
  try {
    let t = window.document.execCommand("copy");
    if (t) {
      clicked = true;
      cnzz.log("copytklss");
      if (G.site === 'taobao-ju') {
        $('#gwd-tkl-text').text("复制成功")
        $('#bjg-tkl img').attr('src', G.s_server + '/images/extensions/TKLSuccess@2x.png')
      }
      $('.cptkl-btn span').text(G.lang === 'zh-tr' ? '復製成功': "复制成功")
      $('.cptkl-btn').removeClass('cpready').addClass('cpsuccess')
      $('.cptkl-remind-err').hide()
    }
  } catch (e) {
    require('common/extConsole').error(e)
  }
}

const addEvent = () => {
  let tklOK
  $('.cptkl-btn').on('click', function() {
    if (tklOK) {
      clipboard()
      return;
    } else {
      cnzz.log("gettklinfo");
    }

    getTkl(function(data) {
      if (data) {
        $('.cptkl-btn span').text(G.lang === 'zh-tr' ? '點擊復製淘口令': "点击复制淘口令")
        $('.cptkl-btn').addClass('cpready')
        tklOK = true;
        let dptle = getTbTle()
        let newTxt = '7' + data
        $('#box_btn').text(newTxt)
        $('.gggbox-input').val(newTxt)
      } else {
        $('.cptkl-remind-err').show()
        // setTimeout(() => {
        //   $('.cptkl-remind-err').fadeOut()
        // }, 5000)
        $('.cptkl-btn').addClass('cpready')
        $('.cptkl-btn span').text(G.lang === 'zh-tr' ? '點擊復製URL': "点击复制链接")
        tklOK = true;
        let dptle = getTbTle()
        let newTxt = location.href
        $('#box_btn').text(newTxt)
        $('.gggbox-input').val(newTxt)
        cnzz.log("gettklerr");
      }
    })
  })
}



