<template>
  <div class="bjg-bar-button gwd-row gwd-align gwd-jcc" @mouseover="startLoad">
    <img src="../assets/collection.svg" alt="" style="width: 22px">
    <span style="margin-left: 7px; font-size: 14px; color: #64615d">收藏夹</span>
    <span class="bjg-collection-tip" v-if="tip > 0">{{ tip }}</span>
    <BjgBottomWindow :style="positionStyle + 'px'" name="降价" v-if="user">
      <div class="gwd-column" style="height: 470px">
        <div style="margin-top: 19px; padding-left: 14px;">
          <OrangeButton :selected="selected === 'all'"
                        @click="select('all')">全部</OrangeButton>
          <OrangeButton :selected="selected === 'reduction'"
                        style="margin-left: 24px"
                        @click="select('reduction')">降价</OrangeButton>
        </div>
        <CollectionList tab="default" ref="default" v-show="selected === 'all'" />
        <CollectionList tab="down" ref="reduction" v-show="selected === 'reduction'" />
      </div>
    </BjgBottomWindow>
    <div v-if="!user" class="gwd-column bjg-login" style="width: 407px; height: 197px; position: absolute; bottom: 59px"
         :style="positionStyle + 'px'">
      <img src="../assets/price-protect-login.svg" alt="" @click="doLogin">
    </div>
  </div>
</template>
<style scoped lang="less">
  .bjg-bar-button {
    width: 114px;
    height: 100%;
    position: relative;

    .bjg-collection-tip {
      background: url(../assets/collectionTip.svg);
      background-size: cover;
      width: 16px;
      height: 16px;
      position: absolute;
      top: 10px;
      right: 6px;
      font-size: 12px;
      line-height: 14px;
      text-align: center;
      color: #fff;
    }

    .bjg-login {
      display: none;
    }
  }

  .bjg-bar-button:hover {
    background: #fffbef;
    .bjg-login {
      display: block;
    }
  }
</style>
<script>
  import { mapState } from 'vuex'

  import BjgBottomWindow from './BjgBottomWindow.vue'
  import OrangeButton from './OrangeButton'
  import CollectionList from './CollectionList'

  import BottomWindowMixin from "../mixins/BottomWindowMixin";

  const bgClient = require('common/background/bgClient')

  export default {
    components: { BjgBottomWindow, OrangeButton, CollectionList },
    mixins: [BottomWindowMixin],
    data() {
      return {
        selected: 'all',
        tip: 0
      }
    },
    methods: {
      startLoad() {
        if (this.tip > 0) {
          this.selected = 'reduction'
        }
        this.tip = 0
        if (this.user) {
          this.$refs.default.init()
          this.$refs.reduction.init()
        }
      },
      select(item) {
        this.selected = item
        if (item === 'all') {
          this.$refs.default.reload()
        } else {
          this.$refs.reduction.reload()
        }
      },
      doLogin() {
        require('../modules/user').goLogin()
      }
    },
    computed: {
      ...mapState({
        userName: state => state.user.userName,
        user: state => state.user.userLogin,
        hasWx: state => state.user.userHasWx
      })
    },
    mounted() {
      bgClient.get('/collection/tip', {}, res => {
        this.tip = parseInt(res)
      })
    }
  }
</script>


