<template>
  <div class="bjg-price-protect-auth gwd-column gwd-align" :style="center ? 'height: 163px;': (login ? 'height: 126px': '')">
    <img
        src="https://cdn.bijiago.com/images/extensions/bijiago/price-protect@2x.png"
        :style="`width: 340px; ${center ? '': 'margin-top: 20px;'}`"
        @click="goIntro()"
        alt="" v-if="(!login) || center">
    <div style="margin-top: 15px;" class="gwd-row gwd-align" v-if="center || (!login)">
      <img :src="img" alt="" style="width: 14px; height: 14px;" @click="checked = !checked">
      <span style="margin-left: 5px; font-size: 12px; color: #64615d">授权比价狗同步我的京东订单，便于申请价格保护</span>
    </div>
    <div v-if="login && !center" style="height: 10px;"></div>
    <button
        class="gwd-button"
        @click="submit"
        :style="checked ? 'background: linear-gradient(270deg, #FFCD47 0%, #FF9F22 100%);': 'background: #d6d6d6'">
      {{ login ? `开启${center ? '授权': '价格保护'}`: '登录开启价保' }}
    </button>
    <div style="margin-top: 15px;" class="gwd-row gwd-align" v-if="login && !center">
      <img :src="img" alt="" style="width: 14px; height: 14px;" @click="checked = !checked">
      <span style="margin-left: 5px; font-size: 12px; color: #64615d">授权比价狗同步我的京东订单，便于申请价格保护</span>
    </div>
  </div>
</template>
<style lang="less">
  .bjg-price-protect-auth {
    height: 201px;
    button {
      margin-top: 20px;
      width: 340px;
      height: 30px;
      border-radius: 15px;
      text-align: center;
      font-size: 14px;
      font-weight: bold;
      color: white;
      box-sizing: border-box!important;
    }
  }
</style>
<script>
  const checkedImg = require('../assets/radio-checked@2x.png')
  const unCheckedImg = require('../assets/radio-unchecked@2x.png')
  const client = require('common/background/bgClient')
  const cnzz = require('common/cnzz')

  export default {
    props: ['login', 'center'],
    data() {
      return {
        checked: true
      }
    },
    computed: {
      img() {
        return this.checked ? checkedImg: unCheckedImg
      }
    },
    methods: {
      goIntro() {
        window.open('https://www.bijiago.com/priceProtectIntro/')
      },
      submit(e) {
        e.preventDefault()
        if (!this.checked) return
        cnzz.log('价格保护' + (this.center ? '中心按钮': ''), this.login ? '用户同意': '用户登录')
        client.get('/setStorage', {
          userAgreed: true,
          enabled: true
        }).then(() => {
          if (this.login) {
            this.$emit('userAgreed')
            return
          }
          require('../modules/user').goLogin(true)
          //location.href = `https://i.bijiago.com/UserUnion/Authorize?utype=2&app_platform=ext&_referer=${encodeURIComponent(location.href + '#forceOpen')}`
        })
      }
    }
  }
</script>


