<template>
  <div class="gwd-promo-plan" v-show="data && data.length">
    <table>
      <thead>
        <tr style="min-height: 30px">
          <th><span>{{ getText('购买方案') }}</span></th>
          <th><span>{{ getText('实付总价') }}(¥)</span></th>
          <th><span>{{ getText('折合每件') }}(¥)</span></th>
          <th><span>{{ getText('使用的促销') }}</span></th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="(item, idx) in data">
          <td style="padding-left: 10px">{{ item.plan_text }}</td>
          <td style="padding-right: 10px; text-align: right" :class="idx === 0 ? 'red': ''">{{ parseFloat(item.total_price).toFixed(2) }}</td>
          <td style="padding-right: 10px; text-align: right" :class="idx === 0 ? 'red': ''">{{ parseFloat(item.current_price).toFixed(2) }}</td>
          <td style="padding: 10px">
            <component v-for="p in item.promo_list" :href="p.id ? link2(p.url_format, p.id): p.url" :key="p.url" target="_blank" :style="'color: #7d7e80;' + (p.url ? 'text-decoration: underline': '')" :is="p.url || p.id ? 'a': 'span'">{{ p.text }} </component>
          </td>
        </tr>
      </tbody>
    </table>
    <div class="gwd-p-qrcode gwd-column gwd-align gwd-jcc" v-if="G.aliSite">
      <div style="width: 100px; height: 100px; position: relative">
        <img :src="qr" alt="" style="width: 100%">
        <img src="../../standard/module/assets/taoQr@2x.png" alt="" style="position: absolute; top: 50%; left: 50%; width: 20px; height: 20px; transform: translate(-50%, -50%)">
      </div>
      <div style="margin-top: 8px; white-space: nowrap; height: 10px; line-height: 10px" class="gwd-row">
        <span class="gwd-font10" style="color: #ff3220; font-weight: bold; transform-origin: top left; width: 42px; margin-left: 6px">{{ getText('淘宝APP') }}</span>
        <span class="gwd-font9" style="color: #070707; transform-origin: top left; width: 64px;">{{ getText('扫码 参加活动') }}</span>
      </div>
    </div>
  </div>
</template>
<style lang="less" scoped>
  .gwd-promo-plan {
    * {
      float: initial;
    }
    z-index: 999;
    display: none;
    background: white;
    position: absolute;
    left: 0;
    right: 0;
    box-shadow:0px 2px 3px 0px rgba(0,0,0,0.2);
    top: 35px;
    box-sizing: border-box;
    padding: 10px;
    table {
      border-collapse: collapse;
      width: 100%;
      white-space: initial;
      .red {
        color: #e4393c;
      }
      th {
        padding-left: 10px;
        text-align: left;
        height: 30px;
        background: #f1f9fc;
        font-weight: normal;
        span {
          display: inline-block;
          font-size: 12px;
          transform: scale(0.833);
          transform-origin: left center;
          color: #969899;
          white-space: nowrap;
        }
      }
      th, td {
        border: 1px solid #edf1f2;
        box-sizing: border-box;
        vertical-align: middle;
        line-height: 17px;
      }
      td {
        min-height: 35px;
        a {
          text-decoration: underline;
        }
        a:hover {
          color: #e4393c!important;
        }
      }
    }

    .gwd-p-qrcode {
      box-sizing: border-box;
      position: absolute;
      bottom: -1px;
      top: -36px;
      z-index: 999;
      width: 130px;
      background: white;
      border: 1px solid #e6e9eb;
      box-shadow: 2px 1px 3px 0 rgba(0,0,0,0.2);
      right: -130px;
      font-size: 0;
      span {
        display: inline-block;
      }
    }
  }
</style>
<script>
  import MemberCouponMixin from "./MemberCouponMixin";

  export default {
    mixins: [MemberCouponMixin],
    props: ['data'],
    data() {
      return {
        G: G
      }
    },
    computed: {

    },
    methods: {
      getText(text) {
        const map = {
          '购买方案': '購買方案',
          '实付总价': '實付總價',
          '折合每件': '折合每件',
          '使用的促销': '使用的促銷',
          '扫码 参加活动': '掃碼 參加活動',
          '淘宝APP': '淘寶APP'
        }
        if (G.lang === 'zh-tr') {
          return map[text]
        }
        return text
      },
      link2(u, src) {
        if (src.indexOf('//') === 0) {
          return u.replace('$URL', encodeURIComponent('https:' + src)).replace('ext_promo_plan', 'promo_calc_plan')
        }
        return u.replace('$URL', encodeURIComponent(src)).replace('ext_promo_plan', 'promo_calc_all')
      }
    }
  }
</script>



