module.exports.init = async (link, text, useQr = false) => {
  await require('common/commonUtil').sleep(1000)
  if ($('#choose-btns .btn-disable').text().includes('加入购物车')) {
    return
  }
  if ($('.J-mobile-only').length) {
    return
  }
  if (useQr) {
    const el = document.createElement('div')
    $('#choose-btns').append(el)
    const FakeBtn = require('./FakeBtn').default
    new Vue({
      el: el,
      render: h => h(FakeBtn, {
        props: {
          text: text,
          ...useQr
        }
      })
    });
    return
  }
  $('#choose-btns').css('min-width', '800px').append(`
    <a href="${link}" target="_blank" class="btn-lg gwd-btn" style="background: #48befe; color: white; font-size: 18px; font-weight: 700;">${text}</a>
  `)
}



