<template>
  <div class="bjg-jd-item-list">
    <div class="bjg-window-status gwd-row gwd-align" v-if="status === 'syncing'">
      <SpinLoading></SpinLoading>
      <span style="font-size: 12px; color: #ff9747; margin-left: 6px;">订单信息同步中</span>
    </div>
    <div class="bjg-window-status gwd-row gwd-align" v-if="status === 'complete'">
      <img src="../assets/pulse.svg" alt="" style="width: 25px; height: 10px;">
      <img src="../assets/monit.svg" alt="" style="width: 12px; height: 11px; margin-left: 6px;">
      <span style="margin-left: 3px; font-size: 12px; color: #ff9747">价保监控中</span>
      <img src="../assets/pulse.svg" alt="" style="width: 25px; height: 10px; margin-left: 6px;">
    </div>
    <div class="bjg-window-status gwd-row gwd-align" v-if="status === 'needLogin'">
      <img src="../assets/alert.svg" alt="" style="width: 12px; height: 12px;">
      <span
          style="margin-left: 10px; font-size: 12px; color: #ff6132">
        您的京东账户未登录，新增订单可能无法价格保护，<span style="text-decoration: underline; cursor: pointer" @click="doLogin()">点击登录</span>
      </span>
    </div>
    <div class="gwd-row bjg-section" style="margin-top: 14px;">
      <SectionTitle>价格保护中订单</SectionTitle>
      <div style="flex: 1"></div>
      <button class="gwd-button bjg-sync" @click="syncNow()" style="white-space: nowrap">
        <img src="../assets/reload@2x.png" alt="" style="width: 10px; height: 10px; vertical-align: middle">
        立即同步订单
      </button>
    </div>
    <div v-if="protectingItems.length === 0" class="gwd-column gwd-align">
      <img src="../assets/empty.svg" alt="" style="width: 60px; height: 52px; margin-top: 30px;">
      <span style="font-size: 14px; color: #333333; margin-top: 21px;">订单中的商品均超过价格保护周期</span>
      <a href=""
         @click.prevent="syncNow"
         style="font-size: 12px; color: #ff9747; text-decoration: underline; margin-top: 13px">刷新试试</a>
      <img
          src="https://cdn.bijiago.com/images/extensions/bijiago/price-protect-help@2x.png"
          alt="help"
          @click="goIntro()"
          style="margin-top: 30px; width: 379px; height: 26px; margin-bottom: 25px;">
    </div>
    <ProductItem v-for="(item, idx) in protectingItems" :line="idx > 0" :product="item" :key="idx"></ProductItem>
    <div class="gwd-row bjg-section gwd-align" style="margin-top: 6px;" v-if="outdatedItems.length">
      <SectionTitle>无法价保订单</SectionTitle>
      <div style="flex: 1; overflow: hidden">
        <span
            style="font-size: 12px; color: #8c847b; transform-origin: left center; margin-left: 5px; transform: scale(0.8333); white-space: nowrap; display: block"
        >商品不支持价保、超过价保周期等</span>
      </div>
      <GwdA href="https://pcsitepp-fm.jd.com/rest/pricepro/pricerule" style="font-size: 12px; color: #333333" target="_blank">京东商城价保规则</GwdA>
      <img src="../assets/rightArrow.png" alt="" style="width: 10px; height: 10px; margin-top: 1px;">
    </div>
    <ProductItem v-for="(item, idx) in outdatedItems" :line="idx > 0" :product="item" :key="'s'+idx" :outdated="true"></ProductItem>
  </div>
</template>
<style scoped lang="less">
  .bjg-sync {
    width: 102px;
    height: 22px;
    border-radius: 11px;
    border: 1px solid #DDDDDD;
    font-size: 12px;
    color: #64615d;
    text-align: center;
    background: white;
    box-sizing: border-box!important;
  }

  .bjg-jd-item-list {
    overflow-y: auto;
    max-height: 414px;
    .bjg-window-status {
      height: 32px;
      background: #fff6ef;
      justify-content: center;
    }
    .bjg-section {
      padding-left: 14px;
      padding-right: 14px;
    }
  }
</style>
<script>
  const client = require('common/background/bgClient')
  const cnzz = require('common/cnzz')
  import SpinLoading from './SpinLoading.vue'
  import SectionTitle from './SectionTitle.vue'
  import ProductItem from './ProductItem.vue'
  import GwdA from 'common/components/GwdA.vue'

  function sleep(time) {
    return new Promise(resolve => {
      setTimeout(() => resolve(), time)
    })
  }

  export default {
    components: { SpinLoading, SectionTitle, ProductItem, GwdA },
    data() {
      return {
        wait: 1000,
        protectingItems: [],
        outdatedItems: [],
        status: 'syncing' // syncing, complete, needLogin
      }
    },
    methods: {
      async syncNow() {
        if (location.href.indexOf('https://pcsitepp-fm.jd.com/?goDown') > -1) {
          return
        }
        cnzz.log('价格保护', '同步按钮点击')
        this.status = 'syncing'
        let data = await client.get('/getDpItemList', {
          reSync: true
        })
        this.process(data)
      },
      goIntro() {
        window.open('https://www.bijiago.com/priceProtectIntro/')
      },
      doLogin() {
        if (G.site !== '360buy') {
          location.href = ('https://pcsitepp-fm.jd.com/')
        } else {
          location.href = 'https://passport.jd.com/new/login.aspx?ReturnUrl=' + encodeURIComponent(location.href.replace('#crumb-wrap', '') + '#forceOpen')
        }
      },
      async process(data) {
        if (!data) {
          if (navigator.userAgent.toLowerCase().indexOf('firefox') > -1) {
            await sleep(this.wait)
            this.wait += 1000
            this.load()
            return
          }
          this.syncNow()
          return
        }
        if (data.needLogin) {
          if (this.protectingItems.length || this.outdatedItems.length) {
            this.status = 'needLogin'
            return
          }
          this.$emit('needLogin')
          return
        }
        this.status = 'complete'
        this.protectingItems = []
        this.outdatedItems = []
        data.forEach(order => {
          let time = order.ctime
          order.related.forEach(item => {
            item.ctime = time
            // item.successPrice = 160
            // this.protectingItems.push(item)
            if (item.inTime) {
              this.protectingItems.push(item)
            } else {
              this.outdatedItems.push(item)
            }
          })
        })
      },
      async load() {
        if (location.href.indexOf('https://pcsitepp-fm.jd.com/?goDown') > -1) {
          return
        }
        let data = await client.get('/getDpItemList', {})
        this.process(data)
        if (location.href.indexOf('forceOpen') > -1) {
          this.syncNow()
          history.replaceState({}, document.title, location.href.replace('#forceOpen', ''))
        }
      }
    },
    watch: {
    },
    mounted() {
      this.load()
    }
  }
</script>


