export class DynamicDetails {
  constructor() {
    this.touchPosition = {
      x: 0,
      y: 0,
    };
    this.touchEventTrusted = false;
    this.mouseEventCount = 0;
    this.mousePosition = {
      x: 0,
      y: 0,
    };
    this.mouseDownCount = 0;
    this.mouseClickPosition = {
      x: 0,
      y: 0,
    };
    this.mouseEventTrusted = false;
    this.keyDownCount = 0;
    this.scrollCount = 0;
    this.windowBlur = false;
    this.windowFocus = false;
    this.consoleWindowOpened = false;
    this.ip = 0; //webrtc ipv4 address
    this.batteryLevel = 127;
    this.deviceOrientationExists = false;
    this.features = packStaticFeatureValue();
    this.checkConsoleLoopHandle = 0;
  };

  touchStartFn(e) {
    this.touchEventTrusted = e.isTrusted;
    this.mouseEventCount++;
    let t = e.touches[0];
    this.touchPosition.x = t.clientX | 0;
    this.touchPosition.y = t.clientY | 0;
  };
  touchMoveFn(e) {
    this.touchEventTrusted = e.isTrusted;
    this.mouseEventCount++;
  };
  mouseMoveFn(e) {
    this.mouseEventTrusted = e.isTrusted;
    this.mouseEventCount++;
  };
  mouseDownFn(e) {
    //数值是不是0, 同时移动没有过界，window.outerHeight跟documentElement.clientHeight 或者document.body.clientHeight是否相等
    this.mouseEventTrusted = e.isTrusted;
    this.mouseEventCount++;
    this.mousePosition.x = e.clientX;
    this.mousePosition.y = e.clientY;
    this.mouseDownCount++;
  };
  mouseClickFn(e) {
    this.mouseEventTrusted = e.isTrusted;
    this.mouseEventCount++;
    this.mouseClickPosition.x = e.clientX;
    this.mouseClickPosition.y = e.clientY;

  };
  keyDownFn(e) {
    this.keyDownCount++;
  };
  scrollFn(e) {
    this.scrollCount++;
  };
  focusFn(e) {
    this.windowFocus = true;
    this.windowBlur = false;
  };
  blurFn(e) {
    this.windowBlur = true;
  };
  devtoolsCb() {
    let details = this;
    var e = new Error();
    Object.defineProperty(e, 'stack', {
      get() {
        clearInterval(details.checkConsoleLoopHandle);
        details.consoleWindowOpened = true;
      }
    });
    console.log(e);
    if(details.consoleWindowOpened) {
      console.clear()
    }
  }
  consoleCheckLoop() {
    let func = this.devtoolsCb.bind(this);
    func();
    this.checkConsoleLoopHandle = setInterval(function (e) {
      func();
    }, 5e3);
  };
  getBatteryStatus(details) {
    if (!navigator.getBattery) {
      return;
    }
    navigator.getBattery().then(function (battery) {
      if (battery) {
        details.batteryLevel = (battery.level * 100) | 0;
      }
    });
  };
  getDeviceOrientation(details) {
    function cb(event) {
      if (event.gamma) {
        details.deviceOrientationExists = true;
      }
      document.removeEventListener("deviceorientation", cb, false);
    }
    window.addEventListener('deviceorientation', cb, false);
  };
  getWebRTCIP(details) {
    var t = window.RTCPeerConnection || window.mozRTCPeerConnection || window.webkitRTCPeerConnection;
    if (!t)
      details.ip = 0;
    var r = {
      iceServers: [{
        urls: [
          "stun:stun.cloudflare.com:3478",
          "stun:stun.qq.com:3478"
        ]
      }],
    };
    try {
      var a = new t(r);
      setTimeout(function () {
        try {
          a.close();
        } catch (t) { }
      }, 5e3);
      a.onicecandidate = function (t) {
        if (t.candidate) {
          const ipRegex = /([0-9]{1,3}(\.[0-9]{1,3}){3}|[a-f0-9]{1,4}(:[a-f0-9]{1,4}){7})/;
          const match = t.candidate.candidate.match(ipRegex)
          // const ipAddress = t.candidate.candidate.match(ipRegex)?.[1];
          const ipAddress = match ? match[1] : null;
          if (ipAddress && !ipAddress.includes('.local')) {
            r = extractIPFromWebRTCCandidate(ipAddress);
            if (null != r) {
              details.ip = r
              a.onicecandidate = null;
            }
          }
        }
      };
      a.createDataChannel("");
      a.createOffer().then(function (n) {
        a.setLocalDescription(n)
      }).catch(function (t) {
        details.ip = 0;
      });
    } catch (e) {
      details.ip = 0
    }
  };
  pack() {
    let group1 = `${this.touchPosition.x | (1 << 30)},${this.touchPosition.y},${this.touchEventTrusted ? 1 : 0}`;
    let group2 = `${this.mouseEventCount},${this.mousePosition.x},${this.mousePosition.y},${this.mouseClickPosition.x},${this.mouseClickPosition.y},${this.mouseDownCount},${this.mouseEventTrusted ? 1 : 0}`;
    let group3 = `${this.keyDownCount},${this.scrollCount},${this.windowBlur ? 1 : 0},${this.windowFocus ? 1 : 0}`;
    let group4 = `${this.consoleWindowOpened ? 1 : 0},${numberToHex(this.ip)},${this.batteryLevel},${this.deviceOrientationExists ? 1 : 0}`;
    let group5 = `${numberToHex(this.features)}`;
    let all = `${group1};${group2};${group3};${group4};${group5}`;
    return all;
  };
  encode() {
    return Base64.encode(this.pack());
  };

};


export function parseMovementText(text) {
  let [group1, group2, group3, group4, group5] = text.split(";");
  let details = new DynamicDetails();
  [details.touchPosition.x, details.touchPosition.y, details.touchEventTrusted] = group1.split(",");
  details.touchEventTrusted = !!parseInt(details.touchEventTrusted);
  [details.mouseEventCount, details.mousePosition.x, details.mousePosition.y, details.mouseClickPosition.x, details.mouseClickPosition.y, details.mouseDownCount, details.mouseEventTrusted] = group2.split(",");
  details.mouseEventTrusted = !!parseInt(details.mouseEventTrusted);
  [details.keyDownCount, details.scrollCount, details.windowBlur, details.windowFocus] = group3.split(",");
  details.windowBlur = !!parseInt(details.windowBlur);
  details.windowFocus = !!parseInt(details.windowFocus);
  [details.consoleWindowOpened, details.ip, details.batteryLevel, details.deviceOrientationExists] = group4.split(",");
  details.consoleWindowOpened = !!parseInt(details.consoleWindowOpened);
  details.deviceOrientationExists = !!parseInt(details.deviceOrientationExists)
  details.ip = int2ip(parseInt(details.ip, 16));
  return [details, group5];
}


export function collectMovement(details) {
  let b = document.body;
  if ("ontouchmove" in document) {
    document.addEventListener("touchmove", details.touchMoveFn.bind(details), true);
  }
  b.addEventListener("touchstart", details.touchStartFn.bind(details), true);
  b.addEventListener("mousemove", details.mouseMoveFn.bind(details), true);
  b.addEventListener("mousedown", details.mouseDownFn.bind(details), true);
  b.addEventListener("click", details.mouseClickFn.bind(details), true);
  b.addEventListener("keydown", details.keyDownFn.bind(details), true);
  b.addEventListener("wheel", details.scrollFn.bind(details), true);
  window.addEventListener("focus", details.focusFn.bind(details), true);
  window.addEventListener("blur", details.blurFn.bind(details), true);

  details.getWebRTCIP(details);
  details.getDeviceOrientation(details);
  details.getBatteryStatus(details);
  details.consoleCheckLoop();
}


function extractIPFromWebRTCCandidate(n) {
  var t = /(\d+)\.(\d+)\.(\d+)\.(\d+)/.exec(n);
  return t ? (+t[1] << 24 | +t[2] << 16 | +t[3] << 8 | +t[4]) >>> 0 : null;
}

function int2ip(ipInt) {
  return ((ipInt >>> 24) + '.' + (ipInt >> 16 & 255) + '.' + (ipInt >> 8 & 255) + '.' + (ipInt & 255));
}

function numberToHex(number) {
  return parseInt(number).toString(16);
}


function isNativeObject(o) {
  return !!/native code/.test(o.toString.toString()) && !!/native code/.test(o.toString());
}


function isWebGLSupported() {
  try {
    const canvas = document.createElement('canvas');
    const context = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');
    return !!context;
  } catch (e) {
    return false;
  }
}


function IsSwiftShader() {
  try {
    const canvas = document.createElement('canvas');
    const gl = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');
    if (!gl) return false;

    const debugInfo = gl.getExtension('WEBGL_debug_renderer_info');
    if (!debugInfo) return false;

    const renderer = gl.getParameter(debugInfo.UNMASKED_RENDERER_WEBGL);
    return renderer.includes('SwiftShader');
  } catch (e) {
    return false;
  }
}


function IsSupportLocalStorage() {
  try {
    localStorage.a = "b";
    return localStorage.a === "b";
  } catch (e) {
    return false;
  }
}


function isMP4Supported() {
  const video = document.createElement('video');

  const isSupported = video.canPlayType('video/mp4; codecs="avc1.42E01E, mp4a.40.2"');

  if (isSupported === "probably" || isSupported === "maybe") {
    return true;
  } else {
    return false;
  }
}

