const template = require('vendor/template')
const userData = require('common/userData')
const request = require('common/request')
const detect = require('common/detect')
const priceParser = require('common/priceParsers')

let nowpage = 0;
let globalPage
let time = 0;
let globalDom
module.exports.init = (data, dom) => {
  if (G.forbidCoupon) return
  if (G.aliSite) return
  globalDom = dom;
  let tbData = userData.get('tbData')
  time++;
  if (tbData.ss === time) {
    if (data.tmall.length === 0 && data.taobao.length === 0) {
      getHymInfo(render2)
    } else {
      var siteName = G.site;
      let siteId = detect.getSiteId(siteName)
      priceParser.init(siteId, function(price) {
        if (price && price > 0) {
          G.dp.oldPrice = price;
          G.dp.price = price;
        }
        render(data, tbData)
      });

    }

  }

}

const getHymInfo = (callback) => {
  if (true) return;
  let info = userData.get('other_info')
  let url = `${G.server}/extension/getCouponTao?keyword=${encodeURIComponent(info.now.coreword)}&class_id=${info['code-server'].class_id}&brand=${encodeURIComponent(info.exact_arr.sbrand)}&sige_id=${info.now.site_id}`;
  request.get(url).done((data) => {
    if (data && data.data && data.data.length > 0) {
      callback(data.data)
    }
  })
}
const render2 = (data) => {
  for (let i = 0; i < data.length; i++) {
    data[i].click_url = data[i].url;
    data[i].promoPri = data[i].currentPrice;
    data[i].price = data[i].originPrice;
    data[i].coupon_money = data[i].couponInfo;
  }
  renderBar(data)
}

const render = (data, tbData) => {
  let comarr = []
  if (tbData.tmm && data.tmall.length > 0) {
    for (let i = 0; i < tbData.tmall.product.length; i++) {
      let itemi = tbData.tmall.product[i];
      for (let j = 0; j < data.tmall.length; j++) {
        let itemj = data.tmall[j];
        if (itemi.num_iid === itemj.reqid) {
          itemi.click_url = itemj.click_url;
          itemi.click_url2 = itemj.click_url2;
          itemi.coupon_money = itemj.coupon.coupon_money;
          itemi.sicon = "https://cdn.gwdang.com/images/favicon/83.ico";
          itemi.promoPri = (Number(itemi.price) - itemj.coupon.coupon_money).toFixed(2);
          if (Number(itemi.promoPri) > G.dp.price)
            continue;
          comarr.push(itemi)
        }
      }
    }
  }
  if (tbData.tbb && data.taobao.length > 0) {
    for (let i = 0; i < tbData.taobao.product.length; i++) {
      let itemi = tbData.taobao.product[i];
      for (let j = 0; j < data.taobao.length; j++) {
        let itemj = data.taobao[j];
        if (itemi.num_iid === itemj.reqid) {
          itemi.click_url = itemj.click_url;
          itemi.click_url2 = itemj.click_url2;
          itemi.coupon_money = itemj.coupon.coupon_money;
          itemi.sicon = "https://cdn.gwdang.com/images/favicon/123.ico";
          itemi.promoPri = (Number(itemi.price) - itemj.coupon.coupon_money).toFixed(2);
          if (Number(itemi.promoPri) > G.dp.price)
            continue;
          comarr.push(itemi)
        }
      }
    }
  }
  renderBar(comarr)
}

const lunbo = () => {
  try {
    let dom = $('#miniCouponCom ul')
    let top = Number(dom.css('top').replace('px', ''));
    top = top - 62;
    nowpage++;
    if (nowpage === globalPage) {
      dom.css('top', '0px');
      nowpage = 0;
      return;
    }
    dom.animate({
      'top': top + 'px'
    }, 600)
  } catch (e) {

  }
}

const renderBar = (data) => {
  data = data.sort(function(v1, v2) {
    if (Number(v1.promoPri) > Number(v2.promoPri))
      return 1;
    else if (Number(v1.promoPri) === Number(v2.promoPri))
      return 0;
    else
      return -1;
  })
  globalPage = data.length;
  if (globalPage === 0) return;
  let html = require('art-template-loader!./views/miniCouponCompare.html')
  if (location.host.indexOf('detail.ju.taobao') > -1 && G.ss_name === 'priceDog') {
    $('.pricedog-bar').before(template.compile(html)({
      data: data,
      fmdv: G.from_device,
      lang: G.lang
    }))
    $('.botbar').css('margin-top', '150px')
  } else {
    $(globalDom).append(template.compile(html)({
      data: data,
      fmdv: G.from_device,
      lang: G.lang
    }))
  }
  setInterval(lunbo, 5000)

}


