const globalCondition = require('common/globalCondition')

module.exports.init = async () => {
  if (G.site !== '360buy') {
    return;
  }
  let localPromo = await globalCondition.met('localPromoGot')
  let promoUrlMap = await globalCondition.met('remoteUrlMap')
  let promos = localPromo.promo.map(item => {
    item = item.replace('http://', '//').replace('https://', '//')
    if (item.indexOf(':') > -1) {
      let [url, text] = item.split(':')
      return {
        text,
        url
      }
    }
  })
  require('common/extConsole').log('localPromo', localPromo)
  $('#prom .prom-item').toArray().forEach(item => {
    let textNode = $(item).find('.hl_red')
    if (!textNode.length) {
      textNode = $(item).find('.mj_red')
    }
    const typeNode = $(item).find('.hl_red_bg')
    const urlNode = $(item).find('a')
    if (!textNode.length || !typeNode.length) {
      return
    }
    let text = textNode[0].innerText
    if (text.includes('距结束还剩')) {
      text = text.split('距结束还剩')[0]
    }
    const type = typeNode[0].innerText
    if (type === '换购') {
      return
    }
    const thePromo = promos.filter(promoItem => {
      if (!promoItem) {
        return false
      }
      let url = false
      // if (urlNode && urlNode.attr('href')) {
      //   url = urlNode.attr('href')
      // }
      if (url && promoItem.url) {
        return url.indexOf(promoItem.url) > -1
      } else {
        if (!(promoItem && promoItem.text)) {
          return false
        }
        let toCompare = promoItem.text
        if (toCompare.indexOf('--') > -1) {
          toCompare = toCompare.split('--')[1]
        }
        if (toCompare.includes('距结束还剩')) {
          toCompare = toCompare.split('距结束还剩')[0]
        }
        require('common/extConsole').log(toCompare, text)
        return toCompare === text
      }
    })
    if (thePromo.length && G.ss_name !== 'priceDog') {
      const url = thePromo[0].url
      const link = promoUrlMap[' ' + url]
      const title = G.lang === 'zh-tr' ? '查看此活動全部商品': '查看此活动全部商品'
      $(item).append(`<a href=${link} target="_blank" style="color: #ee2f36; text-decoration: underline; margin-left: 5px; font-size: 12px; white-space: nowrap">${title}<img src="https://cdn.gwdang.com/images/extensions/redArrow.svg" style="width: 10px; height: 10px;"></a>`)
    }
  })

  let coupons = localPromo.quan.map(item => {
    item = item.toString().replace('http://', '//').replace('https://', '//')
    if (item.indexOf(':') > -1) {
      let itemArr = item.split(':')
      // let [url, text] = item.split(':')
      // url = '//search.jd.com/Search?activity_id=' + url.split('_')[0] + '&sku=' + G.dp.itemId.replace('-3', '')
      return {
        text: itemArr[itemArr.length - 1],
        url: itemArr[0]
      }
    }
  })
  // const remotePromos = await globalCondition.met('promoGot')
  // let coupons = remotePromos.promo_list.filter(x => x.tag === 'coupon').map(x => {
  //   return {
  //     text: x.text.split(':').length > 1 ? x.text.split(':')[1] : x.text,
  //     url: x.id
  //   }
  // })

  coupons = coupons.filter(item => item && item.url)
  coupons = require('common/commonUtil').arrayUnique(coupons, x => x.url)
  const couponLinks = coupons.map((item, idx) => {
    const link = promoUrlMap[' ' + item.url]
    return `<a href=${link} target="_blank"">查看${item.text.split(',')[0]}商品${idx === 0 ? '<img src="https://cdn.gwdang.com/images/extensions/redArrow.svg" style="width: 10px; height: 10px;">': ''}</a>`
  }).join('')
  if (coupons.length > 1) {
    $('#summary-quan .lh').append(`
      <div class="gwd-jd-promo-coupons-wrapper ${coupons.length === 1 ? 'gwd-single-coupon': ''}">
        <div class="gwd-jd-promo-coupons">
          ${couponLinks}
        </div>
      </div>
    `)
  } else {
    $('#summary-quan .lh').append(`
      <div class="gwd-single-coupon">
        ${couponLinks}
      </div>
    `)
  }
  $('#summary-quan .lh').css('line-height', 0)

  require('common/css/jdPromoLink.less')

}



