const getCouponInfo = require('common/coupon/getCouponInfo')
const getQRCode = require('common/coupon/getQRCode')
export default {
  computed: {
    link() {
      return require('common/productInfo').appendTbInfoForUrl(`${G.tb_server}/extension/qrpage?union=${G.union}&dp_id=${this.dpId ? this.dpId: G.dp.dpId}&tag=${this.tag}`)
    }
  },
  methods: {
    getText(text) {
      const map = {
        '当前商品可领券': '當前商品可領券',
        '店铺券(满': '店鋪券(滿',
        '减': '減',
        '立即领取': '立即領取',
        '领券满': '領券滿',
        '淘宝APP扫码': '淘寶APP掃碼',
        '领店铺券': '領店鋪券'
      }
      if (G.lang === 'zh-tr') {
        return map[text]
      }
      return text
    },
    over(e) {
      if (this.img) return
      if (this.loading) return
      this.loading = true
      require('common/cnzz').log('店铺券中间二维码', '悬浮')
      if (this.useTb) {
        require('common/request').rawGet(G.u_server + `/helper/qrcode?event=appQrcode${this.tag ? `&tag=${this.tag}`: ''}&dp_id=` + (this.dpId ? this.dpId: G.dp.dpId)).then(res => {
          console.log(res)
          if (typeof res === 'string') {
            res = JSON.parse(res)
          }
          this.img = res.data.qrImgStr
        })
      } else {
        getCouponInfo({
          pid: 'gwd-middle',
          coupon: {
            coupon_money: this.coupon.discount
          }
        }, data => {
          data._type = 'item'
          data.tip = `${this.coupon.limit}-${this.coupon.discount}`
          getQRCode(data, '', res => {
            this.img = res[0].imgSrc
          })
        })
      }
    }
  }
}



