//返回单品页的标题信息
let getProductInfo = () => {
  return {
    name: $('title').html(),
    price: 0,
    isbn: '',
    url: window.location.href
  }
}

const getPrice = selector => {
  if ($(selector).length) {
    let text = $(selector).eq(0).text().trim()
    if (text.includes('定金') || text.includes('首付') || text.includes('尾款') || text.includes('?')) {
      return ''
    }
    // get only number part
    text = text.replace(/[^0-9.]/g, '')
    if (!isNaN(parseFloat(text))) {
      return text
    }
  }
  return ''
}

const tbInfoFix = info => {
  if (!info) return {}
  let shopName = $('.tb-shop-name a').text()
  if (!shopName) {
    shopName = $('[class^=ShopHeader--title]').text()
  }
  if (!shopName) {
    shopName = $('.slogo-shopname strong').text()
  }
  if (!shopName) {
    shopName = $('.shop-name-link').attr('title')
  }
  if (!shopName) {
    shopName = $('.shop-name-link').text()
  }
  if (!shopName) {
    shopName = $('[class^=ShopHeader--shopName--]').text()
  }
  if (!shopName) {
    shopName = $('[class^=ShopHeaderNew--shopName--]').text()
  }
  if (!shopName) {
    shopName = $('[class^=shopName--]').text()
  }
  info.shopName = (shopName || '').trim()

  let shopAmount = $('#J_SellCounter').text()
  if (!shopAmount) {
    shopAmount = $('[class^=ItemHeader--salesDesc]').text()
  }
  if (!shopAmount) {
    shopAmount = $('[class^=salesDesc]').text()
  }
  if (!shopAmount) {
    shopAmount = $('[class^=subTitleInnerWrap--]').text().replace('已售', '')
  }
  info.shopAmount = (shopAmount || '').trim()
  const pageTitle = require('common/commonUtil').findStringFromSelectors([
    '[class^=ItemTitle--root--] h1',
    '[class^=ItemTitle--] h1'
  ])
  if (pageTitle) {
    info.name = pageTitle
  }

  if (!info.price) {
    const toCheck = [
      '[class^=extraPrice--]',
      '[class^=originPrice--]',
      '.text--Mdqy24Ex',
      '.priceText--YZzF3UMh',
      '[class^=highlightPrice--]'
    ]
    for (let i = 0; i < toCheck.length; i++) {
      info.price = getPrice(toCheck[i])
      if (info.price) break
    }
  }

  const secPrice = $('[class^=SecurityPrice--text--]').text()
  if (secPrice) {
    info.price = secPrice
  }
  if (!info.img && G.GwdConfig) {
    const imgCfg = G.GwdConfig.aliImgSelector
    if (imgCfg) {
      for (let i = 0; i < imgCfg.length; i++) {
        const img = $(imgCfg[i].img).attr('src')
        if (img) {
          info.img = img
          info.pic = img
          break
        }
      }
    }
  }
  return info
}

//提取第三方评测导购网站中的商品信息
let getArticleInfo = (className, childPos, newSiteName) => {
  var dp = getProductInfo();
  G.site = newSiteName;
  try {
    var a = $(className).eq(childPos);
    dp.name = a.text();
    G.href = G.makeUrl(G.href, a.attr('href'));
    dp.url = G.href
    if (typeof G.href == 'undefined' || G.href == "") {
      dp.useless = true;
    } else {
      var check = siteInfo.isProductPage();
      if (!check) {
        dp.useless = true;
      }
    }
  } catch (e) {

    dp.useless = true;
  }
  return dp;
}
let getArticleInfoNew = (className, childPos, attr, newSiteName) => {
  var dp = getProductInfo();
  G.site = newSiteName;
  if (G.crc64) return dp;
  try {
    var a = $(className).eq(childPos);
    G.href = a.attr(attr);
    dp.url = a.attr(attr);
    if (a.attr(attr)) dp.url = a.attr(attr)
    if (typeof G.href == 'undefined' || G.href == "") {
      G.href = window.location.href;
    }
  } catch (e) {}
  return dp;
}
