const request = require('common/request')
const getCoupon = require('common/getCoupon')
const getCouponNew = require('common/getCouponNew')
const cnzz = require('common/cnzz')
const QRReloader = require('common/coupon/QRReloader')

let globalInfo = {},
  randomNum, hasReqId = []
let domPattern = {
  'taobao': {
    '#J_Pine': {
      "isSmall": true,
      'listdom': "li.tuijian-item",
      'href': '.pic-con a.img-con',
      'insertdom': 'div.pic-con'
    },
    '.tb-main-layout .col-sub .skin-box-bd': {
      'listdom': ".item1line1 .photo",
      'href': 'a',
      'insertdom': '.item1line1 .photo'
    },
    '#J_Pinus_Enterprise_Module .tuijian-bd-window': {
      'listdom': ".tuijian-item",
      'href': '.tuijian-img a.img-con',
      'insertdom': '.tuijian-item'
    },
    '#viewed-items-slide .item-list': {
      'listdom': "li .item",
      'href': 'a.side-item',
      'insertdom': 'div.pic'
    },
    '#bought-items-slide .item-list': {
      'listdom': "li .item",
      'href': 'a.side-item',
      'insertdom': 'div.pic'
    },
    '#detail-recommend-linjia .linjia-items-slide .slide-content': {
      'listdom': "li .item",
      'href': 'a.side-item',
      'insertdom': 'div.pic'
    }
  },
  'tmall': {
    '#ald-skuRight': {
      'listdom': ".ald-switchable-content li",
      'href': 'a.ALDCLS-act',
      'insertdom': 'div.img'
    },
    '#J_DcLeft .skin-box-bd': {
      'listdom': ".item1line1 .photo",
      'href': 'a',
      'insertdom': '.item1line1 .photo'
    },
    '#J_TjWaterfall': {
      'listdom': "li",
      'href': 'a.ald-wf-pic',
      'insertdom': 'li'
    }
  },
  'taobao-ju': {

  }
}

let listenDomPattern = {
  'tmall': ["#J_TabRecommends", "#J_TjWaterfall"],
  'taobao': ['#detail-recommend-viewed', ["#viewed-items-slide .item-list", "#bought-items-slide .item-list", "#detail-recommend-linjia .linjia-items-slide .slide-content"]]
}
let searchZoneId = {
  'bjg923253': '10015',
  'union_bijiago': '10013',
  'union_bijiago_uos': '10013',
  'union_east': '10007',
  'union_universal': '40009',
  'union_cchrome': '10025',
  'union_yunqi': '10025',
  '538625': '10025'
};

let pidConfig = {
  'bjg923253': 'pid-bjg-923253',
  'union_bijiago': 'pid-bjg-union',
  'union_east': 'pid-east',
  'union_universal': 'pid-universal',
  'union_cchrome': 'pid-cchrome',
  'union_yunqi': 'pid-yunqi'
};

// 淘宝天猫商品详情页   一些推荐的商品  添加优惠券
module.exports.init = () => {
  randomNum = parseInt(Math.random() * 100);
  if (G.from_device === "kuaik") {
    randomNum = 100;
  }
  setTimeout(render, 5000)
}

const render = () => {
  let site = G.site;
  let domOjb = domPattern[site];
  if (!domOjb) return;
  for (let pt in domOjb) {
    if ($(pt).length > 0 && $(pt).is(':visible')) {
      render2(pt, domOjb)
    }
  }
  listenDom()
  addEvent()
}
const render2 = (pt, domOjb) => {
  let site = G.site;
  let dom = $(pt).find(domOjb[pt]['listdom'])
  if (dom.find('.detail_coupon_tip').length > 0) return;
  for (let i = 0; i < dom.length; i++) {
    let href = dom.eq(i).find(domOjb[pt]['href']).attr('href');
    let id = href.match(/[?&]id=([0-9]+)/)
    if (id)
      id = id[1];
    if (!id) continue;
    let insertDom = dom.eq(i).find(domOjb[pt]['insertdom']);
    if ($(insertDom).length === 0)
      insertDom = dom.eq(i);
    renderTip(id, insertDom, site, domOjb[pt]["isSmall"])
  }
}

const renderTip = (id, insertDom, site, isSmall) => {
  const cb = function(data) {
    if (!data) return
    if (!data.data) return;
    data = data.data;
    data.site = site;
    globalInfo[id] = data;
    let dom = `<a href="${data.click_url2}" data-id="${id}" title="当前商品领券立减${data.coupon.coupon_money}元" class="detail_coupon_tip detail_coupon_tip_big" target="_blank"><span>¥${data.coupon.coupon_money}</span> 券</a>`
    if (randomNum > -1) {
      dom = `<a  data-id="${id}" class="detail_coupon_tip detail_coupon_tip_big" style="cursor:default;" target="_blank"><span>¥${data.coupon.coupon_money}</span> 券</a>`
    }
    if (isSmall) {
      dom = `<a href="${data.click_url2}" data-id="${id}" title="当前商品领券立减${data.coupon.coupon_money}元" class="detail_coupon_tip detail_coupon_tip_small" target="_blank">¥${data.coupon.coupon_money} </a>`
      if (randomNum > -1) {
        dom = `<a  data-id="${id}" class="detail_coupon_tip detail_coupon_tip_small" style="cursor:default;" target="_blank">¥${data.coupon.coupon_money}</a>`
      }
    }
    // if (randomNum > -1) {
    //   dom = `<a  data-id="${id}" class="search_coupon_tip" style="cursor:default;" target="_blank">￥${data.coupon.coupon_money} 优惠券<a>`
    // }
    $(insertDom).eq(0).append($(dom))
  };
  getCoupon.init(id, searchZoneId[G.union], cb)
  // if (G.union !== '538625') {
  //   getCouponNew.initWithDp(id, pidConfig[G.union], 'mini', cb)
  // } else {
  //   getCoupon.init(id, searchZoneId[G.union], cb)
  // }
}

const listenDom = () => {
  let Timer, hasrun
  let arr = listenDomPattern[G.site];
  if (!arr) return;
  let dom = $(arr[0])[0];
  if (!dom) return;
  dom.addEventListener('DOMSubtreeModified', function() {
    clearTimeout(Timer)
    if (G.site === 'tmall' && $(dom).find(arr[1]).find('li').length > 0 && hasrun) return;
    if (G.site === 'taobao' && $(dom).find(arr[1][0]).find('li').length > 0 && hasrun) return;
    Timer = setTimeout(() => {
      hasrun = true;
      if (G.site === 'tmall') {
        render2(arr[1], domPattern[G.site])
      } else {
        render2(arr[1][0], domPattern[G.site])
        render2(arr[1][1], domPattern[G.site])
        render2(arr[1][2], domPattern[G.site])
      }
    }, 3000)
  }, false)
}

const addEvent = () => {
  $('body').on('click', function(e) {
    if ($(e.target).hasClass('detail_coupon_tip')) {
      cnzz.log('click:searchcoupon')
      // utils.tongjiLog('click:searchcoupon')
    }
  })
  $('body').on('mouseover', function(e) {
    if ($(e.target).hasClass('detail_coupon_tip')) {
      let id = $(e.target).attr('data-id')
      if ($(e.target).find('.qr_coupondetail').length === 0 && randomNum > -1) {
        cnzz.log('track:searchcoupon')
        // utils.tongjiLog('track:searchcoupon')
        addQRcode(id, e.target)
      }
    }
  })
}

const getQRcode = require('common/coupon/getQRCode')
let callbacks, hasreq, urls
const getPageInfo = (info, callback) => {
  let infoObj = {}
  if (hasreq) {
    callbacks = callback;
    urls = info.click_url;
    return;
  }
  let itemId = info.itemId;
  let obj = {
    itemNumId: itemId
  }
  let url = `https://acs.m.taobao.com/h5/mtop.taobao.detail.getdetail/6.0/?data=${encodeURIComponent(JSON.stringify(obj))}`
  request.getPure(url).then(function(data) {
    try {
      let item = data.data.item
      let seller = data.data.seller
      let item2 = JSON.parse(data.data.apiStack[0].value)
      infoObj.title = item.title;
      infoObj.picUrl = item.images[0]
      infoObj.shopName = seller.shopName
      infoObj.shopLogo = seller.shopIcon;
      infoObj.shopUrl = seller.shopUrl;
      infoObj.biz30Day = item2.item.sellCount;
      infoObj.discountPrice = (Number(item2.skuCore.sku2info['0'].price.priceMoney) / 100).toFixed(2);
    } catch (e) {
      //require('common/extConsole').error(e)
    }
    if (!infoObj.title) {
      infoObj.title = info.titleGot
    }
    if (!infoObj.picUrl) {
      infoObj.picUrl = info.imgGot
    }
    if (!infoObj.discountPrice) {
      infoObj.discountPrice = info.priceGot
    }
    infoObj.id = itemId;
    infoObj.amount = info.coupon.coupon_money
    infoObj.effectiveStartTime = info.coupon.start_time;
    infoObj.effectiveEndTime = info.coupon.end_time;
    infoObj.pid = info.pid;
    infoObj.tkl = info.tkl;
    infoObj.tmall = (location.host.indexOf('tmall') > -1) ? true : false;
    console.log(infoObj)
    callback(infoObj, info.click_url)
    if (callbacks) {
      callbacks(infoObj, urls)
    }
  })
}
const addQRcode = (id, dom) => {
  if (G.forbidCoupon) return;
  if (hasReqId.indexOf(id) > -1) return;
  hasReqId.push(id);
  if (!id) return;
  let data = globalInfo[id];
  data.pid = searchZoneId[G.union];
  data.itemId = id;

  data.imgGot = $(dom).parents('li').find('.img img').attr('src')
  data.titleGot = $(dom).parents('li').find('.look_title a').text().replace(/ /g, '').replace(/\n/g, '')
  data.priceGot = $(dom).parents('li').find('.look_price').text().replace(/ /g, '').replace('¥', '')
  getPageInfo(data, function(newData, url) {
    let id = 'gwd-coupon-' + parseInt(Math.random() * 1000)
    const name = '微信'
    let view = `<div class="minicoupon_detail" id="${id}">
        <img src="xxx">
        <span>${name}扫码领券</span>
      </div>`
    $(dom).append(view)

    QRReloader.init(newData, url, `#${id} > img`, function(newData2) {
      $(dom).parent().css('overflow', 'visible')
      $(dom).parents('.tuijian-bd').css('overflow', 'visible')
    }, false, false)
  })
}



