module.exports.getTimeNumber = (time, type) => {
  // 1: xxxx-xx-xx 2.xx-xx 3.xx.xx 4. xxxx.xx.xx
  let dateObj = new Date(time);
  let y = dateObj.getFullYear();
  let m = dateObj.getMonth() + 1;
  let d = dateObj.getDate();
  if (m < 10)
    m = '0' + m;
  if (d < 10)
    d = '0' + d;
  let str = ``;
  switch (type) {
    case "1":
      str = `${y}-${m}-${d}`
      break;
    case "2":
      str = `${m}-${d}`
      break;
    case "3":
      str = `${m}.${d}`;
      break;
    case "4":
      str = `${y}.${m}.${d}`;
      break;
    case "5":
      str = `${y}/${m}/${d}`;
      break;
    default:
      str = `(${y}.${m}.${d})`;
  }
  return str;
}

/**
 * 数组去重
 * @param array
 */
module.exports.arrayUnique = (array) => {
  let newArray = []
  array.forEach(item => {
    if (newArray.indexOf(item) === -1) {
      newArray.push(item)
    }
  })
  return newArray
}

module.exports.setSimplePagePos = (dom, detail, detailW) => {
  let mainW = $(window).width();
  let left = dom.offset().left;
  let domw = dom.outerWidth();
  let dleft = left + domw - detailW - 2;
  if (dleft < 0)
    dleft = 0;
  if ((dleft + detailW) > mainW)
    dleft = (mainW - detailW - 2);
  detail.css('left', dleft + 'px');
}

module.exports.deepCopy = (obj) => {
  return $.extend(true, {}, obj);
}

module.exports.stringToNumber = text => {
  if (!text) {
    return 0
  }
  let x = parseInt(text)
  if (text.includes('万')) {
    x = x * 10000
  }
  return x
}

module.exports.numberToString = (number, digit = 2) => {
  if (typeof number === 'string' && number.includes('万')) {
    return number
  }
  let x = parseInt(number)
  if (x > 10000) {
    x = x / 10000
    x = x.toFixed(digit).replace('.' + '0'.repeat(digit), '') + '万'
  }
  return x
}

module.exports.waitForConditionFn = (conditionFn: () => boolean, checkInterval = 300, maxTryTimes = 0) => {
  return new Promise(resolve => {
    if (conditionFn()) {
      resolve(true)
      return
    }
    let tryTimes = 0
    let t = setInterval(() => {
      if (conditionFn()) {
        resolve(true)
        clearInterval(t)
      }
      tryTimes++
      if (maxTryTimes && tryTimes > maxTryTimes) {
        clearInterval(t)
      }
    }, checkInterval)
  })
}



