<template>
  <div style="overflow-y: auto; flex: 1" @scroll="scroll">
    <CollectionItem v-for="item in list" :product="item" :key="item.id" @delete="deleteItem"></CollectionItem>
    <div v-if="list.length === 0 && ended" class="gwd-column gwd-align gwd-jcc" style="height: 100%">
      <img src="../assets/emptyList@2x.png" alt="" style="width: 60px; height: 52px;">
      <span class="bjg-hintText" v-if="tab === 'down'">暂无商品降价<br>降价会及时通知您</span>
      <span class="bjg-hintText" v-if="tab === 'default'">暂未收藏任何商品，去收藏</span>
    </div>
  </div>
</template>
<style scoped lang="less">
  .bjg-hintText {
    color: #333333;
    line-height: 19px;
    font-size: 14px;
    text-align: center;
    margin-top: 16px;
  }
</style>
<script>
  import CollectionItem from './CollectionItem'

  const user = require('../modules/user')
  const bgClient = require('common/background/bgClient')

  export default {
    data() {
      return {
        list: [],
        loading: false,
        ended: false,
        pg: 1
      }
    },
    props: ['tab'],
    components: { CollectionItem },
    methods: {
      scroll(e) {
        if (e.target.scrollTop + e.target.offsetHeight - e.target.scrollHeight > -100) {
          this.load()
        }
      },
      deleteItem(id) {
        user.del(id).then(res => {
          console.log(res)
          if (res.code === 1) {
            this.list = this.list.filter(x => x.id !== id)
          }
        })
      },
      load() {
        if (this.loading || this.ended) return
        this.loading = true
        user.getList(this.pg, this.tab).then(res => {
          console.log(res)
          this.pg += 1
          this.loading = false
          bgClient.get('/collection/reset')
          this.list = this.list.concat(res.data)
          if (res.data.length === 0) {
            this.ended = true
          }
        })
      },
      reload() {
        this.list = []
        this.pg = 1
        this.ended = false
        this.load()
      },
      init() {
        if (!this.list.length) {
          this.load()
        }
      }
    }
  }
</script>


