const requestInfo = (url, callback, price) => {
  let cbrun = false
  if (G.allowBackgroundRequest) {
    require('common/request').getCouponFromUrl(url, price).then(res => {
      if (cbrun) return
      cbrun = true
      callback(res)
    })
    setTimeout(() => {
      if (!cbrun) {
        cbrun = true
        callback()
      }
    }, 3000)
  } else {
    require('common/request').getCouponFromUrl(url, price).then(res => {
      callback(res)
    })
  }
  // var xmlhttp = new XMLHttpRequest();
  // xmlhttp.addEventListener('load', function() {
  //   try {
  //     callback(JSON.parse(xmlhttp.responseText))
  //   } catch (e) {
  //     callback({})
  //   }
  //
  // })
  // xmlhttp.open("GET", url, true);
  // xmlhttp.send();
  // require('common/request').get(`${G.server}/extension/CouponHandler?op=get&rawApi=${encodeURIComponent(url)}`).then(data => {
  //
  // })
}

module.exports.init = (id, adzone_id, callback, direct = true, price = null) => {
  let cbrun = false
  if (G.forbidCoupon) {
    return
  }
  if (!id) {
    callback && callback()
    cbrun = true
    return;
  }
  id = `${id}`.replace('-83', '')
  id = `${id}`.replace('-8', '')
  let hosts = "open.lesiclub.cn";
  // if ((G.from_device === 'bijiago' && navigator.userAgent.toLocaleLowerCase().indexOf('firefox') > -1))
  //   hosts = "browser.gwdang.com/adbats"
  let url = location.protocol + "//" + hosts + "/coupon/get_ext/10005/" + adzone_id + "/" + id;
  requestInfo(url, (data) => {
    if (data && data.data) {
      data.data.reqid = id;
      data.data.click_url2 = `${G.u_server}/?url=${encodeURIComponent(data.data.click_url)}`

      if (G.from_device === 'bijiago' && G.aliSite && data.data.coupon) {
        data.data.click_url2 = `https://tb.${G.ss_name === 'priceDog' ? 'pricedog': 'bijiago'}.com/extension/qrpage?union=${G.union}&dp_id=${id}-83&tag=9_chrome&discount=${data.data.coupon.coupon_money}&lang=${G.lang}`
      }

      if (G.from_device === 'biyibi' && G.aliSite) {
        data.data.click_url2 = `https://tb.biyibi123.com/extension/qrpage?union=${G.union}&dp_id=${id}-83&tag=9_chrome&discount=${data.data.coupon.coupon_money}`
      }

      data.data.click_url2 = require('common/productInfo').appendTbInfoForUrl(data.data.click_url2)

      data.data.cpid = adzone_id;
      if (callback)
        callback(data)
    } else {
      callback(null)
    }
    cbrun = true
  }, price)

};

module.exports.byIdAndAdzone = (id, adzone_id) => {
  if (!id) {
    return new Promise(resolve => resolve(null));
  }
  id = `${id}`.replace('-83', '')
  id = `${id}`.replace('-8', '')
  let hosts = "open.lesiclub.cn";
  if ((G.from_device === 'bijiago' && navigator.userAgent.toLocaleLowerCase().indexOf('firefox') > -1))
    hosts = "browser.gwdang.com/adbats"
  let url = location.protocol + "//" + hosts + "/coupon/get_ext/10005/" + adzone_id + "/" + id;
  return new Promise(resolve => {
    requestInfo(url, (data) => {
      if (data && data.data) {
        data.data.reqid = id;
        data.data.click_url2 = `${G.u_server}/?url=${encodeURIComponent(data.data.click_url)}&union=${G.union}`
        if (G.from_device === 'bijiago' && G.aliSite) {
          data.data.click_url2 = require('common/productInfo').appendTbInfoForUrl(`https://tb.${G.ss_name === 'priceDog' ? 'pricedog': 'bijiago'}.com/extension/qrpage?union=${G.union}&dp_id=${dpId}&tag=9_chrome&discount=${data.data.coupon.coupon_money}`)
        }
        if (G.from_device === 'biyibi' && G.aliSite) {
          data.data.click_url2 = require('common/productInfo').appendTbInfoForUrl(`https://tb.biyibi123.com/extension/qrpage?union=${G.union}&dp_id=${dpId}&tag=9_chrome&discount=${data.data.coupon.coupon_money}`)
        }
        resolve(data)
      } else {
        resolve(null)
      }
    })
  })
}



