<template>
  <div class="gwd-row gwd-align bjg-product-item" :class="last ? 'bjg-last': ''" @click="open(product.go_url)">
    <img :src="product.img" alt=""
         onerror="this.src='https://cdn.bijiago.com/images/extensions/default_load_image.png'"
         style="width: 100px; height: 100px; margin-left: 14px">
    <div style="margin-left: 10px; width: 260px; height: 100px;" class="gwd-column">
      <div class="bjg-item-title">{{ product.title }}</div>
      <div class="gwd-row gwd-align" style="margin-top: 13px;" v-if="product.price">
        <span style="font-size: 14px; color: #ff3434;">{{ currencySymbol }}{{ product.price.toFixed(2) }}</span>
        <div style="flex: 1"></div>
        <span v-if="product.price < product.collect_price"
              class="bjg-reduct"
              style="">比收藏时下降{{ currencySymbol === '¥' ? '': currencySymbol }}{{ (product.collect_price - product.price).toFixed(2).replace('.00', '') }}{{ currencySymbol === '¥' ? '元': '' }}</span>
      </div>
      <div style="flex: 1"></div>
      <div class="gwd-row gwd-align">
        <img :src="product.site_icon" alt="" style="width: 12px; height: 12px">
        <span style="margin-left: 4px; font-size: 12px; color: #999">{{ product.site_name }}</span>
        <div style="flex: 1"></div>
        <img src="../assets/rubbish_small@2x.png" alt="" style="width: 10px;" @click="deleteClick">
      </div>
    </div>
  </div>
</template>
<style scoped lang="less">
  .bjg-product-item {
    height: 140px;
    border-bottom: 1px solid #f1f1f1;
    .bjg-item-title {
      height: 40px;
      font-size: 13px;
      color: #333333;
      line-height: 20px;
      overflow: hidden;
      text-overflow: ellipsis;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
    }
    .bjg-reduct {
      font-size: 12px;
      color: #31c38a;
    }
  }

  .bjg-product-item.bjg-last {
    border-bottom: none;
  }
</style>
<script>
  import { amazonMoney } from '../modules/amazonGlobal'

  export default {
    props: ['product', 'last'],
    computed: {
      currencySymbol() {
        let s = this.product.site_id
        if (amazonMoney[s]) {
          return amazonMoney[s]
        }
        return '¥'
      }
    },
    methods: {
      open(link) {
        if (G.aliSite && [83, 123, 8].indexOf(parseInt(this.product.site_id)) > -1) {
          window.open(this.product.url)
          return
        }
        window.open(link)
      },
      deleteClick(e) {
        e.preventDefault()
        e.stopPropagation()
        this.$emit('delete', this.product.id)
      }
    }
  }
</script>



