<template>
  <div class="bjg-price-protect-jd-login gwd-column gwd-align">
    <img src="https://cdn.bijiago.com/images/extensions/bijiago/hi@2x.png" alt="" style="width: 112px; height: 55px; margin-top: 41px;">
    <div class="bjg-hint" style="margin-top: 30px">
      请您先登录京东网站<br>
      价格保护才能正常工作
    </div>
    <button class="gwd-button" @click="doJdLogin()">登录京东</button>
  </div>
</template>
<style scoped lang="less">
  .bjg-price-protect-jd-login {
    height: 250px;
    .bjg-hint {
      width: 120px;
      height: 44px;
      font-size: 12px;
      color: #64615D;
      line-height: 22px;
      text-align: center;
    }
    .gwd-button {
      margin-top: 30px;
      width: 340px;
      height: 30px;
      border-radius: 15px;
      background: linear-gradient(270deg, #FFCD47 0%, #FF9F22 100%);
      font-weight: bold;
      font-size: 14px;
      color: white;
    }
  }
</style>
<script>
  export default {
    methods: {
      doJdLogin() {
        if (G.site !== '360buy') {
          location.href = ('https://pcsitepp-fm.jd.com/')
        } else {
          location.href = 'https://passport.jd.com/new/login.aspx?ReturnUrl=' + encodeURIComponent(location.href.replace('#crumb-wrap', '') + '#forceOpen')
        }
      }
    }
  }
</script>


