const TbScrollLink = require('standard/module/components/TbScrollLink').default

module.exports = {
  reset() {
    $('#gwd-tb-mini-coupon').remove()
  },
  add(text, icon, link, mainColor, secondColor, showStampBg, rebate) {
    if (!G.aliSite) {
      return
    }
    const div = document.createElement('div')
    $('.gwd-minibar-bg').after(div)
    new Vue({
      el: div,
      render: h => h(TbScrollLink, {
        props: {
          text, icon, link, mainColor, secondColor, showStampBg, rebate
        }
      })
    })
    require('standard/module/miniBar').recoverMiniBar()
  }
}


