define('mobileprice', function() {
  // var protocol = location.protocol === 'https:' ? 'https:' : 'http:';
  var exports = {};
  var $ = require('jQuery');
  var request = require('./request');
  var cnzz = require('common/cnzz');
  var template = require('vendor/template');
  var now_site, num = 0;
  var dp_now, thisunion;
  var sitePatterns = {
    '360buy': ['#prom-mbuy .mob-buy', '#m-pirce'],
    'yihaodian': ['#productSubName'],
    'dangdang': ['#mobile_exclusive_price'],
    'suning': ['#qrCode', '#phoneOrderCode'],
    'gome': ['#shoujizhuanxiang_box'],
    '51buy': ['#sea_desc']
  };
  var getPricePattern = {
    '360buy': '#prom-mbuy .J-m-price',
    '360buy_1': '#m-pirce .J-m-price',
    'dangdang': '#mobile_price'
  };
  var viewsPatterns = {
    '360buy': '<a id="bjd_m_price" href="{{url}}" target="_blank"  rel="noreferrer" title="{{title}}"style="text-decoration:underline;color:#005aa0;">无需扫码，电脑上也可享受手机优惠价!</a>',
    '360buy_1': '<a id="bjd_m_price" href="{{url}}" target="_blank"  rel="noreferrer" title="{{title}}"style="text-decoration:underline;color:#005aa0;">无需扫码，电脑上也可享受手机优惠价!</a>',
    'yihaodian': '<a id="bjd_m_price" href="{{url}}" target="_blank"  rel="noreferrer" title="{{title}}"style="text-decoration:underline;color:#06c;background-color: #fff4f2;display: block;padding-left: 10px;height: 26px;line-height: 26px;font-size: 13px;">手机专享价{{price}}，立即前往购买</a>',
    'dangdang': '<a id="bjd_m_price" href="{{url}}" target="_blank" rel="noreferrer" title="{{title}}"style="text-decoration:underline;color:#005aa0;">无需扫码，电脑上也可享受手机优惠价!</a>',
    'suning': '<a id="bjd_m_price" href="{{url}}" target="_blank" rel="noreferrer" title="{{title}}"style="text-decoration:underline;float:right;position:absolute;right:15px;width:110px;color: #003399;">前往手机版页面购买</a>',
    '51buy': '<a id="bjd_m_price" href="{{url}}" target="_blank" rel="noreferrer" title="{{title}}"style="text-decoration:underline;color:#06c;display: block;height: 26px;line-height: 26px;font-size: 13px;">手机专享价{{price}}，立即前往购买</a>',
    'gome': '<a id="bjd_m_price" href="{{url}}" target="_blank" rel="noreferrer" title="{{title}}"style="text-decoration:underline;color:#06c;display: block;height: 26px;line-height: 26px;font-size: 13px;">手机专享价{{price}}，立即前往购买</a>'

  }
  var insertPatterns = {
    '360buy': ['#m-pirce', '.J-prom-mbuy', '#prom-one'],
    'yihaodian': `#${G.extBrand}_promo_active_yihaodian`,
    'dangdang': '#mobile_exclusive_price',
    'suning': ['#qrCode .qrcode-main-img', '.ph-price-qrcode .qrcode-region'],
    '51buy': `#${G.extBrand}_promo_active_51buy`,
    'gome': '#shoujizhuanxiang_box'
  }
  exports.init = function(now, union) {
    thisunion = union;
    dp_now = now;
    if (forbitSite())
      hasMobilePrice()
  }

  function findPattern(pattern) {
    var doms = sitePatterns[pattern];
    for (var i = 0; i < doms.length; i++) {
      if ($(doms[i]).is(':visible') && siteHasMobile()) {
        now_site = pattern;
        sendUrl(thisunion);
        return;
      }
    }
    num++;
    if (num === 10) return;
    setTimeout(function() {
      findPattern(pattern);
    }, 1000)
  }

  function siteHasMobile() {
    var hasmobile = false,
      site = G.site;
    switch (site) {
      case '360buy':
        hasmobile = true;
        break;
      case 'dangdang':
        hasmobile = true;
        break;
      case 'suning':
        if ($('#qrCode').text().indexOf('手机购买') > -1) {
          hasmobile = true;
        } else if ($('#phoneOrderCode').text().indexOf('手机专享价') > -1 && $('#phoneOrderCode').is(':visible')) {
          hasmobile = true;
        } else {
          hasmobile = false;
        }
        break;
      case '51buy':
        if ($('#sea_desc').text().indexOf('手机专享价') > -1) {
          hasmobile = true;
        } else if ($('.xprice .m-qrcode .txt em').text().indexOf('手机购买省') > -1) {
          if ($('.xprice .m-qrcode .txt em').text().indexOf('￥0.00') > -1) return false;
          hasmobile = true;
        } else {
          hasmobile = false;
        }
        break;
      case 'gome':
        if ($('#shoujizhuanxiang_box .hl_red_bg').text() == '手机专享') {
          hasmobile = true
        }
        break;
      case 'yihaodian':
        if ($('#productSubName').text().indexOf('手机端下单') > -1) {
          hasmobile = true;
        } else {
          hasmobile = false;
        }
        break;
    }
    return hasmobile;
  }

  function hasMobilePrice() {
    for (var pattern in sitePatterns) {
      if (G.site === pattern)
        findPattern(pattern);
    }
    if (num === 0)
      return false;
  }

  function sendUrl(union) {
    var url = document.location.href;
    request.get(G.server + '/extension?ac=go_mobile&url=' + encodeURIComponent(url)).done(function(data) {
      if (data.url !== '' && data.status === 1) {
        if (G.btype == 'luyou' || G.from_device === 'juzi') {
          insert_a(data.url);
          insert_b(data.url);
        } else {
          renderMinibar(data.url)
        }
      }
    })
  }
  const renderBaidu = url => {
    let price = getPrice()
    let dom = `<li class="mobile_price">
              <span>手机专享</span>
              <a href="${url}" target="_blank">${price}</a>
            </li>`
    $('#bdext_minibar .promo-box ul').prepend($(dom))
    $('#bdext_minibar .promo-box').show()
    $('.bdext-toptabs .bdext-mini-logo, .bdext-mini-compare').addClass('hasPromo')
  }

  const renderMinibar = (url) => {
    if (G.from_device === 'baidu') {
      renderBaidu(url)
    } else {
      renderWishlistMobile(url)
    }
  }

  let renderWishlistMobile = (url) => {
    if (G.site === '360buy') return;
    if (G.site != '360buy' || G.from_device == 'mi_new')
      url = editUrl(url);
    if (!url) return;
    var price = getPrice()
    var spandom = `<li class="li_0" data-type="mob"><a href="${url}" title="购物党将带您前往手机版页面，以专享价购买商品" target="_blank" id="${G.extBrand}_mobile_price" rel="noreferrer"><span class="mobile_title" >专享价购买</span><span class="mobile_num">${price}</span>>></a></li>`;
    $('.promo_box_left ul').prepend($(spandom));
    var domli = $('.promo_box_left ul li');
    var len = domli.length;
    for (let i = 0; i < len; i++) {
      domli.eq(i).attr('class', 'li_' + i);
    }
    if (len < 3) {
      $(`#${G.extBrand}_wishlist_div`).addClass('oneline')
      $(`#${G.extBrand}_promo_box`).show()
      if (len == 1)
        $('.promo_shuxian').hide()
    } else {
      $(`#${G.extBrand}_wishlist_div`).removeClass('oneline').addClass('twolines')
    }
    cnzz.log('新版嵌入手机专享价展现')
    $(`#${G.extBrand}_mobile_price`).on('click', () => {
      cnzz.log('新版嵌入手机专享价点击')
    })
  }

  function forbitSite() {
    if (G.site == '360buy') {
      return true;
    } else {
      if ("ActiveXObject" in window) {
        return false;
      } else {
        return true;
      }
    }
  }

  function addEvent() {
    var color = '';
    $('#bjd_m_price').on('mouseenter', function() {
      color = $(this).css('color');
      if (G.site == 'suning' || G.site.indexOf('suning') > -1) {
        $(this).css('color', '#fff');
      } else {
        $(this).css('color', '#003399');
      }
    }).on('mouseleave', function() {
      $(this).css('color', color);
    })
    $('#bjd_m_price').on('click', function() {
      require('common/log')('click:mobile_price');
      cnzz.log('手机专享价点击')
    })
  }

  function insert_a(url) {
    if (!url || now_site != '360buy') return;
    var price = getPrice();
    var html = require("art-template-loader!common/views/mobileprice_1.html");
    $('#summary-price .dd').eq(0).append(template.compile(html)({
      url: editUrl(url),
      price: price,
      new_extension: G.new_extension,
      extBrand: G.extBrand
    }))

    $(`#${G.extBrand}_mobile_price`).on('click', function() {
      require('common/log')('click:mobile_price_360buy');
      cnzz.log('手机专享价点击2jd')
    })
  }

  function insert_b(url) {
    if (!url) return;
    var price = getPrice();
    var title = "购物党将带您前往手机版页面，以专享价购买商品";
    if (G.new_extension)
      title = '';
    var html = viewsPatterns[now_site];
    var insertPt
    if ($.isArray(insertPatterns[now_site])) {
      for (var i = 0; i < insertPatterns[now_site].length; i++) {
        if ($(insertPatterns[now_site][i]).length > 0) {
          insertPt = insertPatterns[now_site][i];
          break;
        }
      }
    } else {
      insertPt = insertPatterns[now_site];
    }
    if (now_site == 'dangdang' || now_site == 'suning' || now_site == '360buy' || now_site == '360buy_1') {
      $(insertPt).eq(0).after(template.compile(html)({
        url: editUrl(url),
        price: price,
        title: title
      }));
    } else {
      $(insertPt).eq(0).before(template.compile(html)({
        url: editUrl(url),
        price: price,
        title: title
      }));
    }
    cnzz.log('展现手机专享价')
    addEvent();
  }

  function editUrl(url) {
    let murl = G.toMobileUrl;
    return murl + "/union/go?site_id=" + dp_now.site_id + '&target_url=' + url + '&union=' + thisunion + '&column=zhuanxiang_' + dp_now.now_dp_id;
  }

  function getPrice() {
    var price = '';
    if (now_site == '360buy' || now_site == '360buy_1') {
      price = $(getPricePattern[now_site]).text();
    }
    if (now_site == 'dangdang') {
      price = $(getPricePattern[now_site]).text();
    }
    if (now_site == 'yihaodian') {
      var p = $("#productSubName").text().match(/([0-9.]+)元/);
      if (p) price = '¥' + p[1];
    }
    if (now_site == '51buy') {
      var p = $('#sea_desc').text().match(/专享价([0-9.]+)/);
      if (p) price = '¥' + p[1];
      else {
        var dpPrice = G.dp.price;
        var discount = $('.xprice .m-qrcode .txt em').text().match(/[0-9.]+/);
        if (discount) {
          discount = discount[0]
          dpPrice = Number(dpPrice) - Number(discount)
          price = '¥' + dpPrice;
        }
      }
    }
    if (now_site == 'suning') {
      var p = Number($('.qrcode-main-price em').text())
      if (p != '') {
        var nowPrice = G.dp.price;
        var price = (nowPrice - p).toString()
        if (price.indexOf('.') == -1) price = '¥' + price + '.00'
      } else {
        var p = $('#phoneOrderCode').text().match(/[0-9.]+/);
        if (p) p = p[0];
        if (p) price = '¥' + p;
      }
    }
    if (now_site == 'gome') {
      var saveprice = $('#savemoney').text().match(/[0-9.]+/)
      if (saveprice) saveprice = Number(saveprice[0]) || 0;
      var nowPrice = G.dp.price;
      var price = (nowPrice - saveprice).toString()
      if (price.indexOf('.') == -1) price = '¥' + price + '.00';
    }
    if (price.match(/[0-9]{5}/)) price = price.replace(/\.[0-9]+/, '')
    return price;
  }

  return exports;
});


