let parseprice = require('common/parseprice')
module.exports = (data) => {
  var newdata = [];
  var dp_price = G.dp.price || 0;
  if (G.site === '189') {
    for (let i=0; i<data.length; i++) {
      if (parseprice( data[i].price) >= dp_price)
        newdata.push(data[i])
    }
    return newdata;
  } else {
    return data;
  }
}
module.exports.tb = (data) => {
  if (data instanceof Array) return data;
  var newdata = [];
  var product = data.product
  var dp_price = G.dp.price || 0;
  for (let i=0; i<product.length; i++) {
    if (product[i].img_url && !(product[i].img_url.match(/_\d+x\d+/)) ) {
      product[i].img_url = product[i].img_url + '_100x100';
    }
    if (product[i].pic_url && !(product[i].pic_url.match(/_\d+x\d+/)) ) {
      product[i].pic_url = product[i].pic_url + '_100x100';
    }
  }
  if (G.site === '189') {
    for (let i=0; i<product.length; i++) {
      if (parseprice( product[i].price) >= dp_price)
        newdata.push(product[i])
    }
    data.min_price = newdata[0] && newdata[0].price;
    data.product = newdata;
  }
  return data;
  
}


