const communicate = require('common/communicate')

module.exports = {
  get(path, params, callback) {
    let reqId = parseInt(Math.random() * 10000).toString() + Date.now()
    return new Promise(resolve => {
      communicate.trigger({
        type: 'backgroundReq',
        reqId: reqId,
        path: path,
        params: typeof params === 'object' ? JSON.stringify(params): '{}',
        referer: location.href
      })
      communicate.on(resp => {
        if (resp.type === 'backgroundResp' && resp.value.reqId === reqId) {
          if (!callback) {
            try {
              resolve(JSON.parse(resp.value.data))
            } catch (e) {
              require('common/extConsole').error(e)
              require('common/extConsole').warn('bg resp json fail', resp.value.data)
              resolve(resp.value.data)
            }
            return
          }
          try {
            callback(JSON.parse(resp.value.data))
          } catch (e) {
            callback(resp.value.data)
          }
        }
      })
    })
  }
}



