const template = require('vendor/template')
const userData = require('common/userData')
const cnzz = require('common/cnzz')
const detect = require('common/detect')
const priceParser = require('common/priceParsers')

let time = 0;
let pageObj = {}
let animateLock

let posPattern = {
  'taobao': ["#detail .tb-item-info-l"],
  'tmall': [
    "#J_DetailMeta .tb-gallery"
  ]
}


module.exports.init = (data) => {
  if (G.forbidCoupon) return;
  if (G.ss_name === 'priceDog') return
  let tbData = userData.get('tbData')
  time++;
  if (tbData.ss === time) {
    var siteName = G.site;
    let siteId = detect.getSiteId(siteName)
    priceParser.init(siteId, function(price) {
      if (price && price > 0) {
        G.dp.oldPrice = price;
        G.dp.price = price;
      }
      render(data, tbData)
    });
  }
}

const editData = (data, tbData) => {
  let newdata = []
  for (let i = 0; i < data.taobao.length; i++) {
    for (let j = 0; j < tbData.taobao.product.length; j++) {
      let tbitem = tbData.taobao.product[j];
      if (data.taobao[i].reqid === tbitem.num_iid) {
        data.taobao[i].imgUrl = tbitem.pic_url;
        data.taobao[i].l_price = tbitem.price;
        data.taobao[i].title = tbitem.title;
        data.taobao[i].coupon_money = data.taobao[i].coupon.coupon_money;
        data.taobao[i].price = (Number(tbitem.price) - data.taobao[i].coupon.coupon_money).toFixed(2);
        if ((Number(tbitem.price) - data.taobao[i].coupon.coupon_money) <= G.dp.price) {
          newdata.push(data.taobao[i])
        }
      }
    }
  }
  for (let i = 0; i < data.tmall.length; i++) {
    for (let j = 0; j < tbData.tmall.product.length; j++) {
      let tmitem = tbData.tmall.product[j];
      if (data.tmall[i].reqid === tmitem.num_iid) {
        data.tmall[i].imgUrl = tmitem.pic_url;
        data.tmall[i].l_price = tmitem.price;
        data.tmall[i].title = tmitem.title;
        data.tmall[i].coupon_money = data.tmall[i].coupon.coupon_money;
        data.tmall[i].price = (Number(tmitem.price) - data.tmall[i].coupon.coupon_money).toFixed(2);
        if ((Number(tmitem.price) - data.tmall[i].coupon.coupon_money) <= G.dp.price) {
          newdata.push(data.tmall[i])
        }
      }
    }
  }
  newdata.sort(function(v1, v2) {
    return Number(v1.price) - Number(v2.price)
  })
  return newdata;
}

const render = (data, tbData) => {
  data = editData(data, tbData)
  let size = data.length;
  if (size === 0) return;
  $('body').addClass('dpc_' + G.site);
  let html = require('art-template-loader!./views/dpCouponImg.html')
  let doms = posPattern[G.site];
  for (let i = 0; i < doms.length; i++) {
    if ($(doms[i]).length > 0) {
      $(doms[i]).append(template.compile(html)({
        data: data,
        s_s: G.s_server,
        size: size,
        lang: G.lang
      }))
      break;
    }
  }
  if (size > 4) {
    pageObj.pages = Math.ceil(size / 4);
    pageObj.nowpage = 1;
  }

  addEvent(size)
}

const turnpage = (type) => {
  let dom = $('.dpcoupon-bd ul');
  let left = dom.css('left');
  left = Number(left.replace('px', '')) || 0;
  if (type === 1) {
    if (pageObj.nowpage === pageObj.pages) return;
    pageObj.nowpage++;
    left = left - 440;
  } else if (type === -1) {
    if (pageObj.nowpage === 1) return;
    pageObj.nowpage--;
    left = left + 440;
  }
  if (dom.animate) {
    animateLock = true;
    dom.animate({
      left: left + 'px'
    }, 300, function() {
      animateLock = false;
    })
  } else {
    dom.css('left', left + 'px')
  }

}

const addEvent = (size) => {
  $('.dpcoupon-bd').on('click', function() {
    cnzz.log('dpcouponimg:click')
  })
  $('.dpc-turn-l').on('click', function() {
    if (animateLock) {
      setTimeout(function() {
        turnpage(-1)
      }, 400)
    } else {
      turnpage(-1)
    }
  })
  $('.dpc-turn-r').on('click', function() {
    if (animateLock) {
      setTimeout(function() {
        turnpage(1)
      }, 400)
    } else {
      turnpage(1)
    }
  })
}



