<template>
  <div class="gwd-contact-link" @mouseover="over" :class="{'gwd-new-tm-style': withLogo}">
    <div v-if="withLogo" class="gwd-ww-logo"></div>
    <span class="gwd-contact-text">{{ transText('扫码联系客服') }}</span>
    <div class="gwd-app-qr-content gwd-column gwd-align" v-if="qr">
      <div class="gwd-qr-img" :style="`margin-top: 7px; margin-left: 7px; margin-right: 7px; height: 111.04px; position: relative; width: 111.04px;`">
        <img src="../assets/taoQr@2x.png" alt="" class="gwd-qr-logo">
        <img :src="qr" alt="" style="width: 100%">
      </div>
      <div class="gwd-row gwd-align gwd-qr-bottom-line" :style="'margin-top: 6px;'">
        <span class="bold" :style="'font-size: 20px;'">{{ transText('淘宝APP') }}</span>
        <span class="normal" :style="'font-size: 18px'">{{ transText('扫码') }}</span>
        <span class="normal" style="margin-left: 10px;">{{ transText('联系客服') }}</span>
      </div>
    </div>
  </div>
</template>
<style scoped lang="less">
  .gwd-ww-logo {
    display: inline-block;
    width: 20px;
    height: 22px;
    background-image: -webkit-image-set(url("//img.alicdn.com/tps/i1/T15AD7FFFaXXbJnvQ_-130-60.gif") 1x,url("//img.alicdn.com/tps/i4/T1Rsz7FPJaXXbZhKn7-520-240.gif") 4x);
    background-position: -110px 0;
    margin-right: 5px;
  }

  .gwd-qr-bottom-line {
    span.bold {
      font-size: 22px;
      font-weight: bold;
      color: #EF6701;
    }
    span.normal {
      font-size: 16px;
      color: #070707;
    }
    transform: scale(0.5);
    transform-origin: top center;
    white-space: nowrap;
    height: 20px;
    line-height: 20px;
  }

  .gwd-qr-logo {
    position: absolute;
    left: 50%;
    top: 50%;
    width: 20px;
    height: 20px;
    margin-left: -10px;
    margin-top: -10px;
  }

  .gwd-contact-link {
    margin-left: 7px;
    top: -3px;
    display: inline-block;
    font-size: 12px;
    color: #333333;
    text-decoration: underline;
    cursor: pointer;
    position: relative;
    z-index: 999999;
    .gwd-app-qr-content {
      position: absolute;
      width: 123px;
      height: 137px;
      background: #FFF3ED;
      border-radius: 0px 0px 2px 2px;
      border: 1px solid #FF9851;
      top: 24px;
      left: -38px;
      visibility: hidden;
      z-index: 999;
    }
  }

  .gwd-contact-link:hover {
    .gwd-app-qr-content {
      visibility: visible;
    }
  }

  .gwd-contact-link.gwd-new-tm-style {
    text-decoration: none;
    position: relative;
    top: 18px;
    display: inline-flex;
    align-items: center;
    z-index: 0;
    .gwd-contact-text {
      text-decoration: underline;
    }
    .gwd-app-qr-content {
      left: -14px;
    }
  }

</style>
<script>
  import MemberCouponMixin from "common/components/MemberCouponMixin";

  export default {
    props: ['withLogo'],
    mixins: [MemberCouponMixin],
    methods: {
      transText(text) {
        const map = {
          '扫码联系客服' : '掃碼聯繫客服',
          '淘宝APP': '淘寶APP',
          '扫码': '掃碼',
          '联系客服': '聯繫客服'
        }
        if (G.lang === 'zh-tr') {
          return map[text]
        }
        return text
      }
    }
  }
</script>



