function getWeightNum(t) {
  let p = t.match(/[0-9]+(?:\.|\,|)(?:[0-9]+|)/)
  if (p)
    p = p[0]
  if (HOST == 'www.amazon.de')
    p = p.toString().replace(',', '.')
  return p;
}

function getWeightType(t) {
  switch (HOST) {
    case 'www.amazon.com':
      if (t.indexOf('pounds') > -1)
        return 'pounds'
      if (t.indexOf('ounces') > -1)
        return 'ounces'
      break;
    case 'www.amazon.de':
      if (t.indexOf('Kg') > -1)
        return 'kg'
      if (t.indexOf('g') > -1)
        return 'g'
      break;
    case 'www.amazon.co.jp':
      if (t.indexOf('Kg') > -1)
        return 'kg'
      if (t.indexOf('g') > -1)
        return 'g'
      break;
    case 'www.6pm.com':
      if (t.indexOf('lb') > -1 && t.indexOf('oz') > -1)
        return 'lb_oz'
      if (t.indexOf('lb') > -1)
        return 'pounds'
      if (t.indexOf('oz') > -1)
        return 'ounces'
      break;
  }
}

function getWeight(noCache) {
  if (HT.weight && !noCache) return HT.weight;
  let weight_1 = 0;
  let domarr = weightDom[HOST];
  let len = domarr.length;
  for (let i = 0; i < len; i++) {
    let w = $(domarr[i]).text()
    if (w != '') {
      let type = getWeightType(w)
      if (type == 'lb_oz') {
        let m = w.match(/[0-9]+/g)
        weight_1 = Math.round((weightDict['pounds'] / 1000 * parseInt(m[0]) + weightDict['ounces'] / 1000 * parseInt(m[1])) * 100) / 100
        HT.weight = weight_1;
        return weight_1;
      }
      if (type != '') {
        weight_1 = Math.round((weightDict[type] / 1000) * getWeightNum(w) * 100) / 100
        if (weight_1 !== 0 && !weight_1) weight_1 = 0;
        HT.weight = weight_1;
        return weight_1;
      }
    }
  }
}

