let tm
let load
let caches
function addcnzz(c) {
  // var head = document.getElementsByTagName('head')
  // if(head && head[0]) head = head[0]
  // var script = document.createElement('script');
  // script.src = c;
  // script.async = true;
  // script.defer = true;
  // script.language = "JavaScript";
  // head.appendChild(script);
  // load = true
}

module.exports.init = function(cnzz) {
  if (cnzz) {
    addcnzz(cnzz);
  }
  setTimeout(() => {
    log('ChromeVersion', require('common/browserType').getChromeVersion())
  }, 1000)
  if (navigator.userAgent.toLowerCase().includes('edg')) {
    G.browser = 'edge'
  } else {
    G.browser = G.from_device
  }
}

window.cnzzLogCount = 0

const log = function(category, action, label, value, nodeid) {
  window.cnzzLogCount ++
  // console.log('cnzz', [category, action, label, value, nodeid])
  if(!load) {
    //console.log('cnzz not load')
    return
  };
  if (caches === category) {
    clearTimeout(tm)
    tm = setTimeout(() => {
      if (window._czc && window._czc.push) {
        action = action || '.'
        label = label || ''
        window._czc.push(["_trackEvent", category, action, label, value, nodeid]);
        caches = category;
      }
    }, 300)
  } else {
    if (window._czc && window._czc.push) {
      action = action || '.'
      label = label || ''
      window._czc.push(["_trackEvent", category, action, label, value, nodeid]);
      caches = category;
    }
  }
  
}

let logged = []
const logOnce = function(category, action, label, value, nodeid) { // 同log，只记录一次
  let id = [category, action, label, value, nodeid].join('-')
  if (logged.indexOf(id) === -1) {
    log(category, action, label, value, nodeid)
    logged.push(id)
  }
}

module.exports.log = log
module.exports.logOnce = logOnce

// 记录某个元素的曝光和悬浮
module.exports.hoverLog = (element, name) => {
  setTimeout(() => {
    if ($(element).length) {
      log(name, '曝光')
    }
    $(element).hover(() => {
      logOnce(name, '悬浮')
    })
  }, 0)
}


