<template>
  <component :is="type === 'link' ? 'a': 'div'"
             :href="alterHref"
             @mouseenter="over()"
             target="_blank"
             :title="type === 'link' ? '点击领取': ''"
             class="gwd-row gwd-align gwd-coupon-bar">
    <div v-if="showStampBg" class="gwd-coupon-color-bg gwd-tl"></div>
    <div v-if="showStampBg" class="gwd-coupon-color-bg gwd-br"></div>
    <img :src="icon" alt="" style="margin-left: 12px; margin-right: 8px; max-height: 20px; z-index: 1">
    <span :style="`color: ${mainColor}; font-size: 14px`" v-html="text"></span>
    <div style="flex: 1">
      <Stamp v-if="rebate" :value="rebate" style="right: 109px; top: 0; position: absolute"/>
    </div>
    <!-- <CouponArrow v-if="type === 'link'" :color="mainColor"/> -->
    <span v-if="type === 'link'" class="gwd-round-click" :style="`background: linear-gradient(180deg, ${secondColor} 0%, ${mainColor} 100%); z-index: 1`">点击领取</span>
    <div v-if="type === 'qr'" class="gwd-take gwd-row gwd-align" :style="`background: url(${takeBg})`">
      <span :style="`color: ${mainColor}`">￥{{ couponValue }}</span>
      <span style="color: white">领取</span>
    </div>
    <div v-if="type === 'qr'" class="gwd-qr-hover-window gwd-column gwd-align" :style="`border-color: ${mainColor}`">
      <img :src="actualQr" alt="" style="width: 120px; height: 120px; margin-top: 8px;" v-if="!error && actualQr">
      <QRError v-if="error" @refresh="over"/>
      <div style="margin-top: 8px;" class="gwd-row">
        <span :style="`color: ${mainColor}; font-size: 12px;`">微信扫码</span>
        <span style="color: #070707; font-size: 12px; transform: scale(0.8333); transform-origin: center left; margin-top: 1px">{{ qrTitle }}</span>
      </div>
    </div>
  </component>
</template>
<style scoped lang="less">
  .gwd-coupon-bar {
    font-family: "PingFang SC-Medium", "Microsoft YaHei", "Arial", "SimSun",serif;
    font-size: 12px;
    background: white;
    position: relative;
    .gwd-round-click {
      margin-left: 24px;
      margin-right: 12px;
      display: block;
      width: 68px;
      height: 20px;
      text-align: center;
      border-radius: 4px;
      color: white;
      font-weight: bold;
    }

    .gwd-take {
      margin-right: 12px;
      width: 74px;
      height: 20px;
      font-size: 12px;
      span {
        flex: 1;
        text-align: center;
      }
    }

    .gwd-qr-hover-window {
      width: 136px;
      height: 160px;
      background: #fff9f6;
      position: absolute;
      box-sizing: border-box;
      border-width: 1px;
      border-style: solid;
      top: 37px;
      left: 345px;
      display: none;
      z-index: 99;
    }

    border: 1px solid #e8e8e8;
    border-top: none;
    width: 462px;
    box-sizing: border-box;
    height: 38px;
  }

  .gwd-coupon-bar:hover {
    text-decoration: none;
    .gwd-qr-hover-window {
      display: flex;
    }
  }
</style>
<style lang="less">
.gwd-coupon-color-bg {
  position: absolute;
  z-index: 0;
  background-size: contain;
  &.gwd-tl {
    top: 0;
    left: 0;
    width: 30px;
    height: 28px;
    background-image: url(https://cdn.gwdang.com/images/extensions/coupon-tl-bg@2x.png);
  }
  &.gwd-br {
    bottom: 0;
    right: 49px;
    width: 46px;
    height: 23px;
    background-image: url(https://cdn.gwdang.com/images/extensions/coupon-br-bg@2x.png);
  }
}
</style>
<script>
  import CouponArrow from './CouponArrow'
  import QRError from 'common/components/QrError'
  import Stamp from './Widgets/Stamp'

  const getQRCode = require('common/coupon/getQRCode')

  export default {
    props: [
        'type', // link, qr,
        'href',
        'text',
        'icon',
        'mainColor',
        'secondColor',
        'takeBg',
        'couponValue',
        'qrParams',
        'qrTitle',
        'qrUrl',
        'rebate',
    ],
    components: { CouponArrow, QRError, Stamp },
    data: () => ({
      loading: false,
      error: false,
      actualQr: '',
      showStampBg: G.from_device === '360server' || navigator.userAgent.includes('Edg')
    }),
    computed: {
      alterHref() {
        return require('common/productInfo').appendTbInfoForUrl(this.href)
      }
    },
    mounted() {
      if (G.aliSite) {
        require('standard/module/tbScrollLink').add(this.text, this.icon, require('common/productInfo').appendTbInfoForUrl(this.href), this.mainColor, this.secondColor, this.showStampBg, this.rebate)
      }
    },
    methods: {
      over() {
        this.$emit('over')
        if (this.type !== 'qr' || this.loading) return
        if (this.qrUrl) {
          this.actualQr = this.qrUrl
          return
        }
        this.loading = true
        getQRCode(this.qrParams, '', (res) => {
          this.loading = false
          if (res[0].etag) {
            this.error = true
          } else {
            this.error = false
            this.actualQr = res[0].imgSrc
          }
        })
      }
    }
  }
</script>


