const template = require('vendor/template')
const getPromoInfo = require('common/getPromoInfo')
const cnzz = require('common/cnzz')
const log = require('common/log')
const request = require('common/request')

let now_dp_id
let posPattern = {
  '360buy': [
    '#notice-downp',
    '.J-notify-sale',
    '.summary-price .dd .p-price+em',
    '#summary-wrap .dd .p-price',
    '.summary-price .dd>:last-child'
  ],
  'suning': [
    '#mainPrice dd #PriceNotice1',
    '#mainPrice dd .btn-price-notice',
    '#mainPrice dd .btn-price-business',
    '#mainPrice dd .mainprice'
  ],
  'taobao': [],
  'tmall': [],
  'dangdang': []
}

const getJdPromotion = (info) => {
  if (G.site !== '360buy') return;
  let dp = G.dp;
  let skuId = dp.itemId.replace('-3', '');
  if (!dp.cat_id) return;
  let catarr = dp.cat_id.split('-')
  catarr = catarr.slice(0, 3)
  let cat = encodeURIComponent(catarr.join(','));
  let price = dp.price.toFixed(2);
  let area = $('.ui-area-text').attr('data-id').replace(/-/g, '_') + '_0';
  let timeStr = new Date().getTime()
  let url = `https://cd.jd.com/promotion/v2?skuId=${skuId}&area=${area}&shopId=${dp.shopId}&venderId=${dp.venderId}&cat=${cat}&isCanUseDQ=isCanUseDQ-1&isCanUseJQ=isCanUseJQ-1&platform=0&orgType=2&jdPrice=${price}&appid=1&_=${timeStr}`;
  // request.get(url).done((data) => {
  //   callback(info, data)
  // })
}
const getProMidPage = (id, callback) => {
  let url = `https://browser.gwdang.com/extension?ac=promoUrl&promo_id=${id}`;
  request.get(url).done((data) => {
    callback(data)
  })
}

const renderServerOnHandPriceResult = (resp) => {
  let html = require('art-template-loader!./views/disPrice2.html')
  let dom = $('#coupon_box')
  if (G.from_device.indexOf('bijiago') > -1 || G.from_device.indexOf('biyibi') > -1) {
    dom = $('#coupon_box_bjg')
    html = require('art-template-loader!../bjgou/views/disPriceBjgou.html')
  } else {
    $('.gwd-minibar-bg > .dsj-content').remove()
  }
  if (dom.length === 0) {
    if (G.from_device.indexOf('bijiago') > -1 || G.from_device.indexOf('biyibi') > -1) {
      dom = $('.promo-box')
      html = require('art-template-loader!../bjgou/views/disPriceBjgou.html')
    } else {
      dom = $('#gwd_minibar')
    }
  }
  if (G.from_device.indexOf('bijiago' ) > -1 || G.from_device.indexOf('biyibi') > -1) {
    $('#bjg-dsj-placeholder').replaceWith(template.compile(html)({
      tle: '',
      desc: resp.promo_list.map(item => {
        if (item.id) {
          let trueUrl = item.id.indexOf('http') === 0 ? item.id: `https:${item.id}`
          trueUrl = encodeURIComponent(trueUrl)
          let url = item.url_format.replace('$URL', trueUrl)
          return `<a href="${url.replace('ext_promo_calc', 'promo_calc')}" target="_blank" style="text-decoration: underline">${item.text}</a>`
        }
        return item.text
      }).join(';'),
      pri: parseFloat(resp.current_price).toFixed(2),
      lang: G.lang
    }))
    if ($('.promo-box').css('display') !== 'none') {
      setTimeout(() => {
        $('.promo-box').prev().css('border-bottom', '1px solid #e6e9eb')
        $('.promo-box').prev().css('width', '100%')
      }, 0)
    }
  } else if (resp && resp.promo_list) {
    let promo2 = {
      tle: '',
      desc: resp.promo_list.map(item => {
        if (item.id) {
          let trueUrl = item.id.indexOf('http') === 0 ? item.id: `https:${item.id}`
          trueUrl = encodeURIComponent(trueUrl)
          let url = item.url_format.replace('$URL', trueUrl)
          //
          // if (item.tag === 'promo') {
          //   globalPromoLink.push({
          //     text: item.text,
          //     url: url.replace('ext_promo_calc', 'promo_calc')
          //   })
          // }
          // if (item.tag === 'coupon') {
          //   globalCouponLink.push({
          //     text: item.text,
          //     url: url.replace('ext_promo_calc', 'promo_calc')
          //   })
          // }
          return `<a href="${url.replace('ext_promo_calc', 'promo_calc')}" target="_blank" style="text-decoration: underline">${item.text}</a>`
        }
        return item.text
      }).join(';'),
      pri: parseFloat(resp.current_price).toFixed(2)
    }
    $('#gwd-dsj-placeholder').replaceWith(template.compile(html)(promo2))
  }
  require('common/promotionPlan').init()
  var img = new Image()
  let promotle = encodeURIComponent(resp.promo_text)
  img.src = `${G.tj_server}/visit/?action=dspricelog&pagePri=${G.dp.price}&dsprice=${resp.current_price}&dp_id=${now_dp_id}&promo=${promotle}`
  cnzz.log('track:dspriceAll')
  log('track:dspriceAll')
  // 获取促销活动对应的网站页面
  getJdPromotion(resp)
  calwidth();

}

const calwidth = () => {
  // let logoW = $('.dsj-content>em').outerWidth() + 22;
  // let priW = $('.dsj-pri-info').outerWidth() + 10;
  // let remindW = $('.dsj-remind-icon').outerWidth() + 12;
  // let freeW = 460 - (logoW + priW + remindW) - 10;
  // $('.dsj-promo-link').width(freeW);
}


module.exports.init = (dp_id) => {
  now_dp_id = dp_id;
  if (!posPattern[G.site]) return;
  getPromoInfo.getPrice(renderServerOnHandPriceResult)
  // getPromoInfo.getPrice(render)
}



