const request = require('common/request')
const template = require('vendor/template')
const getQRCode = require('common/coupon/getQRCode')
const globalCondition = require('common/globalCondition')
const cnzz = require('common/cnzz')

let bdom, mdom


module.exports.init = (dp_id, bardom, minidom) => {
  bdom = bardom;
  mdom = minidom
  if (['360buy', 'yangkeduo'].indexOf(G.site) === -1) {
    // setTimeout(() => {
    //   require('bjgou/modules/specialActivityBjgou').init(false)
    // }, 1000)
    return
  };
  let url
  getCouponInfo(dp_id, url, renderCoupon)
}

const getCouponInfo = (dp_id, url, callback) => {
  G.dp.itemId = dp_id
  dp_id = dp_id ? `dp_id=${dp_id}` : '';
  url = url ? `url=${url}` : '';
  let url2 = `${G.server}/extension/Coupon?${dp_id}${url}`;
  request.get(url2).then((data) => {
    if (data.coupon && data.click_url) {
      globalCondition.setMet('coupon', data.coupon)
      callback(data)
      setTimeout(() => {
        require('bjgou/modules/specialActivityBjgou').init(true)
      }, 1000)
    }else if (G.site === 'yangkeduo') {
      data.coupon = 0
      callback(data)
      setTimeout(() => {
        require('bjgou/modules/specialActivityBjgou').init(false)
      }, 1000)
    } else {
      globalCondition.setMet('coupon', 0)
      setTimeout(async () => {
        await globalCondition.met('noOtherGiftMoney')
        require('bjgou/modules/specialActivityBjgou').init(false)
      }, 1000)
      require('bjgou/modules/subsidy').init()
    }
  })
}

const showCustomQrCode = (content, couponValue = '') => {
  if (G.site !== 'yangkeduo') return ;
  if ($('html').hasClass('gwd_yangkeduo')) return ;
  const templateHtml = require('art-template-loader!./views/qrcode-bijiago.html')
  let result = template.compile(templateHtml)({
    qrcode: content,
    s_server: G.s_server,
    coupon: couponValue
  });
  $('body').append(result);
};

const renderCoupon = (data) => {
  require('common/log')('coupon:show')
  let tle = "点击领券"
  let html = require('art-template-loader!./views/topCoupon.html')
  if (G.lang === 'zh-tr') {
    html = require('art-template-loader!bjgou/views/topCoupon.html')
  }
  $('#bijiago-banner-ad').remove()
  if (G.site === 'yangkeduo' || data._jump === 'qrcode') {
    let productInfo = {
      itemNumId: G.dp.itemId,
      amount: data.coupon,
      couponUrl: data.click_url,
      discountPrice: data.price,
      effectiveStartTime: data.start_time,
      effectiveEndTime: data.end_time,
      id: G.dp.itemId,
      picUrl: $('.islider-outer img').attr('src'),
      pid: 'top',
      tmall: false,
      pdd: G.site === 'yangkeduo',
      shopName: G.site === 'yangkeduo' ? '拼多多': '京东',
      title: $('.enable-select').text()
    };
    if (G.site === 'yangkeduo') {
      getQRCode(productInfo, data.click_url, function (qrcodeData) {
        if (parseInt(data.coupon)) {
          $(bdom).append(template.compile(html)({
            price: data.coupon,
            url: data.click_url,
            tle: tle,
            isShowPic: true,
            picUrl: qrcodeData[0].imgSrc,
            isBottom: true,
            lang: G.lang
          }));
          showCustomQrCode(qrcodeData[0].imgSrc, `当前商品领券立减${data.coupon}元`)
        } else {
          showCustomQrCode(qrcodeData[0].imgSrc)
        }
      }, true)
    } else {
      if (parseInt(data.coupon)) {
        $(bdom).append(template.compile(html)({
          price: data.coupon,
          url: data.click_url,
          tle: tle,
          isShowPic: true,
          picUrl: 'xx',
          isBottom: true
        }));
      }
      let qr = false
      $('#top_coupon_btn').hover(() => {
        if (qr) return
        getQRCode(productInfo, data.click_url, function (qrcodeData) {
          qr = true
          $('#top_coupon_btn img').attr('src', qrcodeData[0].imgSrc)
        }, true)
      })
    }
  } else {
    $(bdom).after(template.compile(html)({
      price: data.coupon,
      url: data.click_url,
      tle: tle,
      isShowPic: false,
      lang: G.lang
    }))
  }
  renderMini(data)
  if (G.site === '360buy') {
    cnzz.log('京东顶部优惠券', '展示')
    cnzz.log('京东中间优惠券', '展示')

    $('#top_coupon_btn').click(function() {
      cnzz.log('京东顶部优惠券', '点击')
    });
    $('#top_coupon_btn').hover(function() {
      cnzz.logOnce('京东顶部优惠券', '悬浮')
    });

    $('.bjgou-coupon-take').click(function() {
      cnzz.log('京东中间优惠券', '点击')
    });
    $('.bjgou-coupon-take').hover(function() {
      cnzz.logOnce('京东中间优惠券', '悬浮')
    });

    require('common/components/JdFakeBtn').init(data.click_url, G.lang === 'zh-tr' ? '領券下單': '领券下单')
  }
}
const renderMini = (info) => {
  let data = {
    coupon: {
      coupon_money: info.coupon
    },
    click_url2: info.click_url
  }
  let html = require('art-template-loader!../bjgou/views/aliMiniCoupon.html')
  let views = template.compile(html)({
    data: data,
    isShowPic: false,
    site: G.site
  });
  let productInfo = {
    itemNumId: G.dp.itemId,
    amount: data.coupon,
    couponUrl: data.click_url,
    discountPrice: data.price,
    effectiveStartTime: data.start_time,
    effectiveEndTime: data.end_time,
    id: G.dp.itemId,
    picUrl: $('.islider-outer img').attr('src'),
    pid: 'top',
    tmall: false,
    pdd: G.site === 'yangkeduo',
    shopName: G.site === 'yangkeduo' ? '拼多多': '京东',
    title: $('.enable-select').text()
  };
  $('#bjg-coupon-placeholder').replaceWith(template.compile(html)({
    data: data,
    price: data.coupon,
    url: data.click_url2,
    tle: G.dp.title,
    isShowPic: info._jump === 'qrcode',
    picUrl: 'xx',
    isBottom: false,
    lang: G.lang,
    site: G.site
  }))
  setTimeout(() => {
    let qr = false
    $('.bjgou-coupon-take').hover(() => {
      if (!qr) {
        getQRCode(productInfo, data.click_url2, function (qrcodeData) {
          qr = true
          $('.bjgou-coupon-take img').attr('src', qrcodeData[0].imgSrc)
          $('.bjgou-coupon-take img').css('visibility', 'visible')
        }, true)
      }
    })
  }, 0)
}



