<template>
  <div class="btn-lg gwd-btn" @mouseover="over">
    {{ text }}
    <div class="qrcode gwd-align" v-if="qr">
      <img :src="qrcode" alt="" style="margin-top: 7px; width: 130px; height: 130px;"
           :style="qrcode ? '': 'visibility: hidden'">
      <QrError @refresh="over" v-if="error"/>
      <div style="margin-top: 4px; text-align: center; line-height: initial">
        <span style="font-weight: bold; color: #f40f0f; font-size: 14px;">微信扫码</span>
        <span style="margin-left: 4px; color: #070707; font-size: 12px;">领红包</span>
      </div>
    </div>
  </div>
</template>
<style scoped lang="less">
  .gwd-btn {
    position: relative;
    background: #48befe;
    color: white;
    .qrcode {
      display: none;
      position: absolute;
      top: 46px;
      left: -2px;
      width: 144px;
      height: 167px;
      background: #FFF7F7;
      border: 1px solid #FF2D53;
      z-index: 9;
    }
  }

  .gwd-btn:hover .qrcode {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-decoration: none!important;
  }

</style>
<script>
import GiftMoneyMixin from './GiftMoneyMixin'
import QrError from './QrError.vue'

export default {
  mixins: [GiftMoneyMixin],
  components: {QrError},
  props: ['value', 'url', 'qr', 'id', 'price', 'tag', 'text'],
}
</script>



