<template>
  <div class="gwd-qrlink-left gwd-row gwd-align" @mouseenter="over"
       :style="`left: ${left}px; ${bottom ? 'bottom: ' + bottom + 'px': ''}`">
    <span style="margin-left: 8px; font-size: 12px; color: #333333; width: 48px; line-height: 14px;">{{ transText('手淘扫码') }}{{ hasBuyButton ? transText('查看优惠'): transText('快捷购买') }}</span>
    <img src="../assets/taoQrLogo@2x.png" alt="" style="width: 24px; height: 24px; margin-left: 6px;">
    <img src="../assets/downTriangle.svg" alt="" style="width: 12px; height: 12px; margin-left: 8px;">
    <div class="gwd-qr-content gwd-align gwd-column">
      <img :src="qr" alt="" style="width: 98px; height: 98px;" v-if="qr">
      <img src="../assets/taoQr@2x.png" alt="" style="width: 20px; height: 20px; position: absolute; left: 50%; top: 42px; transform: translate(-50%, 0%);">
    </div>
  </div>
</template>
<style scoped lang="less">
  .gwd-qrlink-left {
    width: 109px;
    height: 44px;
    background: white;
    border-radius: 2px;
    // border: 1px solid #EAEAEA;
    position: fixed;
    //bottom: 205px;
    border-top-right-radius: 8px;
    border-bottom-right-radius: 8px;
    z-index: 999;
    top: 548px;
    left: 0px;
    cursor: pointer;
    box-sizing: border-box;
    box-shadow: 2px 2px 30px 0px rgba(97,105,119,0.18);
    .gwd-qr-content {
      position: absolute;
      width: 109px;
      height: 108px;
      border: 1px solid #eaeaea;
      padding-top: 5px;
      display: none;
      top: 43px;
      left: -1px;
      box-sizing: border-box;
      z-index: 9999;
      background: white;
      border-radius: 8px;
    }
  }

  .gwd-qrlink-left:hover {
    .gwd-qr-content {
      display: flex;
    }
  }
</style>
<script>
  import MemberCouponMixin from "common/components/MemberCouponMixin";

  export default {
    props: ['left', 'bottom'],
    mixins: [MemberCouponMixin],
    data: () => ({
      hasBuyButton: true
    }),
    methods: {
      transText(text) {
        const map = {
          '手淘扫码' : '手淘掃碼',
          '查看优惠': '查看優惠',
          '快捷购买': '快捷購買'
        }
        if (G.lang === 'zh-tr') {
          return map[text]
        }
        return text
      }
    },
    mounted() {
      setTimeout(() => {
        if ($('#J_ButtonWaitWrap').length) {
          this.hasBuyButton = false
        }
      }, 500)
    }
  }
</script>



