module.exports = {
  init() {
    setTimeout(() => {
      let list = $('.bjgext-item-dp').toArray().filter(x => {
        return x.dataset.id.indexOf('-83') > -1 || x.dataset.id.indexOf('-123') > -1
      })
      let pidConfig = require('bjgou/modules/pidConfig');

      list.forEach(async item => {
        if ($(item).find('.bjgext-item-img .coupon_span').length > 0) {
          return
        }
        const coupon = await require('common/getCouponNew').initWithDpAsync(item.dataset.id, pidConfig[G.union], 'compare');
        if (coupon && coupon.data) {
          const m = coupon.data.coupon.coupon_money
          const html = `<span class="coupon_span">领${m}元券</span>`
          $(item).find('.bjgext-item-img').append(html)
        }
      })
    }, 1000)
  }
}



