// const data = require('data/transport.json')

module.exports.init = (data) => {
  if (!(G.aliSite || G.site === '360buy')) {
    return
  }
  // let match = classId ? data[classId]: ''
  // if (!match && classId) {
  //   match = data[classId.substr(0, 4) + '0000']
  // }
  // require('common/extConsole').log(match)
  // if (!match) {
  //   match = {
  //     catName: ''
  //   }
  // }
  require('standard/module/util').waitForConditionFn(() => $('#bjgext_mb_bg').length)

  const el = document.createElement('DIV')
  $('#bjgext_mb_bg').prepend(el)
  const TransPort = require('bjgou/components/TransPort').default
  new Vue({
    el: el,
    render: h => h(TransPort, {
      props: {
        data: data
      }
    })
  })
}


