<template>
  <div class="bjg-bar-button"
       :class="hide ? 'bjg-hide': ''"
       @click="ppClick()"
       :style="hintShow ? 'width: 144px': (notifyCount > 0 || (user && userAgreed && enabled && !isJdLogin) ? 'width: 128px;': '')" ref="btn">
    <img src="../assets/protectIcon@2x.png" alt="" style="width: 19px; height: 22px; margin-left: 15px;">
    <span style="margin-left: 10px; font-size: 14px; color: #64615d">价格保护</span>
    <img src="../assets/new@2x.png" alt="" style="width: 32px; height: 16px; position: absolute; top: 10px; right: 10px;" v-if="hintShow">
    <div class="bjg-notify" style="width: 16px; height: 16px; position: absolute; top: 10px; right: 14px;" v-if="notifyCount > 0">
      {{ notifyCount }}
    </div>
    <div class="bjg-notify bjg-alert" style="width: 16px; height: 16px; position: absolute; top: 10px; right: 14px;" v-if="user && userAgreed && enabled && !isJdLogin"></div>
    <BjgBottomWindow
        v-if="(user && isJdLogin)"
        name="价保"
        @mouseover="mouseOver"
        :style="positionStyle + 'px;' + (forceOpen ? 'display: block': '')">
      <PriceProtectAuthLoginRequest
          @userAgreed="setEnable()"
          v-if="!userAgreed"
          :login="user"></PriceProtectAuthLoginRequest>
      <PriceProtectJdLogin v-if="user && userAgreed && enabled && !isJdLogin"></PriceProtectJdLogin>
      <JdItemList
          ref="jdItemList"
          v-show="user && userAgreed && isJdLogin && enabled"
          @needLogin="isJdLogin = false">
      </JdItemList>
      <div v-if="user && userAgreed && !enabled" class="gwd-column gwd-align bjg-pp-disabled" style="height: 201px; background: white">
        <img src="../assets/forbidden.svg" alt="" style="margin-top: 30px; width: 30px; height: 30px;">
        <span style="margin-top: 14px;">价格保护功能关闭</span>
        <span>无法获取最新价保信息</span>
        <button class="gwd-button" style="margin-top: 30px;" @click="enable()">重新开启</button>
      </div>
      <div class="bjg-window-bottom gwd-row gwd-align" v-if="user">
        <GwdA href="https://www.bijiago.com/priceProtectIntro/" target="_blank" style="margin-left: 14px;">价格保护使用帮助</GwdA>
        <GwdA href="https://pcsitepp-fm.jd.com/" target="_blank" style="margin-left: 32px;">京东价格保护中心</GwdA>
        <div style="flex: 1"></div>
        <img src="../assets/gear.svg" alt="" style="width: 16px; height: 15px; margin-right: 14px;" @click="settingOpen = !settingOpen" v-if="user && isJdLogin && enabled">
      </div>
      <div class="gwd-column gwd-align bjg-setting" v-show="enabled && settingOpen">
        <span style="margin-top: 6px; font-size: 12px; color: #333333">是否开启价保</span>
        <img src="../assets/yellowSwitch.svg" alt="" style="width: 33px; height: 18px; margin-top: 6px;" @click="disable">
      </div>
    </BjgBottomWindow>
  </div>
</template>
<style scoped lang="less">
  .bjg-hide {
    width: 0!important;
    overflow: hidden;
    border-left: none;
  }

  .bjg-notify {
    background: url("../assets/bubble.png");
    background-size: contain;
    text-align: center;
    font-size: 12px;
    color: white;
  }

  .bjg-alert {
    background: url("../assets/bubbleAlert@2x.png");
    background-size: contain;
  }

  .bjg-pp-disabled {
    span {
      font-size: 12px;
      color: #8c847b;
      line-height: 20px;
    }
    .gwd-button {
      width: 340px;
      height: 30px;
      border-radius: 15px;
      text-align: center;
      font-size: 14px;
      font-weight: bold;
      color: white;
      background: linear-gradient(270deg, #FFCD47 0%, #FF9F22 100%);
    }
  }

  .bjg-setting {
    width: 92px;
    height: 52px;
    background: white;
    position: absolute;
    border: 1px solid #f1f1f1;
    bottom: 41px;
    right: 0;
  }

  .bjg-bar-button {
    width: 114px;
    height: 100%;
    position: relative;
    display: flex;
    align-content: center;
    align-items: center;
    //justify-content: center;
    border-left: 1px solid #f1f1f1;
    border-right: 1px solid #f1f1f1;
    font-size: 0;
  }

</style>
<script>
  import { mapState } from 'vuex'

  import PriceProtectAuthLoginRequest from './PriceProtectAuthLoginRequest.vue'
  import PriceProtectJdLogin from './PriceProtectJdLogin.vue'
  import JdItemList from './JdItemList.vue'
  import BjgBottomWindow from './BjgBottomWindow.vue'
  import GwdA from 'common/components/GwdA.vue'

  import BottomWindowMixin from "../mixins/BottomWindowMixin";

  const user = require('../modules/user')
  const client = require('common/background/bgClient')
  const cnzz = require('common/cnzz')
  // const store = require('../store/index')
  // window.store = store

  export default {
    components: { PriceProtectAuthLoginRequest, PriceProtectJdLogin, JdItemList, GwdA, BjgBottomWindow },
    mixins: [ BottomWindowMixin ],
    data() {
      return {
        hide: G.site !== '360buy',
        isJdLogin: false,
        userAgreed: false,
        functionOpened: false,
        forceOpen: location.href.indexOf('forceOpen') > -1,
        settingOpen: false,
        hintShow: true,
        notifyCount: 0,
        recent: false,
      }
    },
    computed: mapState({
      userName: state => state.user.userName,
      user: state => state.user.userLogin,
      hasWx: state => state.user.userHasWx,
      enabled: state => state.user.priceProtectEnabled
    }),
    methods: {
      ppClick() {
        if (!(this.user && this.userAgreed && this.enabled && this.isJdLogin) && !this.recent) {
          window.open('https://pcsitepp-fm.jd.com/')
        }
        if (this.recent) {
          this.recent = false
        }
      },
      setEnable() {
        this.enable()
        this.userAgreed = true
        this.hintShow = false
      },
      async checkUserLogin() {
        await user.init()
        client.get('/getStorage', { key: 'enabled' }, data => {
          this.$store.commit('user/setState', {
            priceProtectEnabled: data
          })
          require('common/globalCondition').setMet('PriceProtectReady')
        })
        if (this.user) {
          this.checkUserAgreed()
        } else {
          client.get('/clearUserName')
        }
      },
      disable(e) {
        this.recent = true
        e.preventDefault()
        this.settingOpen = false
        cnzz.log('价格保护', '用户手动关闭')
        client.get('/setStorage', {enabled: false})
        this.$store.commit('user/setState', {
          priceProtectEnabled: false
        })
      },
      enable() {
        cnzz.log('价格保护', '用户手动开启')
        client.get('/setStorage', {enabled: true})
        this.$store.commit('user/setState', {
          priceProtectEnabled: true
        })
      },
      mouseOver() {
        this.forceOpen = false
        this.notifyCount = 0
        client.get('/clearNotifyCount')
      },
      checkUserAgreed() {
        client.get('/getStorage', { key: 'userAgreed' }).then(result => {
          this.userAgreed = result
        })
      },
      checkOpened() {
        client.get('/getStorage', { key: 'userOpened' }).then(result => {
          this.userOpened = result
        })
      },
      checkJdLogin() {
        client.get('/getLoginStatus', {}, (res) => {
          this.isJdLogin = res
          if ($('a.nickname').text() && !res) {
            this.isJdLogin = true
            client.get('/setLoginStatus', {
              loginStatus: true
            })
          }
        })
      },
      listenOpen() {
        document.body.addEventListener('bjgWindowOpen', () => {
          this.forceOpen = true
          this.$nextTick(() => {
            setTimeout(() => {
              this.$refs.jdItemList.syncNow()
            }, 500)
          })
        })
      }
    },
    mounted() {
      this.checkUserLogin()
      this.checkJdLogin()
      this.listenOpen()
      client.get('/getStorage', {key: 'hintShowed'}).then(res => {
        if (res) {
          this.hintShow = false
        } else {
          this.hintShow = true
          client.get('/setStorage', { hintShowed: true })
        }
      })
      client.get('/getNotifyCount', {}).then(res => {
        this.notifyCount = parseInt(res)
      })
      // this.$el.parentElement.addEventListener('DOMSubtreeModified', () => {
      //   if (window.innerWidth - this.$el.offsetLeft <= 564) {
      //     this.positionStyle = 'right: -1'
      //   }
      // })
      let k = setInterval(() => {
        this.checkJdLogin()
      }, 3000)
      setTimeout(() => {
        clearInterval(k)
      }, 9000)
    }
  }
</script>


