<template>
  <div class="bjg-qr-error">
    <img src="https://cdn.gwdang.com/images/extensions/warn@2x.png" alt="" >
    <span style="margin-top: 10px" class="grayText">当前网络异常<br>点此<span class="red" @click="click">刷新</span></span>
  </div>
</template>
<style scoped lang="less">
  .bjg-qr-error {
    width: 118px;
    height: 118px;
    background: white;
    display: flex;
    flex-direction: column;
    align-items: center;
    img {
      margin-top: 22px;
      width: 32px;
      height: 32px;
    }
    .grayText {
      color: #999999;
      display: inline-block;
      font-size: 20px;
      width: 125px;
      text-align: center;
      .red {
        color: #ff2d53;
        text-decoration: underline;
        cursor: pointer;
      }
      line-height: 32px;
      transform: scale(0.5);
      transform-origin: top center;
    }
  }
</style>
<script>
  export default {
    methods: {
      click() {
        this.$emit('refresh')
      }
    }
  }
</script>


