const request = require('common/request');
const md5 = require('js-md5');
const host = 'i.gwdang.com';
const userData = require('common/userData')
const communicate = require('common/communicate')

type Response = {
  code: number
}

const getUserToken = () => {
  let resolved = false
  return new Promise(resolve => {
    communicate.trigger({
      type: 'checkUserToken'
    })
    communicate.on(data => {
      if (typeof data === 'string') {
        data = JSON.parse(data)
      }
      if (data.type === 'checkUserToken') {
        resolved = true
        resolve(data.value)
      }
    })
  })
}

const signParams = params => {
  const query = Object.keys(params).sort((a, b) => {
    return a.localeCompare(b);
  }).map(x => x + (params[x])).join('');
  const first = md5(query) + params.ac
  let res = md5(first)
  return res;
};

const post = (url, params, data) => {
  if (!data.price) {
    data.price = '0'
  }
  params.platform = 'ext';
  params.t = parseInt((new Date()).getTime() / 1000)
  const toSign = {...params, ...data, ac: url.toLowerCase().replace('/', '').replace(/\//g, '.')}
  params.sign = signParams(toSign);
  const query = Object.keys(params).map(x => x + '=' + encodeURIComponent(params[x])).join('&');

  return request.post(`https://${host}${url}?${query}`, data, true, true)
};

function requestXHR(url, callback, referer) {
  var xmlhttp = new XMLHttpRequest();
  xmlhttp.addEventListener('load', function() {
    callback(xmlhttp.responseText)
  })
  xmlhttp.withCredentials = true
  xmlhttp.open("GET", url, true);
  // if (referer) {
  //     xmlhttp.setRequestHeader('x-referer', referer)
  // }
  xmlhttp.send();
};

const get = (url, params) => {
  params.platform = 'ext';
  if (!params.t) {
    params.t = parseInt((new Date()).getTime() / 1000)
  }
  // let cb = 'cb' + parseInt(Math.random() * 10000)
  // if (!G.allowBackgroundRequest) {
  //   params.callback = cb
  // }
  params.sign = signParams({
    ...params,
    ac: url.toLowerCase().replace('/', '').replace(/\//g, '.')
  });
  const query = Object.keys(params).map(x => x + '=' + encodeURIComponent(params[x])).join('&');
  if (G.allowBackgroundRequest && G.canUseLocalLoginCheck) {
    return request.rawGet(`https://${host}${url}?${query}`)
  } else {
    return new Promise(resolve => {
      let cancel = true
      requestXHR(`https://${host}${url}?${query}`, function(res) {
        cancel = false
        try {
          let r = JSON.parse(res)
          resolve(r)
        } catch (e) {
          resolve(res)
        }
      })
      setTimeout(() => {
        if (cancel) {
          resolve({ code: 0 })
        }
      }, 4000)
      // $.get(`https://${host}${url}?${query}`).then(res => {
      //   try {
      //     let r = JSON.parse(res)
      //     resolve(r)
      //   } catch (e) {
      //     resolve(res)
      //   }
      // })
      // $.ajax({
      //   url: `https://${host}${url}?${query}`,
      //   dataType: 'jsonp',
      //   jsonp: '',
      //   jsonpCallback: cb,
      //   success: function(data){
      //     resolve(data)
      //   }
      // });

    })
  }
};

const getQueryString = (url, params) => {
  params.platform = 'ext';
  params.t = parseInt((new Date()).getTime() / 1000)
  params.sign = signParams({
    ...params,
    ac: url.toLowerCase().replace('/', '').replace(/\//g, '.')
  });
  const query = Object.keys(params).map(x => x + '=' + encodeURIComponent(params[x])).join('&');
  return (`https://${host}${url}?${query}`)
};

let current = null;

let currentCollectId = null;

const getDetail = dp_id => {
  return new Promise((resolve, reject) => {
    if (!G.productChecked || !G.productChecked.collected) {
      resolve({})
      return
    }
    if (current) {
      resolve(current)
    } else {
      get('/UserCollection/Detail', {
        dp_id: dp_id
      }).then(res => {
        try {
          if (typeof res === 'string') {
            res = JSON.parse(res);
          }
          current = res;
          resolve(res)
        } catch (e) {
          resolve({})
        }
      })
    }
  })
};

module.exports = {
  reset() {
    current = null;
    currentCollectId = null;
  },
  /**
   * 登录
   * @param username
   * @param password
   * @param remember
   * @returns {*}
   */
  login(username, password, remember) {
    return post('/User/Login', {}, {
      account: username,
      passwd: password,
      remember_me: remember
    })
  },
  /**
   * 退出登录
   */
  logout() {
    return get('/User/Logout', {})
  },
  /**
   * 发送短信
   * @param {string} phone - 电话号码
   * @returns Promise
   */
  sendSms(phone) {
    return post('/UserHelper/SmsCode', {}, {
      phone: phone,
      tag: 'login'
    })
  },

  /**
   * 检查某个商品是否被收藏
   * @param dp_id
   * @returns {*}
   */
  async checked(dp_id: string) {
    if (G.canUseLocalLoginCheck) {
      let token = await getUserToken()
      if (!token) {
        return new Promise(resolve => resolve({
          code: 0
        }))
      }
    }
    return get('/UserCollection/Checked', {
      dp_id: dp_id
    })
  },

  /**
   * 收藏详情
   * @param dp_id
   */
  detail(dp_id: string) {
    return getDetail(dp_id)
  },

  /**
   * 获取收藏列表
   * @param tab
   * @param pg
   * @param ps
   * @returns {*}
   */
  getList(tab = 'default', pg: number,  ps: number = 30) {
    return get('/UserCollection/List', {ps: ps, tab: tab})
  },
  /**
   * 添加商品收藏
   * @param settingPrice
   * @param type
   * @returns {*}
   */
  async add(settingPrice, type, mode = 0, mPromo = 1, blackClass = 0) {
    if (current && current.data) {
      const payload = {
        collection_id: current.data.id,
        notifier_site: type,
        notifier_threshold: settingPrice,
      }
      if (G.showMPromo) {
        payload.notifier_mpromo = mPromo ? 1: 0
      }
      if (G._pp) {
        payload._pp = G._pp
      }
      return post('/UserCollection/Modify', {}, payload)
    }
    let price = G.dp.price;
    if (G.dp.storeInfo && G.dp.storeInfo.length) {
      if (G.dp.storeInfo[0].currency) {
        price = G.dp.oldPrice
      }
    }
    if (isNaN(parseFloat(price))) {
      price = 0
    }
    let oinfo = userData.get('other_info')
    if (!price) {
      if (oinfo && oinfo['code-server'] && oinfo['code-server']['price']) {
        price = oinfo['code-server']['price']
      }
    }
    if (!price) {
      price = await require('common/globalCondition').met('NowPrice')
    }
    if (!price) {
      price = 0
    }
    return new Promise(resolve => {
      const payload = {
        dp_id: G.dp.dpId,
        title: (G.dp.name ? G.dp.name: document.title).trim(),
        url: location.href,
        img: G.dp.img ? G.dp.img: '',
        price: price,
        promo_price: G.dp.promoPrice ? G.dp.promoPrice: 0,
        notifier_site: type,
        notifier_threshold: settingPrice,
        is_black_class: blackClass
      }
      if (G.showMPromo) {
        payload.notifier_mpromo = mPromo ? 1: 0
      }
      if (G._pp) {
        payload._pp = G._pp
      }
      post('/UserCollection/Add', {}, payload).then(res => {
        if (typeof res === 'string') {
          res = JSON.parse(res)
        }
        if (res.data) {
          current = res
        }
        resolve(res)
      })
    });
  },
  /**
   * 删除商品收藏
   * @returns {*}
   * @param collectionId
   */
  delete(collectionId = null) {
    let id = collectionId ? collectionId: (current && current.data ? current.data.id: '')
    if (current && current.data && id === current.data.id) {
      current = {}
    }
    return post('/UserCollection/Delete', {}, {
      collection_ids: id
    })
  },
  clearCurrent() {
    current = null
  },
  checkLoginStatus() {
    return post('/User/Detail', {}, {})
  },
  /**
   * 降价数量
   * @param time
   */
  checkFavor(time) {
    return get('/UserCollection/Tip', {
      t: time / 1000
    })
  },
  getQueryString,
  reportMonitorEvent(dpId, title, img, url, price, buy_cnt, create_time, days) {
    return post('/UserExtend/ReportMonitorEvent', {
      dp_id: dpId,
      title: title,
      img: img,
      url: url
    }, {
      price: price,
      buy_cnt: buy_cnt,
      create_time: create_time,
      days: days
    })
  }
};



