<template>
  <div style="font-family: 'microsoft yahei'" class="gwd-qrlink">
    <div style="clear: both"></div>
    <div class="gwd-row gwd-align" v-if="site === '360buy'" :class="'site-' + site">
      <div class="gwd-app-button gwd-row gwd-align" :class="mode" @mouseover="over">
        <img src="../assets/taoButton@2x.png" alt="" style="width: 17px; height: 17px" v-if="site !== '360buy'">
        <img src="../assets/jdButton@2x.png" alt="" style="width: 17px; height: 17px" v-if="site === '360buy'">
        <span :style="mode ? 'font-size: 18px;': ''">{{ transText('用') }}{{ transText(site === '360buy' ? '京东': '淘宝') }}APP{{ transText(mode && mode.includes('login') ? `扫码${actionText}`: '扫码') }}</span>
        <div class="gwd-app-qr-content gwd-column gwd-align" v-if="qr">
          <div class="gwd-qr-img" :style="`margin-top: 7px; margin-left: 7px; margin-right: 7px; height: ${mode ? 168 : 111.04}px; position: relative; ${mode ? 'width: 168px;': ''}`">
            <img src="../assets/taoQr@2x.png" alt="" class="gwd-qr-logo" v-if="!mode && site !== '360buy'">
            <img src="../assets/jdQr@2x.png" alt="" class="gwd-qr-logo" v-if="!mode && site === '360buy'">
            <img :src="qr" alt="" style="width: 100%">
          </div>
          <div class="gwd-row gwd-align gwd-qr-bottom-line" :style="mode ? 'margin-top: 8px;': ''">
            <span class="bold" :style="mode ? 'font-size: 32px;': ''">{{ transText(site === '360buy' ? '京东': '淘宝') }}APP</span>
            <span class="normal" :style="mode ? 'font-size: 30px': 'font-size: 22px'" v-if="mode">{{ mode ? '&nbsp;': '' }}{{ transText('扫码直接') }}{{ transText(actionText.replace('，无需验证', '')) }}</span>
            <span class="normal" v-if="!mode">{{ transText('扫码') }}{{ transText(site === '360buy' ? '查看商品': (hasBuyButton ? '查看优惠': '快捷购买')) }}</span>
          </div>
        </div>
      </div>
      <span class="gwd-qr-hint" v-if="!mode">{{ transText('在') }}{{ transText(site === '360buy' ? '京东APP': '手淘') }}{{ transText('内') }}{{ transText(site === '360buy' ? '浏览该商品': (hasBuyButton ? '查看优惠详情': '快捷购买')) }}</span>
    </div>
  </div>
</template>
<style>
#page #content #bd {
  z-index: 0!important;
}
</style>
<style scoped lang="less">
  .gwd-qr-bottom-line {
    span.bold {
      font-size: 22px;
      font-weight: bold;
      color: #EF6701;
    }
    span.normal {
      font-size: 16px;
      color: #070707;
    }
    transform: scale(0.5);
    transform-origin: top center;
    white-space: nowrap;
  }

  .gwd-qr-logo {
    position: absolute;
    left: 50%;
    top: 50%;
    width: 20px;
    height: 20px;
    margin-left: -10px;
    margin-top: -10px;
  }

  .gwd-app-button {
    width: 123px;
    height: 26px;
    background: #FFF3ED;
    border-radius: 2px;
    border: 1px solid #FF9851;
    line-height: 26px;
    text-align: center;
    font-size: 0;
    justify-content: center;
    position: relative;
    cursor: pointer;
    span {
      font-size: 12px;
      color: #ee6701;
      margin-left: 4px;
      white-space: nowrap;
    }
    .gwd-app-qr-content {
      position: absolute;
      width: 123px;
      height: 137px;
      background: #FFF3ED;
      border-radius: 0px 0px 2px 2px;
      border: 1px solid #FF9851;
      top: 24px;
      left: -1px;
      visibility: hidden;
      z-index: 999;
    }
  }

  .gwd-app-button:hover {
    .gwd-app-qr-content {
      visibility: visible;
    }
  }

  .gwd-app-button.gwd-mode-login {
    position: absolute;
    left: 50%;
    margin-left: -93px;
    bottom: 310px;
    background: none!important;
    border: none!important;
    width: 186px;
    .gwd-app-qr-content {
      width: 186px;
      height: 212px;
      background: none!important;
      border: none!important;
      top: 35px;
      visibility: visible;
      .gwd-qr-img {
        margin: 0;
        padding: 7px;
        border: 1px solid #d4d4d4;
      }
    }
  }

  .site-tmall {
    .gwd-qr-img {
      margin-bottom: 4px;
    }
    .gwd-app-button {
      margin-left: 40px;
    }
  }

  .site-taobao {
    .gwd-qr-img {
      margin-bottom: 4px;
    }
  }

  .site-360buy {
    margin-top: 15px;
    .gwd-qr-img {
      margin-bottom: 4px;
    }
    .gwd-app-button {
      background: #FFEDED;
      border: 1px solid #FF3220;
      span {
        color: #ff3220;
      }
      .gwd-app-qr-content {
        background: #FFEDED;
        border: 1px solid #FF3220;
        .gwd-qr-bottom-line {
          .bold {
            color: #ff3220;
          }
          .normal {
            color: #070707;
          }
        }
      }
    }
  }

  .gwd-qr-hint {
    font-size: 12px;
    color: #7d7e80;
    margin-left: 11px;
    font-family: 'microsoft yahei'
  }
</style>
<script>
  import QRCode from 'qrcode'
  import util from 'common/commonUtil'

  export default {
    //props: ['mode', 'dpId', 'tag'],
    props: {
      mode: {
        default: '',
        type: String
      },
      dpId: String,
      tag: Number,
      url: String
    },
    data() {
      return {
        site: this.mode ? '360buy': G.site,
        qr: '',
        loading: false,
        hasBuyButton: true
      }
    },
    mounted() {
      setTimeout(() => {
        if ($('#J_ButtonWaitWrap').length) {
          this.hasBuyButton = false
        }
      }, 500)
    },
    computed: {
      actionText() {
        if (this.dpId !== '1-3') {
          return `领${this.mode.includes('gift') ? '红包': '券'}${this.mode.includes('cfe') ? '，无需验证': ''}`
        }
        return '参加活动'
      }
    },
    methods: {
      transText(text) {
        const map = {
          '扫码联系客服' : '掃碼聯繫客服',
          '淘宝APP': '淘寶APP',
          '天猫APP': '天貓APP',
          '京东': '京東',
          '京东APP': '京東APP',
          '用': '用',
          '扫码': '掃碼',
          '联系客服': '聯繫客服',
          '在': '在',
          '内': '內',
          '浏览该商品': '瀏覽該商品',
          '查看商品': '查看商品',
        }
        if (G.lang === 'zh-tr' && map[text]) {
          return map[text]
        }
        return text
      },
      over() {
        if (!this.qr && !this.loading) {
          this.loading = true
          if (this.mode && this.mode.includes && this.mode.includes('cfe')) {
            let link1 = util.getParameterByName('returnurl')
            // let link2 = util.getParameterByName('returnurl', link1)
            // console.log(link2)
            QRCode.toDataURL(link1.replace('&isMainBack=1&loginback=1', ''), {}, (err, url) => {
              if (err) {
                //require('common/extConsole').error(err)
                return
              }
              this.qr = url
            })
            return
          }
          require('common/request').rawGet(
              G.u_server + `/helper/qrcode?union=${G.union}&event=appQrcode${
                (this.mode || this.tag) ? (this.mode.includes('gift')? '&rebate=1'
                  : `&tag=${this.tag ? this.tag: 1}`): ''}&dp_id=` + (this.dpId ? this.dpId: G.dp.dpId)
              + (this.dpId === '1-3' ? `&url=${encodeURIComponent(this.url)}`: '')
          ).then(res => {
            console.log(res)
            if (typeof res === 'string') {
              res = JSON.parse(res)
            }
            this.qr = res.data.qrImgStr
          })
        }
      }
    }
  }
</script>



