module.exports = {
  async init() {
    require('common/extConsole').log('ad init')
    const config = await require('common/globalCondition').met('GwdConfig')
    require('common/extConsole').log('ad config', config)
    if (config.newestBuild && G.from_device === 'chrome') {
      const newestBuild = new Date(config.newestBuild).getTime()
      const currentBuild = gwd_G.version
      if (newestBuild > currentBuild) {
        const ua = navigator.userAgent.toLowerCase()
        if (ua.includes('edg')) {
          return
        }

        const add = function() {
          if (document.getElementById('gwd-upgrade-link')) {
            return
          }
          let right = document.querySelectorAll('.gwd-topbar-right')[0]
          if (!right) {
            return
          }
          let a = document.createElement('A')
          a.id = 'gwd-upgrade-link'
          let img = document.createElement('IMG')
          img.src = 'https://cdn.gwdang.com/images/extensions/update@2x.png'
          img.style.height = '15px'
          img.style.verticalAlign = 'middle'
          a.target = '_blank'
          a.style.float = 'left'
          a.style.lineHeight = '36px'
          a.style.marginRight = '15px'
          a.appendChild(img)
          a.href = 'https://www.gwdang.com/v2/app/questions?page=chrome&fromUpgrade=1'
          if (navigator.userAgent.toLowerCase().indexOf('qqbrowser') > -1) {
            a.href = 'https://www.gwdang.com/v2/app/questions?page=qqbrowser&fromUpgrade=1'
          }
          if (navigator.userAgent.toLowerCase().indexOf('yabrowser') > -1) {
            a.href = 'https://www.gwdang.com/app/extension?page=question&guide=yandex'
          }
          // if (navigator.userAgent.toLowerCase.indexOf('opr') > -1) {
          //   a.href = 'https://www.gwdang.com/app/extension?page=question&guide=qq'
          // }
          right.prepend(a)
        }

        if (location.href.includes('.tmall.com') || location.href.includes('.taobao.com')) {
          setInterval(function() {
            if (!document.getElementById('gwd-upgrade-link')) {
              add()
            }
          }, 2000)
        } else {
          add()
        }
      }
    }
    if (G.from_device.includes('bijiago') && config.adsBijiago) {
      config.ads = config.adsBijiago
    }
    if (G.from_device.includes('biyibi') && config.adsBiyibi) {
      config.ads = config.adsBiyibi
    }
    if (config.ads) {
      config.ads.forEach(async item => {
        if (location.host.includes(item.site)) {
          if (item.startTime && (new Date(item.startTime) > new Date())) return
          if (item.endTime && (new Date(item.endTime) < new Date())) return
          await require('standard/module/util').waitForConditionFn(() => $(item.selector).length)
          const el = $(item.selector)
          switch (item.position) {
            case 'top':
              el.prepend(item.html)
              break
            case 'bottom':
              el.append(item.html)
              break
            case 'before':
              el.before(item.html)
              break
            case 'after':
              el.after(item.html)
              break
            default:
              el.append(item.html)
          }
        }
      })
    }
  }
}



