<template>
  <div class="bjgou-subsidy-bar-bottom " :title="transText('点击领取')" @mouseover="over" @click="click" style="cursor: pointer">
    <span class="coupon-marleft"></span>
    <a id="top_coupon_btn">
    <span class="top-coupon-tle">{{ transText('当前商品领红包立减') }}</span>
    <span class="price-num" style="margin-left: 17px"><span class="price-sm">¥</span><span>{{value}}</span></span>
    <em class="link_hand"></em>

      <div class="qrcode" v-if="qr">
        <img :src="qrcode" alt="" style="margin-top: 7px; width: 120px; height: 120px;">
        <QrError @refresh="over" v-if="error"/>
        <div style="margin-top: 4px; text-align: center">
          <span style="font-weight: bold; color: #ff6132; font-size: 14px;">{{ transText('微信扫码') }}</span>
          <span style="margin-left: 4px; color: #333333; font-size: 12px;">{{ transText(site === '360buy' ? '领优惠券': '领礼金') }}</span>
        </div>
      </div>
    </a>
  </div>
</template>
<style scoped>
#top_coupon_btn {
  background: url(https://cdn.gwdang.com/images/extensions/bijiago/bottomCoupon@2x.png) 0 0 no-repeat;
  display: inline-flex;
  height: 28px;
  width: 161px;
  white-space: nowrap;
  position: relative;
  z-index: 999999999999;
  padding: 0 !important;
  margin: 3px 40px 4px 0!important;
  border: none !important;
  background-size: cover;
  align-items: center;
  text-decoration: none!important;
}

.coupon_detail {
  position: absolute;
  right: 1px;
  height: 156px;
  width: 146px;
  z-index: 99999999999;
  background: #FFF6F4;
  border: 1px solid #FF6132;
  display: none;
}

#bjgext_mainbar .coupon_detail {
  top: initial!important;
}

#top_coupon_btn:hover .coupon_detail {
  display: block;
}

.coupon_detail img {
  width: 118px;
  height: 118px;
  float: left;
  margin-left: 14px;
  margin-top: 8px;
}

.coupon_detail span {
  font-size: 14px;
  color: #FF4335 !important;
  letter-spacing: 0.22px;
  font-weight: bold;
  float: left;
  height: 14px;
  line-height: 14px;
  width: 100%;
  margin-top: 6px;
  text-align: center;
}

.coupon-marleft {
  height: 100%;
  width: 10px;
  float: left !important;
  border-left: 1px solid #edf1f2;
}

.link_hand {
  display: inline-block;
  height: 30px;
  width: 38px;
  position: absolute;
  right: -38px;
  top: -2px;
  background: url(https://cdn.gwdang.com/images/extensions/newbar/hand.gif) 0px 0px no-repeat;
}

#top_coupon_btn * {
  color: #fff;
  /*float: left;*/
  font-family: "microsoft yahei";
}

#top_coupon_btn .top-coupon-tle {
  height: 16px;
  text-align: center;
  line-height: 16px;
  margin-left: 2px;
  font-size: 12px !important;
  font-weight: normal !important;
}

#top_coupon_btn .price-num {
  font-size: 14px;
  color: #FFFFFF;
  font-weight: bold;
  width: 46px;
  height: 22px;
  text-align: center;
  margin-left: 3px;
  line-height: 22px !important;
  padding: 0px !important;
  vertical-align: middle;
}

#top_coupon_btn .price-num span {
  display: inline;
}

#top_coupon_btn .price-sm {
  font-size: 12px;
  transform: scale(0.8333);
  transform-origin: bottom right;
}
</style>
<style scoped lang="less">
  .bjgou-subsidy-bar-bottom {
    .qrcode {
      display: none;
      position: absolute;
      bottom: 45px;
      right: 5px;
      width: 148px;
      height: 156px;
      background: #FFF6F4;
      border: 1px solid #FF6132;
      z-index: 9;
    }
  }

  .bjgou-subsidy-bar-bottom:hover .qrcode {
    display: flex;
    flex-direction: column;
    align-items: center;
  }
</style>
<script>
  const getQRCode = require('common/coupon/getQRCode')
  const cnzz = require('common/cnzz')

  import QrError from './QrError.vue'

  export default {
    name: "SubsidyBottom",
    props: ['value', 'url', 'qr'],
    components: { QrError },
    data() {
      return {
        qrcode: '',
        error: false
      }
    },
    methods: {
      transText(text) {
        const map = {
          '点击领取': '點擊領取',
          '店铺红包': '店鋪紅包',
          '立即领取': '立即領取',
          '微信扫码': '微信掃碼',
          '领优惠券': '領優惠券',
          '领礼金': '領禮金',
          '当前商品领红包立减': '當前商品領紅包立減',
        }
        if (G.lang === 'zh-tr') {
          return map[text]
        }
        return text
      },
      click() {
        if (!this.qr) window.open(this.url)
      },
      over() {
        if (!this.qr) return
        if (this.qrcode) return
        getQRCode({
          id: G.dp.dpId,
          pid: 'bjgou-mini',
          amount: this.value,
          title: '',
          _type: 'rebate'
        }, '', res => {
          cnzz.log((G.site === '360buy' ? 'jd': 'taobao') + 'GiftMoney:hover')
          if (res[0].etag) {
            this.error = true
            return
          } else {
            this.error = false
          }
          this.qrcode = res[0].imgSrc
        })
      }
    }
  }
</script>



