const cnzz = require('common/cnzz')
const QRCode = require('qrcode')

/**获取二维码
 *
 * @param obj
 * @param url
 * @param callback
 * @param useOriTitle 使用原始标题
 * @param noReplace 直接生成二维码，不请求接口
 */
module.exports = async (obj, url, callback, useOriTitle = false, noReplace = false) => {

    obj.couponUrl = url;
    if (obj.title.length === 0 && !useOriTitle) {
        obj.title = 'x'
    }
    let id = obj.id
    obj = JSON.stringify(obj)
    // let xml = new XMLHttpRequest()
    // xml.open('POST', `${G.server}/extension/CouponQrCode?w=150`)
    // xml.addEventListener('load', function() {
    //     try {
    //         let data = JSON.parse(xml.response);
    //         callback(data)
    //     } catch (e) {}
    // })
    // xml.send(obj);
    if (noReplace) {
        QRCode.toDataURL(url, { errorCorrectionLevel: 'L' }, function(err, url) {
            if (err) {
                //require('common/extConsole').error(err)
                return
            }
            callback([{
                imgSrc: url
            }])
        });
        return ;
    }
    if (G.ss_name === 'priceDog' && G.aliSite) {
        require('common/request').get(`${G.u_server}/helper/qrcode?event=appQrcode&dp_id=${id}&union=${G.union}`).then(res => {
            if (res.code === 1 && res.data && res.data.qrImgStr) {
                callback([{
                    imgSrc:res.data.qrImgStr
                }])
            } else {
                callback([{ etag: 0 }])
            }
        })
        return
    }
    require('common/request').post(
      `${G.server}/extension/CouponQrCode?union=${G.union}&w=150&from_device=${G.from_device}&rand=${parseInt(Math.random() * 1000)}`, obj, false, false).then( function(data) {
        try {
            data = JSON.parse(data);
            callback(data)
        } catch (e) {
            callback(data)
            //require('common/extConsole').error(e)
        }
    })
    cnzz.log("实时抓取发送请求");
}


