module.exports = (time, type) => {
  // 1: xxxx-xx-xx 2.xx-xx 3.xx.xx 4. xxxx.xx.xx
  let dateObj = new Date(time);
  let y = dateObj.getFullYear();
  let m = dateObj.getMonth() + 1;
  let d = dateObj.getDate();
  let h = dateObj.getHours();
  let mi = dateObj.getMinutes();
  let ss = dateObj.getSeconds();

  if (m < 10)
    m = '0' + m;
  if (d < 10)
    d = '0' + d;
  if (ss < 10)
    ss = '0' + ss
  if (mi < 10)
    mi = '0' + mi
  if (h < 10)
    h = '0' + h
  let str = ``;
  switch (type) {
    case "1":
      str = `${y}-${m}-${d}`
      break;
    case "2":
      str = `${m}-${d}`
      break;
    case "3":
      str = `${m}.${d}`;
      break;
    case "4":
      str = `${y}.${m}.${d}`;
      break;
    case "5":
      str = `${y}/${m}/${d}`;
      break;
    case "6":
      str = `${y}/${m}/${d}/${h}:${mi}:${ss}`;
      break;
    case "7":
      str = `${y}-${m}-${d} ${h}:${mi}:${ss}`;
      break;
    default:
      str = `(${y}.${m}.${d})`;
  }
  return str;
}

const offset = 0 * 3600000

module.exports.isSameDay = (a, b) => {
  let aTime = (new Date(a + offset))
  let bTime = (new Date(b + offset))
  return aTime.toLocaleDateString() === bTime.toLocaleDateString()
}

module.exports.localeDateString = x => {
  return (new Date(x + offset)).toLocaleDateString()
}



