import Vuex from 'vuex'
import userData from "common/userData";
import log from "../../common/log";
import cnzz from "../../common/cnzz";
import request from "../../common/request";

const userCenter = require('common/models/usercenter')
const extConsole = require('common/extConsole')

let inited = false
let instanceId = null, store = null

const getStore = () => {
  require('common/extConsole').log('getStore with instanceId', instanceId, 'G.instanceId', G.instanceId, 'G', G)
  if (G.instanceId !== instanceId) {
    instanceId = G.instanceId
    store = makeStore()
    window.gwdStore = store
    return store
  } else {
    window.gwdStore = store
    return store
  }
}

module.exports.getStore = getStore

const makeStore = () => new Vuex.Store({
  modules: {
    user: {
      namespaced: true,
      state: {
        login: false,
        wxQr: '',
      },
      mutations: {
        setLogin(state, login = true) {
          state.login = login
        },
        setWxQr(state, qr) {
          state.wxQr = qr
        }
      }
    },
    priceRemind: {
      namespaced: true,
      state: {
        instanceId: G.instanceId,
        mode: 0,
        notifySite: 0, // 0 全网商家 1 当前商家
        notifierMPromo: 1, // 多件推送 0 不开启 1 开启
        allPrice: 0,
        currentPrice: 0,
        hovered: false,
        collected: false,
        settedNotifySite: null,
        nowPrice: 0,
        showMPromo: false
      },
      mutations: {
        setState(state, payload) {
          Object.keys(payload).forEach(key => {
            state[key] = payload[key]
          })
        },
        updateRemindSettings(state, payload) {
          // if (G.productChecked && G.productChecked.collected) {
          //   debugger
          // }
          Object.keys(payload).forEach(key => {
            state[key] = payload[key]
          })
        }
      },
      actions: {
        async cancel(ctx) {
          return userCenter.delete().then(res => {
            ctx.commit('updateRemindSettings', {
              collected: false,
              settedNotifySite: null
            })
            return new Promise(resolve => resolve())
          })
        },
        async reset(ctx) {

        },
        async init(ctx) {
          // if (inited) {
          //   return
          // }
          inited = true
          if (G.userLogin) {
            ctx.commit('user/setLogin', true, { root: true })
          }
          if (G.userLogin && G.productChecked && G.productChecked.collected) {
            ctx.commit('setState', {
              collected: true
            })
          }

          await require('common/globalCondition').met('dp_query_set')
          let dp_query = userData.get('dp_query')
          let currentPrice = await require('common/globalCondition').met('NowPrice')
          // let single = await Promise.race([
          //   require('common/globalCondition').met('SinglePrice'),
          //   require('common/commonUtil').sleep(1000)
          // ])
          // if (single) {
          //   currentPrice = single
          // }
          if (G.aliSite && G.dp.price)
            currentPrice = G.dp.price;
          let allPrice = parseFloat(dp_query.b2c.min_price) || currentPrice;
          if (!allPrice || isNaN(allPrice)) allPrice = currentPrice
          currentPrice = parseFloat(currentPrice.toString().replace(',', ''))
          allPrice = parseFloat(allPrice.toString().replace(',', ''))
          if (dp_query.b2c.product && dp_query.b2c.product.length !== 0) {
            log('allsite-lowpri-show');
            cnzz.log('allsite-lowpri-show')
          }
          if (!(G.productChecked && G.productChecked.collected)) {
            ctx.commit('updateRemindSettings', {
              allPrice: allPrice,
              currentPrice: currentPrice,
              notifySite: 1,
              nowPrice: currentPrice
            })
            require('common/globalCondition').met('SinglePrice').then((single) => {          
              ctx.commit('updateRemindSettings', {
                currentPrice: single
              })
            })
          }
          require('common/globalCondition').setMet('PriceRemindSetted')
        },
        async hover(ctx) {
          if (!ctx.state.hovered) {
            if (G.userLogin) {
              let url = `https://www.gwdang.com/collect/get_qrcode/`
              if (G.qrApi && G.qrApi !== 'default') {
                url = G.qrApi
              }
              request.rawGet(url, true).then((data) => {
                ctx.commit('user/setWxQr', data.img_url, { root: true })
              })
              let cat_id = G.dp.cat_id
              if (cat_id && cat_id.includes('-')) {
                let cats = cat_id.split('-')
                if (cats.length > 3) {
                  cats.pop()
                }
                cat_id = cats.join(',')
              }
              request.get(`${G.server}/extension/ProductFilter?scene=collection&dp_ids=${G.dp.dpId}&one=1&cid=${cat_id}`).then(r => {
                if (r.data && !r.data.is_black_class) {
                  G.showMPromo = true
                  ctx.commit('setState', {
                    showMPromo: true
                  })
                }
              })
            }
            if (G.userLogin && ctx.state.collected) {
              await require('common/globalCondition').met('GwdDpIdGot')
              userCenter.detail(G.dp.dpId).then(r => {
                extConsole.log('detail', r)
                let payload = {
                  mode: r.data.notifier.mode,
                  notifySite: r.data.notifier.site,
                  settedNotifySite: r.data.notifier.site,
                  notifierMPromo: r.data.notifier.mpromo,
                }
                if (payload.notifySite === 1) {
                  payload.currentPrice = r.data.notifier.threshold
                } else {
                  payload.allPrice = r.data.notifier.threshold
                }
                // payload.currentPrice = r.data.notifier.threshold
                ctx.commit('updateRemindSettings', payload)
              })
            }
            ctx.commit('setState', {
              hovered: true
            })
          }
        },
        async submit(ctx, payload) {
          return userCenter
            .add(payload.price, payload.notifySite, payload.mode, payload.notifyMPromo, ctx.state.showMPromo ? 0 : 1)
            .then(r => {
              if (r.error_code && r.error_code === 1000) {
                ctx.commit('user/setLogin', false, { root: true })
              }
              if (r.code === 100 || r.code <= 0) {
                return new Promise(((resolve, reject) => {
                  reject(r.msg)
                }))
              }
              if (r.code === 1) {
                let mode = payload.mode
                let site = payload.notifySite
                if (r.data) {
                  mode = r.data.notifier.mode
                  site = r.data.notifier.site
                }
                let payloadRes = {
                  mode: mode,
                  notifySite: site,
                  settedNotifySite: site,
                  collected: true,
                  notifierMPromo: payload.notifyMPromo ? 1 : 0,
                }
                if (r.data) {
                  if (payloadRes.notifySite === 1) {
                    payloadRes.currentPrice = r.data.notifier.threshold
                  } else {
                    payloadRes.allPrice = r.data.notifier.threshold
                  }
                } else {
                  if (payloadRes.notifySite === 1) {
                    payloadRes.currentPrice = payload.price
                  } else {
                    payloadRes.allPrice = payload.price
                  }
                }
                ctx.commit('updateRemindSettings', payloadRes)
                return new Promise(resolve => {
                  resolve('提交成功')
                })
              }
            })
        }
      }
    },
    priceTrend: {
      namespaced: true,
      state: {
        money: '',
        priceRange: '',
        nowPrice: ''
      },
      mutations: {
        setState(state, payload) {
          Object.keys(payload).forEach(key => {
            state[key] = payload[key]
          })
        },
      }
    }
  }
})



