function addScheme(url) {
  if (url.indexOf('http') === 0) {
    return url
  }
  return 'https:' + url
}

const client = require('common/background/bgClient')

const getOrders = (config) => {
  let arrs = $('.co-th').toArray()
  console.log(arrs)
  let related = arrs.map(x => {
    const d = x.id.split('_')
    let errText = $(x).find('.show-detail').text().trim().split('申请价保失败，')
    if (errText.length > 1) {
      errText = errText[1].replace('查看详细规则', '')
    } else {
      errText = ''
    }
    if (errText.indexOf('此商品未发生降价') > -1) {
      errText = ''
    }
    if (x.innerText.indexOf('商品为赠品') > -1) {
      errText = '商品为赠品，不支持价保'
    }
    const skuId = $(x).attr('skuid')
    let product = {
      title: $(x).find('.p-name a').text().trim(),
      url: addScheme(`https://item.jd.com/${skuId}.html`),
      img: addScheme($(x).find('img').attr('src')),
      price: parseFloat($(x).find('.price').text().replace('￥', '').replace(/,/g, '').trim())*100,
      buy_cnt: parseInt($(x).find('.count').text().replace('x', '').trim()),
      dp_id: d[2] + '-3',
      order: d[1],
      inTime: x.innerText.indexOf('已超过价保周期') === -1 && errText.length === 0,
      errorText: errText
    }
    if (product.inTime && config.autoClick) {
      window.skuApply(product.order, d[2], 1, 'Others')
    }
    //product.price = product.price / product.buy_cnt
    product.total_price = product.price * product.buy_cnt
    return product
  })
  const getTime = orderId => {
    let t = $('.tr-th').toArray().filter(x => x.innerText.indexOf(orderId) > -1)
    return $(t[0]).find('.time').text()
  }
  return require('standard/module/util').arrayUnique(related.map(x => x.order)).map(x => {
    let data = related.filter(y => y.order === x)
    return {
      orderNo: x,
      ctime: getTime(x),
      related: data,
      total_price: data.map(x => x.price * x.buy_cnt).reduce((a, b) => a + b),
      pay_price: data.map(x => x.total_price).reduce((a, b) => a + b),
    }
  })
}

function sleep(time) {
  return new Promise(resolve => {
    setTimeout(() => resolve(), time)
  })
}

module.exports = {
  async init() {
    let config = await require('common/request').requestXHR('https://cdn.bijiago.com/js/configs/priceProtect-bijiago.json', false)
    let payload = []
    let done = false
    let page = 1
    do {
      let orders = getOrders(config)
      if (orders.length === 0) break
      console.log('第' + page + '页', orders)
      orders.forEach(item => {
        if (Date.now() - (new Date(item.ctime)).getTime() > 30 * 24 * 3600000) {
          done = true
          item.related.forEach(x => x.inTime = false)
        }
      })
      payload = payload.concat(orders)
      page++
      window.mescroll.optUp.callback({num: page, size: 10, time: null}) // 价保页面用这个翻页
      await sleep(400)
    } while (!done)
    console.log(payload)
    client.get('/setDpItemList', {
      items: payload
    })
    payload = payload.filter(x => x.related[0].inTime)
    payload = require('common/models/base64').bytesToBase64(require('common/models/gzip').gZip(payload))
    console.log(payload)
    //let allowPriceProtect = await require('bjgou/modules/util.js').getStorage('allowPriceProtect')
    if (config.sync) {
      require('bjgou/modules/user').sendCartLog(payload).then(res => console.log(res))
    }
    client.get('/setLoginStatus', {
      loginStatus: true
    }, () => {})
  }
}



