const addEvent = () => {
  var time1
  $('.bjgext-item-dp').on('mouseenter', function() {
    clearTimeout(time1);
    $('.bjgext-product-detail').hide();
    var dom = $(this);
    var detail = dom.find('.bjgext-product-detail');
    if (detail.length > 0) {
      detail.show();
    } else {
      let id = dom.attr('data-id');
      if (id) {
        renderDetail(dom, id);
      }
    }
  })
  $('.bjgext-item-dp').on('mouseleave', function() {
    let that = this;
    time1 = setTimeout(() => {
      $(that).find('.bjgext-product-detail').hide();
    }, 100);
  })
}

