const globalCondition = require('common/globalCondition')

module.exports.init = async () => {
  require('common/extConsole').warn('reload begin')
  if (!$('#bjgext_mainbar').length && location.hostname !== 's.taobao.com') {
    require('common/extConsole').warn('reload interrupted because no bar detected')
    return
  }
  require('common/priceParsers').clear()
  globalCondition.clearAll()
  G.productChecked = null
  G.showMinibar = false
  G.showMainbar = false
  G.instanceId = null
  window.bjgActivity = false
  window.bjgTrendInit = false
  $('.is_tm_site').remove()
  $('#cptklbox').remove()
  $('#tttgbgbs').remove()
  require('./util').clearRun()
  $('#bjgext_mainbar').remove()
  $('.pricedog-tax-bar').remove()
  $('.pricedog-bar').remove()
  $('#biggraph_bijiago').remove()
  $('#biggraph_biyibi').remove()
  $('#bjgext_mb_bg').remove()

  G.instanceId = parseInt(Math.random() * 10000)
  require('common/extConsole').log('set instance id', G.instanceId)
  $('html').attr('data-bjg-id', G.instanceId)

  require('common/forbidCity').common((data) => {
    if (data && data.result instanceof Array) {
      G.set_force = false;
      G.forbidCoupon = true;
    } else if (data && data.result) {
      let result = data.result.address;
      if (result.indexOf('北京') > -1 || result.indexOf('上海') > -1 || result.indexOf('广州') > -1 || result.indexOf('深圳') > -1 || result.indexOf('杭州') > -1) {
        G.set_force = false;
        G.forbidAd = true;
      } else if (result.indexOf('南京') > -1) {
        G.set_force = false;
      }
      if (result.indexOf('北京') > -1 || result.indexOf('上海') > -1) {
        G.forbidTkl = true;
      }
      if (result.indexOf('北京') > -1 || result.indexOf('杭州') > -1) {
        G.forbidCoupon = true;
        G.forbidApp = true;
      }
    }

    require('common/parseprice').getRate(() => {
      require("bjgou/modules/main").init();
    })
  })
}



