// 会员券

import MemberCouponTop from 'common/components/MemberCouponTop.vue'
import MemberCouponMini from 'common/components/MemberCouponMini.vue'
import MemberCouponMiniBjg from 'bjgou/components/MemberCouponMiniBjg'
import MemberCouponBottomBjg from 'bjgou/components/MemberCouponBottomBjg'

const getMemberCoupon = async (shopId, userId) => {
  return await require('common/request').rawGet(`https://alisitecdn.m.taobao.com/minidata/shop/index/downgrade.htm?pathInfo=shop/index2&userId=${userId}&shopId=${shopId}`);
}

const render = () => {
  require('common/globalCondition').setMet('couponLink', {
    content: '发现店铺优惠券，速领',
    url: `https://tb.gwdang.com/extension/qrpage?dp_id=${G.dp.dpId}&tag=2`
  })

  const divTop = document.createElement('div');
  $('.gwd-topbar-left').append(divTop);
  new Vue({
    el: divTop,
    render: h => h(MemberCouponTop, {
      props: {
        tag: 2
      }
    })
  })

  // const divBottom = document.createElement('div');
  // $('#gwd_minibar').after(divBottom);
  new Vue({
    el: '#gwd-coupon-placeholder',
    render: h => h(MemberCouponMini, {
      props: {
        tag: 2
      }
    })
  })
}

const renderBjg = () => {
  new Vue({
    el: '#bjg-coupon-placeholder',
    render: h => h(MemberCouponMiniBjg, {
      props: {
        tag: 8
      }
    })
  })

  let el = document.createElement('DIV')
  $('.bjg-coupon-space').after(el)
  new Vue({
    el: el,
    render: h => h(MemberCouponBottomBjg, {
      props: {
        tag: 8
      }
    })
  })
}

module.exports = {
  init() {
    return new Promise(((resolve, reject) => {
      if (!G.aliSite) {
        resolve(false)
      }
      const metaStr = $('meta[name="microscope-data"]').attr('content')
      if (!metaStr) {
        resolve(false)
        return
      }
      const parsedMetaStr = metaStr.split(';').map(item => {
        const arr = item.split('=')
        return {
          key: arr[0],
          value: arr[1]
        }
      })
      const meta = {}
      parsedMetaStr.forEach(item => {
        meta[item.key.trim()] = item.value
      })

      getMemberCoupon(meta.shopId, meta.userid).then(res => {
        if (JSON.stringify(res).indexOf('market.m.taobao.com/app/cem-fe/benefit-exchange/benefit-exchange/index.html') > -1) {
          require('common/cnzz').logOnce('淘宝会员券:展示')
          if (G.from_device === 'bijiago' || G.from_device === 'biyibi') {
            renderBjg()
          } else {
            render()
          }
          resolve(true)
        } else {
          resolve(false)
        }
      })
    }))
  }
}



