const loadingList = []

module.exports.get = (tag, dpId) => {
  return new Promise(((resolve, reject) => {
    if (loadingList.indexOf(`${tag}-${dpId}`) > -1) {
      return
    }
    loadingList.push(`${tag}-${dpId}`)
    const union = G.union ? G.union: gwd_G.union
    const u =  (G && G.u_server ? G.u_server: 'https://u.gwdang.com')
    require('common/request').rawGet(u + `/helper/qrcode?union=${union}&event=appQrcode${tag ? `&tag=${tag}`: ''}&dp_id=` + (dpId ? dpId: G.dp.dpId)).then(res => {
      loadingList.splice(loadingList.indexOf(`${tag}-${dpId}`), 1)
      if (typeof res === 'string') {
        res = JSON.parse(res)
      }
      resolve(res.data.qrImgStr)
    }).catch(err => {
      loadingList.splice(loadingList.indexOf(`${tag}-${dpId}`), 1)
      reject(err)
    })
  }))
}



