const communicate = require('common/communicate')
var globalData, callbacks

const getBasicInfo = () => {
  var product = G.dp;
  let itemID = product.itemId,
    cid = product.cat_id,
    userid = G.guid || product.userid || createUserId(),
    title = encodeURIComponent(product.name),
    price = product.price,
    url = product.url,
    pic = encodeURIComponent(product.pic),
    website = product.website;
  if (!website) return;
  let str = `itemId=${itemID}&title=${title}&cid=${cid}&price=${price}&url=${encodeURIComponent(url)}&pic=${pic}&website=${website}&userId=${userid},`
  return str;
}

const createUserId = () => {
  var str = '0122';
  var randomstr = '0123456789abcdefghijklmn';
  for (var i = 0; i < 28; i++) {
    str += randomstr[parseInt(Math.random() * 28)];
  }
  return str;

}
module.exports.init = (callback) => {
  if (globalData) {
    callback(globalData)
  } else if (globalData === 0) {
    callback(null)
  } else {
    callbacks = callback;
  }

}

module.exports.ready = (done) => {
  let info = getBasicInfo()
  if (!info) return;
  let url =  "http://kksofts.com/api/recomm";
  communicate.on(data => {
    try {
      if (data.type == 'taotaosou') {
        globalData = JSON.parse(data.value)
        if (callbacks)
          callbacks(globalData)
        done(globalData)
      }
    } catch (e) {
      globalData = 0;
    }
  })
  communicate.trigger({
    type: 'taotaosou',
    info: getBasicInfo(),
    url: url 
  })
}


