const renderMini = (dom) => {
  $('body').addClass('ht_site');
  let host = location.host;
  let html = require('art-template-loader!../views/miniBarHt.html')
  let t = template.compile(html)({})
  switch (sitePattern[host]['position']) {
    case 'before':
      $(dom).before(t);
      break;
    case 'after':
      $(dom).after(t);
      break;
  }
  addCommonEvent()

  const store = require('standard/store/index').getStore()
  new Vue({
    el: '#gwd_mini_remind .minibar-btn-box',
    store,
    render: h => h(MiniBarCollectionButton)
  })
}

function baidufanyi(t, callback) {
  /*百度翻译接口*/
  var url = location.protocol + `//browser.${G.extName}.com/extension?ac=fanyi&string=` + t;
  request.get(url).done(function(data) {
    if (data.trans_result && !data.error_code) {
      var trans = [];
      for (var i = 0; i < data.trans_result.length; i++) {
        trans.push(data.trans_result[i].dst);
      }
      callback(trans);
    } else {
      callback([t])
    }
  })
}

function requestFanyi(t, callback) {
  /*请求翻译接口*/
  baidufanyi(t, callback)
  log('request:haitao:fanyi')
  cnzz.log('请求划词翻译')
}

function insertFanyi(data) {
  /*插入翻译内容*/
  data = data.join('');
  $('.ht_fanyi').remove();
  var html = '<div class="ht_fanyi" style="top:{{hty}};left:{{htx}}"><span id="ht_top"></span>{{data}}</div>';
  var t = template.compile(html)({
    data: data,
    'htx': calPosition() + 'px',
    'hty': htY + 'px'
  })
  $('body').append(t);
  addFanyiEvent()
}

function calPosition() {
  /*计算插入位置*/
  var pos = 0;
  if (htX > mouseDownX)
    pos = htX - (htX - mouseDownX) / 2 - 65;
  else
    pos = htX + (mouseDownX - htX) / 2 - 65;
  return pos;
}

function editTxt(t) {
  requestFanyi(t, insertFanyi);
}

function addFanyiEvent() {
  $('.ht_fanyi').siblings().on('click', function() {
    $('.ht_fanyi').remove()
  })
}

function getSelect() {
  $('body').on('mousedown', function(e) {
    clearTimeout(timer2)
    mouseDownX = e.pageX;
  })
  $('body').on('mouseup', function(e) {
    timer2 = setTimeout(function() {
      var txt = '';
      htX = e.pageX;
      htY = e.pageY + 20;
      if (window.getSelection) {
        txt = window.getSelection().toString();
      } else if (document.selection) {
        txt = document.selection.createRange().text;
      }
      if (txt == '')
        return;
      else
        editTxt(txt);
    }, 100)
  })
}

function isZiying() {
  if (HOST == 'www.6pm.com')
    return 'ziying';
  if ($('#merchant-info').length > 0) {
    if (HOST == 'www.amazon.com') {
      if ($('#merchant-info').text().indexOf('sold by Amazon') > -1)
        return 'ziying'
      else
        return 'sanfang'
    }
    if (HOST == 'www.amazon.co.jp') {
      if ($('#merchant-info').text().indexOf('jp が販売') > -1)
        return 'ziying'
      else
        return 'sanfang'
    }
    if (HOST == 'www.amazon.de') {
      if ($('#merchant-info').text().indexOf('Verkauf und Versand durch Amazon') > -1)
        return 'ziying'
      else if ($('#merchant-info').text().indexOf('Dispatched from and sold by Amazon') > -1)
        return 'ziying'
      else
        return 'sanfang'
    }

  } else
    return 'sanfang';
}

