<template>
  <div class="bjgou-subsidy-bar bjgou-component" @mouseover="over" @click="click" :title="transText('点击领取')">
    <span class="bjg-coupon-white" style="font-family: Arial; font-size: 14px; font-weight: bold; margin-left: 95px; margin-top: 10px">¥</span>
    <span class="bjg-coupon-white" style="font-size: 30px; font-weight: bold;">{{value}}</span>
    <span class="bjg-coupon-white" style="font-size: 18px; font-weight: bold; margin-left: 6px; margin-top: 6px;">{{ transText('店铺红包') }}</span>
    <div style="flex: 1"></div>
    <span class="bjg-coupon-white" style="font-size: 18px; font-weight: bold; margin-right: 22px">{{ transText(site === '360buy' ? '点击领取': '立即领取') }}</span>

      <div class="qrcode" v-if="qr">
        <img :src="qrcode" alt="" style="margin-top: 7px; width: 120px; height: 120px;">
        <QrError @refresh="over" v-if="error"/>
        <div style="margin-top: 4px; text-align: center">
          <span style="font-weight: bold; color: #ff6132; font-size: 14px;">{{ transText('微信扫码') }}</span>
          <span style="margin-left: 4px; color: #333333; font-size: 12px;">{{ transText(site === '360buy' ? '领优惠券': '领礼金') }}</span>
        </div>
      </div>
  </div>
</template>
<style scoped lang="less">
  .bjg-coupon-white {
    color: #ffffff;
  }

  .bjgou-subsidy-bar {
    cursor: pointer;
    margin-top: 5px;
    width: 442px;
    height: 67px;
    position: relative;
    display: inline-flex;
    align-items: center;
    background: url(https://cdn.bijiago.com/images/extensions/bijiago/bigCoupon@2x.png);
    box-sizing: border-box!important;
    background-size: contain;
    .qrcode {
      display: none;
      position: absolute;
      top: 70px;
      right: -15px;
      width: 148px;
      height: 156px;
      background: #FFF6F4;
      border: 1px solid #FF6132;
      z-index: 9;
    }
    .bjg-bold {
      font-size: 13px;
      font-weight: bold;
      color: #ff2d53;
    }
    .bjg-take {
      min-width: 87px;
      height: 22px;
      border-radius: 11px;
      border: 1px solid #FF2D53;
      position: relative;
      display: flex;
      cursor: pointer;
      span {
        font-size: 12px;
        text-align: center;
        line-height: 22px;
      }
      .taker {
        color: white;
        width: 36px;
        height: 24px;
        line-height: 24px;
        background: linear-gradient(90deg, #FF3A62 0%, #FF665B 100%);
        border-radius: 11px;
        display: inline-block;
      }
    }
  }

  .bjgou-subsidy-bar:hover {
    text-decoration: none;
  }

  .bjgou-subsidy-bar:hover .qrcode {
    display: flex;
    flex-direction: column;
    align-items: center;
  }
</style>
<script>
  const getQRCode = require('common/coupon/getQRCode')
  const cnzz = require('common/cnzz')

  import QrError from './QrError.vue'

  export default {
    name: "Subsidy",
    props: ['value', 'url', 'qr'],
    components: { QrError },
    data() {
      return {
        qrcode: '',
        error: false,
        site: G.site
      }
    },
    methods: {
      transText(text) {
        const map = {
          '点击领取': '點擊領取',
          '店铺红包': '店鋪紅包',
          '立即领取': '立即領取',
          '微信扫码': '微信掃碼',
          '领优惠券': '領優惠券',
          '领礼金': '領禮金'
        }
        if (G.lang === 'zh-tr') {
          return map[text]
        }
        return text
      },
      click() {
        if (!this.qr) window.open(this.url)
      },
      over() {
        if (!this.qr) return
        if (this.qrcode) return
        getQRCode({
          id: G.dp.dpId,
          pid: 'bjgou-mini',
          amount: this.value,
          title: '',
          _type: 'rebate'
        }, '', res => {
          cnzz.log((G.site === '360buy' ? 'jd': 'taobao') + 'GiftMoney:hover')
          if (res[0].etag) {
            this.error = true
            return
          } else {
            this.error = false
          }
          this.qrcode = res[0].imgSrc
        })
      }
    }
  }
</script>



