let communicate = require('communicate')
var browsertype = require('browserTypePure');
var minibrowser = browsertype.getBrowser();
let globalObj = {};

let haslog
let renderInfo = (info) => {
  if (!info) return;
  if (!G.site) return;
  if (haslog) return;
  if (info.type === 'user_extension_id') {
    haslog = true;
    require('common/log')('browser_user:' + G.logsite + ':extType:' + getExtType());
  }
}
const getExtType = () => {
  let type = '';
  if (G.from_device === 'default')
    type = minibrowser.utype;
  else
    type = G.from_device;
  return type;
}
module.exports.init = () => {
  if (G.userid) {
    renderInfo({
      type: 'user_extension_id'
    })
    return;
  }
  communicate.trigger({
    type: 'user_extension_id'
  })
  communicate.on((info) => {
    try {
      if (info && info.type === 'browser_setinfo') {
        if (info.value && info.value instanceof Object) {
          for (let p in info.value) {
            globalObj[p] = info.value[p];
          }
        }
      } else if (info.type) {
        globalObj[info.type] = info.value;
        renderInfo(info)
      }
    } catch (e) {}

  })
}

module.exports.getInfo = (type) => {
  return globalObj[type];
}


