<template>
  <div class="bjg-bar-button gwd-row gwd-align gwd-jcc" @mouseover="startLoad">
    <img src="../assets/history.svg" alt="" style="width: 19px; height: 23px;">
    <span style="margin-left: 7px; font-size: 14px; color: #64615d">{{ transText('浏览历史') }}</span>
    <BjgBottomWindow :style="positionStyle + 'px'" always-show="1">
      <div style="height: 470px; overflow-y: auto">
        <CollectionItem v-for="(item, idx) in list"
                        :product="item"
                        :last="idx === list.length - 1"
                        :key="item.dp_id" @delete="deleteItem"/>
        <div class="gwd-row gwd-align gwd-jcc" style="margin-bottom: 19px;" v-if="list.length">
          <img src="../assets/rubbish_big@2x.png"
               @click="clearAll"
               style="width: 12px; height: 13px; cursor: pointer;" alt="">
          <span style="margin-left: 8px; font-size: 12px; cursor: pointer; color: #999"
                @click="clearAll">{{ transText('清空历史') }}</span>
        </div>
        <div v-if="list.length === 0 && loaded" class="gwd-column gwd-align gwd-jcc" style="height: 100%">
          <img src="../assets/emptyList@2x.png" alt="" style="width: 60px; height: 52px;">
          <span class="bjg-hintText">{{ transText('暂无浏览历史记录') }}</span>
        </div>
      </div>
    </BjgBottomWindow>
  </div>
</template>
<style scoped lang="less">
  .bjg-bar-button {
    width: 114px;
    height: 100%;
    position: relative;
    border-left: 1px solid #f1f1f1;
  }

  .bjg-bar-button:hover {
    background: #fffbef;
  }

  .bjg-hintText {
    color: #333333;
    line-height: 19px;
    font-size: 14px;
    margin-top: 16px;
  }
</style>
<script>
  const request = require('common/request')
  const bgClient = require('common/background/bgClient')

  import BjgBottomWindow from './BjgBottomWindow'
  import CollectionItem from './CollectionItem'
  import BottomWindowMixin from "../mixins/BottomWindowMixin";

  export default {
    components: { BjgBottomWindow, CollectionItem },
    mixins: [ BottomWindowMixin ],
    data() {
      return {
        list: [],
        loading: false,
        loaded: false,
        historyDpIdList: []
      }
    },
    methods: {
      transText(text) {
        const map = {
          '浏览历史': '瀏覽歷史',
          '清空历史': '清空歷史',
          '暂无浏览历史记录': '暫無瀏覽歷史記錄'
        }
        if (G.lang === 'zh-tr') {
          return map[text]
        }
        return text
      },
      clearAll() {
        this.list = []
        this.saveHistory([])
      },
      deleteItem(id) {
        this.list = this.list.filter(x => x.id !== id)
        this.saveHistory(this.historyDpIdList.filter(x => x !== id))
      },
      saveHistory(newList) {
        bgClient.get('/setStorage', {
          history: JSON.stringify(newList)
        }, data => {
        })
      },
      async addCurrent() {
        let historyDpIdList = await bgClient.get('/getStorage', { key: 'history' })
        if (!historyDpIdList) {
          historyDpIdList = []
        }
        this.historyDpIdList = historyDpIdList
        let dpId = await require('common/globalCondition').met('GwdDpIdGot')
        let res = await request.post('https://i.bijiago.com/UserHistory/Add?app_platform=ext', {
          dp_id: dpId
        }, true)
        if (res.code !== 1) return
        let newList = historyDpIdList.filter(x => x !== dpId)
        newList.unshift(dpId)
        newList = newList.filter((item, idx) => idx < 30)
        this.saveHistory(newList)
      },
      async startLoad() {
        if (this.loading || this.list.length > 0 || this.loaded) {
          return
        }
        this.loading = true
        let historyDpIdList = this.historyDpIdList
        if (!historyDpIdList.length) {
          this.loaded = true
          return
        }
        let result = await request.post('https://i.bijiago.com/UserHistory/List?app_platform=ext&union=' + G.union, {
          dp_ids: historyDpIdList.join(',')
        }, true)
        if (historyDpIdList.length > 20) {
          let result2 = await request.post('https://i.bijiago.com/UserHistory/List?app_platform=ext&union=' + G.union, {
            dp_ids: historyDpIdList.slice(20).join(',')
          }, true)
          result.data = result.data.concat(result2.data)
        }
        this.list = result.data.map(item => {
          item.id = item.dp_id
          return item
        })
        this.loaded = true
        this.loading = false
      }
    },
    mounted() {
      this.addCurrent()
    }
  }
</script>



