const request = require('common/request')
const parseprice = require('common/parseprice')
const template = require('vendor/template')
const go_union = require('common/go_union')

let amazonName = {
  '1': '中国',
  '228': '美国',
  '229': '日本',
  '246': '德国',
  '266': '英国',
  '365': '法国',
  '366': '加拿大'
}
let amazonCurrency = {
  '228': 'USD',
  '229': 'JPY',
  '246': 'EUR',
  '266': 'GBP',
  '365': 'EUR',
  '366': 'CAD'
}
let amazonMoney = {
  '1': '¥',
  '228': '$',
  '229': '円',
  '246': 'EUR',
  '266': '£',
  '365': 'EUR',
  '366': 'CDN$'
}

const reqInfo = (dp_id, callback) => {
  let url = `${G.server}/extension?ac=amazonGlobal&dp_id=${dp_id}`;
  request.get(url).done(data => {
    if (data && data.length > 0) {
      callback(data)
    } else {
      $('.bjgext-mini-trend').css('border-right', 'none')
    }
  })
}

const editData = data => {
  for (let i = 0, len = data.length; i < len; i++) {
    let site_id = data[i].dp_id.split('-')[1];
    if (data[i].nowpage === '1')
      data[i].siteName = amazonName[site_id] + '亚马逊(当前商城)';
    else
      data[i].siteName = amazonName[site_id] + '亚马逊';
    let price = (Number(data[i].pri) / 100).toFixed(2);
    let purePrice = '';
    if (site_id !== "1") {
      let price2 = '';
      if (site_id === '229')
        price2 = price + amazonMoney[site_id]
      else
        price2 = amazonMoney[site_id] + price;
      purePrice = parseprice(price, amazonCurrency[site_id]);
      price = '¥' + purePrice + `(${price2})`;
    } else {
      purePrice = price;
      price = '¥' + price;
    }
    var obj = {
      'site_id': site_id,
      'url': data[i].url,
      'mod': 'amazon_global',
      'union': G.union.split('_')[1],
      'dp_id': data[i].dp_id
    }
    data[i].url = go_union.init(obj)
    data[i].price = price;
    data[i].purePrice = purePrice;
  }
  data.sort(function(value1, value2) {
    return (Number(value1.purePrice) - Number(value2.purePrice));
  })
  return data;
}

const render = (data) => {
  if (G.showYjht) {
    $('.bjgext-mini-trend').css('border-right', 'none')
    return;
  }
  data = editData(data)
  let dp = data[0]
  let btn = `<a href="${dp.url}" target="_blank" id="amazon_global_link">亚马逊海外购：<span>${dp.price}</span></a>`
  $('.bjgext-mini-compare').append($(btn)).show();
  $('#bjgext_minibar').css('min-width', '393px')
  if (!G.showMinibar) {
    $('#bjgext_minibar').css('display', 'inline-block')
    G.showMinibar = true;
  }
  G.amazonGlobal = true;
}

module.exports.init = (dp_id) => {
  reqInfo(dp_id, render)
}

module.exports.amazonMoney = amazonMoney



