<template>
  <div class="gwd-qrlink-left gwd-row gwd-align" @mouseenter="over">
    <img src="../assets/taoQrLogo@2x.png" style="width: 26px; height: 26px; margin-left: 8px;">
    <span style="margin-left: 4px; font-size: 14px; color: #11192d; ">{{ transText('手淘扫码') }} {{ hasBuyButton ? transText('查看优惠'): transText('快捷购买') }}</span>
    <div class="gwd-qr-content gwd-align gwd-column">
      <img :src="qr" alt="" style="width: 98px; height: 98px;" v-if="qr">
      <img src="../assets/taoQr@2x.png" alt="" style="width: 20px; height: 20px; position: absolute; left: 50%; top: 42px; transform: translate(-50%, 0%);">
    </div>
  </div>
</template>
<style scoped lang="less">
  .gwd-qrlink-left {
    width: 165px;
    height: 36px;
    background: white;
    border-radius: 4px;
    border: 1px solid #dadde0;
    position: absolute;
    //bottom: 205px;
    top: 10px;
    right: 0;
    cursor: pointer;
    box-sizing: border-box;
    .gwd-qr-content {
      position: absolute;
      width: 109px;
      height: 108px;
      border: 1px solid #eaeaea;
      padding-top: 5px;
      display: none;
      top: 0px;
      left: -109px;
      box-sizing: border-box;
      z-index: 9999;
      background: white;
    }
  }

  .gwd-qrlink-left:hover {
    .gwd-qr-content {
      display: flex;
    }
  }
</style>
<script>
  import MemberCouponMixin from "common/components/MemberCouponMixin";

  export default {
    props: ['left', 'bottom'],
    mixins: [MemberCouponMixin],
    data: () => ({
      hasBuyButton: true
    }),
    methods: {
      transText(text) {
        const map = {
          '手淘扫码' : '手淘掃碼',
          '查看优惠': '查看優惠',
          '快捷购买': '快捷購買'
        }
        if (G.lang === 'zh-tr') {
          return map[text]
        }
        return text
      }
    },
    mounted() {
      setTimeout(() => {
        if ($('#J_ButtonWaitWrap').length) {
          this.hasBuyButton = false
        }
      }, 500)
    }
  }
</script>



