const request = require('common/request')
const template = require('vendor/template')
const mobileprice = require('common/mobileprice')
const userData = require('userData')

const getPromoInfo = (callback) => {
  let dp_data = userData.get('dp_data');
  let dp_id = dp_data.now.dp_id;
  let class_id = dp_data.now.class_id;
  let sbrand = dp_data.exact_arr.sbrand;
  let brand_id = dp_data.exact_arr.brand_id;
  let keyword = encodeURIComponent(dp_data.now.coreword);
  let tb_class = dp_data.exact_arr.taobao_class_id;
  let title = (dp_data.collectInfo && dp_data.collectInfo.title) ? dp_data.collectInfo.title: G.dp.name;
  //order说明： 0 最新 1 最热 2 即将结束
  let url = `${G.server}/brwext/promo_brand?pg=1&ps=5&order=0&tb_class=${tb_class}&keyword=${keyword}&class_id=${class_id}&dp_id=${dp_id}&title=${encodeURIComponent(title)}&url=${encodeURIComponent(window.location.href)}&sbrand=${encodeURIComponent(sbrand)}&brand_id=${brand_id}`;
  request.get(url).done(data => {
    if (data && data.products && data.products.length > 0)
      callback(data)
    else
      callback(null)
  })
}
const render = data => {

  if (data) {
    if (data.products.length < 4 && data.products.length !== 2) return;
    data.products = data.products.slice(0, 4)
    let dom = require('art-template-loader!../views/item_promo.html');
    let html = template.compile(dom)({
      data: data.products
    })
    $('#bjgext_minibar .promo-box ul').append(html)
    //$('.promo-box').show()
    // $('.promo-box').prev().css('border-bottom', '1px solid #e6e9eb')
    //$('.bjgext-toptabs .bjgext-mini-logo, .bjgext-mini-compare').addClass('hasPromo')
  } else {
    hidePrev()
  }
  mobileprice.init()
}

function hidePrev() {
  setTimeout(() => {
    $('.promo-box').prev().css('border-bottom', 'none')
    $('.promo-box').remove()
  }, 0)
}

module.exports.init = () => {
  if (G.site === 'amazon-com' || G.site === 'amazon-uk' || G.site === 'amazon-jp' || G.site === '6pm') {
    hidePrev()
    return;
  }
  if (G.show_promo === '0' || G.show_minibar === '0') {
    hidePrev()
    return;
  }
  if (G.aliSite) {
    hidePrev()
    return;
  }
  getPromoInfo(render)
}


