  var href = window.location.href;
  var host = window.location.host;
  var pageInfo;

  //检查是否在此页面出现小工具栏
  module.exports.isAvailablePage = () => {
    if (location.hostname.includes('.gwdang.com') && location.href.includes('/jd_enhance')) {
      return 'gwdang'
    }
    for (var pattern in sitePattern) {
      if (host.match(new RegExp(pattern, 'i'))) {
        return sitePattern[pattern];
      }
    }
    return false;
  }

  //检查是否在此页面出现比价
  module.exports.isProductPage = (url) => {
    url = url || href;
    if (url.indexOf('oneplus.com/cn/store') > -1) {
      return false;
    }
    if (G.from_device === 'bijiago' && (location.href.indexOf('https://pcsitepp-fm.jd.com/') > -1)) {
      return '360buy'
    }
    for (var pattern in productPattern) {
      let matchs = url.match(new RegExp(pattern, 'i'));
      if (matchs) {
        //if (url.match(new RegExp(pattern))) {
        let site = productPattern[pattern];
        const host = (new URL(url)).host
        if (site === "amazon" && host !== "www.amazon.cn" && matchs[1]) {
          let m = matchs[1];
          if (m.indexOf('.') > -1)
            m = m.split('.')[1];
          m = 'amazon-' + m;
          return m;
        }
        return productPattern[pattern];
      }
    }
    return false;
  }

  const page404 = (site) => {
    var page;
    switch (site) {
      default: if ($('#content h2').text().indexOf('您查看的商品找不到了') > -1)
        page = true;
      break;
    }
    return page;
  }
  //检查是否屏蔽此域名
  module.exports.isInBanList = () => {
    if (G.dcmExt) return false;
    if (!(G.iframe)) {
      var no_url = href.match(/[&\?]no_url/);
      if (!no_url && (self.location != top.location || self.frameElement && self.frameElement.tagName == "IFRAME" || window.top != window.self)) {
        return true;
      }
    }
    var main_url = href;
    if (location.href.indexOf('?') > 0) {
      main_url = href.substr(0, href.indexOf('?'));
    }
    // kaluli网站
    if (main_url.match(/\.kaluli.com/)) {
      return false;
    }
    //有一个carters的网站，防止被下面cart匹配到给屏蔽，提前判断如果匹配到carters就return false
    if (main_url.match(/(?:cartridge|Camcorder|carters|feifei\.com\/order\/|ref=ord_cart_shr)/) != null) {
      return false;
    }
    if (location.host.indexOf(`${G.extName}.com`) > -1 && !location.href.includes('jd_enhance')) return true;
    if (main_url.match(/detail\.zol\.com\.cn/))
      return false;
    if (main_url.match(/(?:cart|member|order|myhome|picture_index|handle-buy-box|chat|t.sina.com.cn|discussion|union.dangdang|eve.360buy|bank.vmall|checkout|confirm|gateway|trade|http:\/\/i.taobao.com|we.taobao.com|passport.yougou.com)/ig) != null) {
      return true;
    }
    return false;
  }
  const specialHost = (name) => {
    if (name === 'swarovski') {
      if (location.href.match(/Web_GB\/en/)) {
        name = 'swarovski-en'
      }
    }
    return name;
  }
  let getPageInfo = () => {
    if (pageInfo) return pageInfo
    var name = "";
    if (module.exports.isInBanList()) {
      return pageInfo = {
        type: 0,
        siteName: name
      };
    }
    name = module.exports.isProductPage();
    if (name) {
      if (typeof name !== 'string') {
        G.hidebar = name.hidebar;
        name = name.name;
      }
      G.site = name
      G.logsite = name;
      if (name.indexOf("amazon") > -1)
        G.site = "amazon";
      if (page404(name)) {
        return pageInfo = {
          type: 0,
          siteName: name
        }
      }
      return pageInfo = {
        type: 2,
        siteName: name
      };
    }
    name = module.exports.isAvailablePage();
    if (name) {
      if (typeof name !== 'string') {
        G.hidebar = name.hidebar;
        name = name.name;
      }
      name = specialHost(name)
      G.site = name
      G.logsite = name;
      return pageInfo = {
        type: 1,
        siteName: name
      };
    }
    return pageInfo = {
      type: 0,
      siteName: ''
    };
  }

