    let pageInfo = getPageInfo()
    require('common/extConsole').log(pageInfo)
    let productSites = new Set(Object.values(productPattern).filter(x => typeof x === 'string'))
    let allSites = new Set(Object.values(sitePattern).map(x => (typeof x === 'string' ? x : x.name)))
    let noProductSites = new Set([...allSites].filter(x => !productSites.has(x)))
    G.pageInfo = pageInfo;
    // if (noProductSites.has(G.site)) {
    //   require('common/log')('view:unsupportedSite')
    // } else {
