const md5 = require('js-md5')

const sendData = data => {
  let toSend = require('common/models/gzip').gZip(data);
  toSend = String.fromCharCode.apply(null, toSend);
  window.gwd_ext.post(`${gwd_G.server}/extension?ac=sendSkuInfo&from=externalJS`, btoa(toSend));
};

const getMdskip = () => {
  return new Promise((resolve) => {
    window.TShop && window.TShop.onProduct(e => resolve(e.get('mdskip')))
  })
};

const getValItemInfo = () => {
  return new Promise((resolve) => {
    setTimeout(() => {
      window.TShop && window.TShop.onProduct(e => resolve(e.get('config').valItemInfo))
    }, 2000)
  })
};

function extract_tmall_sku_map() {
  let attrs_list = []
  let props = document.querySelectorAll(".tb-sku > .tm-sale-prop")
  for (let i of props) {
    let levelName = i.querySelector("dt").textContent
    let level = {
      "name": levelName,
      "attrs": [],
    }
    let attrs = i.querySelectorAll("ul > li");
    for (let attr of attrs) {
      let value = attr.getAttribute("data-value");
      let name = attr.querySelector("a > span").textContent;
      level.attrs.push({ name: name, value: value })
    }
    attrs_list.push(level)
  }
  return attrs_list
}

