async function ajaxGetRequest(u) {
  return new Promise((resolve, reject) => {
    let xhr = new XMLHttpRequest()
    xhr.onreadystatechange = function () {
      if (xhr.readyState == 4) {
        if (xhr.status == 200) {
          resolve(xhr.responseText)
          // console.log(xhr.responseText)
        } else {
          reject(xhr.status)
        }
      }
    }
    xhr.open("GET", u, true)
    xhr.withCredentials = true;
    xhr.send()
  })
}

async function tmallH5Detail(pid) {
  if (!pid) {
    return
  }
  if (window.gwdDetailStorage && window.gwdDetailStorage[pid]) {
    return window.gwdDetailStorage[pid]
  }
  let spm = ""
  if (document.URL.match(/&spm=(.*?)(?:&|$)/)) {
    spm = document.URL.match(/&spm=(.*?)(?:&|$)/)[1]
  }
  let longText = `{"abbucket":"1","id":"${pid}","ns":"1","spm":"${spm}","sku_properties":"","detail_v":"3.5.0","appReqFrom":"detail","container_type":"xdetail","dinamic_v3":"true","supportV7":"true","ultron2":"true","itemNumId":"${pid}","pageCode":"miniAppDetail","_from_":"miniapp","openFrom":"pagedetail","pageSource":"1"}`
  let r = { "id": pid, "detail_v": "3.5.0", "exParams": longText }
  let token = document.cookie.match(/_m_h5_tk=([^;]+)/)[1].split("_")[0]
  let jsonpTs = new Date().getTime()
  let jsonString = JSON.stringify(r)
  let appKey = "12574478"
  let text = `${token}&${jsonpTs}&${appKey}&${jsonString}`
  let sign = md5(text)
  let jsv = "2.7.0"
  let t = jsonpTs
  let api = "mtop.taobao.detail.data.get"
  let v = "1.0"
  let type = "jsonp"
  let dataType = "jsonp"
  let callback = "mtopjsonp1"
  let u = `https://h5api.m.tmall.com/h5/mtop.taobao.detail.data.get/1.0/?jsv=${jsv}&appKey=${appKey}&t=${t}&sign=${sign}&api=${api}&v=${v}&ttid=201200%40taobao_h5_10.2.10&isSec=0&ecode=0&AntiFlood=true&AntiCreep=true&H5Request=true&type=${type}&dataType=${dataType}&safariGoLogin=true&mainDomain=tmall.com&subDomain=m&prefix=h5api&getJSONP=true&token=${token}&callback=${callback}&data=${encodeURIComponent(jsonString)}`
  let resText = await ajaxGetRequest(u)
  let json = resText.match(/mtopjsonp1\((.*)\)$/)[1]
  try {
    let data = JSON.parse(json).data
    let result = JSON.parse(data.apiStack[0]["value"])["global"]["data"]
    result.seller = data.seller
    result.pcdetail = false
    window.gwdDetailStorage = window.gwdDetailStorage || {}
    window.gwdDetailStorage[pid] = result
    return result
  } catch (e) {
    return {}
  }
}

