async function deleteFootprint(pid, timestamp, days = null) {
  // console.log('deleteing', pid, timestamp)
  const api = 'mtop.taobao.cmin.deletepath'
  const v = '1.0'
  const type = 'jsonp'
  const appKey = '12574478'
  const token = document.cookie.match(/_m_h5_tk=([^;]+)/)[1].split("_")[0]
  const jsonpTs = new Date().getTime()
  const jsonString = days ? JSON.stringify({
    ids: ``,
    days: days
  }):JSON.stringify({
    ids: `${timestamp}_${pid}`,
    days: ''
  })
  const text = `${token}&${jsonpTs}&${appKey}&${jsonString}`
  const sign = md5(text)

  let host = 'taobao'
  if (location.host.includes('tmall')) {
    host = 'tmall'
  }
  const url = (`https://h5api.m.${host}.com/h5/${api}/${v}/?jsv=2.7.0&appKey=${appKey}&t=${jsonpTs}&sign=${sign}&api=${api}&v=${v}&preventFallback=true&type=${type}&dataType=jsonp&callback=mtopjsonp1&data=${encodeURIComponent(jsonString)}`)
  // console.log('delete request', url)
  const res = await ajaxGetRequest(url)
  if (res.includes('SUCCESS')) {
    require('common/infoCollect/aliSkuHistory').remove(`${timestamp}_${pid}`)
    return 'SUCCESS'
  } else {
    require('common/infoCollect/aliSkuHistory').add(`${timestamp}_${pid}`)
    if (res.includes('过期')) {
      return 'EXPIRED'
    }
    return 'FAIL'
  }
}

async function couponInfo(id, promotionFloatingData) {
  if (!promotionFloatingData || !id) {
    return
  }
  if (location.hostname.includes('.tmall.com')) return
  if (localStorage.getItem('gwd-coupon-info-last-error-time')) {
    let lastErrorTime = localStorage.getItem('gwd-coupon-info-last-error-time')
    if (new Date().getTime() - lastErrorTime < 1000 * 60 * 60 * 24 * 10) {
      return
    }
  }
  if (window.gwdCouponInfo && window.gwdCouponInfo[id]) {
    return window.gwdCouponInfo[id]
  }
  let token = document.cookie.match(/_m_h5_tk=([^;]+)/)[1].split("_")[0]
  let jsonpTs = new Date().getTime()
  let appKey = "12574478"
  let jsonString = JSON.stringify({
    itemId: id,
    promotionFloatingData: JSON.stringify(promotionFloatingData),
  })
  let text = `${token}&${jsonpTs}&${appKey}&${jsonString}`
  let sign = md5(text)
  let t = jsonpTs

  let u = `https://h5api.m.taobao.com/h5/mtop.tmall.detail.couponpage.newcouponpage/1.0/?jsv=2.7.0&appKey=12574478&t=${t}&sign=${sign}&api=mtop.tmall.detail.couponpage.newcouponpage&v=1.0&ttid=201200%40taobao_h5_10.2.10&isSec=0&ecode=0&AntiFlood=true&AntiCreep=true&H5Request=true&type=jsonp&dataType=jsonp&safariGoLogin=true&mainDomain=taobao.com&subDomain=m&prefix=h5api&getJSONP=true&token=${token}&callback=mtopjsonp1&data=${encodeURIComponent(jsonString)}`
  try {
    let resText = await ajaxGetRequest(u)
    let json = resText.match(/mtopjsonp1\((.*)\)$/)[1]
    const result = JSON.parse(json).data.couponFloatLayer2VO
    window.gwdCouponInfo = window.gwdCouponInfo || {}
    window.gwdCouponInfo[id] = result
    if (!result) {
      localStorage.setItem('gwd-coupon-info-last-error-time', Date.now())
    }
    return result
  } catch (e) {
    localStorage.setItem('gwd-coupon-info-last-error-time', Date.now())
    return {}
  }
}
function isUserLogin() {
  if (document.querySelector("#login-info1") && document.querySelector("#login-info1").textContent.includes("请登录")) {
      return false
  }

  if (document.querySelector("#J_SiteNavLogin") && document.querySelector("#J_SiteNavLogin").textContent.includes("请登录")) {
      return false
  }
  return true
}

function mountResult(id, result) {
  if (!window.gwd_G.aliSkuResults) {
    window.gwd_G.aliSkuResults = {}
  }
  window.gwd_G.aliSkuResults[id] = result
}

const init = async () => {
  if (window.gwd_G.mtopRequested) {
    return
  }
  let id;
  if (gwd_G.site === 'taobao') {
    id = document.URL.match(/(?:\?|&)id=(\d+)/)[1]
  } else {
    id = require('common/commonUtil').getParameterByName('id')
  }

  window.gwd_G.mtopRequested = true

  let s;
  if (gwd_G.site === "taobao") {
    s = await tmallDetail(id, "taobao")
  } else if (gwd_G.site === "tmall") {
    s = await tmallDetail(id, "tmall")
  } else {
    return
  }
  let r = {
    skuBase: s.skuBase,
    skuCore: s.skuCore,
    item: s.item,
    props: s.props,
    rate: s.rate,
    componentsVO: s.componentsVO,
    seller: s.seller,
    priceSectionData: s.priceSectionData,
    version: "h5",
    pcdetail: s.pcdetail,
  }
  let data = {
    url: location.href,
    fp: localStorage.getItem('gwdang-fp'),
    dfp: localStorage.getItem('gwdang-dfp'),
    data: r,
    userLogin: isUserLogin(),
  };
  sendData(data)
  const couponInfoData = await couponInfo(id, s.promotionFloatingData)
  if (couponInfoData && couponInfoData.commonPromotions) {
    mountResult(id, {
      couponInfo: {
        limit: couponInfoData.commonPromotions[0].titles[0].match(/满(\d+)使用/)[1],
        discount: couponInfoData.commonPromotions[0].priceText
      },
    })
  } else {
    mountResult(id, 'no-coupon')
  }
};

module.exports = {
  init: init,
  getValItemInfo: getValItemInfo,
  tmallDetail: tmallDetail,
  taobaoDetail: taobaoH5Detail,
  deleteFootprint: deleteFootprint,
  couponInfo: couponInfo
};



