export default {
  props: ['tag'],
  data() {
    return {
      qr: '',
      loading: false
    }
  },
  computed: {
    link() {
      return require('common/productInfo').appendTbInfoForUrl(`${G.tb_server}/extension/qrpage?union=${G.union}&dp_id=${this.dpId ? this.dpId: G.dp.dpId}&tag=${this.tag}`)
    }
  },
  methods: {
    getText(text) {
      const map = {
        '当前商品可领会员券': '當前商品可領會員券',
        '立即领取': '立即領取',
        '手淘扫码': '手淘掃碼',
        '联系客服领取': '聯系客服領取'
      }
      if (G.lang === 'zh-tr') {
        return map[text]
      }
      return text
    },
    over() {
      if (this.tag === 2) {
        require('common/cnzz').logOnce('淘宝hu会员券:悬浮')
      }
      if (this.loading || this.qr) return
      this.loading = true
      require('common/request').rawGet(G.u_server + `/helper/qrcode?union=${G.union}${this.url ? '&url=' + this.url: ''}&event=appQrcode${this.tag ? `&tag=${this.tag}`: ''}&dp_id=` + (this.dpId ? this.dpId: G.dp.dpId)).then(res => {
        if (typeof res === 'string') {
          res = JSON.parse(res)
        }
        this.qr = res.data.qrImgStr
      })
    }
  }
}



