module.exports = obj => {
  if (G.from_device === '360' || G.site.indexOf('taobao') > -1 || G.site.indexOf('tmall') > -1) {
    if ((G.from_device === 'bijiago' && G.ss_name !== 'priceDog') || G.cooperation) {
      obj.sitename = 'taobao';
    } else {
      if (obj.source) {
        let url = obj.pureUrl || obj.url;
        url = url + ((url.indexOf('?') > -1) ? '&' : '?') + 'source=' + obj.source;
        // if (!G.forbidCoupon) {
        //   url = `${G.server}/extension/RedirectInTb?id=${obj.id}&format=&site=taobao`
        // }

        return url;
      }
    }
  }
  let source = '';
  let site = obj.sitename || '';
  if (obj.source)
    source = obj.source;
  // if (G.ss_name === 'priceDog' && G.aliSite) {
  //   debugger
  //   return `https://tb.pricedog.com/extension/qrpage?dp_id=${obj.id}&tag=9_chrome&discount=${data.coupon.coupon_money}`
  // }
  if (true) return `${G.u_server}/redirect/tao?id=${obj.id}&site=${site}&source=${source}&from_device=${G.from_device}&union=${G.union}`;
}

const makeUrl = (item, site) => {
  if (G.from_device === 'biyibi') {
    return `https://item.taobao.com/item.htm?id=${item.num_iid}`
  }
  return require('common/request').makeUrl(
    G.tb_server, '/extension/qrpage', {
      dp_id: item.num_iid + '-' + site,
      directLink: 1,
      position: 'extSame',
      title: item.title,
      img: item.pic_url,
      price: item.price,
      shopName: item.nick,
      sellAmount: item.volume,
      union: G.union
    })
}

module.exports.buildCommon = (data) => {
  // 针对淘宝客接口tbres 返回的数据  没有优惠券的部分做链接转换。
  if (!(data.tmall instanceof Array)) {
    for (var i = 0; i < data.tmall.product.length; i++) {
      let item = data.tmall.product[i];
      let obj = {
        'source': 'common',
        'img_url': item.pic_url,
        'title': item.title,
        'price': item.price,
        'shop_name': item.nick,
        'sales': item.volume || '0',
        'id': item.num_iid,
        'url': item.url,
        'discuss': item.comment_count || '0',
        'istaobao': '0',
        'pureUrl': "https://detail.tmall.com/item.htm?id=" + item.num_iid,
        'dp_id': G.now_dp_id,
        'site_id': G.site_id
      }
      if (G.site.indexOf('taobao') > -1 || G.site.indexOf('tmall') > -1) {
        if ((G.from_device === 'bijiago' || G.cooperation) && !G.forbidCoupon) {
          item.url = module.exports(obj)
        } else {
          item.url = makeUrl(item, 83)
        }

      } else {
        item.url = module.exports(obj)
      }
    }
  }
  if (!(data.taobao instanceof Array)) {
    for (var i = 0; i < data.taobao.product.length; i++) {
      let item = data.taobao.product[i];
      let obj = {
        'source': 'common',
        'img_url': item.pic_url,
        'title': item.title,
        'price': item.price,
        'shop_name': '',
        'sales': item.volume || '0',
        'id': item.num_iid,
        'url': item.url,
        'discuss': item.comment_count || '0',
        'istaobao': '1',
        'pureUrl': "https://item.taobao.com/item.htm?id=" + item.num_iid,
        'dp_id': G.now_dp_id,
        'site_id': G.site_id
      }
      if (G.site.indexOf('taobao') > -1 || G.site.indexOf('tmall') > -1) {
        if ((G.from_device === 'bijiago' || G.cooperation) && !G.forbidCoupon) {
          item.url = module.exports(obj)
        } else {
          item.url = makeUrl(item, 123)
        }
      } else {
        item.url = module.exports(obj)
      }
    }
  }
  return data;
}



