module.exports.init = () => {
  if (location.href.indexOf('.vip.com') > -1) {
    if (new Date() < new Date('2023-12-14T10:00:00')) {

      let b = document.createElement('a')
      b.classList.add('close-models')
      b.href = "https://tb.bijiago.com/static_page/activity_scan/vip.html"
      b.target = "_blank"
      b.style = 'border-left: 1px solid #f1f1f1; height: 100%'
      b.innerHTML = '<img src="https://cdn.gwdang.com/images/extensions/activity/vipBottom.png" alt="" style="height:44px; margin-top: 8px;">'
      $('.bjgext-closeBtn').before(b)
    }
  }

  if (location.href.indexOf('.kaola.com') > -1) {
    if (new Date() < new Date('2021-11-11T23:59')) {

      let b = document.createElement('a')
      b.href = "https://tb.jiuxinban.com/7cqq1K"
      b.target = "_blank"
      b.style = 'border-left: 1px solid #f1f1f1; height: 100%'
      b.innerHTML = '<img src="https://cdn.gwdang.com/images/extensions/activity/kola1111bottom@2x.png" alt="" style="width: 163px; margin-top: 3px">'
      $('.bjgext-closeBtn').before(b)
    }
  }
}



