<template>
  <div style="flex: 1; display: inline-block" :style="style" id="gwd_mini_compare" :class="{ bjg: isBjg, 'gwd-fake-tr': position.top }" @mouseover="mouseover" @mouseleave="mouseleave" class="minibar-tab" @hover.once="logHover">
    <div v-if="!position.top" class="minibar-btn-box">
      <em class="setting-bg mini-compare-icon "></em>
      <span style="float: none" v-if="data.length && data[0].view_price < pri">{{ transText('更低价') }}:¥{{ data[0].view_price }}</span>
      <span style="float: none" v-else-if="data.length === 0">{{ transText('暂无结果') }}</span>
      <span style="float: none" v-else>{{ transText('其他') }}{{ data.length }}{{ transText('家报价') }}</span>
    </div>
    <div v-if="position.top"></div>
    <div id="gwd_mini_compare_detail" class="minibar-detail">
      <ul>
        <li v-for="item in data" :key="item.nid">
          <a :href="item.url"
             @click="logLink()"
             target="_blank">
            <img :src="`https://cdn.gwdang.com/images/favicon/${item.site}.png`">
            <span class="m-item-sitename">{{ item.shopName }}</span>
            <span class="m-item-price prifontf">¥{{ item.view_price }}</span>
          </a>
        </li>
      </ul>
    </div>
  </div>
</template>
<style scoped lang="less">
#gwd_mini_compare {
  width: 155px;
  cursor: default;
  text-align: center;
  font-family: 'Microsoft YaHei',Arial,SimSun!important;
}

#gwd_mini_compare:hover {
  background-color: rgb(237, 241, 242);
}

#gwd_mini_compare.gwd-fake-tr:hover {
  background-color: transparent;
}

#gwd_mini_compare.bjg {
  border-right: 1px solid #e6e9eb;
}

.setting-bg {
  background: url('https://cdn.gwdang.com/images/extensions/xbt/new_wishlist_pg5_2.png') no-repeat;
  width: 18px;
  height: 18px;
  vertical-align: middle;
  float: left;
  margin-right: 8px;
  margin-top: 0px;
}

.mini-compare-icon {
  background-position: -93px -134px;
}

.minibar-btn-box {
  display: inline-flex;
  align-items: center;
  margin: 0 auto;
  float: none;
  height: 100%;
}
.minibar-btn-box * {
  float: left;
}
.minibar-btn-box span {
  color: #404547;
  font-size: 13px;
}
.minibar-btn-box span em {
  font-style: normal;
  line-height: 36px;
}
.minibar-btn-box span .price-em {
  margin-left: 2px;
  line-height: 37px;
}

#gwd_mini_compare_detail {
  display: none;
}

#gwd_mini_compare:hover #gwd_mini_compare_detail {
  display: block;
}
</style>
<style scoped>
#gwd_mini_compare_detail {
  position: absolute;
  margin: 0px 0 12px 0px;
  height: auto;
  width: 278px;
  top: 36px;
  left: 50%;
  margin-left: -139px;
  background-color: #fff;
  display: none;
  z-index: 9999999;
  border: 1px solid #edf1f2;
  box-shadow: 0 2px 4px 0 rgba(0,0,0,0.11);
  /* z-index: 999; */
}
#gwd_mini_compare_detail li:hover {
  background-color: #edf1f1;
}
#gwd_mini_compare_detail li {
  height: 40px;
}
#gwd_mini_compare_detail li * {
  float: left;
}
#gwd_mini_compare_detail li a {
  display: inline-block;
  height: 39px;
  width: 248px;
  border-bottom: 1px solid #edf1f1;
  margin-left: 15px;
}
#gwd_mini_compare_detail li img {
  width: 16px;
  margin-top: 12px;
  margin-right: 14px;
}
#gwd_mini_compare_detail li .m-item-sitename {
  width: 113px;
  margin-right: 6px;
  line-height: 40px;
  height: 40px;
  font-size: 14px;
  color: #404547;
  text-align: left;
  overflow: hidden;
}
#gwd_mini_compare_detail li .m-item-price {
  color: #E4393C;
  font-size: 14px;
  float: right;
  line-height: 40px;
  font-weight: bold;
}
#gwd_mini_compare_detail .m-all-link {
  color: #969899;
  text-decoration: none!important;
  float: right;
  height: 12px;
  line-height: 12px;
  margin-right: 15px;
  margin-top: 15px;
  margin-bottom: 15px;
  font-size: 12px;
}
#gwd_mini_compare_detail .m-all-link:hover {
  color: #48beff!important;
}


.bjg-hover-bg {
  background: #fffbef;
}
</style>
<style scoped lang="less">
.bjg {
  .minibar-btn-box span {
    color: #6b6761;
    font-size: 14px;
  }
}

.bjg#gwd_mini_compare:hover {
  background: #fffbef;
}
</style>
<script>
const log = require('common/log')

export default {
  props: ['data', 'pri', 'position'],
  data() {
    return {
      isBjg: G.from_device === 'bijiago'
    }
  },
  mounted() {
    log('miniCompare:length', this.data.length)
  },
  methods: {
    transText(text) {
      const map = {
        '更低价': '更低價',
        '暂无结果': '暫無結果',
        '其他': '其他',
        '家报价': '家報價',
      }
      if (G.lang === 'zh-tr') {
        return map[text] || text
      } else {
        return text
      }
    },
    logLink() {
      log('miniCompare:linkClick')
    },
    logHover() {
      log('miniCompare:hover')
    },
    mouseover() {
      if (this.position.top) {
        $('.gwd-minibar-bg #gwd_mini_compare').addClass('ms-tab-enter')
        if (G.from_device.includes('bijiago')) {
          $('#bjgext_minibar #gwd_mini_compare').addClass('bjg-hover-bg')
        }
      }
    },
    mouseleave() {
      if (this.position.top) {
        $('.gwd-minibar-bg #gwd_mini_compare').removeClass('ms-tab-enter')
        if (G.from_device.includes('bijiago')) {
          $('#bjgext_minibar #gwd_mini_compare').removeClass('bjg-hover-bg')
        }
      }
    }
  },
  computed: {
    style() {
      if (this.position.top) {
        const style = {
          top: this.position.top + 'px',
          left: this.position.left + 'px',
          width: (this.position.width + 1) + 'px',
          height: this.position.height + 'px',
          position: 'absolute',
        }
        if (G.from_device.includes('bijiago')) {
          style.background = 'transparent'
          style.borderRight = 'none'
        }
        return style
      }
      return {}
    }
  }
}
</script>



